        private void Section(System.Collections.Generic.List<string> checks, string name, Action run)
        {
            if (!SmokeRun.EnterSection(name)) return;
            string before = SmokeState();
            bool mainframeShown = mainframe.Visible, onTop = preferences.OnTop, topWas = NativeTop;
            bool hiddenWas = hidden, manualWas = manualHidden, fullWas = fullScreenHidden;
            FormWindowState mainframeState = mainframe.WindowState;
            try { run(); }
            catch (Exception problem) { TestFailed = true; checks.Add("FAIL section " + name + ": " + problem.Message); }
            finally
            {
                // A section leaves her as it found her. One that doesn't fails by name and is put back, so the steps after it
                // don't fail for it (her Mainframe left up once broke step 0 and everything after).
                string after = SmokeState();
                if (after != before)
                {
                    TestFailed = true;
                    checks.Add("FAIL section " + name + " left her changed: " + before + " became " + after);
                    if (menu.Visible) menu.Close();
                    if (mainframe.FreeKeysShown) mainframe.CloseFreeKeys();
                    if (playerMenu != null && playerMenu.Visible) playerMenu.Close();
                    if (preferences.OnTop != onTop) { preferences.OnTop = onTop; TopMost = onTop; Layer(); }
                    // WinForms keeps its own TopMost, so a window that lost Windows' topmost bit behind its back is told again directly.
                    if (NativeTop != topWas && IsHandleCreated)
                    {
                        if (topWas) LiftTop(); else Native.SetWindowPos(Handle, new IntPtr(-2), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
                        Layer();
                    }
                    if (!mainframeShown) { if (mainframe.Visible) mainframe.Hide(); }
                    else
                    {
                        if (!mainframe.Visible) mainframe.Show();
                        if (mainframe.WindowState != mainframeState) mainframe.WindowState = mainframeState;
                    }
                    if (hidden != hiddenWas) { manualHidden = manualWas; fullScreenHidden = fullWas; ApplyHidden(hiddenWas); }
                    string repaired = SmokeState();
                    if (repaired != before) checks.Add("FAIL section " + name + " couldn't be put back: " + repaired);
                }
                SmokeRun.LeaveSection(name, checks);
            }
        }

        private string SmokeState()
        {
            return "Mainframe " + (mainframe.Visible ? mainframe.WindowState.ToString() : "hidden") + ", her " + (hidden ? "hidden" : "shown")
                + ", her menu " + (menu.Visible ? "open" : "closed") + ", the player's menu " + (playerMenu != null && playerMenu.Visible ? "open" : "closed")
                + ", free key menu " + (mainframe.FreeKeysShown ? "open" : "closed")
                + ", Always on top " + preferences.OnTop + ", topmost in Windows " + NativeTop;
        }

        // Windows' own topmost bit on her window. An owned window made not-topmost takes its owner down with it, which WinForms'
        // TopMost never hears about (the mini player above her at smoke step 0).
        private bool NativeTop { get { return IsHandleCreated && (Native.GetWindowLong(Handle, -20) & 0x8) != 0; } }
        internal bool TestFinished;
        internal string TestStep = "startup";

        internal Companion(string data, EventWaitHandle signal, EventWaitHandle shownSignal, bool smoke)
        {
            groove = new Groove(delegate { return clock.Elapsed.TotalSeconds; });
            dance = new Clip(idle);
            Takeover.Face = LoadArt("Capri.Sprite.face.png");
            testing = smoke;
            voice = new Voice(new Speaker(smoke));
            AllowDrop = true;
            instant = smoke;
            speaker = new Speaker(smoke);
            effects = new Speaker(smoke) { Plain = true };
            typist = new Speaker(smoke) { Plain = true };
            restore = signal;
            shown = shownSignal;
            settingsPath = Path.Combine(data, "settings.json");
            HerCursor.Marker = Path.Combine(data, "her-cursor.on");
            // Smoke tests never touch the real Windows cursor.
            if (smoke) HerCursor.Apply = delegate(bool on) { cursorSwaps.Add(on); };
            // Nor a real audio device for her voice in your mic, or Windows' choice of default mic.
            if (smoke)
            {
                MicMix.Devices = new StandInDevices();
                Ears.DefaultName = delegate { return "Microphone (stand-in)"; };
            }
            HerCursor.Recover();
            CloneWindow.Marker = Path.Combine(data, "moved-windows.txt");
            CloneWindow.Recover();
            IconMischief.Marker = Path.Combine(data, "scattered-icons.txt");
            iconRecoveryTimer.Tick += IconRecoveryTick;
            // Smoke tests never touch the real desktop: point her icon prank at nothing until a check hands it a fake list view.
            if (smoke) DesktopIcons.Target = delegate { return IntPtr.Zero; };
            else BeginIconRecovery();
            iconTimer.Interval = 120;
            iconTimer.Tick += IconTick;
            Computer.Track = herPointer.MoveTo;
            Computer.Tapped = delegate { Post(herPointer.Tap); };
            Computer.Lending = Lend;
            taskPanel.Moved += delegate { if (onPanel) { HoldPanel(); Location = anchor; } };
            updater = new Updater(data, Application.ExecutablePath, smoke);
            updateExit = delegate { quitting = true; Close(); };
            startMarker = smoke ? null : Path.Combine(data, Program.StartMarker);
            Brain.LogPath = Path.Combine(data, "errors.txt");
            Brain.MemoryPath = Path.Combine(data, "me.md");
            // personality.md is made only when they press Edit, so an old one from 0.7.4 or 0.7.5 is read as it is.
            Brain.PersonalityPath = Path.Combine(data, Brain.PersonalityName);
            if (smoke) foreach (string old in new[] { Brain.PersonalityPath, Brain.PersonalityBackup }) if (File.Exists(old)) File.Delete(old);
            reminders = new Reminders(data, DateTime.Now);
            Brain.MemoriesPath = Path.Combine(data, "memories.md");
            Hands.Websites = new Websites(data);
            Brain.TranscriptPath = Path.Combine(data, "transcripts");
            GameNotes.Folder = Path.Combine(data, "games");
            Hands.GameOpen = delegate { return Computer.GameOpen(); };
            engine = new Engine(data);
            kokoro = new LocalVoice(data);
            qwen = new QwenVoice(data);
            ModelFile.Engine = LocalVoice.Folder(data);
            ModelFile.Shelf = Path.Combine(Path.Combine(data, "voice"), "models");
            parakeet = new LocalEars(data);
            heyCapri = new WakeWord(data);
            presence = new Presence(Assembly.GetExecutingAssembly().GetName().Version.ToString(3));
            preferences = smoke ? new Preferences() : LoadPreferences();
            foreach (Form form in new Form[] { this, pill, box, taskPanel, player }) form.HandleCreated += delegate { PassThrough(); };
            PassThrough();
            qwen.CpuOnly = preferences.HdCpu;
            bool careNew = !preferences.CareWritten;
            careLines = new CareLines(Path.Combine(data, "check-ins.md"));
            if (careNew) preferences.CareWritten = careLines.Create();
            care = new Care(delegate { return clock.Elapsed.TotalSeconds; }, delegate { return DateTime.Now; }, careLines.Pick);
            // SECURITY: their toggles, with "Hey Capri" kept in its own setting for her wake word.
            Migrate(preferences);
            Security.Load(preferences.Permissions);
            Security.HeyOn = delegate { return preferences.HeyCapri; };
            Security.SetHey = SetHeyCapri;
            Security.Changed = SecurityChanged;
            ears.Chosen = preferences.Mic;
            if (!smoke) MixVoice();
            kokoro.Style = LocalVoice.Find(preferences.VoiceStyle);
            Brain.Language = Brain.LanguageCode(preferences.Language) == "en" ? null : preferences.Language;
            PointEars();
            Brain.Nickname = Brain.Nick(preferences.Nickname).Length == 0 ? null : Brain.Nick(preferences.Nickname);
            Brain.Wordiness = Math.Max(0, Math.Min(2, preferences.Wordiness));
            Brain.Recall = preferences.Recall == 16 || preferences.Recall == 32 ? preferences.Recall : 8;
            Brain.MemorySize = Array.IndexOf(Brain.MemorySizes, preferences.MemorySize) >= 0 ? preferences.MemorySize : 0;
            Brain.ReplyLength = Math.Max(0, Math.Min(Brain.ReplySizes.Length - 1, preferences.ReplyLength));
