        internal void OpenCare()
        {
            string path = Path.Combine(Path.GetDirectoryName(settingsPath), "check-ins.md");
            if (!File.Exists(path)) File.WriteAllText(path, "# Capri's check-ins\n\n");
            Hands.Run("\"" + Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows), "notepad.exe") + "\" \"" + path + "\"");
        }

        private void PopIn(double now)
        {
            bool wasHidden = hidden;
            string line = Lines.Pick(PopLines);
            // With Wander off, or on a spot they picked (Sit here, Hang here, riding the cursor), she says hi from where she is.
            if (!wasHidden && (!preferences.Wander || riding || hanging || (seat != null && seat.Free)))
            {
                if (IsHandleCreated) Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
                SayOwn("", line);
                popOut = preferences.OnTop ? -1 : clock.Elapsed.TotalSeconds + 6;
                popClicks = clicks;
                popHide = false;
                return;
            }
            Rectangle area = Screen.FromPoint(Cursor.Position).WorkingArea;
            Point spot = new Point(area.Left + (int)(random.NextDouble() * Math.Max(1, area.Width - Width)), area.Bottom - Height - 12);
            Action arrive = delegate
            {
                StopRide();
                seat = null;
                falling = false;
                walking = false;
                anchor = spot;
                ShowHidden(false);
                DropSoon();
                if (IsHandleCreated) Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
                SayOwn("", line);
                popOut = wasHidden || !preferences.OnTop ? clock.Elapsed.TotalSeconds + 6 : -1;
                popClicks = clicks;
                popHide = wasHidden;
            };
            if (wasHidden) arrive();
            else GlitchOut(arrive, false);
        }

        private void CheckReminders(DateTime now)
        {
            if (quitting || dragging || pressed || typer.Visible || menu.Visible || outro != null) return;
            if (!InChat && working == null && (speech != null || talkState != TalkState.Off)) return;
            string line;
            try { line = reminders.Take(now); }
            catch (IOException) { return; }
            catch (UnauthorizedAccessException) { return; }
            if (line == null) return;
            reminderUp = true;
            bool bubbleOnly = InChat || Hushed || (preferences.Quiet && !preferences.ServerVoice) || FullScreen();
            if (working != null)
            {
                asideShown = line;
                asideUntil = clock.Elapsed.TotalSeconds + BubbleHold(line.Length);
                UpdateTalk(clock.Elapsed.TotalSeconds);
                if (!bubbleOnly && job != null) SayAside(line, job);
            }
            else Remark("reminder", line, bubbleOnly);
            if (IsHandleCreated) Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
        }

        private bool popHide;

        private void EndPopIn(bool leave)
        {
            popOut = -1;
            if (!preferences.OnTop && IsHandleCreated) Native.SetWindowPos(Handle, new IntPtr(-2), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
            if (leave && popHide && !hidden) SetHidden(true);
            popHide = false;
        }

        internal void ToggleCheckIns()
        {
            preferences.CheckIns = !preferences.CheckIns;
            nextPopIn = -1;
            nudgeOut = -1;
            nudgeGap = NudgeGap;
            noticed = -1;
            SavePreferences();
            mainframe.Sync();
        }

        internal bool Shushed { get { return shushed; } }

        // Her quiet key or any nap: no glances, pop-ins, check-ins, cheers or jokes.
        private bool Hushed { get { return shushed || napAsked || napping || Asleep || ownNap; } }

        // Her quiet key, for when they focus or game: she stops what she's saying and talks only when they talk to her.
        // Watch my screen and Check in on me keep their settings and pick up again on the next press. Her settings tool flips it
        // without her line, since her brain says so.
        internal void ToggleShush(bool say = true)
        {
            shushed = !shushed;
            nextPopIn = -1;
            nudgeOut = -1;
            nudgeGap = NudgeGap;
            noticed = -1;
            nextGlance = -1;
            if (shushed) { ownLines.Clear(); voicePreview = null; BargeIn("quiet key"); }
            if (docked) GameHud.Status(!preferences.Silent, shushed);
            if (say) Say(shushed ? "Going quiet. " + QuietKeyName + " when you want me back." : "I'm back, choom.");
        }

        // With Check in on me on, ignored for a while when they're at the PC, she comes over and asks for attention: a click gets a happy line, silence gets a sulk and a longer wait.
        private void CheckNudge(double now, long quiet)
        {
            if (quiet > Care.Away) { noticed = -1; nudgeOut = -1; nudgeGap = NudgeGap; boredAsk = false; return; }
            if (boredAsk && !preferences.CareBored) { nudgeOut = -1; boredAsk = false; }
            // Her own bubble isn't them noticing her: their clicks, typing and menus are.
            bool attending = clicks != noticedClicks || dragging || pressed || InChat || typer.Visible || menu.Visible || (talkState != TalkState.Off && remarkTicket != asking) || onPanel;
            if (noticed < 0 || attending) { noticed = now; noticedClicks = clicks; }
            if (nudgeOut >= 0)
            {
                if (attending)
                {
                    nudgeOut = -1;
                    nudgeGap = NudgeGap;
                    // A click while her ask is still up gets her happy line in its place.
                    if (talkState != TalkState.Off && remarkTicket == asking) CloseTalk();
                    if (PopFree(now, quiet)) SayOwn("check-in", boredAsk ? careLines.Pick("Bored noticed") : Lines.Pick(NoticedLines));
                    boredAsk = false;
                }
                else if (now >= nudgeOut && speech == null)
                {
                    nudgeOut = -1;
                    nudgeGap = Math.Min(nudgeGap * 2, NudgeGap * 4);
                    noticed = now;
                    if (quiet < 20000 && !hidden && PopFree(now, quiet)) SayOwn("check-in", boredAsk ? careLines.Pick("Bored ignored") : Lines.Pick(SnubbedLines));
                    boredAsk = false;
                }
                return;
            }
            if (preferences.CareBored || !preferences.CheckIns || Hushed || hidden || quiet > 30000 || now - noticed < nudgeGap || (lastGlance >= 0 && now - lastGlance < 300)) return;
            if (quitting || riding || onPanel || falling || hanging || typer.Visible || speech != null || outro != null || popOut >= 0 || (clip != idle && clip != perch)) return;
            if (!PopFree(now, quiet)) return;
            Nudge(now);
        }

        private void AskedForAttention(double now, bool bored = false)
        {
            noticed = now;
            noticedClicks = clicks;
            nudgeOut = now + 20;
            boredAsk = bored;
        }

        private void Nudge(double now)
        {
            AskedForAttention(now);
            string line = Lines.Pick(NudgeLines);
            Point cursor = Cursor.Position;
            Point hip = Hip();
            Rectangle area = Screen.FromPoint(cursor).WorkingArea;
            Action ask = delegate
            {
                // Behind other windows she can't be noticed, so she comes to the front until it's over, the way a pop-in does.
                if (!preferences.OnTop && IsHandleCreated)
                {
                    Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
                    popOut = clock.Elapsed.TotalSeconds + 20;
                    popClicks = clicks;
                    popHide = false;
                }
                SayOwn("check-in", line);
            };
            // With Wander off, or on a Sit here spot, she asks from where she is.
            if (!preferences.Wander || (seat != null && seat.Free) || (area.Contains(hip) && Math.Abs(hip.X - cursor.X) <= Math.Max(300, Width * 2))) { ask(); return; }
            int x = cursor.X - area.Left < area.Width / 2 ? cursor.X + Width / 2 : cursor.X - Width - Width / 2;
            Point spot = new Point(Math.Max(area.Left, Math.Min(area.Right - Width, x)), area.Bottom - Height - 12);
            GlitchOut(delegate
            {
                StopRide();
                seat = null;
                falling = false;
                walking = false;
                anchor = spot;
                ShowHidden(false);
                DropSoon();
                ask();
            }, false);
        }

        private static bool Installed()
        {
            try { return string.Equals(Path.GetFullPath(Application.ExecutablePath), Path.GetFullPath(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "Capri", "Capri.exe")), StringComparison.OrdinalIgnoreCase); }
            catch (ArgumentException) { return false; }
            catch (NotSupportedException) { return false; }
            catch (IOException) { return false; }
        }

