        // PREBUILT LOCAL (paid false) or ElevenLabs under CLOUD VOICE. Without a key she uses her free voice either way, so ElevenLabs
        // only clears Quiet for the key that comes next.
        internal void ChooseVoiceTier(bool paid)
        {
            if (AfterLine(delegate { ChooseVoiceTier(paid); })) return;
            if (paid && preferences.CloudVoice != ElevenLabs)
            {
                preferences.CloudVoice = ElevenLabs;
                SavePreferences();
            }
            bool wasSilent = preferences.Silent;
            if (!keepVoiceOff) preferences.Silent = false;
            if (wasSilent)
            {
                preferences.Quiet = !paid;
                SavePreferences();
                if (!paid) GetFreeVoice();
                if (!preferences.Silent && !hidden && !IsDisposed && (!paid || voice.Key != null))
                {
                    heard = "settings";
                    box.Prompt = "> sys: ";
                    Answer(++asking, VoiceOnLine, TalkState.Talking);
                }
            }
            else if (voice.Key != null && paid == preferences.Quiet) ToggleSpeaking();
            else if (paid && preferences.Quiet) { preferences.Quiet = false; SavePreferences(); }
            mainframe.Sync();
            ShowVoice();
            if (paid && voice.Key == null) mainframe.VoiceNote("Paste your ElevenLabs key, then press Connect.", false);
        }

