        private void Layer()
        {
            pill.Above = preferences.OnTop;
            box.Above = preferences.OnTop;
            typer.TopMost = preferences.OnTop;
            if (callPanel != null) callPanel.TopMost = preferences.OnTop;
            if (minis != null)
            {
                minis.Above = preferences.OnTop;
                if (minis.IsHandleCreated) Native.SetWindowPos(minis.Handle, new IntPtr(preferences.OnTop ? -1 : -2), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
            }
            if (chess != null)
            {
                chess.Above = preferences.OnTop;
                if (chess.IsHandleCreated) Native.SetWindowPos(chess.Handle, new IntPtr(preferences.OnTop ? -1 : -2), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
            }
            foreach (Form above in new Form[] { pill, box, typer })
            {
                if (above.Owner != this) above.Owner = this;
                if (above.IsHandleCreated) Native.SetWindowPos(above.Handle, new IntPtr(preferences.OnTop ? -1 : -2), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
            }
            if (preferences.OnTop) LiftTop();
            player.Above = preferences.OnTop;
            if (!player.IsHandleCreated) return;
            Native.SetWindowPos(player.Handle, new IntPtr(preferences.OnTop ? -1 : -2), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
            if (player.Visible) PlayerLayer(true);
        }

        // Puts her in the topmost band. After Always on top went off and on, with her mini player's window made, Windows took
        // TOPMOST on her as done and left her where she was, under the boards and the player (smoke step 0, 2 Nov). From the top
        // of the normal band it takes.
        private void LiftTop()
        {
            if (!IsHandleCreated) return;
            Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
            if (NativeTop) return;
            Native.SetWindowPos(Handle, new IntPtr(-2), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
            Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
        }

        internal void FindBrain()
        {
            Cloud remote = brain.Remote;
            if (remote != null && remote.Kind != "local")
            {
                brain.Local = null;
                brain.Model = remote.Model;
                mainframe.ShowCloud(remote, cloudModels);
                ListCloud(remote.Key, false);
                return;
            }
            if (SettingUp) return;
            mainframe.Searching();
            if (finding) return;
            finding = true;
            string address = preferences.LocalAddress;
            int port = preferences.BrainPort;
            string selected = preferences.BrainAddress;
            ThreadPool.QueueUserWorkItem(delegate
            {
                string[] installed = null;
                try { installed = Brain.InstalledModels(); } catch (WebException) { } catch (IOException) { } catch (SerializationException) { }
                System.Collections.Generic.List<Cloud> servers = Brain.LocalBrains(address, port, selected);
                Machine found = Machine.Read();
                Pick local = engine.Installed();
                Post(delegate
                {
                    finding = false;
                    if (address != preferences.LocalAddress) { FindBrain(); return; }
                    mainframe.ShowServers(servers, installed, local);
                    if (brain.Remote == null && preferences.Tier == 0 && (installed == null || installed.Length == 0) && local == null && servers.Count > 0)
                    {
                        Cloud first = servers[0];
                        brain.Remote = new Cloud(first.Port, first.Model, first.Host);
                        Keep(brain.Remote);
                    }
                    UseBrain(installed, found, local);
                });
            });
        }

        internal string LocalAddress { get { return preferences.LocalAddress ?? ""; } }

        internal string SetLocalAddress(string address)
        {
            int port = Brain.LocalPort(address);
            if (!string.IsNullOrWhiteSpace(address) && port == 0) return "Use a loopback address, like http://127.0.0.1:1234.";
            preferences.LocalAddress = Brain.LocalAddress(address);
            localAddressTyped = port > 0;
            SavePreferences();
            bool local = brain.Remote == null || brain.Remote.Kind == "local";
            if (!testing && local) FindBrain();
            return port == 0 ? "Local server address cleared." : local ? "Local server address saved. Pick its model under BRAIN." : "Local server address saved. Pick NORMAL to use it.";
        }

        internal void ChooseLocalBrain(Cloud server, string model, Pick local)
        {
            if (AfterLine(delegate { ChooseLocalBrain(server, model, local); })) return;
            ++cloudListing;
            cloudModels = null;
            brain.Cancel();
            ++asking;
            CloseTalk();
            brain.Remote = server == null ? null : new Cloud(server.Port, model, server.Host);
            localAddressTyped = false;
            brain.Local = local == null ? null : engine;
            brain.LocalPick = local;
            brain.Model = model;
            preferences.BrainPort = server == null ? 0 : server.Port;
            preferences.BrainAddress = server == null ? null : server.Host;
            if (server != null) preferences.LocalModel = model;
            else preferences.Model = model;
            SavePreferences();
        }

        private void Post(Action action)
        {
            try { if (!IsDisposed) BeginInvoke(action); } catch (InvalidOperationException) { }
        }

        // --bench runs her as usual from another folder and takes what lands in its ask.txt as if it was typed, so her hands can be
        // scored on real games. Each turn of a job goes in bench.txt.
        internal void StartBench(string data)
        {
            string asked = Path.Combine(data, "ask.txt");
            string traced = Path.Combine(data, "bench.txt");
            Job.TraceFolder = data;
            Job.Trace = delegate(string line) { lock (asked) File.AppendAllText(traced, DateTime.Now.ToString("HH:mm:ss.fff") + " " + line + Environment.NewLine); };
            Commentary.Trace = Job.Trace;
            System.Windows.Forms.Timer polling = new System.Windows.Forms.Timer { Interval = 400 };
            polling.Tick += delegate
            {
                if (!File.Exists(asked)) return;
                string text;
                try { text = File.ReadAllText(asked); File.Delete(asked); }
                catch (IOException) { return; }
                if (text.Trim().Length > 0) Hear(text.Trim());
            };
            polling.Start();
        }

        // Her stream's job loop is running, so a stop from her stream tool ends it like their Esc.
        private volatile bool streamLoop;

        private string RunJob(string task, string asked)
        {
            if (Hands.StreamAsked(task) || Hands.StreamAsked(asked)) Computer.Streaming = true;
            if (!Computer.Streaming)
            {
                Job plain = new Job(task, asked);
                string finished = Work(plain);
                if (!Computer.Streaming || plain.Outcome == "stopped" || Computer.Interrupted) { Computer.Streaming = Computer.StreamingAlways; return finished; }
            }
            // On stream only their Esc ends it (Lachy, 30 Oct: "play for hours ... while im asleep"). Anything else that stops
            // her, like a brain error or a run of turns without a move, starts the stream again after a breather, a longer one
            // each time it breaks again within two minutes, up to eight minutes.
            int rests = 0;
            streamLoop = true;
            try
            {
                while (true)
                {
                    Job running = new Job(task, asked);
                    int began = Environment.TickCount;
                    string result;
                    try { result = Work(running); }
                    catch (Exception error) { result = "That didn't work: " + error.Message; }
                    if (running.Outcome == "stopped" || Computer.Interrupted) { Computer.Streaming = Computer.StreamingAlways; return result; }
                    rests = unchecked(Environment.TickCount - began) < 120000 ? Math.Min(rests + 1, 5) : 0;
                    int wait = 15000 << rests;
                    Brain.Log("stream", -1, "stopped (" + (running.Outcome ?? "failed") + "): " + result + " Starting again in " + wait / 1000 + " s.");
                    Computer.Pause(wait);
                    if (Computer.Interrupted) { Computer.Streaming = Computer.StreamingAlways; return result; }
                }
            }
            finally { streamLoop = false; }
        }

        private string ResumeJob(string text)
        {
            // Her asking first for SECURITY: their yes runs what she held, and their no leaves it.
            string answered = Security.Resume(text, ResumeTool);
            if (answered != null) return answered;
            Job waiting = job;
            if (waiting == null || !waiting.Asking) return null;
            string said = text.Trim();
            if (Regex.IsMatch(said, @"^(yes|yeah|yep|yup|ya|yea|sure|ok|okay|do it|go ahead|go for it|send it|press it|oui)\b[\s.!,]*(please|pls|plz|choom)?[\s.!]*$", RegexOptions.IgnoreCase)) return Work(waiting);
            job = null;
            if (Regex.IsMatch(said, @"^(no|nah|nope|don't|do not|stop|cancel|never mind|nevermind|leave it|non)\b", RegexOptions.IgnoreCase)) return "Okay, I left it alone.";
            return null;
        }

        // One job holds the mouse at a time. Another waits its turn, so two never fight over the cursor.
        private readonly object mouseGate = new object();

        private string Work(Job running)
        {
            lock (mouseGate) return Worked(running);
        }

        private string Worked(Job running)
        {
            if (quitting) return Computer.Why;
            job = running;
            if (InvokeRequired) Invoke(new Action(StopExplore)); else StopExplore();
            running.Think = delegate(string system, string user, System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, ToolArguments>> calls) { return brain.Step(system, user, Computer.Tools, Computer.ClaudeTools, Computer.Listing, calls); };
            Cloud driver = brain.Remote;
            // A game job thinks harder on every turn, on her fast hands unless they've turned those off.
            running.Drive = brain.Drives && driver.Model != blindModel ? new Func<string, string, string, ClaudeReply>(delegate(string system, string tools, string messages) { return brain.Drive(system, tools, messages, running.Playing, running.Playing && !preferences.SlowHands); }) : null;
            running.Advised = delegate { return !preferences.SlowHands && brain.Advises; };
            // Anything else that can see plays from pictures.
            running.Seer = running.Drive == null && Unseeing() == null ? new Func<byte[], string, string, string>(delegate(byte[] jpeg, string system, string user) { return brain.See(jpeg, system, user, 700, true); }) : null;
            running.Aside = delegate(string system, string user) { return brain.Aside(system, user, 320, true); };
            running.Reader = testing ? null : new Action<Sight>(delegate(Sight read) { if (Ink.ScreenRequest(running.Task)) Computer.ReadWords(read, Computer.Shoot(null)); else Computer.ReadWords(read); });
            running.Says = delegate(string line) { Post(delegate { if (Computer.Streaming) ChatLine(line, running); else PlayLine(line, running); }); };
            running.Blind = delegate { if (!running.Playing || preferences.SlowHands) blindModel = driver.Model; };
            running.Progress = delegate(string status) { Post(delegate { working = status + " Esc stops me."; UpdateTalk(clock.Elapsed.TotalSeconds); }); };
            running.Seen = delegate(Sight sight)
            {
                if (sight == null || sight.Window == IntPtr.Zero) return;
                IntPtr window = sight.Window;
                Rectangle bounds = sight.Bounds;
                string name = AppName(sight);
                Post(delegate { if (job == running && preferences.Motion && !hidden) takeover.Follow(window, name, bounds, preferences.Size / 240f); });
            };
            running.Busy = delegate(string what) { Post(delegate { taskPanel.Busy(running, what); }); };
            running.Stepped = delegate(JobStep step) { Post(delegate { taskPanel.Add(running, step); }); if (step.Finished) AgentStep(running); };
            Computer.PlacePointer(PointerHome());
            Post(delegate { JobOn(running); });
            string result = null;
            // A job that plays a song or video notes what Windows had on first, so one it leaves paused can be started after.
            bool media = !testing && Computer.PlaysMedia(running.Task, running.Words, running.Playing);
            Tune before = media ? Tunes.Current() : null;
            try
            {
                result = running.Run();
                if (media && !running.Playing) KeepPlaying(running.Outcome, before, 800);
                return result;
            }
            finally
            {
                // However it ended, a held button is let go and their mouse handed back.
                Computer.Finish();
                jobEndedAt = Environment.TickCount;
                if (job == running && !running.Asking) job = null;
                string outcome = running.Outcome ?? "failed";
                Post(delegate { JobOff(running, outcome, result); });
            }
        }

        // YouTube starts a video by itself, and her hands sometimes clicked it to play it, which paused it (a tester, 30 Oct). After
        // a job that played something, what Windows has on gets play pressed once if it's paused, unless it was already paused
        // before the job and the job left it alone. True when she pressed it.
        internal static bool KeepPlaying(string outcome, Tune before, int settle)
        {
            if (outcome != "done") return false;
            for (int look = 0; look < 2; look++)
            {
                Tune after = Tunes.Current();
                if (after == null || after.Playing || (before != null && before.Key == after.Key && !before.Playing)) return false;
                // A video that's still loading can read as paused for a moment.
                if (look == 0) { Thread.Sleep(settle); continue; }
                return Tunes.Send(after, "play");
            }
            return false;
        }

        private void JobOn(Job running)
        {
            WakeRest(true);
            string start = Lines.Pick(Lines.OnIt);
            working = start;
            if (typer.Visible) typer.Hide();
            pointing = true;
            if (!hidden)
            {
                Rectangle work = Screen.FromControl(this).WorkingArea;
                // On stream the panel, and her on it, go bottom left, clear of the chat panel at the top right.
                if (Computer.Streaming) taskPanel.Corner(new Point(work.Left + 8, work.Bottom - 8));
                taskPanel.Begin(running, running.Words, work);
            }
            // Her pointer sets off from beside her on the panel.
            if (SitOnPanel()) Computer.PlacePointer(PointerHome());
            herPointer.Begin(Computer.HerAt);
            PassThrough();
            // With Hey Capri on, her own offline ears open for the job, so they can tell her more without saying it first (Lachy, 29 Oct).
            // Not on a Bluetooth headset's mic, which would put the job's sound at call quality.
            if (!chatting && !testing && preferences.HeyCapri && FreeChatOn && OwnEars && HandsFreeMic(preferences.Mic) == null) { jobEars = true; StartLocal(); }
            UpdateTalk(clock.Elapsed.TotalSeconds);
            SayJobStart(start, running);
        }

        // She says her job's first line out loud too (Lachy, 29 Oct: "she doesnt verbally say 'on it, esc stops me'"), in the voice
        // her replies use, picked the way Answer picks it (Quiet only turns her cloud voice off). It plays beside the job, after
        // any line she's still saying, and leaves the reply the job ends with alone. Silent keeps it to her bubble, and so does
        // ElevenLabs voice chat, which speaks for itself.
        private void SayJobStart(string start, Job running) { SayAside(start.Replace("Esc", "Escape"), running); }

        // A line said beside her job, like her "Got it." when they tell her more mid-job. It leaves her ask's turn alone.
        private double playVoiced;
        private bool asideVoiceTest;

        // A line she says while she plays. A chat reply or a watch's alert that's still up keeps the bubble.
        private void PlayLine(string line, Job running)
        {
            double now = clock.Elapsed.TotalSeconds;
            if (job != running || working == null || (asideShown != null && now < asideUntil)) return;
            if (docked) Commentary.Stage.Say(line);
            asideShown = line;
            asideUntil = now + BubbleHold(line.Length);
            UpdateTalk(now);
            // A slow voice would never speak if each new line cancelled the one it's still making, so the next line waits for it.
            if ((chatting && !local) || Hushed || now < playVoiced) return;
            playVoiced = now + 15;
            SayAside(line, running);
        }

        // Her say lines on stream are for chat, so every one goes in her bubble and out loud, in her usual voice.
        private void ChatLine(string line, Job running)
        {
            if (job != running || working == null) return;
            double now = clock.Elapsed.TotalSeconds;
            if (docked) Commentary.Stage.Say(line);
            asideShown = line;
            asideUntil = now + BubbleHold(line.Length);
            UpdateTalk(now);
            SayAside(line, running);
        }

        private void SayAside(string line, Job running, int toolReply = -1)
        {
            if ((testing && !asideVoiceTest) || preferences.Silent || Hushed || (chatting && !local && !Computer.Streaming)) return;
            Func<string, byte[]> free;
            Func<string, byte[]> speak = PickVoice(false, out free, false);
            if (speak == null) return;
            string words = Voice.Spoken(line);
            int turn = ++asideVoice;
            ToolVoicing(toolReply, turn);
            ThreadPool.QueueUserWorkItem(delegate
            {
                string problem;
                byte[] wav = Voiced(speak, free, words, out problem, false);
                if (wav == null) { if (problem != null) Brain.Log("job line", -1, problem); Post(delegate { ToolVoiced(turn); }); return; }
                int tries = 0;
                Action play = null;
                play = delegate
                {
                    if (job != running || turn != asideVoice || IsDisposed || (chatting && !local && !Computer.Streaming) || preferences.Silent || Hushed) { ToolVoiced(turn); return; }
                    double now = clock.Elapsed.TotalSeconds;
                    if (Voicing)
                    {
                        if (tries++ < 16) ThreadPool.QueueUserWorkItem(delegate { Thread.Sleep(500); Post(play); });
                        else ToolVoiced(turn);
                        return;
                    }
                    voiceUntil = now + Voice.Seconds(wav) + 0.6;
                    ToolVoiced(turn);
                    playVoiced = voiceUntil;
                    CheckEars(now);
                    Played(wav);
                    PlayVoice(wav);
                };
                Post(play);
            });
        }

        // Asking them something counts as an end too, so her pointer is put away while they answer.
        // She stays on the panel until it fades.
        private void JobOff(Job running, string outcome, string result)
        {
            working = null;
            asideShown = null;
            if (jobEars)
            {
                jobEars = false;
                if (chatting && local) StopChat();
            }
            pointing = false;
            herPointer.End();
            PassThrough();
            takeover.Release();
            taskPanel.End(running, outcome, result);
        }

        // During a job she sits on the task panel instead of riding her pointer, which she'd hide. A ride they started carries on.
        private bool SitOnPanel()
        {
            if (onPanel) return true;
            if (riding || hidden || !preferences.Motion || !taskPanel.Showing || !IsHandleCreated) return false;
            Halt();
            EndWalk();
            panelHome = anchor;
            panelSeat = seat;
            panelHung = hanging;
            seat = null;
            falling = false;
            fallTo = null;
            hanging = false;
            dropAfter = false;
            pendingClick = false;
            clickDelay.Stop();
            pressed = false;
            dragging = false;
            Capture = false;
            leanAngle = 0;
            onPanel = true;
            taskPanel.Room = Headroom();
            HoldPanel();
            Location = anchor;
            Play(perchGlitch);
            frames.Start();
            pill.Hide();
            // Above the panel, so she sits on it rather than behind it.
            Native.SetWindowPos(Handle, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
            return true;
        }

        // Keeps her on the panel's top edge, near its right end, as it grows a row or they drag it.
        private void HoldPanel()
        {
            if (!taskPanel.Showing) { LeavePanel(true); return; }
            Rectangle plate = taskPanel.Plate;
            if (plate.IsEmpty) return;
            Rectangle area = Screen.FromRectangle(plate).WorkingArea;
            int x = plate.Right - plate.Width * 3 / 10;
            x = Math.Max(area.Left + (int)Math.Ceiling(preferences.Size * (SitX - PerchedBody.Left)), Math.Min(x, area.Right - (int)Math.Ceiling(preferences.Size * (PerchedBody.Right - SitX))));
            anchor = Seated(x, plate.Top);
        }

        // Off the panel: once it's gone she goes back to where she was before the job; going anywhere else she just leaves it.
        private void LeavePanel(bool home)
        {
            if (!onPanel) return;
            onPanel = false;
            taskPanel.Room = 0;
            if (!preferences.OnTop && IsHandleCreated) Native.SetWindowPos(Handle, new IntPtr(-2), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
            if (!home) return;
            anchor = panelHome;
            seat = panelSeat;
            hanging = panelHung;
            leanAngle = 0;
            if (hidden || IsDisposed) return;
            Location = anchor;
            Play(hanging ? dangle : seat != null ? perchGlitch : glitch);
            frames.Start();
            if (seat == null && !hanging) DropSoon();
        }

        private string AppName(Sight sight)
        {
            if (sight.Window == namedWindow && namedApp != null) return namedApp;
            string name = sight.Program ?? "";
            try
            {
                int id;
                Native.GetWindowThreadProcessId(sight.Window, out id);
                using (Process process = Process.GetProcessById(id))
                {
                    string described = process.MainModule.FileVersionInfo.FileDescription;
                    if (!string.IsNullOrWhiteSpace(described)) name = described.Trim();
                }
            }
            catch (System.ComponentModel.Win32Exception) { }
            catch (InvalidOperationException) { }
            catch (ArgumentException) { }
            catch (NotSupportedException) { }
            name = Regex.Replace(name, @"\s+", " ").Trim();
            if (name.Length == 0) name = "this app";
            if (name.Length > 26) name = name.Substring(0, 26).TrimEnd() + "...";
            namedWindow = sight.Window;
            namedApp = char.ToUpperInvariant(name[0]) + name.Substring(1);
            return namedApp;
        }

