        // Her settings tool's actions: edit_check_in_lines opens her check-in lines like Habits' button, and preview_voice plays her
        // voice as it's set now once the reply it came with is over, without touching her voice service.
        private string SettingAction(string action, bool fromAgent)
        {
            if (InvokeRequired) return (string)Invoke(new Func<string, bool, string>(SettingAction), action, fromAgent);
            if (action == "edit_check_in_lines") { OpenCare(); return "Opened your check-in lines."; }
            if (action == "preview_voice")
            {
                if (preferences.Silent) return "My voice is off. Turn it on to hear a preview.";
                bool ready = !preferences.Quiet && !voiceBroke && (Speak != null || voice.Ready) || FreeSpeak != null || kokoro.Installed || preferences.HdVoice && qwen.Installed || preferences.ServerVoice;
                if (!ready) return "My voice isn't ready. Set it up in Mainframe > VOICE first.";
                styleCheckDue = true;
                styleAsked = asking;
                styleAgent = fromAgent ? agent : null;
                styleReply = chatReplies;
                return "I'll play my current voice after this reply.";
            }
            return "Couldn't do that just now.";
        }

        internal bool HologramOn { get { return preferences.Hologram; } }

        internal void ToggleHologram() { SetHologram(!preferences.Hologram); }

        private void SetHologram(bool on)
        {
            preferences.Hologram = on;
            hologramItem.Checked = on;
            rideItem.Enabled = !on;
            if (on)
            {
                pressed = dragging = pendingClick = false;
                Capture = false;
                clickDelay.Stop();
                petTurns.Clear();
                petWay = 0;
                petTicket++;
                StopRide();
                if (clip == dangle) { Play(idle); Drop(); }
            }
            PassThrough();
            RenderFrame();
            SavePreferences();
            if (mainframe != null) mainframe.Sync();
        }

        // During a job her pill and bubble let clicks through. She and the task panel only do while their cursor is lent out
        // for one of her presses, so between presses they can drag her and the panel out of the way, including over full screen.
        private void PassThrough()
        {
            foreach (Form form in new Form[] { this, pill, box, taskPanel, player })
            {
                bool through = lentOut || (preferences.Hologram && (form == this || form == pill || form == box)) || (form == this ? riding : form != taskPanel && pointing);
                Overlay overlay = form as Overlay;
                if (overlay != null) overlay.ClickThrough = through;
                if (!form.IsHandleCreated) continue;
                int style = Native.GetWindowLong(form.Handle, -20);
                if ((style & 0x80000) == 0) continue;
                int wanted = through ? style | 0x20 : style & ~0x20;
                if (wanted != style) Native.SetWindowLong(form.Handle, -20, wanted);
            }
        }

        // Called from her hands' thread as their cursor is lent out and handed back. Any drag of her or the panel stops,
        // so the press lands in the app underneath.
        private void Lend(bool lent)
        {
            if (InvokeRequired)
            {
                try
                {
                    IAsyncResult done = BeginInvoke(new Action(delegate { Lend(lent); }));
                    // A busy UI thread gets a second to catch up before the press goes ahead anyway.
                    done.AsyncWaitHandle.WaitOne(1000);
                }
                catch (InvalidOperationException) { }
                return;
            }
            lentOut = lent;
            if (lent)
            {
                taskPanel.LetGo();
                player.LetGo();
                if (pressed) { pressed = false; dragging = false; Capture = false; }
            }
            PassThrough();
        }

        private void UseBrain(string[] installed, Machine found, Pick local)
        {
            machine = found;
            fit = Engine.Fit(found);
            ollamaRunning = installed != null;
            Cloud remote = brain.Remote;
            if (remote != null)
            {
                brain.Local = null;
                brain.Model = remote.Model;
                mainframe.ShowCloud(remote, cloudModels);
                return;
            }
            if (installed != null && installed.Length > 0 && (local == null || preferences.Model != local.Name))
            {
                brain.Local = null;
                brain.Model = Brain.PickModel(installed, preferences.Model, fit);
                mainframe.ShowOllama(installed, brain.Model);
            }
            else if (local != null)
            {
                brain.LocalPick = local;
                brain.Local = engine;
                brain.Model = local.Name;
                mainframe.ShowLocal(local);
            }
            else
            {
                brain.Local = null;
                brain.Model = null;
                mainframe.ShowSetup(found, fit, ollamaRunning, null);
            }
        }

        internal void SetUpBrain()
        {
            if (SettingUp || machine == null) return;
            SettingUp = true;
            engine.Cancel = false;
            Pick pick = fit;
            bool viaOllama = ollamaRunning;
            mainframe.ShowProgress(1, "Starting download", 0, 0);
            long shownAt = 0;
            ThreadPool.QueueUserWorkItem(delegate
            {
                Action<string, long, long> progress = delegate(string text, long done, long total)
                {
                    long now = clock.ElapsedMilliseconds;
                    if (now - Interlocked.Read(ref shownAt) < 200 && done < total) return;
                    Interlocked.Exchange(ref shownAt, now);
                    string label = viaOllama ? "Downloading " + pick.Name : text;
                    Post(delegate { if (SettingUp) mainframe.ShowProgress(1, label, done, total); });
                };
                try
                {
                    if (viaOllama) Brain.Pull(pick.Ollama, progress, delegate { return engine.Cancel; });
                    else engine.Install(pick, progress);
                    Post(delegate { mainframe.ShowProgress(2, "Loading " + pick.Name, 0, 0); });
                    if (viaOllama) { brain.Local = null; brain.Model = pick.Ollama; brain.Warm(); }
                    else { brain.LocalPick = pick; brain.Local = engine; brain.Model = pick.Name; engine.Ensure(pick); }
                    Post(delegate
                    {
                        SettingUp = false;
                        if (viaOllama) { preferences.Model = pick.Ollama; SavePreferences(); FindBrain(); }
                        else mainframe.ShowLocal(pick);
                        Greet();
                    });
                }
                catch (OperationCanceledException) { Post(delegate { SettingUp = false; mainframe.ShowSetup(machine, pick, viaOllama, "Cancelled. It picks up where it left off."); }); }
                catch (Exception error) { string problem = Brain.Brief(error.Message) ?? (error.Message.Length > 70 ? error.Message.Substring(0, 67) + "..." : error.Message); Post(delegate { SettingUp = false; mainframe.ShowSetup(machine, pick, viaOllama, problem); }); }
            });
        }

        internal void CancelSetup() { engine.Cancel = true; }

        private void Greet()
        {
            // After setup, once she's said hi with her new brain, she gets to know them. Only the first time.
            if (!preferences.Met && !testing) meetAt = clock.Elapsed.TotalSeconds + 1;
            // They got in first, so her hello doesn't cancel what they asked.
            if (box.Prompt == "> you: " && talkState != TalkState.Off) return;
            if (hidden) SetHidden(false);
            Hear("(You just woke up on this PC with a brand new brain. Say hi to the user in one short line.)", "brain online", "> sys: ");
        }

        internal void ChooseModel(string name, bool keep = true)
        {
            if (name == brain.Model) return;
            if (keep && AfterLine(delegate { ChooseModel(name, keep); })) return;
            brain.Cancel();
            ++asking;
            CloseTalk();
            // Her chat carries on with the new model, a stand-in for a stuck one too, so changing brains never wipes what she was doing.
            brain.Model = name;
            Cloud remote = brain.Remote;
            if (remote != null) remote.Model = name;
            if (!keep) return;
            if (remote != null) Keep(remote);
            else
            {
                preferences.Model = name;
                SavePreferences();
            }
        }

        internal void ChooseCloudModel(Cloud remote, string name)
        {
            if (remote != brain.Remote || cloudModels == null || !cloudModels.Contains(name)) return;
            ChooseModel(name);
            mainframe.ShowCloud(remote, cloudModels);
        }

        private void SplitKeys()
        {
            if (preferences.Tiered) return;
            string textKey = Voice.Unprotect(preferences.TextKey);
            bool nvidia = textKey != null && Cloud.KindOf(textKey) == "nvidia";
            if (nvidia)
            {
                preferences.NvidiaKey = preferences.TextKey;
                preferences.NvidiaModel = preferences.TextModel;
            }
            else if (textKey != null)
            {
                preferences.PaidKey = preferences.TextKey;
                preferences.PaidModel = preferences.TextModel;
            }
            preferences.Tier = textKey == null ? 0 : nvidia ? 1 : 2;
            preferences.Tiered = true;
            if (!testing) SavePreferences();
        }

        private Cloud TierCloud()
        {
            if (preferences.Tier == 0 && preferences.BrainPort > 0 && preferences.BrainPort <= 65535 && !string.IsNullOrEmpty(preferences.LocalModel)) return new Cloud(preferences.BrainPort, preferences.LocalModel, preferences.BrainAddress);
            string key = Voice.Unprotect(preferences.Tier == 1 ? preferences.NvidiaKey : preferences.Tier == 2 ? preferences.PaidKey : null);
            string model = preferences.Tier == 1 ? preferences.NvidiaModel : preferences.PaidModel;
            string kind = Cloud.KindOf(key);
            if (kind == null || preferences.Tier == 1 && !Cloud.MediumKind(kind)) return null;
            bool fits = Brain.ModelFits(kind, model) && (preferences.Tier != 1 || kind != "openrouter" || model.EndsWith(":free", StringComparison.Ordinal));
            return new Cloud(key, fits ? model : null);
        }

        private void Mirror()
        {
            preferences.TextKey = preferences.Tier == 1 ? preferences.NvidiaKey : preferences.Tier == 2 ? preferences.PaidKey : null;
            preferences.TextModel = preferences.Tier == 1 ? preferences.NvidiaModel : preferences.Tier == 2 ? preferences.PaidModel : null;
        }

        private void ShowTiers()
        {
            string nvidia = Voice.Unprotect(preferences.NvidiaKey), paid = Voice.Unprotect(preferences.PaidKey);
            mainframe.ShowTiers(preferences.Tier, nvidia == null ? null : Voice.Tail(nvidia), paid == null ? null : Voice.Tail(paid), Cloud.KindOf(nvidia));
        }

        private void Keep(Cloud remote)
        {
            if (remote.Kind == "local") { preferences.BrainPort = remote.Port; preferences.BrainAddress = remote.Host; preferences.LocalModel = remote.Model; }
            else if (preferences.Tier == 1) preferences.NvidiaModel = remote.Model;
            else preferences.PaidModel = remote.Model;
            Mirror();
            SavePreferences();
        }

        internal void ChooseTier(int tier)
        {
            if (tier == preferences.Tier) return;
            if (AfterLine(delegate { ChooseTier(tier); })) return;
            ++cloudListing;
            brain.Cancel();
            ++asking;
            CloseTalk();
            preferences.Tier = tier;
            Mirror();
            SavePreferences();
            brain.Remote = TierCloud();
            brain.Model = brain.Remote == null ? null : brain.Remote.Model;
            cloudModels = null;
            ShowTiers();
            FindBrain();
        }

