            SavePreferences();
            mainframe.ShowMic(MicName(preferences.Mic));
            hearingCaptureProblem = null;
            ResetHearingSignal();
            RefreshHearingDevices();
            // "Hey Capri" opens the new mic on its next check.
            if (wakeOpen) CloseWake();
            wakeMuteAt = -1;
