        // Windows Settings > Privacy & security > Speech, where Online speech recognition is.
        internal const string SpeechSettings = "ms-settings:privacy-speech";
        internal void OpenSpeechSettings() { Browse(SpeechSettings); }

        // A setting changed partway through her line, a preview of her voice, or a line she starts herself, like a comment, cut
        // off the line she was saying (john_sandevistan, 3 Nov). A setting now waits for her voice to finish and applies from her
        // next line. A preview or her own line also waits for her reply and for them talking, and only the newest preview plays.
        // Talking over her, her quiet key and turning her voice off still stop her at once.
        private readonly System.Collections.Generic.Queue<Action> voiceChanges = new System.Collections.Generic.Queue<Action>();
        private readonly System.Collections.Generic.Queue<Action> ownLines = new System.Collections.Generic.Queue<Action>();
        private Action voicePreview;
        private int voiceOffTurn;
        private bool keepVoiceOff, changingVoice;

        // Her voice is still being made or played, past its estimate too: an answer's, a reaction's, a clone's or voice chat's.
        private bool Voicing
        {
            get
            {
                return voice.Busy || speaker.Busy || chatTail.Enabled || clock.Elapsed.TotalSeconds < voiceUntil || answerVoice == asking || hdSpeaking == asking;
            }
        }

        private bool LineBusy { get { return Voicing || pushing || transcribing || talkState == TalkState.Thinking || talkState == TalkState.Talking; } }

        private bool AfterLine(Action change)
        {
            if (!Voicing && (changingVoice || voiceChanges.Count == 0)) return false;
            int turn = voiceOffTurn;
            voiceChanges.Enqueue(delegate
            {
                bool held = keepVoiceOff, changing = changingVoice;
                keepVoiceOff = held || preferences.Silent && turn != voiceOffTurn;
                changingVoice = true;
                try { change(); }
                finally { keepVoiceOff = held; changingVoice = changing; }
            });
            return true;
        }

        // A preview they asked for waits for her voice and for them talking, but plays over a line still showing in her bubble,
        // and a newer preview cuts off the one she's saying, so sliding a slider hears where it ended up.
        private bool PreviewBusy { get { return pushing || transcribing || (heard != "voice check" && (Voicing || talkState == TalkState.Thinking)); } }

        private bool PreviewAfterLine(Action preview)
        {
            if (!PreviewBusy) return false;
            voicePreview = preview;
            return true;
        }

        // Settings go in even while she's hidden; her own lines would bring her back, so they wait.
        private void CheckNextLine()
        {
            if (quitting || IsDisposed) return;
            while (voiceChanges.Count > 0 && !Voicing) voiceChanges.Dequeue()();
            if (hidden && !docked) return;
            if (voicePreview != null && !PreviewBusy)
            {
                Action preview = voicePreview;
                voicePreview = null;
                preview();
                return;
            }
            if (!LineBusy && ownLines.Count > 0) ownLines.Dequeue()();
        }

        private void Tell(string shown, string line)
        {
            if (hidden) SetHidden(false);
            heard = shown;
            box.Prompt = "> sys: ";
            Answer(++asking, line, TalkState.Talking);
        }

        // Something she says on her own, like what she makes of their screen: her bubble shows only her words, with no
        // "> sys: watching" above them (Lachy, 30 Oct: testers found it too robotic).
        private void Remark(string shown, string line, bool bubbleOnly = false, byte[] prepared = null, bool ready = false)
        {
            // Out loud it waits for her to finish and for them; in her bubble only it waits just for her own voice, so a reminder
            // still shows in a call.
            bool aloud = prepared != null || !(bubbleOnly || ready);
            if (aloud ? LineBusy : voice.Busy || clock.Elapsed.TotalSeconds < voiceUntil || answerVoice == asking || hdSpeaking == asking)
            {
                ownLines.Enqueue(delegate { Remark(shown, line, bubbleOnly, prepared, ready); });
                return;
            }
            if (hidden) SetHidden(false);
            heard = shown;
            box.Prompt = "";
            remarkTicket = ++asking;
            if (bubbleOnly || ready) Begin(remarkTicket, line, TalkState.Talking, prepared);
            else Answer(remarkTicket, line, TalkState.Talking);
        }

        internal void SetUpFreeVoice(bool told = false)
        {
            if (SettingUpVoice) return;
            SettingUpVoice = true;
            kokoro.Cancel = false;
            voiceGot = voiceTotal = 0;
            ShowVoice(false);
            mainframe.VoiceNote("This may take some time. For a better sounding, faster voice, get an API key.", false);
            ShowInstall();
            ThreadPool.QueueUserWorkItem(delegate
            {
                string problem = null;
                bool cancelled = false;
                Action<string, long, long> progress = delegate(string text, long done, long total)
                {
                    Post(delegate { if (total > 0) { voiceGot = done; voiceTotal = total; } ShowInstall(); });
                };
                try { kokoro.Install(progress); kokoro.Warm(); }
                catch (OperationCanceledException) { problem = "Cancelled. It picks up where it left off."; cancelled = true; }
                catch (Exception error) { problem = Voice.Short(error.Message); }
                if (problem != null && !cancelled && !testing) Brain.Log("free voice setup", -1, problem);
                Post(delegate
                {
                    SettingUpVoice = false;
                    ShowInstall();
                    ShowVoice();
                    if (problem != null)
                    {
                        mainframe.VoiceNote(problem, true);
                        if (told && !cancelled) { balloonPage = null; balloonUpdate = false; balloonMainframe = true; tray.ShowBalloonTip(15000, "Capri's free voice didn't download", problem + " Click to try again from Capri Mainframe.", ToolTipIcon.Warning); }
                    }
                    else
                    {
                        if (voice.Key == null || preferences.Quiet || voiceBroke) voiceCheckDue = true;
                        GetFreeEars();
                        EarsArrived();
                    }
                });
            });
        }

        // The language she listens for: the one picked in Settings, English included. Left on English without ever being
        // picked, she listens for Windows' language, for people who never changed her from English but speak their own.
        internal static string Listening(string picked, string windows) { return LocalEars.Spoken(Brain.LanguageCode(picked), picked == null ? windows : null); }

        // Parakeet hears English and 24 other European languages; the rest keep Windows speech, which knows them.
        private void PointEars()
        {
            string was = parakeet.Model;
            parakeet.Language = Listening(preferences.Language, System.Globalization.CultureInfo.CurrentUICulture.TwoLetterISOLanguageName);
            UpdateHearing();
            if (parakeet.Model == was || !chatting || !local) return;
            Dictation closing = dictation;
            dictation = null;
            if (closing != null) closing.Dispose();
            ListenLocally();
        }

        private bool OwnEars { get { return ownEarsTest ?? parakeet.Ready; } }

        // Speakers of a language her Parakeet ears know wait for those instead of Windows' offline dictation, which mishears nearly everything.
        private bool EarsComing { get { return earsComingTest ?? (!testing && FreeChatOn && parakeet.Fits); } }

        // Her own ears come after her free voice, which brings the speech engine they run on. Until they're in she hears
        // through Windows speech.
        private void GetFreeEars(bool retry = false)
        {
            // It downloads alongside her free voice; they work once both are in.
            if (testing || HearingChoice == 2 || settingUpEars || !FreeChatOn || parakeet.Installed || !parakeet.Fits) return;
            settingUpEars = true;
            hearingInstallProblem = null;
            parakeet.Cancel = false;
            earsGot = earsTotal = 0;
            ShowInstall();
            if (!SettingUpVoice && !retry)
            {
                balloonPage = null;
                balloonUpdate = false;
                balloonMainframe = true;
                tray.ShowBalloonTip(8000, "Getting Capri's ears", Engine.Amount(parakeet.Size) + ", one time. Then she hears any mic, offline. Click to watch it download.", ToolTipIcon.Info);
            }
            ThreadPool.QueueUserWorkItem(delegate
            {
                string problem = null;
                Action<string, long, long> progress = delegate(string text, long done, long total)
                {
                    Post(delegate { if (total > 0) { earsGot = done; earsTotal = total; } ShowInstall(); });
                };
                try { parakeet.Install(progress); }
                catch (OperationCanceledException) { problem = "Cancelled."; }
                catch (Exception error) { problem = Voice.Short(error.Message); }
                if (problem != null) Brain.Log("ears setup", -1, problem);
                Post(delegate
                {
                    settingUpEars = false;
                    ShowInstall();
                    if (problem != null) { EarsFailed(problem); return; }
                    earsFailures = 0;
                    // Her language changed while they downloaded, so she gets the ones it needs.
                    if (!parakeet.Installed) { GetFreeEars(); return; }
                    if (EarsArrived()) return;
                    if (chatting && local) mainframe.VoiceNote("Her own ears are in.", false);
                });
            });
        }

        // In free voice chat she says the download failed and tries again after 30 seconds, then 1, 2 and 4 minutes, then every 5.
        private void EarsFailed(string problem)
        {
            hearingInstallProblem = problem;
            if (problem == "Cancelled." || !chatting || !local) { UpdateHearing(); mainframe.VoiceNote(hearingStatus.Text, true); return; }
            earsFailures++;
            int wait = EarsRetryWait(earsFailures);
            earsRetryAt = clock.Elapsed.TotalSeconds + wait;
            if (earsAwaited && earsFailures == 1) HearingNote();
            else { UpdateHearing(); mainframe.VoiceNote(hearingStatus.Text, true); }
        }

        internal static int EarsRetryWait(int failures) { return Math.Min(300, 30 << Math.Max(0, Math.Min(4, failures - 1))); }

        // Free voice chat checks two things: a failed ears download gets another go, and a mic that sends only silence gets a warning.
        private void CheckHearing(double now)
        {
            CheckMicTest(now);
            CheckHearingSignal(now);
            SayHeldEarsNote();
            if (chatting && local && dictation != null && earsReady && now >= dictationMicAt)
            {
                dictationMicAt = now + 2;
                string current = Dictation.DefaultMic();
                // The cable is caught even when it was already the default as Windows speech opened, so the id never changed.
                bool cable = MicMix.IsCableOut(Ears.DefaultName());
                if (cable || current != null && !string.Equals(current, dictationMic, StringComparison.OrdinalIgnoreCase))
                {
                    Brain.Log("ears", -1, cable ? "Windows default mic is CABLE Output; leaving Windows speech." : "Windows default mic changed from " + dictationMic + " to " + current + "; reopening Windows speech.");
                    dictation.Dispose();
                    dictation = null;
                    earsReady = false;
                    ListenLocally();
                }
            }
            KeepListening(now);
            if (earsRetryAt >= 0 && now >= earsRetryAt)
            {
                earsRetryAt = -1;
                if (chatting && local) GetFreeEars(true);
            }
            // A line her ears never hand back would keep them shut for good, so after 30 s she lets it go and listens again.
            if (transcribing && chatting && local && Environment.TickCount - transcribingAt > 30000)
            {
                Brain.Log("ears", -1, "A line took over 30 s to turn into words, so she listened again.");
                transcribing = false;
                nameOver = false;
                CheckEars(now);
            }
            // A mic that stopped sending, unplugged, lost in sleep or dropped by its driver, is opened again, like Hey Capri's.
            if (chatting && ears.Stalled) ReopenMic(now);
        }

        // What she says when her ears' engine fails on a line. It isn't the mic, and the reason shows on the hearing line.
        internal const string EarsGlitched = "My ears glitched on that. Say it again?";
        internal const string MicStopped = "Your mic keeps cutting out. Pick it again under VOICE, or check it in Windows sound settings.";
        private double micReopened = -100;

        // Twice in a minute is more than a blip, so she says so.
        private void ReopenMic(double now)
        {
            Brain.Log("ears", -1, "Her mic stopped sending or Windows changed the input, so she opened it again.");
            ears.Stop();
            try { if (!testing) ears.Start(); }
            catch (VoiceException error)
            {
                StopChat();
                HearingCaptureFailed(error.Message, true);
                return;
            }
            bool again = now - micReopened < 60;
            micReopened = now;
            if (again) Missed(MicStopped, true);
        }

        private void HeardLevel(double value)
        {
            HearingLevel(value);
            callYou = value;
            double level = local && (preferences.ListenCapri && !pushing || earsShut || transcribing || noiseHold || !earsReady) ? 0 : value;
            pill.SetLevel(level);
            if (docked) DockLevel(level);
        }

        private void GetFreeVoice()
        {
            if (testing || SettingUpVoice || kokoro.Installed || preferences.Silent) return;
            balloonPage = null;
            balloonUpdate = false;
            balloonMainframe = true;
            tray.ShowBalloonTip(8000, "Getting Capri's free voice", Engine.Amount(LocalVoice.PackSize) + ", one time. She'll talk as soon as it's in. Click to watch it download.", ToolTipIcon.Info);
            SetUpFreeVoice(true);
        }

        private bool WakeReady { get { return wakeReadyTest ?? heyCapri.Ready; } }

        // Voice chat has the mic, or they muted it (her mute or Windows'), or pressed her quiet key.
        private bool WakePaused { get { return chatting || micTest != null || ears.Muted || shushed || wakeMicMuted; } }

        // "Hey Capri" listens on its own mic while the setting is on. The first turn-on gets her free voice, which brings
        // sherpa-onnx, if it isn't in, then the wake word's pack. Anything that pauses it closes the mic; while she talks the
        // mic stays open but hears nothing, so her own voice can't wake her.
        private void CheckWake(double now)
        {
            // Her smoke test flips the setting in other checks too (SECURITY's Blackwall preset turns it on), so there it
            // only ever runs inside her own wake checks, and even then never opens the mic or downloads.
            if (testing && !wakeChecks) return;
            if (!preferences.HeyCapri || quitting) { if (wakeOpen) CloseWake(); return; }
            if (!WakeReady) { if (wakeOpen) CloseWake(); GetWake(now); return; }
            if (wakeAskedVoice || wakeTries > 0) { wakeAskedVoice = false; wakeTries = 0; wakeRetryAt = -1; }
            heyCapri.Held = now < voiceUntil || speaker.Busy;
            if (now >= wakeMuteAt) { wakeMuteAt = now + 2; wakeMicMuted = MicMuted(preferences.Mic) == true; wakeHandsFree = HandsFreeMic(preferences.Mic); }
            if (WakePaused) { if (wakeOpen) CloseWake(); return; }
            // A Bluetooth headset's mic would keep the headset on a call, playing everything at call quality, for as long as she
            // listens (a tester, 30 Oct), so she leaves it shut and says why once. Voice chat still uses it.
            if (wakeHandsFree != null)
            {
                if (wakeOpen) CloseWake();
                if (wakeHandsFreeSaid) return;
                wakeHandsFreeSaid = true;
                string why = "I'm not listening for \"Hey Capri\" on your Bluetooth headset: while its mic is open, everything you hear drops to phone-call quality. Pick another mic under VOICE, or use my talk key.";
                if (wakeTell) WakeNote(why, false);
                else mainframe.VoiceNote(why, false);
                return;
            }
            // A mic that stopped sending, unplugged or lost in sleep, is opened again: the picked one, or Windows' default.
            if (wakeOpen && !testing && heyCapri.Stalled) { CloseWake(); wakeRetryAt = now + 2; return; }
            if (!wakeOpen && now >= wakeRetryAt) OpenWake(now);
        }

        private void OpenWake(double now)
        {
            // Loading the spotter takes a few seconds the first time, so it loads off her thread and the mic opens after.
            if (!testing && !heyCapri.Warmed)
            {
                if (wakeWarming) return;
                wakeWarming = true;
                ThreadPool.QueueUserWorkItem(delegate
                {
                    string problem = null;
                    try { heyCapri.Warm(); }
                    catch (Exception error) { problem = Voice.Short(error.Message); }
                    if (problem != null && !wakeMicSaid) Brain.Log("hey capri", -1, problem);
                    Post(delegate
                    {
                        wakeWarming = false;
                        if (!preferences.HeyCapri) { heyCapri.Dispose(); return; }
                        if (problem == null) return;
                        wakeRetryAt = clock.Elapsed.TotalSeconds + 30;
                        if (!wakeMicSaid) { wakeMicSaid = true; WakeNote("I can't listen for \"Hey Capri\": " + problem, true); }
                    });
                });
                return;
            }
            wakeOpens++;
            try { if (!testing) heyCapri.Listen(preferences.Mic); }
            catch (Exception error)
            {
                // A mic that won't open, or a sherpa-onnx that won't run it: said once, tried again every 30 s.
                if (!(error is VoiceException) && !(error is IOException) && !wakeMicSaid) Brain.Log("hey capri", -1, Voice.Short(error.Message));
                wakeRetryAt = now + 30;
                if (!wakeMicSaid) { wakeMicSaid = true; WakeNote("I can't listen for \"Hey Capri\": " + error.Message, true); }
                return;
            }
            wakeOpen = true;
            if (wakeSaid) return;
            wakeSaid = true;
            string on = "Listening for \"Hey Capri\". Nothing leaves your PC until you say it.";
            if (wakeTell) WakeNote(on, false);
            else mainframe.VoiceNote(on, false);
        }

        private void CloseWake()
        {
            wakeOpen = false;
            if (!testing) heyCapri.Pause();
        }

        // Turned on, she gets what it needs and says when she's listening; turned off, the mic closes and any download it started stops.
        private void WakeChanged()
        {
            if (testing && !wakeChecks) return;
            wakeTell = preferences.HeyCapri;
            wakeSaid = wakeMicSaid = wakeHandsFreeSaid = false;
            wakeRetryAt = wakeMuteAt = -1;
            wakeTries = 0;
            if (preferences.HeyCapri) { CheckWake(clock.Elapsed.TotalSeconds); return; }
            heyCapri.Cancel = true;
            if (wakeAskedVoice && SettingUpVoice) kokoro.Cancel = true;
            wakeAskedVoice = false;
            wakeOpen = false;
            if (!testing) heyCapri.Dispose();
            mainframe.VoiceNote("Not listening for \"Hey Capri\".", false);
        }

        private void GetWake(double now)
        {
            if (settingUpWake || SettingUpVoice || now < wakeRetryAt) return;
            if (IntPtr.Size != 8)
            {
                if (!wakeMicSaid) { wakeMicSaid = true; WakeNote("Listening for \"Hey Capri\" needs 64-bit Windows.", true); }
                return;
            }
            if (!(wakeVoiceTest ?? heyCapri.VoiceIn))
            {
                // Her free voice didn't land: she waits, then tries again.
                if (wakeAskedVoice) { wakeAskedVoice = false; wakeRetryAt = now + EarsRetryWait(++wakeTries); return; }
                wakeAskedVoice = true;
                // After a download she says in her bubble when she's listening, for those it was turned on for at startup too.
                wakeTell = true;
                WakeNote("To hear \"Hey Capri\" I need my free voice, so I'm getting it: " + Engine.Amount(LocalVoice.PackSize) + ", then " + Engine.Amount(WakeWord.PackSize) + " more, one time.", false);
                getWakeVoice();
                return;
            }
            wakeAskedVoice = false;
            wakeTell = true;
            WakeNote("Getting what I need to hear \"Hey Capri\": " + Engine.Amount(WakeWord.PackSize) + ", one time. It all stays on your PC.", false);
            getWakePack();
        }

        private void FetchWake()
        {
            settingUpWake = true;
            wakeFetches++;
            heyCapri.Cancel = false;
            ThreadPool.QueueUserWorkItem(delegate
            {
                string problem = null;
                int shown = -1;
                Action<string, long, long> progress = delegate(string text, long done, long total)
                {
                    int percent = total > 0 ? (int)(done * 10 / total) * 10 : 0;
                    if (percent == shown) return;
                    shown = percent;
                    Post(delegate { if (settingUpWake && preferences.HeyCapri) mainframe.VoiceNote("Getting \"Hey Capri\" (" + Engine.Amount(WakeWord.PackSize) + "): " + percent + "%", false); });
                };
                try { heyCapri.Install(progress); heyCapri.Warm(); }
                catch (OperationCanceledException) { problem = "Cancelled."; }
                catch (Exception error) { problem = Voice.Short(error.Message); }
                if (problem != null && problem != "Cancelled.") Brain.Log("hey capri setup", -1, problem);
                Post(delegate
                {
                    settingUpWake = false;
                    if (!preferences.HeyCapri) return;
                    if (problem == null) { wakeTries = 0; wakeRetryAt = -1; return; }
                    int wait = EarsRetryWait(++wakeTries);
                    wakeRetryAt = clock.Elapsed.TotalSeconds + wait;
                    WakeNote("\"Hey Capri\" didn't download: " + problem + " I'll try again in " + (wait < 60 ? wait + " seconds" : wait == 60 ? "a minute" : wait / 60 + " minutes") + ".", true);
                });
            });
        }

        // Her bubble when she's free to show it, and the Mainframe always.
        private void WakeNote(string text, bool problem)
        {
            mainframe.VoiceNote(text, problem);
            if (hidden || chatting || talkState != TalkState.Off) return;
            Say(text);
        }

        // "Hey Capri": she glitches in if she's hidden, opens voice chat the way her talk key does and says she's there.
        private void HeardHeyCapri()
        {
            if (testing && !wakeChecks) return;
            wakeHeard++;
            if (!preferences.HeyCapri || !wakeOpen || WakePaused || quitting || IsDisposed) return;
            CloseWake();
            if (hidden) SetHidden(false);
            ToggleChat();
            if (!chatting) return;
            string line = Lines.Pick(WakeLines);
            // Mid-job she answers beside the job, so it keeps going and what they say next goes to it.
            Job running = job;
            if (local && running != null && working != null) { SayAside(line, running); return; }
            heard = "hey capri";
            box.Prompt = "> you: ";
            // Free voice chat says it in her voice; ElevenLabs voice chat has its own voice, so there it's in her bubble.
            if (local) Answer(++asking, line, TalkState.Talking);
            else Begin(++asking, line, TalkState.Talking, null);
        }

        // One row under VOICE, with the brain setup's dotted bar, for whichever of her free voice, ears and HD voice is downloading.
        private void ShowInstall()
        {
            UpdateHearing();
            bool voicing = SettingUpVoice, hearing = settingUpEars, hd = settingUpHd;
            if (!voicing && !hearing && !hd) { mainframe.HideInstall(); return; }
            long done = (voicing ? voiceGot : 0) + (hearing ? earsGot : 0) + (hd ? hdGot : 0);
            long total = (voicing ? (voiceTotal > 0 ? voiceTotal : LocalVoice.PackSize) : 0) + (hearing ? (earsTotal > 0 ? earsTotal : parakeet.Size) : 0) + (hd ? (hdTotal > 0 ? hdTotal : QwenVoice.PackSize) : 0);
            string what = voicing && hearing ? "Installing the speech model + ears" : voicing ? "Installing the local speech model" : hearing ? "Installing her ears" : "Installing her HD voice";
            mainframe.ShowInstall(hd && (voicing || hearing) ? what + " + HD voice" : what, done, total);
        }

        internal void CancelFreeVoice() { kokoro.Cancel = true; }

        private Machine HdMachine
        {
            get
            {
                if (qwen.Hardware == null) qwen.Hardware = Machine.Read();
                return qwen.Hardware;
            }
        }

        internal bool HdCpu { get { return preferences.HdCpu; } }

        internal void ToggleHdCpu()
        {
            if (AfterLine(ToggleHdCpu)) return;
            preferences.HdCpu = !preferences.HdCpu;
            qwen.CpuOnly = preferences.HdCpu;
            qwen.Stop();
            hdRest = -1;
            SavePreferences();
            ShowVoice();
            if (preferences.HdVoice) WakeHd();
        }

        // HD is opt-in: one download, then it wakes on the graphics card when she talks and hands back to her free voice while games run.
        private void ChooseHd()
        {
            if (AfterLine(ChooseHd)) return;
            preferences.HdVoice = true;
            preferences.ServerVoice = false;
            hdRest = -1;
            SavePreferences();
            ShowVoice();
            if (testing) return;
            if (!qwen.Installed) { SetUpHd(); return; }
            hdTest = voice.Key == null;
            WakeHd();
        }

        private void SetUpHd()
        {
            if (settingUpHd) return;
            settingUpHd = true;
            qwen.Cancel = false;
            hdGot = hdTotal = 0;
            ShowInstall();
            mainframe.VoiceNote("Getting her HD voice (" + Engine.Amount(QwenVoice.PackSize) + "), one time. Pick another free voice to stop.", false);
            ThreadPool.QueueUserWorkItem(delegate
            {
                string problem = null;
                bool cancelled = false;
                Action<string, long, long> progress = delegate(string text, long done, long total)
                {
                    Post(delegate { if (total > 0) { hdGot = done; hdTotal = total; } ShowInstall(); if (text.StartsWith("HD may need ", StringComparison.Ordinal)) mainframe.VoiceNote(text, true); });
                };
                try { qwen.Install(progress); }
                catch (OperationCanceledException) { cancelled = true; }
                catch (Exception error) { problem = Voice.Short(error.Message); }
                if (problem != null) Brain.Log("HD voice setup", -1, problem);
                Post(delegate
                {
                    settingUpHd = false;
                    ShowInstall();
                    ShowVoice();
                    if (cancelled) return;
                    if (problem != null) { mainframe.VoiceNote(problem, true); return; }
                    if (!preferences.HdVoice) return;
                    hdTest = voice.Key == null;
                    WakeHd();
                });
            });
        }

        private void WakeHd()
        {
            if (wakingHd || testing) return;
            wakingHd = true;
            hdUsed = clock.Elapsed.TotalSeconds;
            ThreadPool.QueueUserWorkItem(delegate
            {
                string problem = null;
                bool stopped = false;
                try { qwen.Warm(); }
                catch (OperationCanceledException) { stopped = true; }
                catch (Exception error) { problem = qwen.Failure(error.Message); }
                Post(delegate
                {
                    wakingHd = false;
                    bool test = hdTest;
                    string line = hdLine;
                    hdTest = false;
                    hdLine = null;
                    if (stopped) return;
                    if (!preferences.HdVoice) { qwen.Stop(); return; }
                    if (problem != null) HdTrouble(problem, qwen.NewProblem(problem));
                    if (line != null) CheckVoice(line, true);
                    else if (test && problem == null) voiceCheckDue = true;
                });
            });
        }

        private Func<string, byte[]> Hd(Func<string, byte[]> fallback)
        {
            if (!preferences.HdVoice || preferences.Silent || !qwen.Installed || clock.Elapsed.TotalSeconds < hdRest) return fallback;
            if (HdStepsAside()) { qwen.Stop(); return fallback; }
            hdUsed = clock.Elapsed.TotalSeconds;
            Action<string> trouble = delegate(string problem) { Post(delegate { HdTrouble(problem); }); };
            if (qwen.Awake) return qwen.Or(fallback, trouble);
            WakeHd();
            // A line with no free voice to hand on to, like one of a job's, still doesn't wait.
            return fallback == null ? null : qwen.Waiting(fallback, trouble, delegate { return wakingHd; });
        }

        // Out of memory, her HD voice rests 10 minutes so a game can have the graphics card. Anything else rests it a minute (2 Nov).
        internal static double HdBreak(string problem) { return (problem ?? "").StartsWith(QwenVoice.MemoryFull, StringComparison.Ordinal) ? HdRest : HdShortRest; }

        private void HdTrouble(string problem, bool tell = true)
        {
            qwen.Stop();
            hdRest = clock.Elapsed.TotalSeconds + HdBreak(problem);
            if (!tell) return;
            if (!testing) Brain.Log("HD voice", -1, problem);
            mainframe.VoiceNote(problem, true);
        }

        // Her HD voice gives the graphics card back after 10 quiet minutes, and while a game is full screen if Free voice in games is on.
        private void CheckHd(double now)
        {
            if (now - hdChecked < 3) return;
            hdChecked = now;
            if (wakingHd || !qwen.Awake) return;
            if (!preferences.HdVoice || preferences.Silent || now - hdUsed > HdRest || HdStepsAside()) qwen.Stop();
        }

        // Only with Free voice in games on does a full-screen game or video send her back to her free voice.
        private bool HdStepsAside() { return preferences.HdGameRest && Native.Gaming(); }

        internal void ChooseVoiceStyle(string name)
        {
            if (AfterLine(delegate { ChooseVoiceStyle(name); })) return;
            if (name == QwenVoice.Style) { ChooseHd(); return; }
            if (preferences.HdVoice || settingUpHd)
            {
                preferences.HdVoice = false;
                qwen.Cancel = true;
                qwen.Stop();
            }
            kokoro.Style = LocalVoice.Find(name);
            preferences.VoiceStyle = kokoro.Style == LocalVoice.Styles[0] ? null : kokoro.Style.Name;
            preferences.ServerVoice = false;
            SavePreferences();
            ShowVoice();
            if (voice.Key == null && kokoro.Installed) TestVoice();
        }

        internal const string TestLine = "Voice link online. Miss me, choom?";
        internal const string SilentNote = "Her voice is OFF. Pick another row under VOICE to hear her.";

        internal void TestMic()
        {
            if (micTest != null) { StopMicTest(true); return; }
            if (wakeOpen) CloseWake();
            Ears input = ears.Listening ? ears : new Ears();
            micTest = input;
            input.Chosen = preferences.Mic;
            micTestUntil = clock.Elapsed.TotalSeconds + 10;
            micTestPeak = 0;
            micTestWindowsMuted = null;
            micTestMuteAt = clock.Elapsed.TotalSeconds + 2;
            AskMicTestMute(input);
            micTestLevel = delegate(double value)
            {
                Post(delegate
                {
                    if (micTest != input) return;
                    micTestPeak = Math.Max(micTestPeak, value);
                    mainframe.ShowMicTest(true, value, input.Muted || micTestWindowsMuted == true);
                });
            };
            input.Level += micTestLevel;
            if (input != ears) input.Changed += delegate(string problem) { OnUi(delegate { HearingCaptureFailed(problem, false); }); };
            mainframe.ShowMicTest(true, 0, input.Muted);
            try { if (!testing) input.Start(); }
            catch (VoiceException error) { StopMicTest(false); HearingCaptureFailed(error.Message, false); mainframe.VoiceNote(error.Message, true); }
        }

        private void AskMicTestMute(Ears input)
        {
            Func<string, bool?> ask = MicMuted;
            // Smoke tests never read this PC's real mic; a check that wants a Windows mute stands in its own answer.
            if (micTestMuteAsking || (testing && ask == (Func<string, bool?>)Mics.Muted)) return;
            micTestMuteAsking = true;
            string chosen = input.Chosen;
            ThreadPool.QueueUserWorkItem(delegate
            {
                bool? muted = null;
                try { muted = ask(chosen); }
                catch (Exception error) { Brain.Log("ears", -1, "Couldn't ask Windows if the mic is muted: " + error.Message); }
                Post(delegate { micTestMuteAsking = false; if (micTest == input) micTestWindowsMuted = muted; });
            });
        }

        private void CheckMicTest(double now)
        {
            if (micTest == null) return;
            if (now >= micTestMuteAt) { micTestMuteAt = now + 2; AskMicTestMute(micTest); }
            if (micTest.Stalled)
            {
                StopMicTest(false);
                mainframe.VoiceNote("Your mic stopped or changed during the test. Pick it under VOICE and test again.", true);
            }
            else if (now >= micTestUntil) StopMicTest(true);
        }

        private void StopMicTest(bool report)
        {
            Ears input = micTest;
            if (input == null) return;
            micTest = null;
            input.Level -= micTestLevel;
            micTestLevel = null;
            if (input != ears) input.Dispose();
            mainframe.ShowMicTest(false, 0, false);
            if (!report) return;
            bool windowsMuted = !input.Muted && micTestWindowsMuted == true, muted = input.Muted || windowsMuted;
            hearingTestSilent = micTestPeak == 0 && !muted;
            hearingWindowsMuted = windowsMuted;
            hearingSilent = false;
            hearingQuiet = micTestPeak > 0 && micTestPeak < QuietWake && !muted;
            hearingCaptureProblem = null;
            UpdateHearing();
            string result = input.Muted ? "Your mic is muted. Unmute it to test." : windowsMuted ? MicMutedInWindows : micTestPeak == 0 ? MicSilent : micTestPeak < QuietWake ? "Your mic is very quiet. Raise its input volume in Windows sound settings." : "Mic test finished. Sound is reaching Capri.";
            mainframe.VoiceNote(result, muted || micTestPeak < QuietWake);
            Brain.Log("ears", -1, "Mic test: peak RMS " + (micTestPeak <= 0 ? "silence" : (20 * Math.Log10(micTestPeak)).ToString("0.0") + " dBFS") + ". " + result);
        }

        // A voice preview her settings tool asked for, held until the reply it came with is over: styleAsked is the request it came
        // with, and styleReply how many replies voice chat had sent then, out of chatReplies.
        private bool styleCheckDue;
        private int styleAsked, styleReply, chatReplies;
        private Agent styleAgent;

        // Whether the reply a settings change came with is over, so playing her voice or changing her ears won't cut it off: the
        // voice chat that asked has sent the tool's result and replied since, and she isn't thinking, talking or working.
        private bool SettingsReplyDone(Agent remote, int replies)
        {
            if (remote != null && remote == agent && (remote.ToolBusy || chatReplies <= replies)) return false;
            return (talkState == TalkState.Off || talkState == TalkState.Dormant || talkState == TalkState.Online && replyDone >= 0)
                && working == null && !speaker.Busy && speech == null && answerVoice != asking && hdSpeaking != asking && clock.Elapsed.TotalSeconds >= voiceUntil;
        }

        // Her voice landed by itself, so the check that says so waits its turn: it would cancel anything they've just asked. A
        // preview her settings tool asked for waits for the reply it came with, and is dropped when they ask something else first.
        private void CheckVoiceReady()
        {
            if (styleCheckDue && styleAsked != asking) styleCheckDue = false;
            if (styleCheckDue && SettingsReplyDone(styleAgent, styleReply))
            {
                styleCheckDue = false;
                HearVoiceStyle();
                return;
            }
            if (!voiceCheckDue || talkState != TalkState.Off || MidJob(job)) return;
            voiceCheckDue = false;
            TestVoice();
        }

        internal void TestVoice()
        {
            if (PreviewAfterLine(TestVoice)) return;
            if (preferences.Silent) { mainframe.VoiceNote(SilentNote, true); return; }
            if (voice.Key == null && Speak == null && !kokoro.Installed && !preferences.ServerVoice) { mainframe.VoiceNote("Get her free voice, or paste an ElevenLabs key.", true); return; }
            if (voice.Key != null && voice.VoiceId == null && Speak == null) { mainframe.VoiceNote("Paste your Voice ID first.", true); return; }
            CheckVoice(TestLine, false);
        }

        internal string ServerUrl { get { return server.Url; } }

        internal string ServerApi { get { return server.Api; } }

        // Whether they've picked one before, so its panel shows that rather than a ready-made choice.
        internal bool ServerSaved { get { return preferences.ServerUrl != null; } }

        internal string ServerModel { get { return server.Model; } }

        internal string ServerSpeaker { get { return server.Speaker; } }

        internal string ServerKeyTail { get { return server.Key == null ? null : Voice.Tail(server.Key); } }

        // A model file's folder loses any quotes it was pasted with.
        private static string ServerAddress(string url, string api) { return api == VoiceServer.Files ? ModelFile.Clean(url) : Typed(url) ?? (api == VoiceServer.Fish ? VoiceServer.FishCloud : VoiceServer.Address); }

        // Their own voice server or voice model file under CUSTOM LOCAL, or Fish Audio or OpenAI under CLOUD VOICE: what was kept
        // for that row comes back, HD and ElevenLabs step aside, and she says her check line through it.
        internal void UseVoiceServer(string url, string model, string speaker, string key, string api)
        {
            if (AfterLine(delegate { UseVoiceServer(url, model, speaker, key, api); })) return;
            api = VoiceServer.Known(api);
            string address = ServerAddress(url, api);
            Bring(Cloudy(address, api));
            // A blank key box keeps the key that's saved, for the server it was saved for. A key never goes to another server,
            // and a model file takes none.
            string typed = api == VoiceServer.Files ? null : Typed(Regex.Replace(key ?? "", @"\s+", ""));
            lock (server.Changing)
            {
                bool same = VoiceServer.Same(server.Url, server.Api, address, api);
                preferences.ServerUrl = server.Url = address;
                server.Api = api;
                preferences.ServerApi = api == VoiceServer.OpenAi ? null : api;
                preferences.ServerModel = server.Model = Typed(model);
                preferences.ServerSpeaker = server.Speaker = Typed(speaker);
                if (typed != null)
                {
                    server.Key = typed;
                    preferences.ServerKey = Voice.Protect(typed);
                }
                else if (!same)
                {
                    server.Key = null;
                    preferences.ServerKey = null;
                }
            }
            if (preferences.HdVoice || settingUpHd)
            {
                preferences.HdVoice = false;
                qwen.Cancel = true;
                qwen.Stop();
            }
            preferences.ServerVoice = true;
            if (Cloudy(address, api)) preferences.CloudVoice = VoiceServer.CloudName(api);
            bool wasSilent = preferences.Silent;
            if (!keepVoiceOff) preferences.Silent = false;
            if (wasSilent || (voice.Key != null && !preferences.Quiet))
            {
                preferences.Quiet = true;
                voice.Stop();
            }
            LeaveCall();
            SavePreferences();
            // A model file runs on her free voice's engine, and her free voice fills in for a server that's down.
            if (wasSilent || api == VoiceServer.Files) GetFreeVoice();
            mainframe.Sync();
            ShowVoice();
            if (!preferences.Silent) TestVoice();
        }

        // Forget in its panel drops the key saved for that server, in use or kept aside.
        internal void ForgetServerKey(string url, string api)
        {
            if (VoiceServer.Same(server.Url, server.Api, url, VoiceServer.Known(api)))
            {
                server.Key = null;
                preferences.ServerKey = null;
            }
            else if (preferences.AsideUrl != null && VoiceServer.Same(preferences.AsideUrl, VoiceServer.Known(preferences.AsideApi), url, VoiceServer.Known(api))) preferences.AsideKey = null;
            SavePreferences();
        }

        // The key saved for this server, in use or kept aside.
        private string SavedKey(string url, string api)
        {
            if (VoiceServer.Same(server.Url, server.Api, url, api)) return server.Key;
            if (preferences.AsideUrl != null && VoiceServer.Same(preferences.AsideUrl, VoiceServer.Known(preferences.AsideApi), url, api)) return Voice.Unprotect(preferences.AsideKey);
            return null;
        }

        private void LoadServer()
        {
            lock (server.Changing)
            {
                server.Url = preferences.ServerUrl ?? VoiceServer.Address;
                server.Api = VoiceServer.Known(preferences.ServerApi);
                server.Model = preferences.ServerModel;
                server.Speaker = preferences.ServerSpeaker;
                server.Key = Voice.Unprotect(preferences.ServerKey);
            }
        }

        private static bool Cloudy(string url, string api) { return url != null && VoiceServer.InCloud(url, api); }

        internal bool ServerPicked { get { return preferences.ServerVoice; } }

        internal bool ServerInCloud { get { return Cloudy(preferences.ServerUrl, preferences.ServerApi); } }

        internal string ServerCloudName { get { return VoiceServer.CloudName(preferences.ServerApi); } }

        internal const string ElevenLabs = "ElevenLabs";

        // The service CLOUD VOICE's menu shows while another row is in use: the one used there last. Before they've used one in
        // this version, ElevenLabs if its key is saved, the Fish Audio or OpenAI voice they set up, or else Fish Audio, whose
        // free tier needs no credits.
        internal string CloudChoice
        {
            get
            {
                if (preferences.CloudVoice != null) return preferences.CloudVoice;
                if (voice.Key != null) return ElevenLabs;
                string api, url, model, speaker, tail;
                return VoiceServer.CloudName(SavedServer(true, out api, out url, out model, out speaker, out tail) ? api : VoiceServer.Fish);
            }
        }

        // Whether they've set up a voice model of this kind, in use or kept aside; for the cloud, from this API when it's given.
        internal bool HasServer(bool cloud, string api)
        {
            return Fits(preferences.ServerUrl, preferences.ServerApi, cloud, api) || Fits(preferences.AsideUrl, preferences.AsideApi, cloud, api);
        }

        private static bool Fits(string url, string api, bool cloud, string wanted)
        {
            return url != null && Cloudy(url, api) == cloud && (wanted == null || VoiceServer.Known(api) == wanted);
        }

        // The voice model of this kind they set up, for its panel.
        internal bool SavedServer(bool cloud, out string api, out string url, out string model, out string speaker, out string tail)
        {
            bool inUse = Fits(preferences.ServerUrl, preferences.ServerApi, cloud, null);
            bool aside = !inUse && Fits(preferences.AsideUrl, preferences.AsideApi, cloud, null);
            api = VoiceServer.Known(inUse ? preferences.ServerApi : preferences.AsideApi);
            url = inUse ? preferences.ServerUrl : aside ? preferences.AsideUrl : null;
            model = inUse ? preferences.ServerModel : aside ? preferences.AsideModel : null;
            speaker = inUse ? preferences.ServerSpeaker : aside ? preferences.AsideSpeaker : null;
            string key = inUse ? server.Key : aside ? Voice.Unprotect(preferences.AsideKey) : null;
            tail = key == null ? null : Voice.Tail(key);
            return inUse || aside;
        }

        // Puts their voice model of this kind in use, swapping it with the other kind kept aside. With none of this kind, the
        // one in use goes aside.
        private void Bring(bool cloud)
        {
            bool held = preferences.ServerUrl != null;
            if (held ? Cloudy(preferences.ServerUrl, preferences.ServerApi) == cloud : !Fits(preferences.AsideUrl, preferences.AsideApi, cloud, null)) return;
            string url = preferences.ServerUrl, api = preferences.ServerApi, model = preferences.ServerModel, speaker = preferences.ServerSpeaker, key = preferences.ServerKey;
            preferences.ServerUrl = preferences.AsideUrl;
            preferences.ServerApi = preferences.AsideApi;
            preferences.ServerModel = preferences.AsideModel;
            preferences.ServerSpeaker = preferences.AsideSpeaker;
            preferences.ServerKey = preferences.AsideKey;
            preferences.AsideUrl = url;
            preferences.AsideApi = api;
            preferences.AsideModel = model;
            preferences.AsideSpeaker = speaker;
            preferences.AsideKey = key;
            LoadServer();
        }

        // CUSTOM LOCAL or CLOUD VOICE with one already set up: back to it, with her check line through it.
        internal void UseSavedServer(bool cloud)
        {
            Bring(cloud);
            if (preferences.ServerUrl == null) return;
            UseVoiceServer(preferences.ServerUrl, preferences.ServerModel, preferences.ServerSpeaker, null, preferences.ServerApi);
        }

        // PREBUILT LOCAL: her own voices. Their voice models stay saved for the other rows.
        internal void UsePrebuilt()
        {
            bool served = preferences.ServerVoice;
            if (served)
            {
                preferences.ServerVoice = false;
                SavePreferences();
            }
            bool wasOn = !preferences.Silent && (voice.Key == null || preferences.Quiet);
            ChooseVoiceTier(false);
            if (served && wasOn && (kokoro.Installed || (preferences.HdVoice && qwen.Installed))) TestVoice();
        }

        private static string Typed(string text)
        {
            text = (text ?? "").Trim();
            return text.Length == 0 ? null : text;
        }

        // A new Fish Audio voice from a clip they pick, with the key they typed or the one saved for Fish Audio. `done` gets its ID.
        internal void MakeFishVoice(string url, string key, string clip, Action<string, string> done)
        {
            string address = ServerAddress(url, VoiceServer.Fish);
            string sent = Typed(Regex.Replace(key ?? "", @"\s+", "")) ?? SavedKey(address, VoiceServer.Fish);
            ThreadPool.QueueUserWorkItem(delegate
            {
                string id = null, problem = null;
                try { id = VoiceServer.MakeFishVoice(address, sent, clip); }
                catch (VoiceException error) { problem = error.Message; }
                catch (Exception error) { problem = Voice.Short("Couldn't make your Fish Audio voice: " + error.Message); }
                Post(delegate { done(id, problem); });
            });
        }

        // Their own Fish Audio voices for its panel's Voice menu, with the key they typed or the one saved for Fish Audio.
        internal void FishVoices(string url, string key, Action<System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, string>>, string> done)
        {
            string address = ServerAddress(url, VoiceServer.Fish);
            string sent = Typed(Regex.Replace(key ?? "", @"\s+", "")) ?? SavedKey(address, VoiceServer.Fish);
            ThreadPool.QueueUserWorkItem(delegate
            {
                System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string, string>> found = null;
                string problem = null;
                try { found = VoiceServer.FishVoices(address, sent); }
                catch (VoiceException error) { problem = error.Message; }
                catch (Exception error) { problem = Voice.Short("Couldn't list your Fish Audio voices: " + error.Message); }
                Post(delegate { done(found, problem); });
            });
        }

        // Test in their voice server's panel: she says her check line through what they typed, before it's saved, or `done` says what went wrong.
        internal void TestVoiceServer(string url, string model, string speaker, string key, string api, Action<string, bool> done)
        {
            VoiceServer trial = new VoiceServer();
            trial.Api = VoiceServer.Known(api);
            trial.Url = ServerAddress(url, trial.Api);
            trial.Model = Typed(model);
            trial.Speaker = Typed(speaker);
            trial.Key = trial.Api == VoiceServer.Files ? null : Typed(Regex.Replace(key ?? "", @"\s+", "")) ?? SavedKey(trial.Url, trial.Api);
            string label = VoiceServer.Label(trial.Url, trial.Api);
            ThreadPool.QueueUserWorkItem(delegate
            {
                byte[] wav = null;
                string problem = null;
                Stopwatch took = Stopwatch.StartNew();
                try { wav = trial.Speak(Voice.Spoken(TestLine)); }
                catch (VoiceException error) { problem = error.Message; }
                catch (Exception error) { problem = Voice.Short("Your voice server glitched: " + error.Message); }
                double seconds = took.Elapsed.TotalSeconds;
                Post(delegate
                {
                    if (problem != null) { done(problem, true); return; }
                    done("It works. " + label + " said that in " + seconds.ToString("0.0") + " s.", false);
                    if (preferences.Silent) return;
                    CheckVoice(TestLine, false, wav);
                });
            });
        }

        // Their voice server says her lines, and her free voice says any it can't. What went wrong shows once under VOICE.
        private Func<string, byte[]> Served(Func<string, byte[]> fallback)
        {
            return server.Or(fallback, delegate(string problem) { Post(delegate { ServerTrouble(problem); }); });
        }

        private void ServerTrouble(string problem)
        {
            if (!testing) Brain.Log("voice server", -1, problem);
            mainframe.VoiceNote(problem, true);
        }

        internal const string StyleLine = "How do I sound now, choom?";
        internal const string StyleSilent = "My voice is OFF, choom. Pick PREBUILT LOCAL to hear that.";
        internal const string StyleMissing = "Get my free voice under VOICE to hear that, choom.";

        // Letting go of her pitch, speed, robot or glitch slider: she says a line in the voice she's using, so they hear it.
        // ElevenLabs makes the line once; after that its audio is restyled here, so dragging around spends no more credits.
        internal void HearVoiceStyle()
        {
            if (PreviewAfterLine(HearVoiceStyle)) return;
            bool paid = !preferences.Quiet && !voiceBroke && (Speak != null || voice.Ready);
            bool free = FreeSpeak != null || kokoro.Installed || (preferences.HdVoice && qwen.Installed) || preferences.ServerVoice;
            string line = preferences.Silent ? StyleSilent : paid || free ? StyleLine : StyleMissing;
            if (line == StyleLine && SpeaksHd && WakeFor(line)) return;
            CheckVoice(line, false);
        }

        private void CheckVoice(string line, bool quiet, byte[] prepared = null)
        {
            if (PreviewAfterLine(delegate { CheckVoice(line, quiet, prepared); })) return;
            if (hidden) SetHidden(false);
            brain.Cancel();
            heard = "voice check";
            box.Prompt = "> sys: ";
            if (prepared == null) Answer(++asking, line, TalkState.Talking, quiet);
            else Begin(++asking, line, TalkState.Talking, prepared);
        }

        internal const string HdWaking = "One sec, waking my HD voice.";

        // Her HD voice sleeps after 10 quiet minutes. Rather than say a voice check in the free voice standing in for it,
        // she wakes it and says the line once it's up.
        private bool WakeFor(string line)
        {
            if (PreviewAfterLine(delegate { if (!WakeFor(line)) CheckVoice(line, true); })) return true;
            if (testing || !preferences.HdVoice || preferences.Silent || !qwen.Installed || qwen.Awake || HdStepsAside() || clock.Elapsed.TotalSeconds < hdRest) return false;
            hdLine = line;
            WakeHd();
            if (hidden) SetHidden(false);
            brain.Cancel();
            voice.Stop();
            heard = "voice check";
            box.Prompt = "> sys: ";
            Begin(++asking, HdWaking, TalkState.Talking, null);
            return true;
        }

        internal const string YourLine = "Got it. I'll talk like you now, choom.";

        // Their own voice: a clip they pick is read, checked and cut on a worker thread, then saved where her HD voice looks for it.
        internal void UseYourVoice(string path)
        {
            mainframe.VoiceNote("Reading your clip...", false);
            ThreadPool.QueueUserWorkItem(delegate
            {
                string problem;
                short[] clip = YourVoice.Prepare(path, out problem);
                Post(delegate { if (clip == null) mainframe.VoiceNote(problem, true); else KeepYourVoice(clip); });
            });
        }

        internal void KeepYourVoice(short[] clip)
        {
            string problem = null;
            try { YourVoice.Save(clip, qwen.Folder); }
            catch (IOException error) { problem = error.Message; }
            catch (UnauthorizedAccessException error) { problem = error.Message; }
            if (problem != null) { mainframe.VoiceNote(Voice.Short("Couldn't save your voice: " + problem), true); return; }
            HearClip(YourLine);
        }

        internal void UseKeptVoice()
        {
            try { YourVoice.Unshelve(qwen.Folder); }
            catch (IOException error) { mainframe.VoiceNote(Voice.Short("Couldn't switch to your voice: " + error.Message), true); return; }
            HearClip(YourLine);
        }

        // Her HD voice reads the clip on its next line, so she says one, waking it first if it's asleep. With HD off, picking it sets it up.
        private void HearClip(string line)
        {
            ForgetReactionVoices();
            if (!preferences.HdVoice) { ChooseVoiceStyle(QwenVoice.Style); return; }
            ShowVoice();
            if (!testing && !qwen.Installed) return;
            if (!WakeFor(line)) CheckVoice(line, true);
        }

        private void ListVoices(string key, bool connecting)
        {
            mainframe.VoiceNote(connecting ? "Checking key..." : "Loading voices...", false);
            ThreadPool.QueueUserWorkItem(delegate
            {
                VoiceListing found = null;
                string problem = null;
                int status = 0;
                try { found = Voice.Fetch(key); }
                catch (VoiceException error) { problem = error.Message; status = error.Status; }
                catch (Exception error) { problem = Voice.Short("Couldn't read your ElevenLabs voices: " + error.Message); }
                Post(delegate
                {
                    if (connecting && status == 401) { mainframe.VoiceNote(Voice.Unsaved(problem), true); return; }
                    if (connecting) { voice.Key = key; voiceBroke = false; preferences.VoiceKey = Voice.Protect(key); SavePreferences(); }
                    if (voice.Key != key) return;
                    if (found != null) voices = found;
                    ShowVoice();
                    if (problem != null) mainframe.VoiceNote(problem, true);
                });
            });
        }

        private void ShowVoice(bool note = true)
        {
            bool ready = kokoro.Installed;
            mainframe.ShowVoice(voice.Key == null ? null : Voice.Tail(voice.Key), voice.VoiceId, voice.Model, voices);
            bool hd = preferences.HdVoice, yours = YourVoice.Active(qwen.Folder), served = preferences.ServerVoice;
            mainframe.ShowFree(ready, hd ? QwenVoice.Style : served ? VoiceServer.Style : kokoro.Style.Name, SettingUpVoice, HdMachine, yours, YourVoice.Saved(qwen.Folder), served && !hd ? VoiceServer.Label(server.Url, server.Api) : null);
            UpdateHearing();
            if (!note) return;
            if (hd && voice.Key == null && !served && !settingUpHd && (preferences.HdCpu || QwenVoice.Warn(HdMachine))) { mainframe.VoiceNote(preferences.HdCpu ? "HD on your CPU: slower, and 16 GB of RAM is best." : QwenVoice.Advice(HdMachine), !preferences.HdCpu || HdMachine.Ram < QwenVoice.RamRecommended); return; }
            if (chatting && local && preferences.ListenCapri && earsReady) { mainframe.VoiceNote(ears.Muted ? "Listening for Capri; mic muted." : LocalListening, false); return; }
            string name = "custom voice";
            if (voices != null) foreach (VoiceEntry entry in voices.Voices) if (entry.Id == voice.VoiceId && entry.Name != null) name = entry.Name;
            mainframe.VoiceNote(voice.Key == null || (served && preferences.Quiet) ? (served ? (server.Api == VoiceServer.Files ? "Voice model " + VoiceServer.Label(server.Url, server.Api) + ", on your PC." : VoiceServer.Name(server.Url, server.Api) + " at " + VoiceServer.Where(server.Url, server.Api) + ".") + (ready ? " Her free voice fills in if it's down." : "") : hd && settingUpHd ? "Getting her HD voice (" + Engine.Amount(QwenVoice.PackSize) + "), one time. Pick another free voice to stop." : hd && qwen.Installed ? (yours ? "HD voice from your clip, on your graphics card. Games get her free voice." : "HD voice on your graphics card. Games get her free voice.") : ready ? (yours ? "Free voice, runs on your PC. Your voice only works with HD." : "Free voice, runs on your PC.") : SettingUpVoice ? "This may take some time. For a better sounding, faster voice, get an API key." : "Get her free voice (" + Engine.Amount(LocalVoice.PackSize) + "), or pick CLOUD VOICE.") : voice.VoiceId == null ? "Needs your Voice ID." : "ElevenLabs · " + name, false);
        }

        private float TalkScale()
        {
            int dpi = 96;
            try { if (IsHandleCreated) dpi = Native.GetDpiForWindow(Handle); } catch (EntryPointNotFoundException) { }
            return Math.Max(1f, dpi / 96f);
        }

        private Point Head() { return new Point(anchor.X + PaddingSize + (int)(preferences.Size * (facingLeft ? 0.48f : 0.52f)), anchor.Y + PaddingSize - 4); }

        private Point Feet() { return new Point(anchor.X + PaddingSize + (int)(preferences.Size * 0.58f), anchor.Y + PaddingSize + (int)(preferences.Size * 0.99f)); }

        // A test sound's pitch in hertz: the first strong peak of its autocorrelation between 60 and 1000 Hz.
        private static double Fundamental(short[] sound, int rate)
        {
            int from = sound.Length / 4, span = Math.Min(rate / 5, sound.Length / 2), least = rate / 1000, most = rate / 60;
            double[] match = new double[most + 2];
            double strongest = 0;
            for (int lag = least; lag <= most + 1; lag++)
            {
                for (int i = from; i < from + span && i + lag < sound.Length; i++) match[lag] += (double)sound[i] * sound[i + lag];
                if (lag <= most) strongest = Math.Max(strongest, match[lag]);
            }
            for (int lag = least + 1; lag <= most; lag++)
                if (match[lag] >= 0.8 * strongest && match[lag] >= match[lag - 1] && match[lag] >= match[lag + 1]) return (double)rate / lag;
            return 0;
        }

        private static string FakeServer(string[] replies, System.Collections.Generic.List<string> asked, out System.Net.Sockets.TcpListener listener, int status = 200, int delay = 0, bool drip = false, int missing = 0, string contentType = "application/json", string headers = "", ManualResetEvent release = null, int port = 0)
        {
            System.Net.Sockets.TcpListener server = new System.Net.Sockets.TcpListener(IPAddress.Loopback, port);
            server.Start();
            listener = server;
            ThreadPool.QueueUserWorkItem(delegate
            {
                try
                {
                    foreach (string reply in replies)
                        using (System.Net.Sockets.TcpClient client = server.AcceptTcpClient())
                        using (System.Net.Sockets.NetworkStream stream = client.GetStream())
                        {
                            MemoryStream got = new MemoryStream();
                            byte[] buffer = new byte[8192];
                            string text = "";
                            while (true)
                            {
                                int read = stream.Read(buffer, 0, buffer.Length);
                                if (read <= 0) break;
                                got.Write(buffer, 0, read);
                                text = System.Text.Encoding.UTF8.GetString(got.ToArray());
                                int end = text.IndexOf("\r\n\r\n", StringComparison.Ordinal);
                                if (end < 0) continue;
                                System.Text.RegularExpressions.Match length = System.Text.RegularExpressions.Regex.Match(text, @"Content-Length:\s*(\d+)", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                                if (got.Length >= end + 4 + (length.Success ? int.Parse(length.Groups[1].Value) : 0)) break;
                            }
                            lock (asked) asked.Add(text);
                            if (release != null && !release.WaitOne(15000)) throw new TimeoutException("The fake model list stayed held.");
                            // A reply starting "!400 " goes out with that status instead.
                            System.Text.RegularExpressions.Match coded = System.Text.RegularExpressions.Regex.Match(reply, @"^!(\d{3}) ");
                            byte[] answer = System.Text.Encoding.UTF8.GetBytes(coded.Success ? reply.Substring(coded.Length) : reply);
                            if (!drip && delay > 0) Thread.Sleep(delay);
                            byte[] head = System.Text.Encoding.ASCII.GetBytes("HTTP/1.1 " + (coded.Success ? coded.Groups[1].Value : status.ToString()) + " Reply\r\nContent-Type: " + contentType + "\r\nContent-Length: " + (answer.Length + missing) + "\r\nConnection: close\r\n" + headers + "\r\n");
                            stream.Write(head, 0, head.Length);
                            if (!drip) stream.Write(answer, 0, answer.Length);
                            else foreach (byte part in answer) { stream.WriteByte(part); Thread.Sleep(delay); }
                        }
                }
                catch (Exception) { }
            });
            return "http://127.0.0.1:" + ((IPEndPoint)server.LocalEndpoint).Port;
        }

        private bool Uncovered(Point screen) { return Native.GetAncestor(Native.WindowFromPoint(new Native.Point(screen.X, screen.Y)), 2) == Handle; }

        // Seconds the pill shows when voice chat starts or stops or the mic is muted or unmuted, so you see the change.
        private const double PillPop = 3;

        // Only the cursor on her or on the pill, or the open typer, keeps it up. Her replies and voice chat don't hold it there,
        // including while she's sitting on a window, and over full screen the cursor doesn't either.
        // While their mic is muted in voice chat her pill stays up with its red MUTED, so muting with the key is never silent
        // (Lachy, 2 Nov: "it was like silently muting").
        private bool PillHeld(bool hovered) { return hovered || typer.Visible || (chatting && ears.Muted); }

        private void UpdatePill(double now)
        {
            if (!IsHandleCreated) return;
            bool allowed = !hidden && !riding && !onPanel && !dragging && !pressed && !falling;
            Point cursor = Cursor.Position;
            Point inside = PointToClient(cursor);
            bool near = frame != null && inside.X >= 0 && inside.Y >= 0 && inside.X < Width && inside.Y < Height && Solid(inside, true);
            if (allowed && PillHeld(near || (pill.Visible && pill.Bounds.Contains(cursor)))) pillUntil = Math.Max(pillUntil, now + 1.5);
            if (!allowed || now > pillUntil) { if (pill.Visible) pill.Hide(); return; }
            float s = TalkScale();
            Point feet = Feet();
            Rectangle area = Screen.FromPoint(feet).WorkingArea;
            int top = Math.Min(feet.Y + (int)(2 * s), area.Bottom - TalkPill.Measure(s).Height - 2);
            pill.Motion = preferences.Motion;
            pill.Place(new Point(feet.X - (int)(4 * s), top), s);
        }

        private void OpenTyper()
        {
            followUp.Drop();
            StopExplore();
            if (typer.Visible) { typer.Hide(); return; }
            WakeRest(!SleepBusy);
            float s = TalkScale();
            if (docked) typer.Open(GameHud.Bounds.Location, GameHud.Bounds.Location, Screen.FromRectangle(GameHud.Bounds).WorkingArea, s, GameHud.Bounds);
            else typer.Open(Head(), new Point(Feet().X, Feet().Y + (int)(44 * s)), Screen.FromPoint(Head()).WorkingArea, s, box.Visible ? box.PanelOnScreen : Rectangle.Empty);
            pillUntil = clock.Elapsed.TotalSeconds + 1.5;
        }

        private void ToggleChat()
        {
            if (chatting) { earsClosed = preferences.ListenCapri; StopChat(); return; }
            earsClosed = false;
            WakeRest(true);
            // Listen for Capri needs her own ears; otherwise voice chat follows the VOICE pick.
            if (CallModeOn || ChatUsesEars(preferences.ListenCapri, preferences.Quiet, preferences.Silent, voice.Key != null)) { StartLocal(); return; }
            if ((preferences.Quiet || preferences.Silent) && voice.Key != null)
            {
                heard = "(voice)";
                box.Prompt = "> you: ";
                Answer(++asking, ElevenOffChat, TalkState.Talking, true);
                return;
            }
            if (voice.Key == null || voice.VoiceId == null)
            {
                heard = "(voice)";
                box.Prompt = "> you: ";
                Answer(++asking, voice.Key == null ? NeedsVoiceKey : "Voice chat needs my Voice ID, choom. Right-click me, open Capri Mainframe and pick a voice in the Voice ID box under VOICE. Type to me for now.", TalkState.Talking);
                mainframe.Restore();
                return;
            }
            chatting = true;
            ears.Muted = false;
            hearingSaid = null;
            hearingCaptureProblem = hearingSpeechProblem = null;
            ResetHearingSignal();
            RefreshHearingDevices();
            if (!testing && !muteKey) muteKey = ByMouse(preferences.MuteVk) || Native.RegisterHotKey(Handle, MuteKeyId, preferences.MuteMods | 0x4000, preferences.MuteVk);
            pill.SetChat(true, false);
            pillUntil = clock.Elapsed.TotalSeconds + PillPop;
            brain.Cancel();
            CloseTalk();
            OpenLink();
        }

        private void StartLocal(bool credits = false)
        {
            StopMicTest(false);
            hearingSaid = null;
            hearingCaptureProblem = hearingSpeechProblem = null;
            ResetHearingSignal();
            RefreshHearingDevices();
            WakeRest(true);
            chatTicket++;
            chatting = true;
            local = true;
            earsReady = false;
            earsShut = true;
            earsLead = credits ? "Out of ElevenLabs credits. " : "";
            earsWarned = -10;
            earsFailures = 0;
            earsRetryAt = -1;
            ears.Muted = false;
            if (!testing && !muteKey) muteKey = ByMouse(preferences.MuteVk) || Native.RegisterHotKey(Handle, MuteKeyId, preferences.MuteMods | 0x4000, preferences.MuteVk);
            pill.SetChat(true, false);
            pill.ListenForName = preferences.ListenCapri;
            pillUntil = clock.Elapsed.TotalSeconds + PillPop;
            // Turned on mid-job, it leaves the job running, so what they say next goes to it.
            if (working == null)
            {
                brain.Cancel();
                CloseTalk();
            }
            ListenLocally();
        }

        internal static bool ChatUsesEars(bool name, bool quiet, bool silent, bool connected) { return name || FreeChatOn && (quiet || silent || !connected); }

        private void EarsNote(string text, bool problem)
        {
            mainframe.VoiceNote(text, problem);
            if (talkState == TalkState.Thinking) return;
            // A note about her ears never cuts into a reply she's still saying (Lachy, 2 Nov). A problem waits for her to finish.
            // Her own last ears note can be followed straight away, like "One sec, opening my ears." by that they're ready.
            if (StillSaying && asking != earsNotice) { if (problem) { earsHeld = text; earsHeldMended = earsMended; } return; }
            earsHeld = null;
            heard = "(voice)";
            box.Prompt = "> you: ";
            earsNotice = ++asking;
            Begin(earsNotice, text, TalkState.Talking, null);
        }

        private string earsHeld;
        // Counts her hearing going from a problem back to working (UpdateHearing), so a held note can tell it's out of date.
        private int earsHeldMended, earsMended;

        // Her words are still coming out, or her voice is still playing them.
        private bool StillSaying { get { return talkState == TalkState.Talking || clock.Elapsed.TotalSeconds < voiceUntil || hdSpeaking == asking; } }

        // A problem held while she finished her line is said now, unless her hearing has recovered since. What VOICE shows
        // can't tell: a glitch's details replace its "Say it again?" there, and a mic that's found again leaves it (Codex review, 3 Nov).
        private void SayHeldEarsNote()
        {
            if (earsHeld == null || StillSaying || talkState == TalkState.Thinking) return;
            string held = earsHeld;
            earsHeld = null;
            if (earsHeldMended == earsMended) EarsNote(held, true);
        }

        // Free voice chat is listening. How it works gets said the first time and after that only shows under VOICE, unless she promised to say when she can hear them.
        private void EarsReady(bool promised)
        {
            if (HearingNote()) return;
            if (preferences.ListenCapri)
            {
                pill.ListenForName = true;
                string waiting = ears.Muted ? "Listening for Capri; mic muted." : LocalListening;
                mainframe.VoiceNote(earsLead + waiting, false);
                if (!preferences.ListenCapriTold && talkState != TalkState.Thinking)
                {
                    EarsNote(earsLead + waiting + " Say my name anywhere in your sentence.", false);
                    preferences.ListenCapriTold = true;
                    if (!testing) SavePreferences();
                }
                return;
            }
            const string on = "Free voice chat on. Talk and I'll type back.";
            if (ears.Muted) EarsNote(earsLead + "Free voice chat is ready; your mic is muted.", false);
            else if (earsLead.Length > 0) EarsNote(earsLead + "Free voice chat is on; talk and I'll type back.", false);
            else if (preferences.FreeChatTold && !promised) mainframe.VoiceNote(on, false);
            else
            {
                bool shown = talkState != TalkState.Thinking;
                EarsNote(on, false);
                if (shown && !testing && !preferences.FreeChatTold) { preferences.FreeChatTold = true; SavePreferences(); }
            }
        }

        private void OnUi(Action action)
        {
            if (InvokeRequired) Post(action);
            else action();
        }

        private void ListenLocally()
        {
            hearingOffline = false;
            hearingSpeechProblem = null;
            nameOver = false;
            lock (waking) { utterance = null; quietRun = 0; loudRun = 0; noiseHold = false; preroll.Clear(); room = -1; lineAt = -100; }
            earsAwaited = false;
            if (HearingStatus.Own(HearingChoice, OwnEars)) { ListenOwn(); return; }
            if (HearingChoice == 1) { if (parakeet.Fits) AwaitEars(null); else HearingNote(); return; }
            Hearing.Own = null;
            GetFreeEars();
            // Windows speech only hears Windows' default mic. When that's VB-CABLE's output it would hear her own voice in their
            // mic (F66), so she hears their real mic offline instead.
            if (MicMix.IsCableOut(Ears.DefaultName())) { HearLater(CableDefault); return; }
            Dictation opened;
            try { opened = Dictation.Make(); }
            catch (Exception error) { hearingSpeechProblem = "Windows speech recognition isn't on this PC: " + Voice.Short(error.Message); HearLater(hearingSpeechProblem); return; }
            opened.Language = preferences.Language;
            dictation = opened;
            opened.Heard = delegate(string text) { OnUi(delegate { if (dictation == opened) HeardDictation(text); }); };
            opened.Partial = delegate(string words) { OnUi(delegate { if (dictation == opened) { if (!string.IsNullOrEmpty(words)) HearingResult(null, true); DockWords(words); } }); };
            opened.Lost = delegate(string problem) { OnUi(delegate { if (dictation == opened) DictationLost(problem); }); };
            opened.Rejected = delegate(string problem) { OnUi(delegate { if (dictation == opened && !ears.Muted) HearingResult(problem, false); }); };
            if ((preferences.ListenCapri || preferences.FreeChatTold) && earsLead.Length == 0) mainframe.VoiceNote("One sec, opening my ears.", false);
            else EarsNote(earsLead + "One sec, opening my ears.", false);
            opened.Start(delegate(string problem) { OnUi(delegate { if (dictation == opened) Dictated(problem); }); });
            UpdateHearing();
        }

        private void Dictated(string problem)
        {
            if (!chatting || !local) return;
            if (problem != null) { DictationLost(problem); return; }
            // Windows speech only hears the default mic, and that can turn into the cable while it opens (Codex review, 2 Nov).
            if (MicMix.IsCableOut(Ears.DefaultName()))
            {
                Dictation closing = dictation;
                dictation = null;
                if (closing != null) closing.Dispose();
                HearLater(CableDefault);
                return;
            }
            try { if (!testing && !ears.Listening) ears.Start(); }
            catch (VoiceException error) { HearingCaptureFailed(error.Message, false); }
            earsReady = true;
            dictation.Hold(ears.Muted);
            dictationMic = Dictation.DefaultMic();
            dictationMicAt = clock.Elapsed.TotalSeconds + 2;
            CheckEars(clock.Elapsed.TotalSeconds);
            string chosen = MicName(preferences.Mic);
            string other = chosen == null || ears.Muted ? null : Dictation.OtherMic(preferences.Mic, chosen, dictationMic);
            if (other != null)
            {
                HearingNote();
                return;
            }
            EarsReady(false);
        }

        private void DictationLost(string problem)
        {
            Dictation closing = dictation;
            dictation = null;
            if (closing != null) closing.Dispose();
            if (!chatting || !local) return;
            earsReady = false;
            hearingSpeechProblem = problem;
            if (problem == Dictation.MicBlocked || problem == Dictation.NoMic) { StopChat(); HearingNote(); return; }
            if (HearingStatus.Own(HearingChoice, OwnEars)) ListenOwn();
            else HearLater(problem);
        }

        private void HearLater(string why)
        {
            if (HearingChoice != 2 && EarsComing) AwaitEars(why);
            else ListenOffline(why);
        }

        // No Windows speech and her own ears aren't in yet: they type until the ears land, then she switches on her own.
        private void AwaitEars(string why)
        {
            lock (waking) { utterance = null; quietRun = 0; loudRun = 0; noiseHold = false; preroll.Clear(); room = -1; lineAt = -100; }
            earsReady = false;
            earsAwaited = true;
            Hearing.Own = null;
            if (why != null) Brain.Log("ears", -1, "waiting for her own ears: " + why);
            GetFreeVoice();
            GetFreeEars();
            HearingNote(true);
        }

        // Her ears work once the ears and the voice pack are both in, whichever lands last.
        private bool EarsArrived()
        {
            UpdateHearing();
            if (HearingChoice == 2 || !chatting || !local || !OwnEars || (dictation == null && !earsAwaited)) return false;
            if (dictation != null) DictationLost(null);
            else ListenOwn();
            return true;
        }

        // Her own Parakeet ears hear the picked mic offline, about as well as Windows' online speech, so no warning.
        private void ListenOwn()
        {
            hearingOffline = false;
            hearingSpeechProblem = null;
            lock (waking) { utterance = null; quietRun = 0; loudRun = 0; noiseHold = false; preroll.Clear(); room = -1; lineAt = -100; }
            bool promised = earsAwaited;
            earsAwaited = false;
            Hearing.Own = parakeet;
            try { if (!testing && !ears.Listening) ears.Start(); }
            catch (VoiceException error)
            {
                StopChat();
                HearingCaptureFailed(error.Message, true);
                return;
            }
            earsReady = true;
            CheckEars(clock.Elapsed.TotalSeconds);
            if (!testing) ThreadPool.QueueUserWorkItem(delegate { try { parakeet.Warm(); } catch (Exception error) { Brain.Log("ears", -1, Voice.Short(error.Message)); } });
            EarsReady(promised);
        }

        private void ListenOffline(string why)
        {
            hearingOffline = true;
            hearingSpeechProblem = why;
            Hearing.Own = null;
            lock (waking) { utterance = null; quietRun = 0; loudRun = 0; noiseHold = false; preroll.Clear(); room = -1; lineAt = -100; }
            earsAwaited = false;
            try { if (!testing && !ears.Listening) ears.Start(); }
            catch (VoiceException error)
            {
                StopChat();
                HearingCaptureFailed(error.Message, true);
                return;
            }
            earsReady = true;
            CheckEars(clock.Elapsed.TotalSeconds);
            if (HearingNote()) return;
            if (preferences.ListenCapri)
            {
                EarsReady(false);
                mainframe.VoiceNote(LocalListening + " Offline hearing. " + why, true);
                return;
            }
            EarsNote(earsLead + (ears.Muted ? "Free voice chat is ready with offline hearing; your mic is muted. " : "Free voice chat on, but I'm hearing offline, so I'll miss some words. ") + (why == Dictation.PrivacyOff ? "Turn on Online speech recognition in Windows Settings > Privacy & security > Speech." : "The reason is under VOICE in the Mainframe."), false);
            mainframe.VoiceNote(why, true);
        }

        private void HeardDictation(string text)
        {
            if (!chatting || !local || !earsReady || ears.Muted) return;
            HearingResult(null, true);
            if (CallModeOn) { if (!earsShut) HearCall(Hearing.Clean(text)); return; }
            text = Hearing.Clean(text);
            if (watchAlong != null && WatchAlong.Request(text) == "stop" && StopWatchAlong(text)) return;
            if (preferences.ListenCapri && !pushing && clock.Elapsed.TotalSeconds < voiceUntil && !nameOver && !VoiceStop(text) && !(PcEars.Active && StopWords(text))) return;
            if (!VoiceForHer(text)) { nameOver = false; return; }
            nameOver = false;
            if (preferences.ListenCapri && (talkState == TalkState.Talking || clock.Elapsed.TotalSeconds < voiceUntil || speaker.Busy))
            {
                if (StopVoice(text)) return;
                BargeIn();
            }
            CheckEars(clock.Elapsed.TotalSeconds);
            if (earsShut || text.Length == 0) return;
            mainframe.VoiceNote(LocalListening, false);
            Hear(text, text, "> you: ");
        }

        internal bool ListenCapriOn { get { return preferences.ListenCapri; } }

        // Listen for Capri's ears stay open while she runs, and that isn't a conversation, so she carries on as usual around it.
        private bool InChat { get { return chatting && !(local && preferences.ListenCapri); } }

        // They open once her hello's out of the way and come back after whatever closed them (hiding her, Quiet, a lost mic), unless they closed them on purpose.
        private bool earsClosed;
        private double listenAt;

        private void AgentVoice()
        {
            string key = voice.Key, agentId = preferences.AgentId;
            if (key == null || agentId == null) return;
            ThreadPool.QueueUserWorkItem(delegate
            {
                try
                {
                    AgentTts tts = Agent.Speech(key, agentId);
                    if (tts == null) return;
                    voice.Settings = tts.Settings;
                    Brain.Log("voice chat agent", -1, "model " + tts.Model + ", settings " + (tts.Settings ?? "none"));
                }
                catch (VoiceException error) { Brain.Log("voice chat agent", -1, error.Message); }
            });
        }

        // Listen for Capri changed by her settings tool, which opens or closes her ears only once the reply it came with is over,
        // since that can end the voice chat that's answering.
        private bool listenChangeDue;
        private int listenReply;
        private Agent listenAgent;

        private void KeepListening(double now)
        {
            if (listenChangeDue)
            {
                if (!SettingsReplyDone(listenAgent, listenReply)) return;
                listenChangeDue = false;
                ApplyListenCapri();
            }
            // Quiet only turns ElevenLabs off, so Fish Audio and her own voices listen too (Lachy, 31 Oct: "hey capri is basically unusable").
            // A job holds her talk state for as long as it runs and a stream runs for hours, and Gaming Mode hides her window, so neither keeps her ears shut (Lachy, 1 Nov).
            if (!preferences.ListenCapri || earsClosed || chatting || now < listenAt || (hidden && !docked) || quitting || (talkState != TalkState.Off && working == null) || speech != null) return;
            listenAt = now + 60;
            ToggleChat();
        }

        // Listen for Capri from her Mainframe, menu or settings tool, saved at once. Her settings tool's change (later) opens or
        // closes her ears after its reply, which from voice chat is that call's.
        internal void ToggleListenCapri(bool later = false, bool fromAgent = false)
        {
            preferences.ListenCapri = !preferences.ListenCapri;
            nameOver = false;
            SavePreferences();
            mainframe.Sync();
            listenChangeDue = later;
            if (later) { listenAgent = fromAgent ? agent : null; listenReply = chatReplies; return; }
            ApplyListenCapri();
        }

        // Opens her ears for her name, or closes them, as Listen for Capri is set now.
        private void ApplyListenCapri()
        {
            if (!chatting)
            {
                // Turning it on is them asking her to listen, so there's no key to press as well (Lachy, 31 Oct).
                earsClosed = false;
                listenAt = 0;
                return;
            }
            if (preferences.ListenCapri && !local) { StopChat(); StartLocal(); return; }
            if (!preferences.ListenCapri && local && !testing) { StopChat(); return; }
            pill.ListenForName = preferences.ListenCapri;
            if (earsReady) EarsReady(false);
        }

        private string LocalListening { get { return CallModeOn ? "Call mode (beta). Voice is conversation only." : preferences.ListenCapri ? "Listening for Capri." : "Free voice chat on. Talk and I'll type back."; } }

        internal const string CableDefault = "Windows speech only hears your default mic, CABLE Output, which has her voice in it. She hears your real mic offline instead.";

        private bool VoiceForHer(string text)
        {
            if (watchAlong != null && (WatchAlong.Request(text) == "stop" || VoiceStop(text))) return true;
            if (!preferences.ListenCapri || pushing || Hands.HeardName(text)) return true;
            return (MidJob(job) || PcEars.Active || talkState == TalkState.Talking || clock.Elapsed.TotalSeconds < voiceUntil || speaker.Busy)
                && (VoiceStop(text) || PcEars.Active && StopWords(text));
        }

        private static bool VoiceStop(string text)
        {
            string stopTool;
            ToolArguments stopArgs;
            return Asides.Plain(text, out stopTool, out stopArgs) == AsideKind.Stop;
        }

        private bool StopVoice(string text)
        {
            if (StopWatchAlong(text)) return true;
            if (StopListening(text)) return true;
            if (!VoiceStop(text)) return false;
            if (MidJob(job)) Hear(text, text, "> you: ");
            else { BargeIn(); CloseTalk(); }
            return true;
        }

        private void CheckEars(double now)
        {
            // A job leaves her thinking until it ends, but her ears stay open through it so they can tell her more.
            earsShut = local && (!earsReady || transcribing || ears.Muted || (talkState == TalkState.Thinking && working == null && !PcEars.Active) || now < voiceUntil && !nameOver);
            if (!earsShut) return;
            lock (waking) { utterance = null; preroll.Clear(); loudRun = 0; quietRun = 0; }
            pill.SetLevel(0);
        }

        private void Missed(string text, bool problem)
        {
            if (preferences.ListenCapri && !problem) return;
            mainframe.VoiceNote(text, problem);
            double now = clock.Elapsed.TotalSeconds;
            if (now - earsWarned < 8 || talkState == TalkState.Thinking) return;
            earsWarned = now;
            EarsNote(text, problem);
        }

        private void Gather(short[] chunk)
        {
            double level = VoiceLevel(chunk);
            if (OverHerLocally(chunk, level)) return;
            if (nameOver && clock.Elapsed.TotalSeconds < voiceUntil && !talkOver.Above(level, SpokenLevel(clock.Elapsed.TotalSeconds), room < 0 ? WakeLevel : RoomWake()))
            {
                chunk = new short[chunk.Length];
                level = 0;
            }
            lock (waking)
            {
                if (!local || !earsReady || dictation != null || ears.Muted || earsShut && !nameOver || transcribing) { utterance = null; preroll.Clear(); loudRun = 0; quietRun = 0; return; }
                // The room's level is its quietest moment: it drops straight to anything quieter and creeps up 2% a chunk between lines, never mid-line. It starts no higher than the old fixed level allows.
                if (room < 0) room = Math.Min(Math.Max(level, 0.0003), WakeLevel / RoomMargin);
                else if (level < room) room = Math.Max(level, 0.0003);
                else if (utterance == null) room = Math.Min(level, room * 1.02);
                double wake = RoomWake();
                bool loud = level >= wake;
                if (noiseHold)
                {
                    quietRun = loud ? 0 : quietRun + 1;
                    if (quietRun >= 9) { noiseHold = false; quietRun = 0; }
                    return;
                }
                if (utterance == null)
                {
                    preroll.Add(chunk);
                    if (preroll.Count > 4) preroll.RemoveAt(0);
                    loudRun = loud ? loudRun + 1 : 0;
                    if (loudRun < 2) return;
                    utterance = new System.Collections.Generic.List<short[]>(preroll);
                    preroll.Clear();
                    loudRun = 0;
                    quietRun = 0;
                    return;
                }
                utterance.Add(chunk);
                quietRun = loud ? 0 : quietRun + 1;
                // Two seconds that never vary more than Speech's steadiness allows are a fan or a hum, not a voice: that becomes the room's level and the line is dropped.
                if (utterance.Count >= 20)
                {
                    double low = 1;
                    double high = 0;
                    for (int i = utterance.Count - 20; i < utterance.Count; i++)
                    {
                        double piece = VoiceLevel(utterance[i]);
                        low = Math.Min(low, piece);
                        high = Math.Max(high, piece);
                    }
                    if (high < low * 1.2) { room = Math.Max(room, low); utterance = null; quietRun = 0; nameOver = false; return; }
                }
                if (quietRun < 9 && utterance.Count < 150) return;
                short[][] taken = utterance.ToArray();
                bool capped = quietRun < 9;
                utterance = null;
                quietRun = 0;
                int ticket = chatTicket;
                int request = asking;
                if (capped)
                {
                    // 15 seconds without a pause is the room, not a line: its quietest chunk after the lead-in becomes the room's level.
                    double quietest = 1;
                    for (int i = 4; i < taken.Length; i++) quietest = Math.Min(quietest, VoiceLevel(taken[i]));
                    room = Math.Max(room, quietest);
                    noiseHold = true;
                    nameOver = false;
                    Post(delegate { if (ticket == chatTicket && local) Missed("I heard 15 seconds without a pause. Try a shorter line or lower your mic volume.", false); });
                    return;
                }
                if (!LineCounts(taken, wake, clock.Elapsed.TotalSeconds)) { nameOver = false; return; }
                transcribing = true;
                transcribingAt = Environment.TickCount;
                bool fromCall = CallLine(taken.Length);
                Post(delegate { Transcribe(taken, ticket, request, wake, fromCall); });
            }
        }

        private double RoomWake() { return Math.Max(QuietWake, Math.Min(room * RoomMargin, Math.Max(WakeLevel, room * 1.6))); }

        // A finished line goes to her ears if it sounds like speech at the wake level. Within a minute of a line that came through, one under the old fixed level and over 10 dB quieter than it is someone else or the TV, not them.
        private bool LineCounts(short[][] taken, double wake, double now)
        {
            if (!Speech(taken, wake)) return false;
            double loudest = 0;
            foreach (short[] piece in taken) loudest = Math.Max(loudest, VoiceLevel(piece));
            if (now - lineAt < 60 && loudest < lineLevel / 3.16 && !Speech(taken)) return false;
            lineAt = now;
            lineLevel = loudest;
            return true;
        }

        // Loudness under about 900 Hz, where a voice is: this low-pass keeps a voice within about 2 dB but drops key clicks and hiss about 7.
        private static double VoiceLevel(short[] samples)
        {
            if (samples.Length == 0) return 0;
            double kept = 0;
            double sum = 0;
            foreach (short sample in samples)
            {
                kept += 0.3 * (sample - kept);
                sum += kept * kept;
            }
            return Math.Sqrt(sum / samples.Length) / 32768.0;
        }

        private static bool Speech(short[][] taken, double wake = WakeLevel)
        {
            int voiced = 0;
            double low = 1;
            double high = 0;
            foreach (short[] piece in taken)
            {
                double level = VoiceLevel(piece);
                if (level < wake) continue;
                voiced += piece.Length;
                low = Math.Min(low, level);
                high = Math.Max(high, level);
            }
            return voiced >= Ears.Rate * 3 / 10 && (voiced < Ears.Rate * 8 / 10 || high >= low * 1.2);
        }

        private void Transcribe(short[][] taken, int ticket, int request, double wake = WakeLevel, bool fromCall = false)
        {
            if (ticket != chatTicket || !local || !chatting) return;
            if (request != asking) { transcribing = false; nameOver = false; CheckEars(clock.Elapsed.TotalSeconds); return; }
            if (ears.Muted || (talkState == TalkState.Thinking && working == null && !PcEars.Active) || clock.Elapsed.TotalSeconds < voiceUntil && !nameOver || !Speech(taken, wake))
            {
                transcribing = false;
                nameOver = false;
                CheckEars(clock.Elapsed.TotalSeconds);
                if (!earsShut) Missed("I couldn't make out any words. Try closer to the mic.", false);
                return;
            }
            int total = 0;
            foreach (short[] piece in taken) total += piece.Length;
            short[] samples = new short[total];
            int at = 0;
            foreach (short[] piece in taken) { Array.Copy(piece, 0, samples, at, piece.Length); at += piece.Length; }
            CheckEars(clock.Elapsed.TotalSeconds);
            if (!preferences.ListenCapri) mainframe.VoiceNote("Hearing you...", false);
            ThreadPool.QueueUserWorkItem(delegate
            {
                string text = null;
                string problem = null;
                try { text = Hearing.Text(samples); }
                catch (Exception error) { problem = Voice.Short(error.Message); }
                Post(delegate { HeardLocally(ticket, request, text, problem, fromCall); });
            });
        }

        private void HeardLocally(int ticket, int request, string text, string problem, bool fromCall = false)
        {
            if (ticket != chatTicket || !chatting || !local) return;
            transcribing = false;
            nameOver = false;
            CheckEars(clock.Elapsed.TotalSeconds);
            if (request != asking || ears.Muted) { if (!preferences.ListenCapri) mainframe.VoiceNote(LocalListening, false); return; }
            if (problem != null)
            {
                HearingResult(problem, false);
                if (!testing) Brain.Log("ears", -1, problem);
                Missed(EarsGlitched, true);
                mainframe.VoiceNote(problem, true);
                return;
            }
            if (string.IsNullOrEmpty(text)) { HearingResult(null, false); Missed("I couldn't make out any words. Try again closer to the mic.", false); return; }
            HearingResult(null, true);
            if (CallModeOn) { HearCall(text, false, fromCall); return; }
            if (!VoiceForHer(text)) return;
            if (preferences.ListenCapri && (talkState == TalkState.Talking || clock.Elapsed.TotalSeconds < voiceUntil || speaker.Busy))
            {
                if (StopVoice(text)) return;
                BargeIn();
            }
            mainframe.VoiceNote(LocalListening, false);
            Hear(text, text, "> you: ");
        }

        private void OpenLink()
        {
            if (CallModeOn) return;
            int callVersion = callSession.Generation;
            mainframe.VoiceNote("Opening voice chat...", false);
            int ticket = ++chatTicket;
            string key = voice.Key;
            string voiceId = voice.VoiceId;
            string agentId = preferences.AgentId;
            bool stale = Agent.Stale(preferences.AgentVersion, preferences.AgentPersonality);
            string stamp = Brain.PersonalityStamp;
            string language = Brain.LanguageCode(Brain.Language);
            string polyglot = preferences.AgentPolyglot;
            ThreadPool.QueueUserWorkItem(delegate
            {
                string url = null;
                string problem = null;
                try
                {
                    if (agentId == null) agentId = Agent.Create(key, voiceId);
                    else if (stale)
                    {
                        try { Agent.Tune(key, agentId); }
                        catch (VoiceException error)
                        {
                            if (error.Status != 404 && error.Status != 400) throw;
                            agentId = Agent.Create(key, voiceId);
                        }
                    }
                    try { url = Agent.Address(key, agentId); }
                    catch (VoiceException error)
                    {
                        if (error.Status != 404 && error.Status != 400) throw;
                        agentId = Agent.Create(key, voiceId);
                        url = Agent.Address(key, agentId);
                    }
                    if (language != "en" && polyglot != agentId)
                    {
                        try { Agent.Polyglot(key, agentId); polyglot = agentId; }
                        catch (VoiceException error) { Brain.Log("https://api.elevenlabs.io/v1/convai/agents", -1, "Voice chat couldn't switch languages: " + error.Message); language = "en"; }
                    }
                }
                catch (VoiceException error) { problem = error.Message; }
                catch (Exception error) { problem = Voice.Short("Voice chat failed: " + error.Message); }
                Post(delegate
                {
                    if (ticket != chatTicket || !chatting || CallModeOn || !callSession.Current(callVersion)) return;
                    if (problem != null) { ChatFailed(problem); return; }
                    if (preferences.AgentId != agentId || preferences.AgentVersion != Agent.Version || preferences.AgentPolyglot != polyglot || (preferences.AgentPersonality ?? "") != stamp) { preferences.AgentId = agentId; preferences.AgentVersion = Agent.Version; preferences.AgentPolyglot = polyglot; preferences.AgentPersonality = stamp; SavePreferences(); }
                    Connect(url, voiceId, language);
                });
            });
        }

        private void Connect(string url, string voiceId, string language = "en")
        {
            if (CallModeOn) return;
            int callVersion = callSession.Generation;
            Agent opened = new Agent();
            opened.Language = language;
            opened.Act = delegate(string tool, ToolArguments args) { return CallModeOn || !callSession.Current(callVersion) ? "That voice call has ended." : AgentAct(opened, tool, args); };
            opened.Opened += delegate(int rate) { Post(delegate { if (agent == opened) ChatOpened(rate); }); };
            opened.Heard += delegate(string text) { Post(delegate { if (agent == opened) ChatHeard(text); }); };
            opened.Replied += delegate(string text) { Post(delegate { if (agent == opened) ChatReplied(text); }); };
            opened.Audio += delegate(short[] samples)
            {
                Post(delegate
                {
                    if (agent != opened || dropping || repeating || clock.Elapsed.TotalSeconds < bargedUntil) return;
                    if (Unprompted()) { dropping = true; checkedIn = true; Hush(); return; }
                    stirred = Environment.TickCount;
                    speaker.Play(ChatVoice(samples));
                    foreach (ToolEnd end in toolEnds) if (end.Replied) end.At = clock.Elapsed.TotalSeconds;
                    if (!frames.Enabled && (!hidden || docked)) frames.Start();
                });
            };
            opened.Interrupted += delegate { Post(delegate { if (agent == opened) ChatInterrupted(); }); };
            opened.Closed += delegate(string problem) { Post(delegate { if (agent != opened) return; if (problem != null) ChatFailed(problem); else Rest(); }); };
            agent = opened;
            opened.Start(url, voiceId);
        }

        // ElevenLabs voice chat streams its audio in, so her pitch, speed, robot, glitch and layers go on a chunk at a time.
        // What the styling still holds back, her layers' delayed tails too, comes out once the stream has been quiet for a moment.
        private short[] ChatVoice(short[] samples)
        {
            int pitch = VoiceFx.Pitch, speed = VoiceFx.Speed, robot = VoiceFx.Robot, glitch = VoiceFx.Glitch;
            VoiceFx.Layering layers = VoiceFx.Layers;
            if (chatFx != null && (chatFx.Pitch != pitch || chatFx.Speed != speed || chatFx.Robot != robot || chatFx.Glitch != glitch || chatFx.Rate != chatRate || !chatFx.Layers.Same(layers)))
            {
                speaker.Play(chatFx.Flush());
                chatFx = null;
            }
            if (chatFx == null && !VoiceFx.Plain(pitch, speed, robot, glitch, layers)) chatFx = new VoiceFx.Live(chatRate, pitch, speed, robot, glitch, Environment.TickCount, true, layers);
            if (chatFx == null) return samples;
            chatTail.Stop();
            chatTail.Start();
            return chatFx.Push(samples);
        }

        private void ChatTail()
        {
            chatTail.Stop();
            if (chatFx != null && agent != null && !dropping) speaker.Play(chatFx.Flush());
        }

        private void Hush()
        {
            speaker.Clear();
            chatTail.Stop();
            chatFx = null;
        }

        private void ChatInterrupted()
        {
            LogVoiceInterruption("server interruption", audioTurn, false);
            CancelAnswerAudio();
            bargedUntil = -1;
            Hush();
        }

        private void ChatOpened(int rate)
        {
            StopMicTest(false);
            chatRate = rate;
            chatTail.Stop();
            chatFx = null;
            try
            {
                speaker.Open(rate);
                if (!testing) ears.Start();
            }
            catch (VoiceException error)
            {
                if (hearingCaptureProblem != null) { StopChat(); HearingNote(); }
                else ChatFailed(error.Message);
                return;
            }
            spoke = false;
            checkedIn = false;
            quietSince = -1;
            lastSaid = null;
            repeating = false;
            bargedUntil = -1;
            lock (waking)
            {
                wokeAt = backlog != null ? clock.Elapsed.TotalSeconds : -1;
                if (backlog != null) foreach (short[] held in backlog) agent.Send(held);
                backlog = null;
            }
            if (!HearingNote()) mainframe.VoiceNote(muteKey ? "Voice chat on. " + MuteKeyName + " mutes your mic." : "Voice chat on. Talk to her.", false);
        }

        private void ChatFailed(string problem)
        {
            StopChat();
            mainframe.VoiceNote(problem, true);
            bool broke = Broke(problem);
            if (broke && !FreeChatOn)
            {
                heard = "(voice)";
                box.Prompt = "> you: ";
                Begin(++asking, NoVoiceCredits, TalkState.Talking, null);
                return;
            }
            if (broke)
            {
                preferences.Quiet = true;
                SavePreferences();
                mainframe.Sync();
                StartLocal(true);
                return;
            }
            heard = "(voice)";
            box.Prompt = "> you: ";
            Begin(++asking, "Can't open my voice link. Right-click me and open Capri Mainframe. The reason and the fix are under VOICE." + Brain.Stuck, TalkState.Dormant, null);
        }

        private readonly object shortcutGate = new object();
        private string shortcutTool;
        private int shortcutAt;
        private string shortcutResult;
        private bool toolAsked;
        // The voice shortcut's call and ask, so only the same call in the same ask reuses its result.
        private string shortcutCall;
        private int shortcutAsk;
        private string toolDone;
        private string heardLast;
        private volatile int stirred;

        // ElevenLabs gives a tool 20 s and a job with her cursor can take minutes, so the agent hears she's on it straight away and how it went once the job ends.
        // Jobs wait their turn on the mouse, and the same job asked again joins the one waiting or running instead of starting twice.
        private readonly System.Collections.Generic.List<string> mouseJobs = new System.Collections.Generic.List<string>();
        private volatile int escTold = -1;
        private Action<string> finishedTest;
        // Not "tell them she's on it": she's usually just said so, and the agent said it again word for word (Lachy, 30 Oct).
        internal const string StartedLater = "Capri started that job with her cursor. It can take a minute, and you'll hear how it went when it's done. If you already told them she's on it, don't say it again; if you didn't, say so in a few words. Don't say it's done yet, and don't call the tool again for it.";
        internal const string AlreadyLater = "Capri is already doing that job with her cursor. Don't call the tool again, and don't repeat what you already told them.";

        // The job a tool call puts on the mouse, if any: a use_computer job, or a quick tool she does with her cursor.
        private string MouseKey(string tool, ToolArguments args)
        {
            if (args == null || brain.Model == null) return null;
            string task = tool == "use_computer" ? args.Task : preferences.QuickHands || !Security.On(Security.Mouse) ? null : CursorJob(tool, args);
            return string.IsNullOrWhiteSpace(task) ? null : Regex.Replace(task.Trim().ToLowerInvariant(), @"\s+", " ");
        }

        // The same job in other words joins it too: the agent often asks again after its first call, like "craft a crafting table"
        // then "craft a crafting table in minecraft", which queued it twice (Lachy, 30 Oct). A different job still gets its turn.
        private bool Claim(string key)
        {
            lock (mouseJobs)
            {
                if (mouseJobs.Exists(held => SameJob(held, key))) return false;
                mouseJobs.Add(key);
                return true;
            }
        }

        private static readonly Regex JobFiller = new Regex(@"^(a|an|the|in|on|at|to|for|of|and|then|now|it|its|me|my|your|their|them|please|pls|capri|can|you|u|up|some|this|that|with)$");

        internal static bool SameJob(string one, string other)
        {
            if (one == other) return true;
            System.Collections.Generic.HashSet<string> first = new System.Collections.Generic.HashSet<string>(), second = new System.Collections.Generic.HashSet<string>();
            foreach (Match word in Regex.Matches(one.ToLowerInvariant(), @"[\p{L}\p{N}']+")) if (!JobFiller.IsMatch(word.Value)) first.Add(word.Value);
            foreach (Match word in Regex.Matches(other.ToLowerInvariant(), @"[\p{L}\p{N}']+")) if (!JobFiller.IsMatch(word.Value)) second.Add(word.Value);
            if (first.Count == 0 || second.Count == 0) return false;
            int both = 0;
            foreach (string word in first) if (second.Contains(word)) both++;
            return both * 10 >= (first.Count + second.Count - both) * 6;
        }

        private void Free(string key) { lock (mouseJobs) mouseJobs.Remove(key); }

        private string Later(Agent told, string tool, ToolArguments args, string key)
        {
            if (!Claim(key)) return AlreadyLater;
            int ticket = asking;
            ThreadPool.QueueUserWorkItem(delegate
            {
                string result;
                try { result = DoTool(tool, args, ticket); }
                finally { Free(key); }
                Finished(told, tool, result, ticket);
            });
            return tool == "find_file" ? "Capri is searching file and folder names on a worker. She will show the paths when it finishes. Don't call it again for the same search." : StartedLater;
        }

        // How a job that outlasted its tool call went: she says it in the call while it's open, or in her bubble once it's closed.
        private void Finished(Agent told, string tool, string result, int ticket)
        {
            if (string.IsNullOrEmpty(result)) return;
            if (tool == "find_file" && ticket != asking) return;
            if (Computer.Stopped(result)) { if (escTold == ticket) return; escTold = ticket; }
            lock (shortcutGate) { toolAsked = true; toolDone = result; }
            stirred = Environment.TickCount;
            Action<string> heard = finishedTest;
            if (heard != null) { heard(result); return; }
            // Their own "stop" in voice chat got its answer from the agent, which only needs to know it happened.
            if (told != null && told.Ready && result != Computer.Escaped && Computer.Stopped(result)) { told.Tell("Capri's hands stopped the job, like they asked. It's over, so don't bring it up again."); return; }
            if (told != null && told.Ready)
            {
                if (tool == "find_file") Post(delegate { if (ticket == asking) Begin(ticket, result, TalkState.Talking, null); });
                DoneLine(told, tool, tool == "find_file" ? FileFinder.Spoken(result) : result);
                return;
            }
            Post(delegate { if (talkState != TalkState.Thinking) Answer(++asking, result, TalkState.Talking); });
        }

        // A tool call from voice chat. A call SECURITY holds is asked about at once instead of waiting its turn on the mouse.
        private string AgentAct(Agent opened, string tool, ToolArguments args)
        {
            if (CallModeOn) return "I can only talk in call mode.";
            if (args == null) args = new ToolArguments();
            args.FromAgent = opened != null;
            stirred = Environment.TickCount;
            lock (shortcutGate)
            {
                toolAsked = true;
                if (shortcutAsk == asking && shortcutCall == Hands.CallKey(tool, args) && tool == shortcutTool && (Environment.TickCount - shortcutAt < 10000 || tool == "listen" && PcEars.Active)) return shortcutResult ?? "Already doing that.";
            }
            if (tool == "find_file" && args != null && (string.IsNullOrEmpty(args.Action) || args.Action == "search")) return Later(opened, tool, args, "find_file " + args.Description);
            string key = Security.Asks(tool, args) ? null : MouseKey(tool, args);
            if (key != null && Folded(tool, args, key)) return FoldedLater;
            if (key != null) return Later(opened, tool, args, key);
            string done = DoTool(tool, args);
            if (string.IsNullOrEmpty(done)) done = Computer.Escaped;
            lock (shortcutGate) toolDone = done;
            stirred = Environment.TickCount;
            return done;
        }

        // Their yes or no in voice chat to her asking first (SECURITY): a yes runs what she held on its own thread, like a
        // shortcut, a no leaves it, and the agent hears which. Anything else drops it. True when it was their answer.
        private bool VoiceAnswer(string text, int ticket, Agent asker)
        {
            string resumed = Security.Holding;
            bool answering = resumed != null && (Security.Agrees(text) || Security.Declines(text));
            if (resumed != null && !answering) Security.Drop();
            if (!answering) return false;
            lock (shortcutGate) { toolAsked = true; heardLast = text; toolDone = null; shortcutTool = resumed; shortcutAt = Environment.TickCount; shortcutResult = null; }
            ThreadPool.QueueUserWorkItem(delegate
            {
                int began = Environment.TickCount;
                string result = Security.Resume(text, delegate(string held, ToolArguments heldArgs)
                {
                    if (heldArgs != null) heldArgs.Reply = 0;
                    lock (shortcutGate) { shortcutTool = held; shortcutCall = Hands.CallKey(held, heldArgs); shortcutAsk = ticket; }
                    return DoTool(held, heldArgs, ticket);
                }) ?? Security.Left;
                lock (shortcutGate) shortcutResult = result;
                stirred = Environment.TickCount;
                if (result != Security.Left && unchecked(Environment.TickCount - began) > 8000) { Finished(asker, resumed, result, ticket); return; }
                string line = result == Security.Left ? "They said no, so Capri left it alone. Say so in one short line and don't call a tool for it." : "Capri's hands did what they just said yes to (" + resumed + "): " + result + " Don't call a tool for it again. React to it in one short line.";
                Action<string> heard = finishedTest;
                if (heard != null) heard(line);
                else if (asker != null) asker.Tell(line);
            });
            return true;
        }

        // ElevenLabs makes her take a turn after 30 s of silence. A line nothing asked for (no words from them, no job, no reply of hers going) is that "still there?", so it never plays and the call rests.
        private bool Unprompted() { return unchecked(Environment.TickCount - stirred) >= 12000; }

        private void ChatHeard(string text)
        {
            if (CallModeOn) return;
            if (!chatting || !VoiceForHer(text)) return;
            WakeRest(!SleepBusy);
            agentComment = false;
            if (StopListening(text)) return;
            // A sorry in voice chat makes up with her too, and the agent hears so before it answers (Zr4, F44).
            if (Sulking && Apology(text)) Forgive();
            Brain.Transcribe("You (voice)", text);
            spoke = true;
            stirred = Environment.TickCount;
            checkedIn = false;
            wokeAt = -1;
            int ticket = ++asking;
            heard = text;
            box.Prompt = "> you: ";
            Brain.Learn(text);
            dropping = false;
            repeating = false;
            bargedUntil = -1;
            if (VoiceMini(text)) return;
            if (agent != null && miniContext.Length > 0) agent.Tell(miniContext);
            string tool = null;
            ToolArguments args = null;
            // Their yes to her asking first (SECURITY) runs what she held, like a shortcut, and their no leaves it.
            bool answering = VoiceAnswer(text, ticket, agent);
            // Mid-job they can stop it, and the agent gets the job's latest to answer from. Her hands carry on either way.
            Job midJob = job;
            if (!answering && MidJob(midJob)) AgentMidJob(text, midJob);
            bool shortcut = !answering && Hands.Heard(text, out tool, out args);
            lock (shortcutGate) { if (!answering) { toolAsked = shortcut; heardLast = text; toolDone = null; } }
            if (shortcut)
            {
                if (tool == "clip") { dropping = true; Hush(); }
                Agent told = agent;
                string key = MouseKey(tool, args);
                bool claimed = key != null && Claim(key);
                lock (shortcutGate) { shortcutTool = tool; shortcutCall = Hands.CallKey(tool, args); shortcutAsk = ticket; shortcutAt = Environment.TickCount; shortcutResult = null; }
                ThreadPool.QueueUserWorkItem(delegate
                {
                    int began = Environment.TickCount;
                    string result;
                    try { result = key != null && !claimed ? "Already doing that." : DoTool(tool, args, ticket); }
                    finally { if (claimed) Free(key); }
                    if (string.IsNullOrEmpty(result)) result = Computer.Escaped;
                    lock (shortcutGate) shortcutResult = result;
                    stirred = Environment.TickCount;
                    // A quick one lands before her reply to their words; a cursor job ends long after it, so she says how it went then.
                    // A call SECURITY held tells the agent to ask them first, as it is.
                    if (tool == "clip")
                    {
                        lock (shortcutGate) toolDone = result;
                        Post(delegate { Answer(ticket, ClipBuffer.Spoken(result), TalkState.Talking); });
                    }
                    else if (Security.IsHold(result)) { if (told != null) told.Tell(result); }
                    else if (tool == "find_file" || unchecked(Environment.TickCount - began) > 8000) Finished(told, tool, result, ticket);
                    else if (told != null) told.Tell("Capri's hands already did what they just asked (" + tool + "): " + result + " Don't call a tool for it again. React to it in one short line.");
                });
            }
            reply = null;
            replyDone = -1;
            Say(null);
            talkState = TalkState.Thinking;
            box.Leaving = -1;
            UpdateAnimation();
        }

        private void ChatReplied(string text)
        {
            chatReplies++;
            if (CallModeOn) return;
            if (!chatting) return;
            checkedIn = !spoke;
            spoke = false;
            if (dropping) return;
            if (checkedIn && Unprompted()) { dropping = true; Hush(); return; }
            string said = Computer.Mask(Voice.Spoken(text));
            remarkTicket = agentComment ? asking : -1;
            agentComment = false;
            // The agent saying the same line again never gets as far as their ears.
            if (SaidAgain(said)) return;
            string promised = null;
            lock (shortcutGate) if (!toolAsked && heardLast != null && Hands.Promised(said)) { promised = heardLast; heardLast = null; }
            if (promised != null) { string missed = said; ThreadPool.QueueUserWorkItem(delegate { Thread.Sleep(4000); lock (shortcutGate) if (toolAsked) return; Brain.Log("https://api.elevenlabs.io/v1/convai/conversation", -1, "Voice chat said she'd do it but no tool ran. Heard: " + promised + " | Said: " + missed); }); }
            Brain.Transcribe("Capri (voice)", said);
            reply = said;
            lock (shortcutGate) if (toolDone != null && toolDone.StartsWith("The closest match is ", StringComparison.Ordinal)) reply = toolDone;
            replyStart = clock.Elapsed.TotalSeconds;
            ToolReplied(0);
            replyDone = -1;
            talkState = TalkState.Talking;
            box.Leaving = -1;
            pace = Agent.Pace;
            Say(null);
        }

        // A call only speaks in ElevenLabs' voice, so her voice moving off ElevenLabs mid-call hands the mic to her own ears
        // instead of shutting it (Lachy, 1 Nov: his mic stopped working after he switched her voice with voice chat on).
        private void LeaveCall()
        {
            if (!chatting || local) return;
            StopChat();
            if (ChatUsesEars(preferences.ListenCapri, preferences.Quiet, preferences.Silent, voice.Key != null)) StartLocal();
        }

        private void StopChat()
        {
            if (!chatting) return;
            StopMicTest(false);
            agentComment = false;
            bool wasLocal = local;
            chatting = false;
            local = false;
            earsReady = false;
            earsAwaited = false;
            earsRetryAt = -1;
            if (muteKey && !ByMouse(preferences.MuteVk)) Native.UnregisterHotKey(Handle, MuteKeyId);
            muteKey = false;
            chatTicket++;
            Agent closing = agent;
            agent = null;
            if (closing != null) closing.Stop();
            Dictation hearing = dictation;
            dictation = null;
            if (hearing != null) hearing.Dispose();
            ears.Stop();
            ears.Muted = false;
            Hearing.Own = null;
            if (!testing) ThreadPool.QueueUserWorkItem(delegate { parakeet.Dispose(); });
            Hush();
            dropping = false;
            checkedIn = false;
            quietSince = -1;
            wokeAt = -1;
            lock (waking) { resting = false; backlog = null; preroll.Clear(); loudRun = 0; utterance = null; quietRun = 0; noiseHold = false; }
            earsShut = false;
            transcribing = false;
            nameOver = false;
            pill.SetChat(false, false);
            pill.ListenForName = false;
            pillUntil = clock.Elapsed.TotalSeconds + PillPop;
            ShowVoice();
            if (wasLocal)
            {
                if (asking == earsNotice) CloseTalk();
                mainframe.VoiceNote("Free voice chat off. Click the wave to listen again.", false);
            }
            UpdateHearing();
        }

        private void CheckChat(double now)
        {
            if (agent != null && ears.Muted && !speaker.Busy)
            {
                Rest();
                mainframe.VoiceNote("Mic muted. Voice chat is paused until you unmute.", false);
                return;
            }
            bool due = agent != null && (checkedIn || (wokeAt >= 0 && now - wokeAt >= 8));
            if (!due || speaker.Busy) { quietSince = -1; return; }
            if (quietSince < 0) quietSince = now;
            else if (now - quietSince >= 1.2) Rest();
        }

        private void Rest()
        {
            if (!chatting) return;
            Agent closing = agent;
            agent = null;
            chatTicket++;
            if (closing != null) closing.Stop();
            dropping = false;
            checkedIn = false;
            quietSince = -1;
            wokeAt = -1;
            lock (waking) { resting = true; backlog = null; preroll.Clear(); loudRun = 0; }
            mainframe.VoiceNote("Voice chat resting. Talk and she'll pick up.", false);
        }

        private void Wake()
        {
            if (!chatting || agent != null) { lock (waking) backlog = null; return; }
            OpenLink();
        }

        private void ToggleMic()
        {
            if (!chatting) return;
            ears.Muted = !ears.Muted;
            ResetHearingSignal();
            UpdateHearing();
            if (ears.Muted) nameOver = false;
            if (dictation != null && earsReady) dictation.Hold(ears.Muted);
            pill.SetChat(true, ears.Muted);
            pillUntil = clock.Elapsed.TotalSeconds + PillPop;
            CheckEars(clock.Elapsed.TotalSeconds);
            if (local && earsReady) mainframe.VoiceNote(ears.Muted ? "Mic muted. Click the mic to unmute." : transcribing && !preferences.ListenCapri ? "Hearing you..." : LocalListening, false);
            else if (!local) mainframe.VoiceNote(ears.Muted ? "Mic muted. Voice chat pauses once she stops talking." : "Mic on. Talk and she'll pick up.", false);
        }

        private void Listen(short[] chunk)
        {
            // Their push-to-talk key, held: what the mic hears is theirs until they let go.
            lock (waking) if (pushed != null) { pushed.Add(chunk); return; }
            if (local) { CallHear(chunk); return; }
            lock (waking)
            {
                if (resting)
                {
                    preroll.Add(chunk);
                    if (preroll.Count > 5) preroll.RemoveAt(0);
                    loudRun = !speaker.Busy && Speaker.Loudness(chunk, 0, chunk.Length) >= WakeLevel ? loudRun + 1 : 0;
                    if (loudRun < 2) return;
                    resting = false;
                    loudRun = 0;
                    backlog = new System.Collections.Generic.List<short[]>(preroll);
                    preroll.Clear();
                    Post(Wake);
                    return;
                }
                if (backlog != null)
                {
                    backlog.Add(chunk);
                    if (backlog.Count > 80) backlog.RemoveAt(0);
                    return;
                }
            }
            Agent open = agent;
            if (open != null) open.Send(OverHer(chunk, open));
        }

        internal void Hear(string text) { Hear(text, text, "> you: "); }

        protected override void OnDragEnter(DragEventArgs e)
        {
            base.OnDragEnter(e);
            e.Effect = e.Data != null && e.Data.GetDataPresent(DataFormats.FileDrop) ? DragDropEffects.Copy : DragDropEffects.None;
        }

        protected override void OnDragDrop(DragEventArgs e)
        {
            base.OnDragDrop(e);
            string[] paths = e.Data == null ? null : e.Data.GetData(DataFormats.FileDrop) as string[];
            if (paths == null) return;
            string names = brain.Attachments.Give(paths);
            if (names.Length > 0) Hear(Files.Dropped, names, "> file: ");
        }

        private bool StopListening(string text)
        {
            if (!PcEars.Active) return false;
            string stopTool;
            ToolArguments stopArgs;
            if (Asides.Plain(text, out stopTool, out stopArgs) != AsideKind.Stop && !StopWords(text)) return false;
            PcEars.Stop();
            return true;
        }

        private static bool StopWords(string text) { return Regex.IsMatch(Hands.Asked(text), @"^(stop|quit|cancel|enough)\W+listening\b", RegexOptions.IgnoreCase); }

        private void Hear(string text, string shown, string prompt, int switches = 0)
        {
            text = (text ?? "").Trim();
            if (text.Length == 0) return;
            WakeRest(!SleepBusy);
            followUp.Drop();
            if (StopWatchAlong(text)) return;
            if (StopListening(text)) return;
            // Sorry, typed or said while she sulks over being thrown, makes up with her, and a plain sorry gets her forgiving line
            // back. Mid-job it still goes to the job (Zr4, F44).
            bool sorry = Sulking && prompt == "> you: " && Apology(text);
            if (sorry) Forgive();
            string afterGaming = Hands.AfterGaming(text);
            if (afterGaming != null)
            {
                WantGaming(true);
                gaming.On(clock.Elapsed.TotalSeconds);
                // "Play Minecraft" alone only opens it; said with Gaming Mode it means her hands on the game.
                text = afterGaming.StartsWith("play ", StringComparison.OrdinalIgnoreCase) ? afterGaming.TrimEnd('.', '!', ' ') + " yourself" : afterGaming;
            }
            // Asked for partway through a job or further into a long message than her brain reads, it still counts.
            if (Hands.StreamAsked(text)) Computer.Streaming = true;
            bool fileMessage = brain.Attachments.Waiting || Files.PathIn(text) != null;
            System.Collections.Generic.KeyValuePair<string, ToolArguments> planned = Hands.Plan(text);
            if (prompt == "> you: " && HearMini(text)) return;
            // Mid-job, what they say goes to the job instead of cancelling it: she says she's got it, does it, then carries on
            // (Lachy, 29 Oct: "she needs to actually listen to me mid way through").
            // Now it's two heads: the job runs on while her fast brain sorts what they said and answers (Asides.cs).
            Job running = job;
            if (MidJob(running) && prompt == "> you: ")
            {
                if (planned.Key != null) AsideTool(text, planned.Key, planned.Value, running);
                else HeardMidJob(text, running);
                return;
            }
            if (local) { talkState = TalkState.Thinking; CheckEars(clock.Elapsed.TotalSeconds); }
            if (hidden) SetHidden(false);
            hideAsked = false;
            brain.Cancel();
            LogVoiceInterruption("explicit input", audioTurn, false);
            CancelAnswerAudio();
            voice.Stop();
            int ticket = ++asking;
            heard = shown;
            box.Prompt = prompt;
            if (sorry && OnlyApology(text)) { Answer(ticket, Lines.Pick(SorryLines), TalkState.Talking); return; }
            // Their answer while she's getting to know them goes to me.md, with or without a brain. Anything else ends it and goes on.
            if (meeting.Asking && prompt == "> you: ")
            {
                string called;
                string next = meeting.Take(text, out called);
                if (next != null)
                {
                    if (called != null) CallThem(called);
                    MeetLine(ticket, next);
                    return;
                }
            }
            bool followAllowed = preferences.FollowUps && prompt == "> you: " && agent == null && (!chatting || local);
            int followInput = FollowInput(), followMic = micTalked;
            string followLine = "";
            Func<string, string> think = Think;
            if (planned.Key != null) think = delegate { return Security.Said(DoTool(planned.Key, planned.Value, ticket)); };
            string quick;
            ToolArguments quickArgs;
            // Their yes or no to her asking first (SECURITY) works before she has a brain too; anything else drops what she held.
            if (think == null && brain.Model == null && Security.Holding != null)
            {
                if (Security.Agrees(text) || Security.Declines(text)) think = delegate { return Security.Resume(text, ResumeTool) ?? Security.Left; };
                else Security.Drop();
            }
            // Volume, mute and music work before she has a brain, and so do her nap, her own moves and her animations.
            if (Hands.Heard(text, out quick, out quickArgs) && (quick == "hologram" || think == null && (quick == "clip" || quick == "nap" || quick == "watch_along" || quick == "draw" && string.IsNullOrEmpty(quickArgs.Description) || brain.Model == null && WithoutBrain(quick)))) { followAllowed = false; think = delegate { return Security.Said(DoTool(quick, quickArgs)); }; }
            if (think == null && fileMessage) think = brain.Ask;
            if (think == null)
            {
                if (brain.Model == null) { Answer(ticket, Brain.Offline, TalkState.Dormant); FindBrain(); mainframe.Restore(); return; }
                think = delegate(string question) { return brain.Ask(question, followAllowed, out followLine); };
            }
            reply = null;
            replyDone = -1;
            Say(null);
            talkState = TalkState.Thinking;
            thinkingSince = clock.Elapsed.TotalSeconds;
            slowWarned = false;
            box.Leaving = -1;
            UpdateAnimation();
            bool quiet = preferences.Quiet;
            Func<string, byte[]> cueFree;
            brain.Cues = FishCues(PickVoice(quiet, out cueFree), cueFree);
            Cloud remote = brain.Remote;
            if (!testing && (voice.Key == null || quiet || voiceBroke) && kokoro.Installed && !preferences.Quiet && !preferences.Silent) ThreadPool.QueueUserWorkItem(delegate { try { kokoro.Warm(); } catch (Exception) { } });
            if (!testing && preferences.HdVoice && (voice.Key == null || quiet || voiceBroke || preferences.Quiet) && !preferences.Silent && qwen.Installed && !qwen.Awake && clock.Elapsed.TotalSeconds >= hdRest && !HdStepsAside()) WakeHd();
            ThreadPool.QueueUserWorkItem(delegate
            {
                string said;
                if (ticket != asking) return;
                TalkState state = TalkState.Talking;
                string problem = null;
                bool stuck = false;
                try { said = Computer.Mask(think(text)); }
                catch (BrainException error) { said = error.Message == Brain.Offline ? Brain.Offline : error.Told ? error.Message : "My brain couldn't answer. The error is under BRAIN in Capri Mainframe."; problem = error.Message; state = TalkState.Dormant; stuck = Brain.Stalled(error); }
                catch (Exception error) { said = Brain.Explain(error, remote) ?? "That reply was cancelled. Try again."; problem = said; state = TalkState.Dormant; stuck = Brain.Stalled(error); }
                if (string.IsNullOrWhiteSpace(said)) { said = "My brain sent an empty reply. Try again."; problem = said; state = TalkState.Dormant; }
                try
                {
                    if (!IsDisposed) BeginInvoke((Action)delegate
                    {
                        if (stuck && ticket == asking && Hops(remote, switches)) { Hear(text, shown, prompt, switches + 1); return; }
                        if (problem != null && ticket == asking) mainframe.ShowProblem(Brain.Brief(problem) ?? (problem.Length > 60 ? problem.Substring(0, 57) + "..." : problem));
                        if (ticket == asking && followAllowed && state == TalkState.Talking && FollowUpAllowed()) followUp.Hold(followLine, ticket, followInput, followMic);
                        Answer(ticket, said, state, quiet);
                        if (said == Brain.Offline) FindBrain();
                    });
                }
                catch (InvalidOperationException) { }
            });
        }

        // A stuck NVIDIA model hands the message to the next one, twice at most, unless Stay on my model is on.
        private bool Hops(Cloud remote, int switches) { return switches < 2 && !brain.Attachments.Has && !preferences.StayOnModel && SwitchModel(remote); }

        internal static bool WithoutBrain(string tool)
        {
            return tool == "media" || tool == "play_music" || tool == "open_app" || tool == "open_website" || tool == "website_nickname" || tool == "find_file" || tool == "nap" || tool == "move_yourself" || tool == "animate" || tool == "clone" || tool == "hologram" || tool == "desktop_icons" || tool == "gaming_mode" || tool == "watch_along";
        }

        private bool SwitchModel(Cloud remote)
        {
            if (remote == null || remote.Kind != "nvidia" || brain.Remote != remote) return false;
            string old = remote.Model;
            stalled.Add(old);
            string next = Brain.Next(old, cloudModels, stalled);
            if (next == null) return false;
            ChooseModel(next, false);
            mainframe.ShowCloud(brain.Remote, cloudModels);
            mainframe.ShowProblem(old.Substring(old.IndexOf('/') + 1) + " wasn't answering, so she switched to " + next.Substring(next.IndexOf('/') + 1) + ".");
            return true;
        }

        private void Answer(int ticket, string said, TalkState state, bool quiet = false)
        {
            if (ticket != asking || IsDisposed) return;
            // Each answer owns its text and completion; talking over her cancels only its audio (ticket 35).
            int turn = ++answerTurn;
            CancelAnswerAudio();
            int audio = audioTurn;
            barging = false;
            voice.Stop();
            voiceUntil = 0;
            Func<string, byte[]> free;
            Func<string, byte[]> speak = PickVoice(quiet, out free);
            // Her Fish Audio voice says her reply's emotion cues (F54). Her bubble and every other voice never see them.
            bool cued = FishCues(speak, free);
            string words = Voice.Spoken((cued ? Brain.Cued(said ?? "") : said ?? "").Replace(Computer.Dots, "the password"), cued);
            if (speak == null || words.Length == 0 || state == TalkState.Dormant) { Begin(ticket, said, state, null); return; }
            answerVoice = ticket;
            reply = null;
            replyDone = -1;
            Say(null);
            talkState = TalkState.Thinking;
            box.Leaving = -1;
            UpdateAnimation();
            int wait = speak == free ? Math.Max(VoiceWait, FreeWait) : VoiceWait;
            hdSpeaking = preferences.HdVoice && speak == free ? ticket : -1;
            ThreadPool.QueueUserWorkItem(delegate
            {
                Thread.Sleep(wait);
                Post(delegate { if (turn == answerTurn && ticket == asking && reply == null && talkState == TalkState.Thinking) Begin(ticket, said, state, null); });
            });
            ThreadPool.QueueUserWorkItem(delegate
            {
                string problem;
                Stopwatch took = Stopwatch.StartNew();
                byte[] wav = Voiced(speak, free, words, out problem);
                if (!testing && (problem != null || (speak == free && took.ElapsedMilliseconds > 5000))) Brain.Log(speak == free ? "free voice" : "ElevenLabs voice", took.ElapsedMilliseconds, problem ?? "slow, " + (wav == null ? 0 : Voice.Seconds(wav)).ToString("0.0") + " s of speech");
                Post(delegate
                {
                    bool current = turn == answerTurn && ticket == asking && !IsDisposed;
                    bool audible = current && audio == audioTurn;
                    // How long her sound is against how much there was to say tells a clip cut short from playback that was stopped (ticket 35).
                    Brain.Log("voice delivery", took.ElapsedMilliseconds, "answer=" + turn + " audio=" + audio + " current_answer=" + answerTurn + " current_audio=" + audioTurn + " text_current=" + current + " audio_current=" + audible
                        + " seconds=" + (wav == null ? "none" : Voice.Seconds(wav).ToString("0.0", System.Globalization.CultureInfo.InvariantCulture)) + " letters=" + VoiceServer.Letters(words));
                    if (!current) return;
                    if (audible)
                    {
                        answerVoice = -1;
                        hdSpeaking = -1;
                        voiceBroken = problem != null;
                        if (problem != null) mainframe.VoiceNote(problem, wav == null);
                    }
                    if (reply == null && talkState == TalkState.Thinking) Begin(ticket, said, state, audible ? wav : null);
                    else if (audible && FollowDelivery(ticket) && talkState != TalkState.Off && box.Leaving < 0 && reply == said && (speak == free || !preferences.Quiet)) PlayReply(said, wav);
                });
            });
        }

        private bool FishCues(Func<string, byte[]> speak, Func<string, byte[]> free) { return speak != null && speak == free && preferences.ServerVoice && server.Api == VoiceServer.Fish; }

        private Func<string, byte[]> PickVoice(bool quiet, out Func<string, byte[]> free, bool fallback = true)
        {
            Func<string, byte[]> own = FreeSpeak ?? (testing || !kokoro.Installed ? null : new Func<string, byte[]>(kokoro.Speak));
            own = Readable(own);
            free = preferences.Quiet && !FreeChatOn ? null : preferences.ServerVoice ? (server.Api == VoiceServer.Files ? Readable(Served(fallback ? own : null)) : Served(fallback ? own : null)) : FreeSpeak != null ? own : (testing ? null : Hd(fallback || !preferences.HdVoice ? own : null));
            if (!fallback && voiceBroke && !quiet && !preferences.Quiet && (Speak != null || voice.Key != null)) return null;
            // Free chat stays free. A job's lines and Listen for Capri share its ears but keep the voice they picked.
            bool freeOnly = quiet || (fallback && local && !jobEars && !preferences.ListenCapri && !CallModeOn);
            Func<string, byte[]> picked = preferences.Quiet || freeOnly || voiceBroke ? null : Speak;
            if (picked == null && !freeOnly && !voiceBroke && !testing && voice.Ready && !preferences.Quiet) picked = voice.Speak;
            if (picked == null && (voice.Key == null || freeOnly || voiceBroke || preferences.Quiet)) picked = free;
            return preferences.Silent ? null : picked;
        }

        // A line her English free voice can't read, like Russian, never comes out spelled letter by letter (ticket 99): a custom
        // voice they added for that language speaks it, then a Windows voice for it, and otherwise she stays quiet for that line,
        // its bubble still shows, and once a run VOICE says how to add a voice for it.
        private Func<string, byte[]> Readable(Func<string, byte[]> own)
        {
            if (own == null) return null;
            string language = Brain.Language;
            string[] folders = { preferences.ServerApi == VoiceServer.Files ? preferences.ServerUrl : null, preferences.AsideApi == VoiceServer.Files ? preferences.AsideUrl : null };
            string[] languages = { preferences.ServerModel, preferences.AsideModel };
            string[] speakers = { preferences.ServerSpeaker, preferences.AsideSpeaker };
            return delegate(string words)
            {
                string code = VoiceLanguage.Tongue(words, language);
                if (code == null) return own(words);
                foreach (string folder in ModelFile.Find(code, folders, languages))
                {
                    try
                    {
                        VoiceServer custom = new VoiceServer { Url = folder, Api = VoiceServer.Files, Model = code };
                        for (int i = 0; i < folders.Length; i++)
                            if (string.Equals(folder, ModelFile.Clean(folders[i]), StringComparison.OrdinalIgnoreCase)) { custom.Model = languages[i]; custom.Speaker = speakers[i]; break; }
                        byte[] wav = custom.Speak(words);
                        if (wav != null && Voice.Seconds(wav) > 0) return wav;
                    }
                    catch (Exception) { }
                }
                byte[] windows = WindowsVoice.Speak(code, words);
                if (windows != null) return windows;
                if (Interlocked.CompareExchange(ref voiceLanguageNoted, 1, 0) == 0)
                {
                    string note = VoiceLanguage.Missing(code.Length == 0 ? Brain.LanguageCode(language) : code, language);
                    Post(delegate { mainframe.VoiceNote(note, false); });
                }
                return null;
            };
        }

        private byte[] Voiced(Func<string, byte[]> speak, Func<string, byte[]> free, string words, out string problem, bool fallback = true)
        {
            problem = null;
            // Her free voices style their own audio; ElevenLabs hands back a finished WAV, so its pitch, speed and glitch go on here.
            try { return speak == free ? speak(words) : VoiceFx.Styled(speak(words), words); }
            catch (VoiceException error)
            {
                problem = error.Message;
                if (!fallback || speak == free || !Broke(error.Message)) return null;
                voiceBroke = true;
                if (free == null && FreeChatOn && !testing) { Post(delegate { GetFreeVoice(); }); problem = "Out of ElevenLabs credits, so she's getting her free voice."; return null; }
                if (free == null) { problem = "Out of ElevenLabs credits. Pick PREBUILT LOCAL in Capri Mainframe and get her free voice."; return null; }
                try
                {
                    byte[] wav = free(words);
                    problem = "Out of ElevenLabs credits, so she's using her free voice.";
                    return wav;
                }
                catch (Exception other) { problem = Voice.Short("Free voice glitched: " + other.Message); return null; }
            }
            catch (Exception error) { problem = Voice.Short("Voice glitched: " + error.Message); return null; }
        }

        private static bool Broke(string problem) { return System.Text.RegularExpressions.Regex.IsMatch(problem ?? "", "quota_exceeded|run out of credits|out of ElevenLabs credits", System.Text.RegularExpressions.RegexOptions.IgnoreCase); }

        private void Begin(int ticket, string said, TalkState state, byte[] wav)
        {
            if (ticket != asking || IsDisposed || !FollowDelivery(ticket)) return;
            if (ticket == followTicket && !followLogged) { brain.Followed(said); followLogged = true; }
            if (slowWarned && brain.Remote != null && state != TalkState.Dormant) mainframe.ShowCloud(brain.Remote, cloudModels);
            reply = said;
            replyStart = clock.Elapsed.TotalSeconds;
            ToolReplied(0);
            replyDone = -1;
            talkState = state;
            thinkingSince = double.NaN;
            slowWarned = false;
            box.Leaving = -1;
            double seconds = wav == null ? 0 : Voice.Seconds(wav);
            pace = seconds < 0.2 ? LettersPerSecond : Math.Max(8, said.Length / seconds);
            Say(said);
            PlayReply(said, wav);
            if (seconds < 0.2 && state != TalkState.Dormant && TypingSound) Sfx.Type(said, pace, ticket);
            else Sfx.Untype();
        }

        private void PlayReply(string said, byte[] wav)
        {
            double seconds = wav == null ? 0 : Voice.Seconds(wav);
            voiceUntil = seconds < 0.2 ? 0 : clock.Elapsed.TotalSeconds + seconds + 0.6;
            CheckEars(clock.Elapsed.TotalSeconds);
            if (seconds < 0.2) return;
            Say(said);
            mouths = Voice.Mouths(wav, MouthRate);
            Played(wav);
            PlayVoice(wav);
        }

        private void PlayVoice(byte[] wav)
        {
            if (testing) return;
            try { voice.Play(wav); }
            catch (Exception error)
            {
                voiceUntil = 0;
                voice.Stop();
                Brain.Log("Voice playback", -1, error.Message);
                mainframe.VoiceNote(error.Message, true);
            }
        }

        private void CloseTalk()
        {
            answerTurn++;
            CancelAnswerAudio();
            voice.Stop();
            Sfx.Untype();
            hdSpeaking = -1;
            voiceUntil = 0;
            talkState = TalkState.Off;
            CheckEars(clock.Elapsed.TotalSeconds);
            thinkingSince = double.NaN;
            slowWarned = false;
            reply = null;
            replyDone = -1;
            box.Opened = -1;
            remarkTicket = -1;
            box.Leaving = -1;
            if (box.Visible) box.Hide();
            speech = null;
            if (docked) DockQuiet();
            if (reminderUp && !preferences.OnTop && IsHandleCreated) Native.SetWindowPos(Handle, new IntPtr(-2), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
            reminderUp = false;
        }

        private void UpdateTalk(double now)
        {
            if (talkState == TalkState.Off) { if (box.Visible) box.Hide(); return; }
            int revealed = reply == null ? 0 : (int)((now - replyStart) * pace);
            if (reply != null && revealed >= reply.Length && replyDone < 0)
            {
                replyDone = now;
                if (talkState == TalkState.Talking) talkState = TalkState.Online;
            }
            bool comment = remarkTicket == asking;
            double hold = reply == null ? 0 : comment ? CommentHold(reply.Length, BubbleTime) : BubbleHold(reply.Length);
            if (replyDone >= 0 && hdSpeaking != asking && box.Leaving < 0 && (comment || (!box.Scrollable && !typer.Visible && !(local && !earsReady && asking == earsNotice))) && now > voiceUntil && !voice.Busy && !speaker.Busy && !chatTail.Enabled && now > replyDone + hold) box.Leaving = now;
            if (box.Leaving >= 0 && now - box.Leaving > 0.25) { CloseTalk(); return; }
            if (docked) { DockTalk(); return; }
            if (!box.Visible && box.Opened < 0) box.Opened = now;
            box.State = talkState;
            box.Heard = heard;
            box.Reply = talkState == TalkState.Thinking ? (AsideNow(now) ?? working ?? (slowWarned ? (brain.Remote != null ? "Still thinking. Waiting for " + brain.Remote.Company + "." : SlowLocal) : null)) : reply;
            box.Revealed = revealed;
            float s = TalkScale();
            Point head = Head();
            Point feet = Feet();
            Rectangle area = Screen.FromPoint(head).WorkingArea;
            box.Update(now, s, head, new Point(feet.X, feet.Y + (int)(44 * s)), area);
            if (typer.Visible) typer.Follow(box.PanelOnScreen, area);
        }

        private void UpdateAnimation()
        {
            if (docked)
            {
                if (speech != null || talkState != TalkState.Off) frames.Start();
                else frames.Stop();
                return;
            }
            if (!preferences.Motion && !riding && seat == null && !falling && clip != glitch && clip != dangle && clip != wake && !Asleep) Play(idle);
            if ((exploring || preferences.Motion || riding || seat != null || falling || Sulking || clip != idle || speech != null || talkState != TalkState.Off) && !hidden) frames.Start(); else frames.Stop();
            RenderFrame();
        }

        private void RenderFrame()
        {
            if (!IsHandleCreated || hidden || docked || IsDisposed) return;
            double now = clock.Elapsed.TotalSeconds;
            int cell = Advance(now);
            if (arrivalDue)
            {
                arrivalDue = false;
                if ((clip == arrive || clip == perchArrive) && !instant && preferences.Motion) Arrival(now);
            }
            Clip shown = clip;
            int blinkFrom = clip == perch || clip == laydown ? PerchBlinkFrom : BlinkFrom;
            int following = (cell + 1) % clip.Count, loopCell = cell;
            if ((clip == idle || clip == perch || clip == laydown) && blinkWith != null && cell >= blinkFrom && cell < blinkFrom + blinkWith.Count) { shown = blinkWith; cell -= blinkFrom; }
            int talk = MouthCell(now, shown);
            if (PerchTalks(TalkingNow)) { shown = perchTalk; cell = loopCell; }
            else if (LieTalks(TalkingNow)) { shown = laydownTalk; cell = loopCell; }
            UpdateTalk(now);
            if (pill.Visible) UpdatePill(now);
            if (!BodyChanged(now, shown, cell, talk)) return;
            Bitmap tween = perchMix > 0 ? Tween(shown, cell, following) : null;
            if (bodySurface == null || bodySurface.Image.Size != Size)
            {
                if (bodySurface != null) bodySurface.Dispose();
                bodySurface = new Native.Surface(Width, Height);
            }
            frame = bodySurface.Image;
            using (Graphics graphics = Graphics.FromImage(frame))
            {
                graphics.Clear(Color.Transparent);
                Draw(graphics, shown, cell, talk, tween);
            }
            if (preferences.Hologram) TintHologram(frame);
            bodySurface.Show(Handle, anchor);
            bodyPaints++;
            drawnClip = shown;
            drawnArt = Art(shown);
            drawnCell = cell;
            drawnMouth = talk;
            drawnMix = perchMix;
            drawnVeil = veiled || now < veilUntil;
            drawnMotion = preferences.Motion;
            drawnHologram = preferences.Hologram;
            drawnSettled = Calm;
            drawnLean = leanAngle;
            drawnTurn = Turn() + Sway(now);
            drawnBreath = Breath(now);
            drawnTilt = Tilt(now);
            drawnNotes = preferences.Motion && notes.Exists(note => now - note.Born < NoteLife);
            drawnStep = veiled || now < veilUntil ? -1 : (long)((now - clipStart) * preferences.PerchFps);
            drawnAt = anchor;
            drawnFacing = facingLeft;
        }

        private static unsafe void TintHologram(Bitmap image)
        {
            BitmapData pixels = image.LockBits(new Rectangle(Point.Empty, image.Size), ImageLockMode.ReadWrite, PixelFormat.Format32bppPArgb);
            try
            {
                for (int y = 0; y < image.Height; y++)
                {
                    byte* row = (byte*)pixels.Scan0.ToPointer() + y * pixels.Stride;
                    for (int x = 0; x < image.Width; x++)
                    {
                        byte* pixel = row + x * 4;
                        int alpha = pixel[3];
                        pixel[0] = (byte)((pixel[0] * 224 + alpha * 31) * 3 / 1275);
                        pixel[1] = (byte)((pixel[1] * 224 + alpha * 27) * 3 / 1275);
                        pixel[2] = (byte)((pixel[2] * 224 + alpha * 8) * 3 / 1275);
                        pixel[3] = (byte)(alpha * 3 / 5);
                    }
                }
            }
            finally { image.UnlockBits(pixels); }
        }

        private bool BodyChanged(double now, Clip shown, int cell, int talk)
        {
            return frame == null || frame.Size != Size || shown != drawnClip || Art(shown) != drawnArt || cell != drawnCell || talk != drawnMouth || perchMix != drawnMix
                || anchor != drawnAt || facingLeft != drawnFacing || leanAngle != drawnLean || Turn() + Sway(now) != drawnTurn || preferences.Motion != drawnMotion || preferences.Hologram != drawnHologram
                || Calm != drawnSettled || (veiled || now < veilUntil) != drawnVeil
                || (preferences.Motion && (walking || clip == dance || clip == perchDance || drawnNotes || notes.Exists(note => now - note.Born < NoteLife)))
                // Her breathing is slower than her art, so a step too small to see isn't worth a paint.
                || (Calm && (Math.Abs(Breath(now) - drawnBreath) >= 0.25f || Math.Abs(Tilt(now) - drawnTilt) >= 0.1f));
        }

        // Above 30 fps, the in-between of a perch frame and the one after it (or the blink frame there), mixed into one spare cell.
        // Neighbouring frames barely differ, so a straight mix reads as the frame between them, with no extra art in memory.
        private Bitmap Tween(Clip shown, int cell, int following)
        {
            Clip after = shown == perchTalk || shown == laydownTalk ? shown : clip;
            if ((after == perch || after == laydown) && blinkWith != null && following >= PerchBlinkFrom && following < PerchBlinkFrom + blinkWith.Count) { after = blinkWith; following -= PerchBlinkFrom; }
            Bitmap from = Art(shown);
            int width = from.Width / shown.Count;
            if (inBetween != null && (inBetween.Width != width || inBetween.Height != from.Height)) { inBetween.Dispose(); inBetween = null; }
            if (inBetween == null) inBetween = new Bitmap(width, from.Height, PixelFormat.Format32bppPArgb);
            Mix(from, cell, Art(after), following, perchMix, inBetween);
            return inBetween;
        }

        // The strip she's drawn from: facing left, a clip's flipped art once it's in.
        private Bitmap Art(Clip shown)
        {
            Bitmap left = facingLeft ? shown.Flipped : null;
            return left ?? shown.Strip;
        }

        // Cell a of one strip mixed with weight 256ths of cell b of another, into a spare cell. Her strips are premultiplied,
        // so a straight mix of each channel fades her edges right too.
        private void Mix(Bitmap from, int a, Bitmap to, int b, int weight, Bitmap into)
        {
            int width = into.Width, high = into.Height;
            if (mixFrom == null || mixFrom.Length != width * high) { mixFrom = new int[width * high]; mixTo = new int[width * high]; }
            Pixels(from, new Rectangle(a * width, 0, width, high), mixFrom, false);
            Pixels(to, new Rectangle(b * width, 0, width, high), mixTo, false);
            uint keep = (uint)(256 - weight), take = (uint)weight;
            for (int i = 0; i < mixFrom.Length; i++)
            {
                uint p = (uint)mixFrom[i], q = (uint)mixTo[i];
                // Two channels at a time: blue and red, then green and alpha, each in its own 16 bits.
                uint blueRed = (((p & 0xFF00FF) * keep + (q & 0xFF00FF) * take + 0x800080) >> 8) & 0xFF00FF;
                uint greenAlpha = (((p >> 8) & 0xFF00FF) * keep + ((q >> 8) & 0xFF00FF) * take + 0x800080) & 0xFF00FF00;
                mixFrom[i] = (int)(greenAlpha | blueRed);
            }
            Pixels(into, new Rectangle(0, 0, width, high), mixFrom, true);
        }

        // Copies a block of a premultiplied bitmap's pixels out, or back in.
        private static void Pixels(Bitmap image, Rectangle area, int[] pixels, bool write)
        {
            BitmapData data = image.LockBits(area, write ? ImageLockMode.WriteOnly : ImageLockMode.ReadOnly, PixelFormat.Format32bppPArgb);
            try
            {
                for (int y = 0; y < area.Height; y++)
                {
                    IntPtr row = new IntPtr(data.Scan0.ToInt64() + (long)y * data.Stride);
                    if (write) Marshal.Copy(pixels, y * area.Width, row, area.Width);
                    else Marshal.Copy(row, pixels, y * area.Width, area.Width);
                }
            }
            finally { image.UnlockBits(data); }
        }

        internal void Say(string text)
        {
            speech = string.IsNullOrEmpty(text) ? null : text;
            speechStart = clock.Elapsed.TotalSeconds;
            mouths = null;
            if (speech != null) EndWalk();
            if (speech != null && Asleep) WakeRest(false);
            if (speech != null && (clip == glitch || clip == grin || clip == dance || clip == perchDance)) Play(idle);
            if (docked && speech != null) GameHud.Say(speech, talkState == TalkState.Off ? LettersPerSecond : pace);
            UpdateAnimation();
        }

        // Whether her mouth is moving: a line she's saying, or her voice chat's audio. Read after MouthCell, which ends a line.
        private bool TalkingNow { get { return (chatting && speaker.Busy) || speech != null; } }

        // On a perch, or lying, she talks in her artist's talking frames, frame for frame with the plain ones, once they're in.
        private bool PerchTalks(bool talking) { return clip == perch && talking && perchTalk.Ready(facingLeft); }

        private bool LieTalks(bool talking) { return clip == laydown && talking && laydownTalk.Ready(facingLeft); }

        // While she sits, the perch art she might need next loads off her thread, facing whichever way she does: her talking
        // frames once she's answering or in voice chat, and facing left her artist's flipped set, with the music perch while a
        // song plays.
        private void WarmPerch()
        {
            if (TalkingNow || talkState != TalkState.Off || chatting) perchTalk.Warm(facingLeft);
            if (!facingLeft) return;
            perch.Warm(true);
            perchBlink.Warm(true);
            perchBlinkGlitch.Warm(true);
            perchGlitch.Warm(true);
            perchLeave.Warm(true);
            if (musicOn) perchDance.Warm(true);
        }

        private int MouthCell(double now, Clip shown)
        {
            if (chatting && speaker.Busy) return docked || (clip == idle && shown != blinkGlitch) ? speaker.Shape() : -1;
            if (speech == null) return -1;
            int step = (int)((now - speechStart) * MouthRate);
            if (mouths != null)
            {
                if (step >= mouths.Length) { speech = null; mouths = null; return -1; }
                return docked || (clip == idle && shown != blinkGlitch) ? mouths[step] : -1;
            }
            int letter = (int)(step / MouthRate * LettersPerSecond);
            if (letter >= speech.Length) { speech = null; return -1; }
            return docked || (clip == idle && shown != blinkGlitch) ? MouthFor(speech[letter], step) : -1;
        }

        internal static int MouthFor(char letter, int step)
        {
            char lower = char.ToLowerInvariant(letter);
            if ("aeo".IndexOf(lower) >= 0) return char.IsUpper(letter) ? 4 : 3;
            if ("iuy".IndexOf(lower) >= 0) return 2;
            if ("mbp".IndexOf(lower) >= 0 || !char.IsLetter(letter)) return 0;
            return step % 2 == 1 ? 1 : 2;
        }

        private void Arrival(double now)
        {
            Bitmap target = new Bitmap(Width, Height, PixelFormat.Format32bppPArgb);
            using (Graphics graphics = Graphics.FromImage(target)) Draw(graphics, clip == perchArrive ? perch : idle, 0);
            shatter.Play(target, anchor, Screen.FromPoint(new Point(anchor.X + Width / 2, anchor.Y + Height / 2)).Bounds, false, preferences.Size);
            veilUntil = now + Shatter.Handoff;
        }

        // tween, when given, is a spare cell to draw in place of the clip's own.
        private bool Calm { get { return preferences.Motion && !dragging && !lying && clip != dangle && !Asleep; } }

        private static float Breath(double now) { return (float)Math.Sin(now * 1.75) * 2.2f; }

        private static float Tilt(double now) { return (float)Math.Sin(now * 0.95) * 0.65f; }

        private void Draw(Graphics graphics, Clip shown, int cell, int talk = -1, Bitmap tween = null)
        {
            if (veiled || clock.Elapsed.TotalSeconds < veilUntil) return;
            graphics.CompositingMode = CompositingMode.SourceOver;
            graphics.CompositingQuality = CompositingQuality.HighQuality;
            graphics.InterpolationMode = InterpolationMode.HighQualityBicubic;
            graphics.PixelOffsetMode = PixelOffsetMode.HighQuality;
            graphics.SmoothingMode = SmoothingMode.HighQuality;
            double now = clock.Elapsed.TotalSeconds;
            bool settled = Calm;
            float breathe = settled ? Breath(now) : 0;
            float tilt = settled ? Tilt(now) : 0;
            // Dizzy, she sways around her hip, so she stays sat where she landed; thrown, she tumbles around her middle.
            float sway = Sway(now);
            if (sway != 0)
            {
                float hipX = PaddingSize + preferences.Size * SitX, hipY = PaddingSize + preferences.Size * SitY;
                graphics.TranslateTransform(hipX, hipY);
                graphics.RotateTransform(sway);
                graphics.TranslateTransform(-hipX, -hipY);
            }
            graphics.TranslateTransform(Width / 2f, Height / 2f + breathe);
            graphics.RotateTransform(tilt + (float)leanAngle + Turn());
            if (facingLeft) graphics.ScaleTransform(-1, 1);
            Bitmap art = Art(shown), strip = tween ?? art;
            int width = art.Width / shown.Count;
            if (tween != null) cell = 0;
            float tall = preferences.Size * shown.Height;
            float wide = tall * width / strip.Height;
            float shiftX = shown.ShiftX * preferences.Size, shiftY = shown.ShiftY * preferences.Size;
            if (shown == walk && walking && preferences.Motion) Wisp(graphics, now, Math.Sign(walkTo - anchor.X) * (facingLeft ? -1 : 1), wide, tall);
            float nod = shown == dance || shown == perchDance ? NodDepth() : 0;
            if (nod > 0.002f) Nod(graphics, strip, cell, width, wide, tall, nod, shown == perchDance, shiftX, shiftY);
            else graphics.DrawImage(strip, new RectangleF(-wide / 2f + shiftX, -tall / 2f + shiftY, wide, tall), new RectangleF(cell * width, 0, width, strip.Height), GraphicsUnit.Pixel);
            if (talk >= 0) graphics.DrawImage(mouth.Strip, new RectangleF(-wide / 2f, -tall / 2f, wide, tall), new RectangleF(talk * width, 0, width, mouth.Strip.Height), GraphicsUnit.Pixel);
            if (notes.Count > 0 && preferences.Motion) Notes(graphics, now, seat != null || riding || onPanel);
        }

        private static GraphicsPath[] NoteShapes()
        {
            if (noteShapes != null) return noteShapes;
            string[] marks = { "\u266A", "\u266B", "\u266C" };
            GraphicsPath[] made = new GraphicsPath[marks.Length];
            FontFamily family;
            try { family = new FontFamily("Segoe UI Symbol"); }
            catch (ArgumentException) { family = new FontFamily(System.Drawing.Text.GenericFontFamilies.SansSerif); }
            using (family)
                for (int i = 0; i < marks.Length; i++)
                {
                    GraphicsPath path = new GraphicsPath();
                    path.AddString(marks[i], family, (int)FontStyle.Bold, 100, PointF.Empty, StringFormat.GenericTypographic);
                    RectangleF bounds = path.GetBounds();
                    using (Matrix centre = new Matrix())
                    {
                        float fit = 1 / Math.Max(1, bounds.Height);
                        centre.Scale(fit, fit);
                        centre.Translate(-(bounds.Left + bounds.Width / 2), -(bounds.Top + bounds.Height / 2));
                        path.Transform(centre);
                    }
                    made[i] = path;
                }
            noteShapes = made;
            return made;
        }

        private void Notes(Graphics graphics, double now, bool sitting)
        {
            GraphicsPath[] shapes = NoteShapes();
            float size = preferences.Size, high = size * 0.095f;
            float startY = sitting ? -0.1f * size : -0.25f * size, outX = sitting ? 0.33f * size : 0.36f * size;
            Color mint = Color.FromArgb(80, 230, 170), ink = Color.FromArgb(8, 6, 10);
            GraphicsState saved = graphics.Save();
            foreach (Note note in notes)
            {
                double age = now - note.Born, t = age / NoteLife;
                if (t < 0 || t >= 1) continue;
                float pop = t < 0.08 ? (float)(t / 0.08 * 1.3) : t < 0.18 ? (float)(1.3 - (t - 0.08) / 0.1 * 0.3) : 1;
                int alpha = (int)(255 * (t < 0.65 ? 1 : (1 - t) / 0.35));
                float x = note.Side * (outX + (float)(0.05 * t + 0.035 * Math.Sin(t * 5 + note.Seed)) * size);
                float y = startY - (float)(0.28 * t) * size;
                float angle = note.Side * (float)(12 + 10 * Math.Sin(note.Seed + t * 4));
                long tick = (long)(age * 30) + (long)(note.Seed * 1000);
                bool spike = (tick * 2654435761L & 1023) < 180;
                float split = (float)(1.5 + 1.5 * Math.Abs(Math.Sin(note.Seed * 7 + age * 23))) * size / 240 * (spike ? 2.5f : 1);
                Action<float, float, Color, bool> mark = delegate(float dx, float dy, Color colour, bool outline)
                {
                    graphics.ResetTransform();
                    graphics.TranslateTransform(Width / 2f + x + dx, Height / 2f + y + dy);
                    graphics.RotateTransform(angle);
                    graphics.ScaleTransform(high * pop, high * pop);
                    if (outline)
                        using (Pen edge = new Pen(colour, 0.09f)) { edge.LineJoin = LineJoin.Round; graphics.DrawPath(edge, shapes[note.Shape]); }
                    else using (Brush fill = new SolidBrush(colour)) graphics.FillPath(fill, shapes[note.Shape]);
                };
                mark(0, 0, Color.FromArgb(alpha * 3 / 4, ink), true);
                mark(-split, 0, Color.FromArgb(alpha * 3 / 5, mint), false);
                mark(split, 0, Color.FromArgb(alpha * 3 / 5, Look.Red), false);
                mark(0, 0, Color.FromArgb(alpha, Look.Pink), false);
                if (!spike) continue;
                graphics.ResetTransform();
                float band = Height / 2f + y + (float)((tick % 5) - 2) * high * 0.15f;
                graphics.SetClip(new RectangleF(0, band, Width, high * 0.22f));
                mark(note.Side * split * 2.5f, 0, Color.FromArgb(alpha, Look.Red), false);
                graphics.ResetClip();
                graphics.ResetTransform();
                float bit = Math.Max(2, size / 100);
                using (Brush square = new SolidBrush(Color.FromArgb(alpha * 2 / 3, (tick & 1) == 0 ? Look.Pink : mint)))
                    for (int i = 0; i < 3; i++) graphics.FillRectangle(square, Width / 2f + x + (float)Math.Sin(tick + i * 2.1) * high * 0.9f, Height / 2f + y + (float)Math.Cos(tick * 1.3 + i) * high * 0.7f, bit, bit);
            }
            graphics.Restore(saved);
        }

        private static readonly ImageAttributes NodEdges = Mirrored();

        private static ImageAttributes Mirrored()
        {
            ImageAttributes edges = new ImageAttributes();
            edges.SetWrapMode(WrapMode.TileFlipXY);
            return edges;
        }

        internal static void Nod(Graphics graphics, Bitmap strip, int cell, int width, float wide, float tall, float nod, bool sitting, float shiftX = 0, float shiftY = 0)
        {
            int high = strip.Height;
            float scale = tall / high, left = cell * width, drop = nod * 10, lean = nod * 0.22f;
            // Her neck rows are measured in her square; a cell that starts lower down has them higher up.
            float rowsDown = shiftY / scale;
            float head = (sitting ? 196 : 138) - rowsDown, chest = (sitting ? 232 : 176) - rowsDown, neck = (sitting ? 214 : 152) - rowsDown;
            Func<float, float, PointF> at = delegate(float x, float y)
            {
                float w = y <= head ? 1 : y >= chest ? 0 : (chest - y) / (chest - head);
                w = w * w * (3 - 2 * w);
                return new PointF((x + (neck - y) * lean * w) * scale - wide / 2f + shiftX, (y + drop * w) * scale - tall / 2f + shiftY);
            };
            Action<float, float> piece = delegate(float top, float bottom)
            {
                graphics.DrawImage(strip, new[] { at(0, top), at(width, top), at(0, bottom) }, new RectangleF(left, top, width, bottom - top), GraphicsUnit.Pixel, NodEdges);
            };
            piece(chest, high);
            for (float y = chest; y > head; y -= 3) piece(Math.Max(head, y - 3), y + 1);
            piece(0, head + 1);
        }

        private void Wisp(Graphics graphics, double now, int way, float wide, float tall)
        {
            if (way == 0) return;
            float scale = preferences.Size / 240f;
            float back = -way * wide * 0.1f;
            float reach = 78 * scale;
            Color[] colours = { Look.Pink, Look.Red, Color.FromArgb(80, 230, 170) };
            float[] rows = { 0.06f, 0.18f, 0.3f };
            for (int i = 0; i < rows.Length; i++)
            {
                float length = reach * (0.55f + 0.45f * (float)Math.Sin(now * 7.5 + i * 2.1));
                float y = tall * rows[i] + 2.5f * scale * (float)Math.Sin(now * 11 + i * 1.7);
                float thick = Math.Max(1.5f, (i == 1 ? 3f : 2f) * scale);
                RectangleF streak = new RectangleF(way > 0 ? back - length : back, y, length, thick);
                using (LinearGradientBrush brush = new LinearGradientBrush(new PointF(back, 0), new PointF(back - way * (length + 1), 0), Color.FromArgb(i == 2 ? 90 : 130, colours[i]), Color.FromArgb(0, colours[i])))
                    graphics.FillRectangle(brush, streak);
            }
            for (int i = 0; i < 4; i++)
            {
                double drift = (now * 1.6 + i * 0.27) % 1;
                float x = back - way * (float)(drift * reach * 1.1);
                float y = tall * (0.04f + 0.09f * i) + (float)Math.Sin(now * 5 + i) * 3 * scale;
                float bit = (2 + i % 2 * 2) * scale;
                using (Brush square = new SolidBrush(Color.FromArgb((int)(150 * (1 - drift)), i % 2 == 0 ? Look.Pink : Look.Red))) graphics.FillRectangle(square, x - bit / 2, y, bit, bit);
            }
        }

        private Preferences LoadPreferences()
        {
            try
            {
                using (FileStream stream = File.OpenRead(settingsPath))
                {
                    Preferences value = (Preferences)new DataContractJsonSerializer(typeof(Preferences)).ReadObject(stream);
                    if (value.Size < MinSize || value.Size > MaxSize) value.Size = 240;
                    value.PerchFps = PerchRate(value.PerchFps);
                    CheckKeys(value);
                    value.TuneOnce();
                    return value;
                }
            }
            // A new install, or settings that can't be read.
            catch { return Preferences.Fresh(); }
        }

        private void SavePreferences()
        {
            // On the task panel she's only visiting, so where she sat before is what's kept. Lying, it's where she'd sit, since
            // she comes back sitting.
            Point spot = onPanel ? panelHome : lying ? new Point(anchor.X + (int)(preferences.Size * SitX) - (int)(preferences.Size * (facingLeft ? 1 - SitRight : SitRight)), anchor.Y) : anchor;
            if (!onPanel && lying && seat != null && seat.Floor) spot.Y = seat.Y - PaddingSize - (int)(preferences.Size * SitY);
            preferences.X = spot.X;
            preferences.Y = spot.Y;
            preferences.HasPosition = true;
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(settingsPath));
                string temporary = settingsPath + ".new";
                using (FileStream stream = File.Create(temporary)) new DataContractJsonSerializer(typeof(Preferences)).WriteObject(stream, preferences);
                if (File.Exists(settingsPath)) File.Replace(temporary, settingsPath, null); else File.Move(temporary, settingsPath);
            }
            catch (IOException) { }
            catch (UnauthorizedAccessException) { }
        }

