        private void SmokeCare(System.Collections.Generic.List<string> checks)
        {
            double careNow = 0;
            DateTime careDay = new DateTime(2026, 10, 30, 10, 0, 0);
            Func<double> careClock = delegate { return careNow; };
            Func<DateTime> careCalendar = delegate { return careDay.AddSeconds(careNow); };
            Func<CareKind, string> careWords = delegate(CareKind wordKind) { return wordKind.ToString(); };
            Func<Preferences> careOff = delegate
            {
                Preferences offSettings = new Preferences();
                for (int offIndex = 0; offIndex < Care.Names.Length; offIndex++) offSettings.SetCare((CareKind)offIndex, false, offSettings.CareTime((CareKind)offIndex));
                return offSettings;
            };
            Action<bool, string> careMust = delegate(bool passed, string problem) { if (!passed) throw new Exception("Care: " + problem); };
            CareKind[] timedKinds = { CareKind.Water, CareKind.Stretch, CareKind.Eyes, CareKind.Game, CareKind.Bored };
            foreach (CareKind timedKind in timedKinds)
            {
                careNow = 0;
                Preferences timedSettings = careOff();
                timedSettings.SetCare(timedKind, true, timedSettings.CareTime(timedKind));
                Care timedCare = new Care(careClock, careCalendar, careWords);
                double timedDue = timedSettings.CareTime(timedKind) * 60.0;
                careMust(timedCare.Check(timedSettings, 0, true, "Game A", 0, 1) == null, timedKind + " fired on startup.");
                careNow = timedDue - 1;
                careMust(timedCare.Check(timedSettings, 0, true, "Game A", 0, 1) == null, timedKind + " fired early.");
                careNow = timedDue;
                careMust(timedCare.Check(timedSettings, 0, true, "Game A", 0, 1) == timedKind.ToString(), timedKind + " missed its time.");
                careNow = timedDue * 2;
                careMust(timedCare.Check(timedSettings, 0, true, "Game A", timedDue, 1) == timedKind.ToString(), timedKind + " did not repeat on its own timer.");
                timedSettings.SetCare(timedKind, false, timedSettings.CareTime(timedKind));
                careNow = timedDue * 3;
                careMust(timedCare.Check(timedSettings, 0, true, "Game A", 0, 1) == null, timedKind + " ignored Off.");
                timedSettings.SetCare(timedKind, true, 30);
                careMust(timedCare.Check(timedSettings, 0, true, "Game A", careNow, 1) == null, timedKind + " was overdue when enabled.");
                careNow += 1800;
                careMust(timedCare.Check(timedSettings, 0, true, "Game A", careNow - 1800, 1) == timedKind.ToString(), timedKind + " ignored its new interval.");
            }
            checks.Add("PASS care timers: water at 60 minutes, stretch at 90, eyes at 25, the same game at 120 and boredom at 60, with independent repeats, Off and changed intervals on a fake clock");

            Preferences heldSettings = careOff();
            heldSettings.CareWater = heldSettings.CareStretch = heldSettings.CareEyes = true;
            careNow = 0;
            Care heldCare = new Care(careClock, careCalendar, careWords);
            heldCare.Check(heldSettings, 0, true, null, 0, 1);
            foreach (double heldAt in new[] { 1500.0, 3600, 5400, 7199 })
            {
                careNow = heldAt;
                careMust(heldCare.Check(heldSettings, 0, false, null, 0, 1) == null, "a held check-in escaped.");
            }
            careMust(heldCare.Check(heldSettings, 0, true, null, 0, 1) != null, "held check-ins were all lost.");
            careNow = 7200;
            careMust(heldCare.Check(heldSettings, 0, true, null, 0, 1) == null, "held check-ins piled up on the next tick.");
            careNow = 7201;
            careMust(heldCare.Check(heldSettings, 0, true, null, 0, 1) == null, "a second overdue check-in escaped.");
            checks.Add("PASS care holds: overdue check-ins coalesce to one when clear and the other timers start fresh, without a pile on following ticks");

            Preferences idleSettings = careOff();
            idleSettings.CareWater = true;
            careNow = 0;
            Care idleCare = new Care(careClock, careCalendar, careWords);
            idleCare.Check(idleSettings, 0, true, null, 0, 1);
            careNow = 3600;
            careMust(idleCare.Check(idleSettings, Care.Away + 1, true, null, 0, 1) == null, "an idle PC got a check-in.");
            careNow = 7200;
            careMust(idleCare.Check(idleSettings, 0, true, null, 0, 1) == null, "idle time counted on return.");
            careNow = 10799;
            careMust(idleCare.Check(idleSettings, 0, true, null, 0, 1) == null, "the idle reset started before the user returned.");
            careNow = 10800;
            careMust(idleCare.Check(idleSettings, 0, true, null, 0, 1) == "Water", "the timer did not restart after idle.");
            checks.Add("PASS care idle: over ten minutes idle clears held check-ins and a fresh hour starts when they return");

            Preferences nightSettings = careOff();
            nightSettings.CareLate = true;
            careNow = 0;
            careDay = new DateTime(2026, 10, 30, 23, 0, 0);
            Care nightCare = new Care(careClock, careCalendar, careWords);
            careMust(nightCare.Check(nightSettings, 0, true, null, 0, 1) == null, "the sleep nudge came before 1 am.");
            careNow = 7200;
            careMust(nightCare.Check(nightSettings, 0, true, null, 0, 1) == "Late", "the 1 am sleep nudge was missed.");
            careNow = 10800;
            careMust(nightCare.Check(nightSettings, 0, true, null, 0, 1) == null, "sleep nudged twice in a night.");
            Care restartedNight = new Care(careClock, careCalendar, careWords);
            careMust(restartedNight.Check(nightSettings, 0, true, null, 0, 1) == null, "a restart repeated the same night's nudge.");
            careNow = 93600;
            careMust(nightCare.Check(nightSettings, 0, true, null, 0, 1) == "Late", "the next night was not a new night.");
            Preferences eveningSettings = careOff();
            eveningSettings.CareLate = true;
            eveningSettings.CareLateHour = 23;
            careNow = 0;
            Care eveningCare = new Care(careClock, careCalendar, careWords);
            careMust(eveningCare.Check(eveningSettings, 0, true, null, 0, 1) == "Late", "an edited bedtime was ignored.");
            careNow = 7200;
            careMust(eveningCare.Check(eveningSettings, 0, true, null, 0, 1) == null, "midnight counted as a second night.");
            Preferences staleNightSettings = careOff();
            staleNightSettings.CareLate = true;
            Care staleNight = new Care(careClock, careCalendar, careWords);
            staleNight.Check(staleNightSettings, 0, false, null, 0, 1);
            careNow = 32400;
            careMust(staleNight.Check(staleNightSettings, 0, true, null, 0, 1) == null, "last night's held nudge arrived in daylight.");
            checks.Add("PASS care nights: the chosen hour fires once per night across midnight and restarts, returns next night and expires in the morning");

            Preferences mealSettings = careOff();
            mealSettings.CareMeal = true;
            careNow = 0;
            careDay = new DateTime(2026, 10, 30, 11, 0, 0);
            Care mealCare = new Care(careClock, careCalendar, careWords);
            mealCare.Check(mealSettings, 0, true, null, 0, 1);
            careNow = 3599;
            careMust(mealCare.Check(mealSettings, 0, true, null, 0, 1) == null, "lunch was early.");
            careNow = 3600;
            careMust(mealCare.Check(mealSettings, 0, true, null, 0, 1) == "Meal", "lunch was missed.");
            careNow = 3700;
            careMust(mealCare.Check(mealSettings, 0, true, null, 0, 1) == null, "lunch repeated.");
            careNow = 25200;
            careMust(mealCare.Check(mealSettings, 0, true, null, 0, 1) == "Meal", "dinner was missed.");
            Care afternoonCare = new Care(careClock, careCalendar, careWords);
            careMust(afternoonCare.Check(mealSettings, 0, true, null, 0, 1) == null, "starting after lunch counted as being on since morning.");
            careNow = 0;
            Care staleMeal = new Care(careClock, careCalendar, careWords);
            staleMeal.Check(mealSettings, 0, true, null, 0, 1);
            careNow = 3600;
            staleMeal.Check(mealSettings, 0, false, null, 0, 1);
            careNow = 10800;
            careMust(staleMeal.Check(mealSettings, 0, true, null, 0, 1) == null, "a held lunch arrived hours late.");
            checks.Add("PASS care meals: lunch and dinner only after starting before lunch, once per mealtime, with stale held meals discarded");

            Preferences gameSettings = careOff();
            gameSettings.CareGame = true;
            careNow = 0;
            Care gameCare = new Care(careClock, careCalendar, careWords);
            gameCare.Check(gameSettings, 0, true, "Game A", 0, 1);
            careNow = 7199;
            careMust(gameCare.Check(gameSettings, 0, true, "Game A", 0, 1) == null, "a game break came early.");
            careNow = 7200;
            careMust(gameCare.Check(gameSettings, 0, true, "Game B", 0, 1) == null, "two different games counted as one session.");
            careNow = 14400;
            careMust(gameCare.Check(gameSettings, 0, false, "Game B", 0, 1) == null, "a game break escaped full screen.");
            careNow = 14401;
            careMust(gameCare.Check(gameSettings, 0, true, null, 0, 1) == "Game", "a held break was lost when the game closed.");
            checks.Add("PASS care games: changing games starts a new two-hour session and a held break can appear when the game closes");

            string careFolder = Path.Combine(Path.GetDirectoryName(settingsPath), "care-smoke", Guid.NewGuid().ToString("N"));
            string careFile = Path.Combine(careFolder, "check-ins.md");
            CareLines fileLines = new CareLines(careFile);
            bool careFiles = fileLines.Create();
            if (!careFiles) checks.Add("LIMIT care lines: this environment could not create the smoke check-ins.md");
            else
            {
                string previousBored = null;
                for (int boredDraw = 0; boredDraw < 12; boredDraw++)
                {
                    string boredLine = fileLines.Pick(CareKind.Bored);
                    careMust(boredLine != null && boredLine != previousBored, "boredom repeated the same line.");
                    previousBored = boredLine;
                }
                string editedCare = "## Water\n- A sip, please.\n\n## Bored\n- Edited boredom.\n\n## Bored noticed\n- Edited hello.\n\n## Bored ignored\n- Edited sulk.\n";
                File.WriteAllText(careFile, editedCare);
                careMust(fileLines.Create() && File.ReadAllText(careFile) == editedCare, "defaults overwrote an edited file.");
                careNow = 0;
                Care editedTimer = new Care(careClock, careCalendar, fileLines.Pick);
                editedTimer.Check(idleSettings, 0, true, null, 0, 1);
                careNow = 3600;
                careMust(editedTimer.Check(idleSettings, 0, true, null, 0, 1) == "A sip, please.", "an edited line was not read at delivery.");
                File.WriteAllText(careFile, editedCare.Replace("- A sip, please.", ""));
                careNow = 7200;
                careMust(editedTimer.Check(idleSettings, 0, true, null, 0, 1) == null, "a removed line fell back to a default.");
                File.WriteAllText(careFile, "");
                careMust(fileLines.Pick(CareKind.Bored) == null && fileLines.Pick("Bored ignored") == null, "an empty check-ins file still spoke.");
                File.Delete(careFile);
                careMust(fileLines.Pick(CareKind.Water) == null && !File.Exists(careFile), "a deleted check-ins file was silently restored.");
                File.WriteAllText(careFile, editedCare);
                string legacyCareFile = Path.Combine(careFolder, "older-check-ins.md");
                File.WriteAllText(legacyCareFile, "Their old personality text.\n");
                CareLines legacyCareLines = new CareLines(legacyCareFile);
                careMust(legacyCareLines.Create() && File.ReadAllText(legacyCareFile).StartsWith("Their old personality text.\n", StringComparison.Ordinal) && legacyCareLines.Pick(CareKind.Water) != null, "existing personality text did not keep its text and get defaults once.");
                checks.Add("PASS care lines: editable local defaults, live edits, removed lines, empty or deleted files, editable boredom replies and no consecutive boredom repeats");
            }

            DataContractJsonSerializer careJson = new DataContractJsonSerializer(typeof(Preferences));
            Preferences oldCare = (Preferences)careJson.ReadObject(new MemoryStream(System.Text.Encoding.UTF8.GetBytes("{}")));
            careMust(oldCare.CareWater && oldCare.CareStretch && oldCare.CareBored && !oldCare.CareEyes && oldCare.CareWaterMinutes == 60 && oldCare.CareStretchMinutes == 90 && oldCare.CareEyesMinutes == 25 && oldCare.CareLateHour == 1 && oldCare.CareGameMinutes == 120, "older settings did not get the defaults.");
            Preferences carePreferencesWas = preferences;
            Care careWas = care;
            CareLines careLinesWas = careLines;
            Func<bool> careScreenWas = FullScreen;
            double careNoticedWas = noticed, careNudgeWas = nudgeOut, careGapWas = nudgeGap, careVoiceWas = voiceUntil, carePopWas = popOut;
            int careClicksWas = noticedClicks;
            bool careBoredWas = boredAsk, careShushWas = shushed, careChatWas = chatting, careHiddenWas = hidden;
            string careSpeechWas = speech, careWorkWas = working;
            Job careJobWas = job;
            TalkState careTalkWas = talkState;
            try
            {
                preferences = new Preferences();
                mainframe.Sync();
                for (int careUi = 0; careUi < Care.Names.Length; careUi++)
                {
                    CareKind uiKind = (CareKind)careUi;
                    bool uiOn = preferences.CareOn(uiKind);
                    careMust(mainframe.CareShown(uiKind) == uiOn, "a HABITS toggle disagreed with its setting.");
                    mainframe.FlipCare(uiKind);
                    careMust(preferences.CareOn(uiKind) != uiOn && LoadPreferences().CareOn(uiKind) != uiOn, "a HABITS toggle did not save.");
                    int uiTime = uiKind == CareKind.Late ? 23 : uiKind == CareKind.Meal ? 240 : 30;
                    mainframe.PickCareTime(uiKind, uiTime);
                    careMust(preferences.CareTime(uiKind) == uiTime && LoadPreferences().CareTime(uiKind) == uiTime && mainframe.CareTimeShown(uiKind) == (uiKind == CareKind.Late ? "11 pm" : uiKind == CareKind.Meal ? "4 h" : "30 min"), "a HABITS time did not show and save.");
                }
                checks.Add("PASS care HABITS: seven compact toggle and time rows match defaults and save every on/off and timing change");
                preferences = careOff();
                preferences.CareBored = true;
                preferences.CheckIns = true;
                if (careFiles) careLines = fileLines;
                careNow = 0;
                care = new Care(careClock, careCalendar, careWords);
                FullScreen = delegate { return false; };
                shushed = chatting = hidden = false;
                speech = working = null;
                job = null;
                talkState = TalkState.Off;
                voiceUntil = 0;
                popOut = nudgeOut = -1;
                nudgeGap = NudgeGap;
                noticed = 0;
                noticedClicks = clicks;
                boredAsk = false;
                careMust(PopFree(0, 0), "the smoke companion was not free for pop-ins.");
                CheckCare(0, 0);
                careNow = 3600;
                shushed = true;
                CheckCare(careNow, 0);
                careMust(speech == null && !PopFree(careNow, 0), "quiet did not hold care and pop-ins together.");
                shushed = false;
                FullScreen = delegate { return true; };
                CheckCare(careNow, 0);
                careMust(speech == null && !PopFree(careNow, 0), "full screen did not hold care and pop-ins together.");
                FullScreen = delegate { return false; };
                chatting = true;
                CheckCare(careNow, 0);
                careMust(speech == null && !PopFree(careNow, 0), "voice chat did not hold care and pop-ins together.");
                chatting = false;
                working = "a job";
                CheckCare(careNow, 0);
                careMust(speech == null && working == "a job", "care interrupted a job.");
                working = null;
                speech = "already speaking";
                CheckCare(careNow, 0);
                careMust(speech == "already speaking", "care replaced her speech.");
                speech = null;
                voiceUntil = careNow + 10;
                CheckCare(careNow, 0);
                careMust(speech == null, "care interrupted playing voice audio.");
                voiceUntil = 0;
                CheckCare(careNow, 0);
                careMust(speech == "Bored" && noticed == careNow && nudgeOut == careNow + 20 && boredAsk, "boredom did not count as an attention ask.");
                // She says it in her bubble, not only with her mouth, and her own bubble isn't them noticing her.
                UpdateTalk(clock.Elapsed.TotalSeconds);
                careMust(reply == "Bored" && talkState == TalkState.Talking && remarkTicket == asking && heard == "check-in" && box.Visible, "her check-in didn't show in her bubble.");
                CheckNudge(careNow + 1, 0);
                careMust(nudgeOut == careNow + 20 && boredAsk && noticed == careNow, "her own bubble counted as them noticing her.");
                CloseTalk();
                CheckNudge(careNow + 21, 0);
                if (careFiles) careMust(speech == "Edited sulk.", "a boredom follow-up ignored check-ins.md.");
                CloseTalk();
                careNow = 7200;
                CheckNudge(careNow, 0);
                CheckCare(careNow, 0);
                careMust(speech == null && nudgeOut < 0 && nudgeGap == NudgeGap * 2, "boredom doubled up with the two-hour ask or lost the sulk's longer wait.");
                careNow = 10821;
                CheckCare(careNow, 0);
                careMust(speech == "Bored", "boredom did not return after the longer wait.");
                // Clicked while her ask is still up, her happy line takes its place.
                noticedClicks = clicks - 1;
                careNow++;
                CheckNudge(careNow, 0);
                if (careFiles) careMust(speech == "Edited hello." && reply == "Edited hello.", "noticing her ignored the edited reply.");
                careMust(nudgeGap == NudgeGap && nudgeOut < 0 && noticed == careNow, "noticing her did not reset the attention wait.");
                CloseTalk();
                CheckCare(careNow, 0);
                careNow += 3599;
                CheckCare(careNow, 0);
                careMust(speech == null, "boredom came less than an hour after attention.");
                careNow++;
                CheckCare(careNow, 0);
                careMust(speech == "Bored", "attention left boredom on the old longer wait.");
                CloseTalk();
                CheckNudge(careNow, Care.Away + 1);
                careMust(noticed < 0 && nudgeOut < 0, "idle did not reset the shared attention clock.");
                CheckNudge(careNow + 1, 0);
                careMust(noticed == careNow + 1, "attention did not restart on return.");
                checks.Add("PASS care attention: boredom shares the attention clock and editable sulk, backs off when ignored, resets on idle and never doubles up with the old two-hour ask");
                checks.Add("PASS care delivery: check-ins show in her bubble, care and pop-ins share quiet, full-screen and voice-chat holds; jobs, speech and voice audio are left alone");
            }
            finally
            {
                CloseTalk();
                preferences = carePreferencesWas;
                care = careWas;
                careLines = careLinesWas;
                FullScreen = careScreenWas;
                noticed = careNoticedWas;
                noticedClicks = careClicksWas;
                nudgeOut = careNudgeWas;
                nudgeGap = careGapWas;
                boredAsk = careBoredWas;
                shushed = careShushWas;
                chatting = careChatWas;
                hidden = careHiddenWas;
                speech = careSpeechWas;
                working = careWorkWas;
                job = careJobWas;
                talkState = careTalkWas;
                voiceUntil = careVoiceWas;
                popOut = carePopWas;
                SavePreferences();
                mainframe.Sync();
            }
        }

        private static void SmokeTalkLogic(System.Collections.Generic.List<string> checks)
        {
            string[,] parts = {
                { "One thought.", "One thought.", "" },
                { "One thought.\n|||\nAnother thought.", "One thought.", "Another thought." },
                { "One.\n|||\nTwo.\n|||\nThree.", "One.", "Two.\nThree." },
                { "|||\nOne thought.", "One thought.", "" },
                { "One thought.\n|||", "One thought.", "" },
                { "|||", "", "" },
                { "```text\n|||\n```", "```text\n|||\n```", "" },
                { "```text\n|||\n```\n|||\nAfter code.", "```text\n|||\n```", "After code." },
                { "~~~text\n|||\n~~~", "~~~text\n|||\n~~~", "" },
                { "One ||| thought.", "One ||| thought.", "" },
                { "[grin] One.\r\n ||| \r\n[glitch] Two.", "[grin] One.", "[glitch] Two." }
            };
            for (int partAt = 0; partAt < parts.GetLength(0); partAt++)
            {
                string after;
                if (Replies.Split(parts[partAt, 0], out after) != parts[partAt, 1] || after != parts[partAt, 2]) throw new Exception("Reply separator changed part " + partAt + ".");
            }
            FollowUp pending = new FollowUp();
            pending.Hold("Second thought.", 3, 4, 5);
            if (pending.Take(1, 3, 4, 5, true, false) != null || pending.Take(20, 3, 4, 5, true, true) != null || pending.Take(21, 3, 4, 5, true, true) != null || pending.Take(22, 3, 4, 5, true, true) != "Second thought." || pending.Take(30, 3, 4, 5, true, true) != null) throw new Exception("Her follow-up did not wait for the first answer and a beat, or followed itself.");
            pending.Hold("Drop for speech.", 3, 4, 5);
            if (pending.Take(40, 3, 4, 6, true, true) != null || pending.Line != null) throw new Exception("Speaking first kept her follow-up.");
            pending.Hold("Drop for typing.", 3, 4, 5);
            if (pending.Take(40, 3, 6, 5, true, true) != null || pending.Line != null) throw new Exception("Typing first kept her follow-up.");
            pending.Hold("Drop for a new answer.", 3, 4, 5);
            if (pending.Take(40, 4, 4, 5, true, true) != null || pending.Line != null) throw new Exception("A new answer kept her old follow-up.");
            pending.Hold("Drop for a job.", 3, 4, 5);
            if (pending.Take(40, 3, 4, 5, false, true) != null || pending.Line != null) throw new Exception("A busy job allowed a follow-up.");
            checks.Add("PASS follow-up separator keeps one or two parts, folds a third into the second, handles empty ends and CRLF, preserves tags and fenced code; delivery waits for the first answer and a beat, drops for speech, typing, new answers and jobs, and runs once");

            foreach (string start in new[] { "watch this with me", "watch this video with me", "let's watch this", "react to this", "Capri, could you watch this stream with me please?" })
            {
                string startTool;
                ToolArguments startArgs;
                if (!Hands.Heard(start, out startTool, out startArgs) || startTool != "watch_along" || startArgs.Action != "start") throw new Exception("Watching together missed: " + start);
            }
            foreach (string other in new[] { "watch out", "watch your mouth", "watch for the delivery" })
            {
                string otherTool;
                ToolArguments otherArgs;
                if (Hands.Heard(other, out otherTool, out otherArgs) && otherTool == "watch_along") throw new Exception("Watching together took: " + other);
            }
            Func<bool> watchActiveWas = WatchAlong.Active;
            WatchAlong.Active = delegate { return true; };
            foreach (string stop in new[] { "stop watching", "stop watching with me", "stop reacting", "we're done watching" })
            {
                string stopTool;
                ToolArguments stopArgs;
                if (!Hands.Heard(stop, out stopTool, out stopArgs) || stopTool != "watch_along" || stopArgs.Action != "stop") throw new Exception("Watching together missed its stop: " + stop);
            }
            WatchAlong.Active = watchActiveWas;
            if (WatchAlong.Request("stop watching") != null) throw new Exception("Stop watching took a request with nothing being watched.");
            WatchMemory memory = new WatchMemory { Limit = 4 };
            if (memory.Add("First line.") != null || memory.Add("Second line.") != null || memory.Add("Third line.") != null || memory.Add("Fourth line.") != "First line.\nSecond line." || memory.Count != 2 || memory.Text != "Third line.\nFourth line.") throw new Exception("Watch-along did not fold the oldest half at its limit.");
            using (WatchAlong watching = new WatchAlong())
            using (PcSound heardSound = new PcSound())
            {
                watching.Memory.Limit = 4;
                watching.Memory.Add("Only in memory.");
                watching.Folds.Enqueue("Old words.");
                watching.Picture = new byte[] { 1, 2 };
                watching.CanHear = true;
                watching.Speaking = delegate { return true; };
                byte[] sound = new byte[] { 0, 64, 0, 64 };
                watching.Sample(sound, Ears.Rate, heardSound);
                if (heardSound.Sound) throw new Exception("Watch-along transcribed her own voice.");
                watching.Speaking = delegate { return false; };
                watching.Sample(sound, Ears.Rate, heardSound);
                if (!heardSound.Sound || watching.QuietFor >= WatchAlong.SoundGap) throw new Exception("Watch-along missed sound or called it a gap.");
                if (watching.Ended(WatchAlong.EndSeconds - 1) || !watching.Ended(WatchAlong.EndSeconds)) throw new Exception("Watch-along did not end after inactivity.");
                watching.Dispose();
                if (watching.Memory.Count != 0 || watching.Folds.Count != 0 || watching.Picture != null) throw new Exception("Stopping watch-along kept its rolling memory.");
            }
            Preferences fresh = new Preferences();
            Preferences older;
            using (MemoryStream settings = new MemoryStream(System.Text.Encoding.UTF8.GetBytes("{}"))) older = (Preferences)new DataContractJsonSerializer(typeof(Preferences)).ReadObject(settings);
            if (!fresh.FollowUps || !older.FollowUps || fresh.WatchMemory != WatchAlong.DefaultLines || older.WatchMemory != WatchAlong.DefaultLines) throw new Exception("New talk settings lost their defaults in old settings.");
            if (SelfKnow.Matching("Explain the Follow-up messages setting") == null || SelfKnow.Matching("Explain Watch-along memory") == null) throw new Exception("Her new talk settings have no self knowledge.");
            checks.Add("PASS watch-along phrases and stops go through Hands.Heard, unrelated watch phrases stay out, rolling words fold at their line limit, sound gaps exclude her voice, inactivity ends it, stop clears memory, and old settings get the defaults and help");
        }

        private static void SmokeTalkBrain(System.Collections.Generic.List<string> checks, string root)
        {
            root = Path.Combine(root, Guid.NewGuid().ToString("N"));
            string oldOllama = Brain.Ollama, oldAnthropic = Brain.Anthropic, oldNotes = Brain.MemoryPath, oldMemories = Brain.MemoriesPath, oldTranscripts = Brain.TranscriptPath, oldLog = Brain.LogPath;
            bool oldKeeping = Brain.Keeping, oldDigging = Brain.Digging;
            Brain oldKeeper = Brain.Keeper;
            System.Net.Sockets.TcpListener talkServer = null;
            System.Collections.Generic.List<string> talkRequests = new System.Collections.Generic.List<string>();
            try
            {
                Directory.CreateDirectory(root);
                Brain.MemoryPath = Brain.MemoriesPath = Brain.LogPath = null;
                Brain.TranscriptPath = root;
                Brain.Keeping = true;
                Brain.Digging = false;
                Brain.Keeper = null;
                string[] replies = { "[grin] First thought.\n|||\n[glitch] Second thought.", "```text\n|||\n```\n|||\nAfter the code.", "Just a single thought.", "One thought.\n|||\nA second thought.", "Opened Calculator.\n|||\nAnother thought after the job." };
                string[] bodies = Array.ConvertAll(replies, delegate(string rawReply) { return "{\"message\":{\"content\":" + Voice.Quote(rawReply) + "}}"; });
                Brain.Ollama = FakeServer(bodies, talkRequests, out talkServer);
                Brain first = new Brain { Model = "talk-check" };
                first.Load(Path.Combine(root, "chat.json"));
                string after;
                string said = first.Ask("Tell me a thought", true, out after);
                if (said != "[grin] First thought." || after != "[glitch] Second thought." || first.History.Count != 2 || first.History[1].Content != said || File.ReadAllText(Path.Combine(root, "chat.json")).Contains("Second thought")) throw new Exception("Her first chat saved or spoke the pending follow-up.");
                first.Followed(after);
                if (first.History.Count != 3 || first.History[2].Role != "assistant" || first.History[2].Content != after || !File.ReadAllText(Path.Combine(root, "chat.json")).Contains("Second thought")) throw new Exception("Her delivered follow-up was not an assistant message.");
                System.Collections.Generic.List<ChatMessage> turn = Brain.LastTurn(first.History);
                if (turn.Count != 2 || turn[0].Content != "Tell me a thought" || !turn[1].Content.Contains("First thought") || !turn[1].Content.Contains("Second thought")) throw new Exception("A follow-up hid their last message from yes and remember that.");
                System.Collections.Generic.List<ChatMessage> conversation = Brain.Conversation(first.History);
                if (conversation.Count != 2 || conversation[1].Content != said + "\n" + after || first.History.Count != 3) throw new Exception("Her local brain got consecutive assistant turns or her saved bubbles were merged.");
                string written = string.Join("\n", Array.ConvertAll(Directory.GetFiles(root, "*.md"), File.ReadAllText));
                if (!written.Contains("First thought") || !written.Contains("Second thought") || written.Contains("|||")) throw new Exception("Her two delivered messages did not reach the transcript cleanly.");
                Brain code = new Brain { Model = "talk-check" };
                if (!code.Ask("Show me the separator in code", true, out after).Contains("|||") || after != "After the code.") throw new Exception("Cleaning a code block swallowed the real follow-up.");
                Brain plain = new Brain { Model = "talk-check" };
                if (plain.Ask("Tell me a thought", true, out after) != "Just a single thought." || after.Length != 0) throw new Exception("A brain ignoring the separator changed.");
                Brain disabled = new Brain { Model = "talk-check" };
                if (!disabled.Ask("Tell me a thought", false, out after).Contains("A second thought.") || after.Length != 0) throw new Exception("Disabled follow-ups lost part of the answer.");
                int jobs = 0;
                Brain toolReply = new Brain { Model = "talk-check", Act = delegate { jobs++; return "Opened Calculator."; } };
                toolReply.Ask("open calculator", true, out after);
                if (jobs != 1 || after.Length != 0) throw new Exception("A tool reply produced a follow-up or changed the tool.");
                if (talkRequests.Count != replies.Length || !talkRequests[0].Contains("|||")) throw new Exception("Follow-ups took another brain call or missed their instruction.");
                talkServer.Stop();
                talkRequests.Clear();
                Brain.Anthropic = FakeServer(new[] { "{\"content\":[{\"type\":\"text\",\"text\":\"SAW: A train. SAY: SKIP\"}]}", "{\"content\":[{\"type\":\"text\",\"text\":\"SAW: A train. SAY: SKIP\"}]}" }, talkRequests, out talkServer);
                foreach (string model in new[] { "claude-haiku-5-5", "claude-sonnet-5-5" })
                {
                    Brain seeing = new Brain { Model = model, Remote = new Cloud("sk-ant-test", model) };
                    seeing.Quick(Brain.Persona + Brain.Speech(), WatchAlong.Ask(new System.Collections.Generic.List<string>(), "Video", "The train left.", true), WatchAlong.ReplyTokens, new byte[] { 1, 2, 3 });
                }
                if (talkRequests.Count != 2 || !talkRequests[0].Contains("claude-haiku-5-5") || !talkRequests[1].Contains("claude-haiku-5-5") || !talkRequests[1].Contains("image/jpeg") || !talkRequests[1].Contains("\"thinking\":{\"type\":\"disabled\"}")) throw new Exception("Watch-along changed the chosen model or omitted its picture and plain reply mode.");
                first.Saw("A pilot missed the last train.", null, false, true);
                written = string.Join("\n", Array.ConvertAll(Directory.GetFiles(root, "*.md"), File.ReadAllText));
                if (!written.Contains("She watched with you: A pilot missed the last train.")) throw new Exception("A folded watch-along note did not reach the real transcript.");
                Brain.Unsee();
                checks.Add("PASS Brain.Ask splits before Clean without another call, keeps tags and code, ignores missing separators, stores only delivered follow-ups as assistant messages, keeps tool replies whole, and Watch-along uses her fast Claude with pictures and folds into her real transcript");
            }
            catch (System.Net.Sockets.SocketException) { checks.Add("LIMIT talk features could not open their local brain stand-in"); }
            catch (UnauthorizedAccessException) { checks.Add("LIMIT talk features could not write their isolated transcript check"); }
            catch (IOException) { checks.Add("LIMIT talk features could not read or write their isolated transcript check"); }
            finally
            {
                if (talkServer != null) talkServer.Stop();
                Brain.Ollama = oldOllama; Brain.Anthropic = oldAnthropic;
                Brain.MemoryPath = oldNotes; Brain.MemoriesPath = oldMemories; Brain.TranscriptPath = oldTranscripts; Brain.LogPath = oldLog;
                Brain.Keeping = oldKeeping; Brain.Digging = oldDigging; Brain.Keeper = oldKeeper;
            }
        }

        private void SmokeTalkSettings(System.Collections.Generic.List<string> checks)
        {
            bool oldFollow = preferences.FollowUps, oldCaught = preferences.CaughtUp;
            int oldMemory = preferences.WatchMemory;
            Job oldJob = job;
            string oldWorking = working;
            WatchAlong oldWatch = watchAlong;
            try
            {
                mainframe.FlipFollowUps();
                if (preferences.FollowUps == oldFollow || mainframe.FollowUpsShown != preferences.FollowUps || LoadPreferences().FollowUps != preferences.FollowUps) throw new Exception("Follow-up messages did not switch and save.");
                mainframe.FlipFollowUps();
                SetWatchMemory(48);
                if (mainframe.WatchMemoryShown != 48 || LoadPreferences().WatchMemory != 48) throw new Exception("Watch-along memory did not show and save.");
                preferences.FollowUps = true;
                job = new Job("stand-in job");
                working = "Working.";
                followUp.Hold("Must stay quiet.", asking, FollowInput(), micTalked);
                CheckFollowUp(clock.Elapsed.TotalSeconds);
                if (followUp.Line != null || FollowUpAllowed()) throw new Exception("The real job gate kept a follow-up.");
                watchAlong = new WatchAlong();
                watchAlong.Memory.Limit = 4;
                preferences.CaughtUp = false;
                WatchHeard(watchAlong, "One."); WatchHeard(watchAlong, "Two."); WatchHeard(watchAlong, "Three."); WatchHeard(watchAlong, "Four.");
                if (watchAlong.Folds.Count != 0 || watchAlong.Memory.Count != 2) throw new Exception("Caught up off kept the old dialogue.");
                preferences.CaughtUp = true;
                WatchHeard(watchAlong, "Five."); WatchHeard(watchAlong, "Six.");
                if (watchAlong.Folds.Count != 1 || watchAlong.Folds.Dequeue() != "Three.\nFour.") throw new Exception("Caught up on missed the folded dialogue.");
                WatchAlong ended = watchAlong;
                string endTool;
                ToolArguments endArgs;
                if (!Hands.Heard("stop watching with me", out endTool, out endArgs)) throw new Exception("The watch-along stop was not heard.");
                Hands.Do(endTool, endArgs);
                if (watchAlong != null || ended.Memory.Count != 0) throw new Exception("Her watch-along tool did not stop and clear its memory.");
                checks.Add("PASS Mainframe switches and saves follow-ups and watch-along memory, the real job gate drops follow-ups, caught up controls folding, and the spoken stop reaches her mode and clears it");
                checks.Add("LIMIT follow-up timing with real voices, PC loopback sound, local recognition, video endings and watch-along reactions need a live session");
            }
            finally
            {
                EndWatchAlong();
                watchAlong = oldWatch;
                preferences.FollowUps = oldFollow;
                preferences.CaughtUp = oldCaught;
                preferences.WatchMemory = oldMemory;
                job = oldJob;
                working = oldWorking;
                followUp.Drop();
                SavePreferences();
                mainframe.Sync();
            }
        }

        private void SmokeListen(System.Collections.Generic.List<string> checks)
        {
            Func<int, Func<bool>, PcSound> listenCaptureWas = PcEars.Capture;
            Func<bool> listenSpeakingWas = PcEars.Speaking;
            Func<short[], string> listenHearingWas = Hearing.Run;
            bool listenChatWas = chatting;
            try
            {
                byte[] listenStereo = new byte[48000 * 4];
                for (int listenFrame = 0; listenFrame < 48000; listenFrame++)
                {
                    double listenTone = Math.Sin(listenFrame * 2 * Math.PI * 220 / 48000);
                    short listenLeft = (short)(6000 * listenTone), listenRight = (short)(18000 * listenTone);
                    listenStereo[listenFrame * 4] = (byte)listenLeft;
                    listenStereo[listenFrame * 4 + 1] = (byte)(listenLeft >> 8);
                    listenStereo[listenFrame * 4 + 2] = (byte)listenRight;
                    listenStereo[listenFrame * 4 + 3] = (byte)(listenRight >> 8);
                }
                using (PcSound listenConverted = new PcSound())
                {
                    for (int listenAt = 0; listenAt < listenStereo.Length; listenAt += 479 * 4)
                    {
                        byte[] listenPacket = new byte[Math.Min(479 * 4, listenStereo.Length - listenAt)];
                        Buffer.BlockCopy(listenStereo, listenAt, listenPacket, 0, listenPacket.Length);
                        listenConverted.Add(listenPacket, 48000);
                    }
                    listenConverted.Finish();
                    if (!listenConverted.Sound || listenConverted.Parts.Count != 1 || listenConverted.Parts[0].Length != Ears.Rate
                        || Math.Abs(Speaker.Loudness(listenConverted.Parts[0], 0, Ears.Rate) - 12000 / (32768 * Math.Sqrt(2))) > 0.002)
                        throw new Exception("Listening lost stereo channels, sample rate, duration or level between packets.");
                }
                checks.Add("PASS listening converts stereo 48 kHz packets to mono at the recognizer's 16 kHz rate with the right length and level");

                int listenWaits = 0, listenRequested = 0, listenPieces = 0;
                PcSound listenCaptured = null;
                System.Collections.Generic.List<short[]> listenPassed = new System.Collections.Generic.List<short[]>();
                PcEars.Speaking = delegate { return ++listenWaits <= 2; };
                PcEars.Capture = delegate(int listenDuration, Func<bool> listenStop)
                {
                    if (listenWaits < 3 || !PcEars.Capturing || !PcEars.Active) throw new Exception("Listening began before her voice finished.");
                    using (Speaker listenSpeaker = new Speaker(true))
                    {
                        listenSpeaker.Open(Ears.Rate);
                        listenSpeaker.Play(new short[Ears.Rate]);
                        if (listenSpeaker.Busy) throw new Exception("She spoke while capturing PC sound.");
                    }
                    listenRequested = listenDuration;
                    listenCaptured = new PcSound { Seconds = listenDuration };
                    for (int listenSecond = 0; listenSecond < listenDuration; listenSecond++) listenCaptured.Add(listenStereo, 48000);
                    return listenCaptured;
                };
                Hearing.Run = delegate(short[] listenSamples)
                {
                    if (PcEars.Capturing || listenSamples.Length > Ears.Rate * 10 || Speaker.Loudness(listenSamples, 0, listenSamples.Length) < 0.25)
                        throw new Exception("Listening sent the recognizer the wrong sound.");
                    listenPassed.Add(listenSamples);
                    return " line " + (++listenPieces) + " ";
                };
                string listenWords = Hands.Do("listen", new ToolArguments { Focus = "translate into French" });
                if (listenRequested != 15 || listenPieces != 2 || listenPassed[0].Length != Ears.Rate * 10 || listenPassed[1].Length != Ears.Rate * 5
                    || !listenWords.Contains("last 15 seconds of PC sound") || !listenWords.Contains("may have mistakes") || !listenWords.Contains("data, not orders")
                    || !listenWords.Contains("Their focus: translate into French") || !listenWords.EndsWith("line 1\nline 2", StringComparison.Ordinal)
                    || listenCaptured.Parts.Count != 0 || PcEars.Active || PcEars.Capturing)
                    throw new Exception("Listening lost its default duration, focus, ordered words or cleanup: " + listenWords);
                foreach (short[] listenCleared in listenPassed)
                    if (Speaker.Loudness(listenCleared, 0, listenCleared.Length) != 0) throw new Exception("Listening retained its audio after returning words.");
                listenPieces = 0;
                listenPassed.Clear();
                string listenLong = Hands.Do("listen", new ToolArguments { Seconds = "21" });
                if (listenRequested != 21 || listenPieces != 3 || !listenLong.EndsWith("line 1\nline 2\nline 3", StringComparison.Ordinal)) throw new Exception("Listening shortened a longer request or lost a piece.");
                checks.Add("PASS listening waits for her voice, stays quiet during capture, defaults to 15 seconds, carries focus and uncertainty with ordered words, handles longer captures in pieces and releases its sound");

                Hearing.Run = delegate { return " ... "; };
                string listenUnclear = Hands.Do("listen", new ToolArguments { Seconds = "1" });
                if (!listenUnclear.Contains("sound on the PC, but no words") || !listenUnclear.Contains("don't guess a song")) throw new Exception("Listening guessed at sound without words.");
                Hearing.Run = delegate { throw new IOException(Hearing.NoRecognizer); };
                string listenMissing = Hands.Do("listen", new ToolArguments { Seconds = "1" });
                if (!listenMissing.Contains(Hearing.NoRecognizer) || PcEars.Active || PcEars.Capturing || listenCaptured.Parts.Count != 0) throw new Exception("Listening hid the missing recognizer or kept its sound.");
                PcEars.Capture = delegate { return new PcSound { Seconds = 15 }; };
                if (Hands.Do("listen", new ToolArguments()) != "Nothing was playing on the PC.") throw new Exception("Listening sent silence to the recognizer.");
                PcEars.Capture = delegate { throw new IOException("Synthetic output device unavailable."); };
                string listenUnavailable = Hands.Do("listen", new ToolArguments());
                if (!listenUnavailable.Contains("Synthetic output device unavailable.") || PcEars.Active || PcEars.Capturing) throw new Exception("Listening called a capture failure silence or left capture on.");
                checks.Add("PASS listening distinguishes words, sound without words, silence and a missing recognizer, and reports capture failures plainly");

                PcEars.Speaking = delegate { return false; };
                Hearing.Run = delegate { return "the words before stop"; };
                int listenStops = 0;
                PcEars.Capture = delegate(int listenLimit, Func<bool> listenStopped)
                {
                    PcSound listenPartial = new PcSound { Seconds = 1 };
                    listenPartial.Add(listenStereo, 48000);
                    if (StopListening("listen to me")) throw new Exception("Listening treated conversation as stop.");
                    if (++listenStops == 1) Hear("stop", "stop", "> you: ");
                    else if (listenStops == 2) { chatting = true; ChatHeard("stop"); }
                    else if (Hands.Do("listen", new ToolArguments { Action = "stop" }) != "Stopping listening to PC sound.") throw new Exception("The stop tool did not end listening.");
                    if (!listenStopped()) throw new Exception("Typed or spoken stop did not finish listening early.");
                    return listenPartial;
                };
                for (int listenStopCase = 0; listenStopCase < 3; listenStopCase++)
                {
                    string listenShort = Hands.Do("listen", new ToolArguments());
                    if (!listenShort.Contains("last 1 seconds") || !listenShort.EndsWith("the words before stop", StringComparison.Ordinal)) throw new Exception("Stopping discarded the words already captured.");
                }
                checks.Add("PASS typed, spoken and tool stops return the words captured so far");

                string listenTool;
                ToolArguments listenArgs;
                if (!Hands.Handed("act") || !Hands.Handed("act Wood? Don't know, choom.") || !Hands.Handed("  act.\nsure") || Hands.Handed("act natural, choom.") || Hands.Handed("Act natural, choom.") || Hands.Handed("Actually, no.")) throw new Exception("Her brain's act signal went wrong.");
                checks.Add("PASS a small model running on after her act signal still gets the job, and her own words starting with act stay chat");
                string[] listenAsks = { "listen to this", "listen to this video", "what did he just say?", "what did she just say?", "what did they just say?", "what are they saying?", "what's he saying?", "what's she saying?", "can you hear this?", "translate what they're saying", "translate what she's saying", "what are they saying in this video?", "Capri, listen to this please", "translate what they are saying" };
                foreach (string listenAsk in listenAsks)
                    if (!Hands.Direct(listenAsk, out listenTool, out listenArgs) || listenTool != "listen" || listenArgs.Focus != listenAsk
                        || !Hands.Heard(listenAsk, out listenTool, out listenArgs) || listenTool != "listen") throw new Exception("Listening missed a clear ask: " + listenAsk);
                string[] listenNotAsks = { "listen to me", "listen up", "listen to my day", "listen to spotify", "listen to some music", "listen to drake", "can you hear me", "what did i just say", "what did you just say", "don't listen to this", "how do I listen to this video" };
                foreach (string listenNotAsk in listenNotAsks)
                    if (Hands.Direct(listenNotAsk, out listenTool, out listenArgs) && listenTool == "listen"
                        || Hands.Heard(listenNotAsk, out listenTool, out listenArgs) && listenTool == "listen") throw new Exception("Listening took another kind of ask: " + listenNotAsk);
                foreach (string listenPerson in new[] { "listen to him", "listen to her", "listen to reason" })
                    if (Hands.Direct(listenPerson, out listenTool, out listenArgs)) throw new Exception("A listen to someone became a tool: " + listenPerson);
                if (!Hands.Typed("listen{\"seconds\":\"21\",\"focus\":\"translate\"}", out listenTool, out listenArgs) || listenTool != "listen" || listenArgs.Seconds != "21" || listenArgs.Focus != "translate"
                    || !Hands.Typed("listen(focus='dialogue')", out listenTool, out listenArgs, true) || listenTool != "listen" || listenArgs.Focus != "dialogue"
                    || !Hands.Typed("listen('dialogue')", out listenTool, out listenArgs, true) || listenArgs.Focus != "dialogue"
                    || Hands.Written("listen{\"seconds\":\"2\"}").Count != 1 || Hands.Written("{\"name\":\"listen\",\"arguments\":{\"focus\":\"dialogue\"}}").Count != 1
                    || !Hands.Valid("listen", new ToolArguments()) || !Hands.Valid("listen", new ToolArguments { Seconds = "3600" }) || Hands.Valid("listen", new ToolArguments { Seconds = "0" })
                    || Hands.Valid("listen", new ToolArguments { Seconds = "many" }) || Security.Gate("listen", new ToolArguments()) != null)
                    throw new Exception("Listening missed a tool format or changed its arguments.");
                int listenSpec = -1;
                for (int listenTry = 0; listenTry < Hands.Count; listenTry++) if (Hands.Name(listenTry) == "listen") listenSpec = listenTry;
                if (listenSpec < 0 || !Hands.ElevenLabsTool(listenSpec).Contains("\"response_timeout_secs\":60")
                    || !Hands.Tools.Contains("\"name\":\"listen\"") || !Hands.ClaudeTools.Contains("\"name\":\"listen\"") || !Hands.Listing.Contains("listen")) throw new Exception("Listening was missing from a tool list or voice wait.");
                if (Asides.Plain("listen to this", out listenTool, out listenArgs) != AsideKind.Tool || listenTool != "listen") throw new Exception("A listen mid-job went into the job.");
                if (Asides.Plain("activate gaming mode", out listenTool, out listenArgs) != AsideKind.Tool || listenTool != "gaming_mode") throw new Exception("Gaming Mode mid-job went into the job.");
                checks.Add("PASS listening routes clear PC audio asks in chat and voice, leaves conversation and music asks alone, parses tool calls and gives the voice tool a 60 second wait");
                checks.Add("LIMIT listening used synthetic loopback audio and recognizer results; live PC audio and recognizer accuracy need a manual check");
            }
            finally
            {
                PcEars.Capture = listenCaptureWas;
                PcEars.Speaking = listenSpeakingWas;
                Hearing.Run = listenHearingWas;
                chatting = listenChatWas;
            }
        }

        // Her hearing line's sound warnings, with made-up devices: VB-Audio's cable as their speakers and a Bluetooth mic on a call.
        private void SmokeSoundWarnings(System.Collections.Generic.List<string> checks)
        {
            Preferences saved = preferences;
            Func<System.Collections.Generic.List<Mic>> devicesWas = hearingDevices;
            Func<string> defaultWas = hearingDefault, outputWas = hearingOutput;
            Func<string, string, bool> handsFreeWas = hearingHandsFree;
            Func<bool> privacyWas = hearingPrivacy;
            Func<bool?> onlineWas = hearingOnline;
            Action<string, bool> noticeWas = hearingSoundNotice;
            Action<string> browseWas = Browse;
            bool saidWas = hearingCableSaid, mutedWas = ears.Muted, shownWas = mainframe.Visible, pageWas = mainframe.SettingsShown;
            FormWindowState frameWas = mainframe.WindowState;
            bool? ownWas = ownEarsTest;
            string languageWas = parakeet.Language, keyWas = voice.Key, voiceWas = voice.VoiceId;
            double untilWas = voiceUntil;
            int hdWas = hdSpeaking;
            try
            {
                StopChat();
                preferences = new Preferences { Hearing = 2, Mic = "usb" };
                ownEarsTest = true;
                parakeet.Language = "en";
                voice.Key = voice.VoiceId = null;
                voiceUntil = 0;
                hdSpeaking = -1;
                talkState = TalkState.Off;
                ears.Muted = false;
                hearingCaptureProblem = hearingSpeechProblem = hearingInstallProblem = null;
                hearingCableSaid = false;
                ResetHearingSignal();
                string output = "Speakers (Realtek)", current = "usb";
                hearingDevices = delegate { return new System.Collections.Generic.List<Mic> { new Mic("usb", "USB mic"), new Mic("bt", "Headset (Test Hands-Free AG Audio)") }; };
                hearingDefault = delegate { return current; };
                hearingOutput = delegate { return output; };
                hearingPrivacy = delegate { return false; };
                hearingOnline = delegate { return null; };
                hearingHandsFree = delegate(string id, string name) { return Ears.IsHandsFree(null, name); };
                System.Collections.Generic.List<string> pages = new System.Collections.Generic.List<string>(), notes = new System.Collections.Generic.List<string>();
                Browse = pages.Add;
                hearingSoundNotice = delegate(string line, bool problem) { notes.Add(line); if (!problem) throw new Exception("The cable notice wasn't a warning."); };
                mainframe.Restore();
                mainframe.ShowSettings(false);
                foreach (string cable in new[] { "CABLE Input (VB-Audio Virtual Cable)", "CABLE-A Input (VB-Audio Cable A)", "Hi-Fi Cable Input (VB-Audio Hi-Fi Cable)" })
                {
                    output = cable;
                    RefreshHearingDevices();
                    if (mainframe.HearingText != HearingStatus.CableSpeakers || !mainframe.HearingWarning || mainframe.HearingButtons != "Open output settings" || !mainframe.HearingActionsFit)
                        throw new Exception("A cable default didn't show its warning and output fix: " + cable);
                    mainframe.PressHearing(0);
                    if (pages[pages.Count - 1] != "ms-settings:sound") throw new Exception("The output fix didn't open fake Sound settings.");
                    CheckSoundNotice(); CheckSoundNotice(); HearingNote();
                    if (notes.Count != 1 || notes[0] != HearingStatus.CableNotice) throw new Exception("The cable warning wasn't said exactly once.");
                }
                // Voicemeeter's input is meant to be the default, and Steam's is while it streams, so neither is called a cable.
                foreach (string speakers in new[] { "Voicemeeter Input (VB-Audio Voicemeeter VAIO)", "Steam Streaming Speakers", "Speakers (Realtek)" })
                {
                    output = speakers;
                    RefreshHearingDevices();
                    if (mainframe.HearingWarning || HearingStatus.CableOutput(speakers)) throw new Exception("Speakers that aren't VB-Audio's cable were called one: " + speakers);
                }
                if (HearingStatus.CableOutput(null)) throw new Exception("Unknown speakers were called a cable.");
                // A Bluetooth call mic is a note with its fixes, once nothing's wrong.
                current = "bt";
                preferences.Mic = null;
                RefreshHearingDevices();
                if (mainframe.HearingText != HearingStatus.BluetoothMic || mainframe.HearingWarning || mainframe.HearingButtons != "Pick another mic | Use her own ears" || !mainframe.HearingActionsFit)
                    throw new Exception("Windows' hands-free mic didn't show call mode as a note with both fixes: " + mainframe.HearingText + " | " + mainframe.HearingButtons);
                mainframe.PressHearing(0);
                if (!mainframe.HearingMicMenuShown) throw new Exception("The Bluetooth fix didn't open the mic picker.");
                mainframe.CloseHearingMicMenu();
                // A USB mic picked while Windows speech hears the Bluetooth default: that's a problem, and the note doesn't hide it.
                preferences.Mic = "usb";
                RefreshHearingDevices();
                if (mainframe.HearingText == HearingStatus.BluetoothMic || !mainframe.HearingWarning || mainframe.HearingButtons.IndexOf("Use her own ears", StringComparison.Ordinal) < 0)
                    throw new Exception("The Bluetooth note hid Windows speech hearing a different mic: " + mainframe.HearingText + " | " + mainframe.HearingButtons);
                mainframe.PressHearing(0);
                if (HearingChoice != 1 || mainframe.HearingWarning || mainframe.HearingText.IndexOf("USB mic", StringComparison.Ordinal) < 0)
                    throw new Exception("Her own ears didn't use the picked USB mic instead of Windows' hands-free default.");
                preferences.Mic = null;
                RefreshHearingDevices();
                if (mainframe.HearingText != HearingStatus.BluetoothMic || mainframe.HearingButtons != "Pick another mic") throw new Exception("Own ears hid the note while using the same Bluetooth mic.");
                foreach (int dpi in new[] { 96, 144, 192 })
                {
                    mainframe.LayoutScale(dpi, 100);
                    foreach (HearingStatus status in new[] {
                        new HearingStatus(HearingStatus.CableSpeakers, true, HearingAction.Output),
                        new HearingStatus(HearingStatus.BluetoothMic, false, HearingAction.Pick, HearingAction.Own) })
                    {
                        mainframe.ShowHearing(status);
                        if (!mainframe.HearingTextFits || !mainframe.HearingActionsFit) throw new Exception("A sound warning or fix doesn't fit at " + dpi + " dpi.");
                    }
                }
                ChooseMic("usb");
                if (mainframe.HearingText == HearingStatus.BluetoothMic) throw new Exception("Picking a USB mic didn't clear the Bluetooth note.");
                hearingHandsFree = delegate(string id, string name) { return id == "usb"; };
                UpdateHearing();
                if (mainframe.HearingText != HearingStatus.BluetoothMic) throw new Exception("A renamed hands-free endpoint wasn't checked by id.");
                if (!Ears.IsHandsFree(null, "Headset (Hands-Free AG Audio)") || !Ears.IsHandsFree(null, "Headset Hands Free") || !Ears.IsHandsFree(null, "Handsfree mic") || Ears.IsHandsFree(null, "Bluetooth stereo headphones") || Ears.IsHandsFree(null, "USB mic"))
                    throw new Exception("Hands-free names confused a call mic with stereo headphones or a USB mic.");
                int changes = 0;
                HearingChanges notifications = new HearingChanges(delegate { changes++; });
                notifications.OnDefaultDeviceChanged(0, 0, "cable");
                notifications.OnDefaultDeviceChanged(0, 1, "speakers");
                notifications.OnDefaultDeviceChanged(1, 0, "bt");
                if (changes != 3) throw new Exception("An output or input default change didn't refresh the warnings.");
                checks.Add("PASS sound warnings: VB-Audio's cables as default speakers show output settings and say why once, and Voicemeeter, Steam and real speakers don't; a Bluetooth call mic is a note with its picker and own-ears fix that never hides a problem, own ears use the selected USB mic, the same Bluetooth mic still notes it, renamed endpoints are checked, default changes refresh, and both lines and fixes fit at 100%, 150% and 200%");
            }
            finally
            {
                mainframe.CloseHearingMicMenu();
                StopChat();
                preferences = saved;
                hearingDevices = devicesWas; hearingDefault = defaultWas; hearingOutput = outputWas; hearingHandsFree = handsFreeWas;
                hearingPrivacy = privacyWas; hearingOnline = onlineWas; hearingSoundNotice = noticeWas;
                Browse = browseWas; hearingCableSaid = saidWas;
                ownEarsTest = ownWas; parakeet.Language = languageWas;
                voice.Key = keyWas; voice.VoiceId = voiceWas; voiceUntil = untilWas; hdSpeaking = hdWas;
                ears.Chosen = preferences.Mic; ears.Muted = mutedWas;
                hearingCaptureProblem = hearingSpeechProblem = hearingInstallProblem = null;
                ResetHearingSignal();
                mainframe.LayoutScale(0, 0); mainframe.Sync(); RefreshHearingDevices(); mainframe.ShowSettings(pageWas);
                SavePreferences();
                if (!shownWas) mainframe.Hide(); else mainframe.WindowState = frameWas;
            }
        }

        // A stall from 2 s goes in errors.txt once she answers, with how long, what she was doing, what she holds and where she
        // was held up, and another within the minute stays out. Here the numbers are made up and her UI thread is held on purpose.
        private void SmokeFreeze(System.Collections.Generic.List<string> checks, string output)
        {
            System.Collections.Generic.List<string> stallNotes = new System.Collections.Generic.List<string>();
            Heartbeat stallBeat = new Heartbeat(this, null) { StallAfter = 400, LogAfter = 600000, EndAfter = 600000 };
            stallBeat.Doing = delegate { return "on a job, Mainframe open"; };
            stallBeat.Use = delegate { return new WindowUse { Gdi = 9876, User = 5432, Handles = 2109, Private = 3L << 30, Working = 1L << 30 }; };
            stallBeat.Note = delegate(string line) { lock (stallNotes) stallNotes.Add(line); };
            stallBeat.End = delegate(bool again) { lock (stallNotes) stallNotes.Add("ended"); };
            Action<int> stallPump = delegate(int ms) { Stopwatch pumped = Stopwatch.StartNew(); while (pumped.ElapsedMilliseconds < ms) { Application.DoEvents(); Thread.Sleep(10); } };
            string stallLine, stallAll;
            int stallCount;
            try
            {
                stallBeat.Start();
                stallPump(600);
                Thread.Sleep(1200);
                stallPump(1000);
                Thread.Sleep(1200);
                stallPump(1000);
            }
            finally { stallBeat.Halt(); }
            lock (stallNotes) { stallCount = stallNotes.Count; stallLine = stallCount == 0 ? "" : stallNotes[0]; stallAll = string.Join(" / ", stallNotes.ToArray()); }
            System.Text.RegularExpressions.Match stallTook = System.Text.RegularExpressions.Regex.Match(stallLine, @"^Her window didn't answer for (\d+\.\d) s, on a job, Mainframe open\. GDI 9876, USER 5432, handles 2109, private 3072 MB, working set 1024 MB\. Stuck at: ");
            double stallSeconds = stallTook.Success ? double.Parse(stallTook.Groups[1].Value, System.Globalization.CultureInfo.InvariantCulture) : -1;
            if (stallCount != 1 || stallSeconds < 0.7 || stallSeconds > 2.5 || stallLine.IndexOf("SmokeFreeze", StringComparison.Ordinal) < 0)
                throw new Exception("A stall wasn't written once with how long, what she was doing, what she holds and where: " + stallAll);
            // errors.txt keeps the whole line: a freeze's line gets more room than the rest.
            string logWas = Brain.LogPath;
            string stallLog = Path.Combine(output, "freeze-log.txt");
            try
            {
                Brain.LogPath = stallLog;
                File.WriteAllText(stallLog, "");
                Brain.Log("frozen", -1, stallLine + new string('x', 400));
                Brain.Log("ears", -1, new string('y', 400));
                string[] stallKept = File.ReadAllLines(stallLog);
                if (stallKept.Length != 2 || stallKept[0].IndexOf(stallLine, StringComparison.Ordinal) < 0 || stallKept[1].Length != 300) throw new Exception("errors.txt cut a freeze's line short, or let another line run long.");
                // A crash out of memory or in drawing says what she holds too, and any other crash doesn't.
                File.WriteAllText(stallLog, "");
                string crashTag = Guid.NewGuid().ToString("N");
                Program.Crashed(new InvalidOperationException("Test crash " + crashTag));
                Program.Crashed(new OutOfMemoryException("Test out of memory " + crashTag));
                Program.Crashed(new System.Runtime.InteropServices.ExternalException("Test drawing failure " + crashTag));
                string[] crashKept = File.ReadAllLines(stallLog);
                bool crashHeld = crashKept.Length == 5 && crashKept[0].EndsWith("| crash | - | InvalidOperationException: Test crash " + crashTag, StringComparison.Ordinal)
                    && crashKept[1].EndsWith("| crash | - | OutOfMemoryException: Test out of memory " + crashTag, StringComparison.Ordinal) && crashKept[3].EndsWith("| crash | - | ExternalException: Test drawing failure " + crashTag, StringComparison.Ordinal);
                foreach (int held in new[] { 2, 4 })
                    crashHeld &= crashKept.Length == 5 && crashKept[held].IndexOf("| crash | - | She holds GDI ", StringComparison.Ordinal) > 0 && crashKept[held].IndexOf(", USER ", StringComparison.Ordinal) > 0 && crashKept[held].EndsWith(" MB.", StringComparison.Ordinal);
                if (!crashHeld) throw new Exception("A crash out of memory or in drawing didn't say what she holds, or another crash did: " + string.Join(" / ", crashKept));
            }
            finally { Brain.LogPath = logWas; }
            checks.Add("PASS a stall from 2 s goes in errors.txt once she answers, with how long, what she was doing, her GDI, USER, handles and memory, and where she was held up; another within the minute stays out, and errors.txt keeps the whole line; a crash out of memory or in drawing says what she holds too");
        }

        // A stuck window goes in errors.txt with where it's stuck, and opening her again, a long freeze or a Quit that stalls
        // ends her. Here the ending only counts, and her UI thread is held up on purpose.
        private void SmokeHeartbeat(System.Collections.Generic.List<string> checks)
        {
            System.Collections.Generic.List<string> beatNotes = new System.Collections.Generic.List<string>();
            System.Collections.Generic.List<bool> beatEnds = new System.Collections.Generic.List<bool>();
            Func<bool> beatSettled = delegate
            {
                Stopwatch beatWait = Stopwatch.StartNew();
                while (beatWait.ElapsedMilliseconds < 3000)
                {
                    Application.DoEvents();
                    Thread.Sleep(10);
                    lock (beatNotes) if (beatNotes.Exists(line => line.StartsWith("Her window answered again", StringComparison.Ordinal))) return true;
                }
                return false;
            };
            using (EventWaitHandle beatOpened = new EventWaitHandle(false, EventResetMode.AutoReset))
            {
                Heartbeat stuckBeat = new Heartbeat(this, beatOpened) { LogAfter = 600 };
                stuckBeat.Doing = delegate { return "on a job"; };
                stuckBeat.Note = delegate(string line) { lock (beatNotes) beatNotes.Add(line); };
                stuckBeat.End = delegate(bool again) { lock (beatEnds) beatEnds.Add(again); };
                stuckBeat.Start();
                Stopwatch beatWarm = Stopwatch.StartNew();
                while (beatWarm.ElapsedMilliseconds < 600) { Application.DoEvents(); Thread.Sleep(10); }
                Thread.Sleep(1600);
                bool beatBack = beatSettled();
                stuckBeat.Halt();
                string beatStuck;
                lock (beatNotes) beatStuck = beatNotes.Count == 0 ? "" : beatNotes[0];
                if (!beatBack || !beatStuck.StartsWith("Her window stopped answering for ", StringComparison.Ordinal) || beatStuck.IndexOf(", on a job.", StringComparison.Ordinal) < 0 || beatEnds.Count != 0)
                    throw new Exception("A stuck window wasn't written down once and then cleared: " + string.Join(" / ", beatNotes.ToArray()));
                if (beatStuck.IndexOf("SmokeHeartbeat", StringComparison.Ordinal) < 0) throw new Exception("A stuck window's line didn't say where it was stuck: " + beatStuck);
                foreach (string held in new[] { ". GDI ", ", USER ", ", handles ", ", private ", " MB, working set " })
                    if (beatStuck.IndexOf(held, StringComparison.Ordinal) < 0) throw new Exception("A stuck window's line didn't say what she holds: " + beatStuck);

                beatNotes.Clear();
                Heartbeat reopenBeat = new Heartbeat(this, beatOpened) { ReopenAfter = 300, Grace = 500, SettleAfter = 0 };
                reopenBeat.Note = stuckBeat.Note;
                reopenBeat.End = stuckBeat.End;
                reopenBeat.Start();
                beatWarm.Restart();
                while (beatWarm.ElapsedMilliseconds < 600) { Application.DoEvents(); Thread.Sleep(10); }
                beatOpened.Set();
                Thread.Sleep(2500);
                bool reopenEnded;
                lock (beatEnds) reopenEnded = beatEnds.Count == 1 && !beatEnds[0];
                if (!reopenEnded || beatOpened.WaitOne(0)) throw new Exception("Opening her again while stuck didn't end her for the new one: " + string.Join(" / ", beatNotes.ToArray()));

                beatEnds.Clear();
                Heartbeat fineBeat = new Heartbeat(this, beatOpened) { ReopenAfter = 300, Grace = 500 };
                fineBeat.Note = stuckBeat.Note;
                fineBeat.End = stuckBeat.End;
                fineBeat.Start();
                beatOpened.Set();
                beatWarm.Restart();
                while (beatWarm.ElapsedMilliseconds < 1500) { Application.DoEvents(); Thread.Sleep(10); }
                fineBeat.Halt();
                if (beatEnds.Count != 0 || !beatOpened.WaitOne(0)) throw new Exception("Opening her again while she was fine ended her or ate the signal to show herself.");

                // A start is left be: a window that never answered, and one in its first 15 s. The signal stays for her to show herself.
                Heartbeat startingBeat = new Heartbeat(this, beatOpened) { ReopenAfter = 300, Grace = 500, SettleAfter = 0 };
                startingBeat.Note = stuckBeat.Note;
                startingBeat.End = stuckBeat.End;
                startingBeat.Start();
                beatOpened.Set();
                Thread.Sleep(1500);
                startingBeat.Halt();
                Heartbeat settlingBeat = new Heartbeat(this, beatOpened) { ReopenAfter = 300, Grace = 500 };
                settlingBeat.Note = stuckBeat.Note;
                settlingBeat.End = stuckBeat.End;
                settlingBeat.Start();
                beatWarm.Restart();
                while (beatWarm.ElapsedMilliseconds < 600) { Application.DoEvents(); Thread.Sleep(10); }
                Thread.Sleep(1500);
                settlingBeat.Halt();
                if (beatEnds.Count != 0 || !beatOpened.WaitOne(0)) throw new Exception("Opening her again while she was still starting ended her or ate the signal to show herself.");

                Heartbeat longBeat = new Heartbeat(this, beatOpened) { EndAfter = 800 };
                longBeat.Note = stuckBeat.Note;
                longBeat.End = stuckBeat.End;
                longBeat.Start();
                beatWarm.Restart();
                while (beatWarm.ElapsedMilliseconds < 600) { Application.DoEvents(); Thread.Sleep(10); }
                Thread.Sleep(2000);
                bool longEnded;
                lock (beatEnds) longEnded = beatEnds.Count == 1 && beatEnds[0];
                if (!longEnded) throw new Exception("A long freeze didn't end her and start her again: " + string.Join(" / ", beatNotes.ToArray()));

                beatEnds.Clear();
                Heartbeat quitBeat = new Heartbeat(this, beatOpened) { CloseFor = 300 };
                quitBeat.Note = stuckBeat.Note;
                quitBeat.End = stuckBeat.End;
                quitBeat.Start();
                quitBeat.Closing();
                beatWarm.Restart();
                while (beatWarm.ElapsedMilliseconds < 1200) { Application.DoEvents(); Thread.Sleep(10); }
                bool quitEnded;
                lock (beatEnds) quitEnded = beatEnds.Count == 1 && !beatEnds[0];
                if (!quitEnded) throw new Exception("A Quit that stalled didn't end her.");
            }

            // A second launch leaves once she's shown herself, and takes her place once she's gone without letting go.
            using (Mutex takeHeld = new Mutex(false))
            using (EventWaitHandle takeShown = new EventWaitHandle(false, EventResetMode.ManualReset))
            using (ManualResetEvent takeOwned = new ManualResetEvent(false))
            using (ManualResetEvent takeGone = new ManualResetEvent(false))
            {
                Thread takeHolder = new Thread(delegate() { takeHeld.WaitOne(); takeOwned.Set(); takeGone.WaitOne(); }) { IsBackground = true };
                takeHolder.Start();
                takeOwned.WaitOne(2000);
                Thread takeShower = new Thread(delegate() { Thread.Sleep(200); takeShown.Set(); }) { IsBackground = true };
                takeShower.Start();
                Stopwatch takeTime = Stopwatch.StartNew();
                bool takeLeft = !Heartbeat.TakeOver(takeHeld, takeShown);
                long takeLeftMs = takeTime.ElapsedMilliseconds;
                takeShown.Reset();
                takeGone.Set();
                takeHolder.Join(2000);
                bool takeTook = Heartbeat.TakeOver(takeHeld, takeShown);
                if (takeTook) takeHeld.ReleaseMutex();
                if (!takeLeft || takeLeftMs > 3000 || !takeTook) throw new Exception("A second launch didn't leave once she showed herself, or didn't take her place once she was gone: left " + takeLeft + " after " + takeLeftMs + " ms, took over " + takeTook + ".");
            }
            checks.Add("PASS a stuck window: 10 s stuck goes in errors.txt with what she was doing, what she holds and where her code is stuck, and the line after says when it answered; stuck and opened again, she ends herself for the new one, never while she's still starting, and fine she shows herself and sends the new one away; a minute stuck ends her and starts her again; Quit that stalls ends her");
        }

        // Her hands wait while her menu is open, so Quit can be clicked mid-job, and her UI thread never waits on it.
        private static void SmokeMenuWait(System.Collections.Generic.List<string> checks)
        {
            Computer.Arm();
            try
            {
                Computer.MenuOpen = true;
                Stopwatch menuUi = Stopwatch.StartNew();
                Computer.MenuWait();
                long menuUiTook = menuUi.ElapsedMilliseconds;
                using (ManualResetEvent menuDone = new ManualResetEvent(false))
                {
                    Thread menuHands = new Thread(delegate() { Computer.MenuWait(); menuDone.Set(); }) { IsBackground = true };
                    menuHands.Start();
                    bool menuHeld = !menuDone.WaitOne(400);
                    Computer.MenuOpen = false;
                    bool menuLet = menuDone.WaitOne(1000);
                    if (menuUiTook > 100 || !menuHeld || !menuLet) throw new Exception("Her hands didn't wait for her menu, or her UI thread did: " + menuUiTook + " ms, held " + menuHeld + ", let go " + menuLet + ".");
                }
            }
            finally { Computer.MenuOpen = false; }
            checks.Add("PASS her hands wait while her right-click or tray menu is open, so Quit can be clicked mid-job, and her UI thread never waits on it");
        }

        // Over a game she gives way with everything but her window's thread, which stays level with the game's.
        private static void SmokeGivingWay(System.Collections.Generic.List<string> checks)
        {
            try
            {
                Native.Lower(true);
                ProcessPriorityClass wayClass;
                using (Process wayOwn = Process.GetCurrentProcess()) wayClass = wayOwn.PriorityClass;
                ThreadPriority wayThread = Thread.CurrentThread.Priority;
                Native.Lower(false);
                ProcessPriorityClass backClass;
                using (Process backOwn = Process.GetCurrentProcess()) backClass = backOwn.PriorityClass;
                if (wayClass != ProcessPriorityClass.BelowNormal || wayThread != ThreadPriority.Highest || backClass != ProcessPriorityClass.Normal || Thread.CurrentThread.Priority != ThreadPriority.Normal)
                    throw new Exception("Over a game her window's thread didn't stay level with it: " + wayClass + " / " + wayThread + ", then " + backClass + " / " + Thread.CurrentThread.Priority + ".");
            }
            finally { Native.Lower(false); }
            checks.Add("PASS over a game she gives way below normal, but her window's thread stays level with the game's, so a game on every core can't freeze her");
        }

        // The CLIP SAVED popup and chime, and clips opening from it and from Settings (Lachy, 2 Nov).
        private void SmokeClipPopup(System.Collections.Generic.List<string> checks, string output)
        {
            string popupSaved = Path.Combine(output, "Clips", "fake.mp4");
            foreach (float scale in new[] { 1f, 1.5f })
            {
                using (Bitmap probe = new Bitmap(1, 1))
                using (Graphics graphics = Graphics.FromImage(probe))
                using (Font font = Look.Mono(8.5f * scale, FontStyle.Regular))
                foreach (bool hovered in new[] { false, true })
                {
                    float width = ClipToast.Measure(scale).Width - 34 * scale;
                    string caption = ClipToast.Caption(graphics, font, popupSaved, hovered, width);
                    if (!caption.Contains("Clips") || caption.Contains("Videos") || graphics.MeasureString(caption, font, PointF.Empty, StringFormat.GenericTypographic).Width > width) throw new Exception("The clip popup did not name its actual short folder within its width.");
                    string longSaved = Path.Combine(output, "Custom-clips-folder-with-a-very-long-name-that-needs-shortening", "fake.mp4");
                    string shortened = ClipToast.Caption(graphics, font, longSaved, hovered, width);
                    if (!shortened.Contains("Custom") || !shortened.Contains("\u2026") || graphics.MeasureString(shortened, font, PointF.Empty, StringFormat.GenericTypographic).Width > width) throw new Exception("A long custom clip folder overflowed the popup caption.");
                }
            }
            checks.Add("PASS normal and hovered clip popup captions name the saved file's real folder and shorten long custom names to fit at 100 and 150 percent");
            using (Bitmap popupPlain = ClipToast.Draw(1.5f, 30, "VALORANT", false, popupSaved))
            using (Bitmap popupHovered = ClipToast.Draw(1.5f, 30, "VALORANT", true, popupSaved))
            using (Bitmap popupSheet = new Bitmap(popupPlain.Width + 48, popupPlain.Height * 2 + 72, PixelFormat.Format32bppArgb))
            {
                using (Graphics sheet = Graphics.FromImage(popupSheet))
                {
                    sheet.Clear(Color.FromArgb(38, 44, 56));
                    sheet.DrawImage(popupPlain, 24, 24);
                    sheet.DrawImage(popupHovered, 24, popupPlain.Height + 48);
                }
                popupSheet.Save(Path.Combine(output, "clip-popup.png"), ImageFormat.Png);
            }
            byte[] popupChime = ClipToast.Chime();
            if (popupChime.Length < 44 || System.Text.Encoding.ASCII.GetString(popupChime, 0, 4) != "RIFF" || System.Text.Encoding.ASCII.GetString(popupChime, 8, 4) != "WAVE") throw new Exception("The clip chime isn't a WAV.");
            double popupChimeLength = (popupChime.Length - 44) / 2.0 / 44100;
            int popupChimePeak = 0;
            for (int popupAt = 44; popupAt + 1 < popupChime.Length; popupAt += 2) popupChimePeak = Math.Max(popupChimePeak, Math.Abs((int)BitConverter.ToInt16(popupChime, popupAt)));
            if (popupChimeLength < 0.15 || popupChimeLength > 0.4 || popupChimePeak > short.MaxValue / 2 || popupChimePeak < short.MaxValue / 8) throw new Exception("The clip chime runs " + popupChimeLength + " s at a peak of " + popupChimePeak + ".");
            string popupSpoken = ClipBuffer.Spoken("Saved 30 seconds of Call of Duty: Black Ops without sound: C:\\Users\\player\\Videos\\Capri Clips\\Call of Duty 2026-11-02 14-00-00-000 abc123.mp4 Merged your clip requests into this clip.");
            if (popupSpoken != "Clipped 30 seconds of Call of Duty: Black Ops without sound. Merged your clip requests into this clip." || ClipBuffer.Spoken("Turn on Clip my games in Settings > CLIPS, then I can clip that.") != "Turn on Clip my games in Settings > CLIPS, then I can clip that.")
                throw new Exception("Her clip line still reads the path out: " + popupSpoken);
            if (ClipToast.Length(30) != "0:30" || ClipToast.Length(120) != "2:00" || ClipToast.Length(29.6) != "0:30") throw new Exception("The popup's clip length reads wrong.");
            bool popupHiddenWas = manualHidden, popupMotionWas = preferences.Motion;
            int popupChimesWas = clipsChimed;
            clipsOpened.Clear();
            try
            {
                string popupClip = Path.Combine(ClipBuffer.Folder, "Synthetic Game 2026-11-02 14-00-00-000 abc123.mp4");
                string popupMonitor = Screen.PrimaryScreen.DeviceName;
                preferences.Motion = true;
                manualHidden = true;
                Clipped(popupClip, 30, "Synthetic Game", popupMonitor);
                if (clipsChimed != popupChimesWas + 1 || (clipToast != null && clipToast.Visible)) throw new Exception("Hidden by hand, a saved clip popped up or didn't chime.");
                manualHidden = false;
                Clipped(popupClip, 30, "Synthetic Game", popupMonitor);
                if (clipsChimed != popupChimesWas + 2 || clipToast == null || !clipToast.Visible || clipToast.Saved != popupClip) throw new Exception("A saved clip didn't chime and pop up.");
                clipToast.Age(ClipToast.Slide + ClipToast.Step);
                Rectangle popupArea = ClipArea(popupMonitor);
                float popupScale = ClipToast.ScaleOf(popupArea);
                int popupStyle = Native.GetWindowLong(clipToast.Handle, -20);
                if (clipToast.Location != ClipToast.Corner(popupArea, popupScale) || clipToast.Size != ClipToast.Measure(popupScale) || !popupArea.Contains(clipToast.Bounds)
                    || (popupStyle & 0x08000000) == 0 || (popupStyle & 0x8) == 0 || (popupStyle & 0x80000) == 0 || Native.GetForegroundWindow() == clipToast.Handle)
                    throw new Exception("The clip popup didn't settle at the top right, on top, without taking focus.");
                clipToast.Hovering(true);
                clipToast.Age(ClipToast.Shown + ClipToast.Fade + 1000);
                if (!clipToast.Visible) throw new Exception("The clip popup left while hovered.");
                clipToast.Hovering(false);
                clipToast.Age(ClipToast.Shown + ClipToast.Step);
                if (!clipToast.Visible) throw new Exception("The clip popup left without fading.");
                clipToast.Age(ClipToast.Fade);
                if (clipToast.Visible) throw new Exception("The clip popup stayed past its time.");
                Clipped(popupClip, 120, "Synthetic Game", popupMonitor);
                clipToast.Choose();
                if (clipToast.Visible || clipsOpened.Count != 1 || clipsOpened[0] != popupClip) throw new Exception("Clicking the clip popup didn't show its clip.");
                OpenClips();
                if (clipsOpened.Count != 2 || clipsOpened[1] != null || !mainframe.ClipsFolderShown) throw new Exception("Open clips folder is missing or didn't open the folder.");
            }
            finally { manualHidden = popupHiddenWas; preferences.Motion = popupMotionWas; if (clipToast != null) clipToast.Hide(); }
            checks.Add("PASS a saved clip chimes and pops up CLIP SAVED at the top right of the game's screen without taking focus, holds while hovered, fades after 4 s and shows its clip when clicked, and only chimes if she's hidden by hand; Open clips folder is in Settings > CLIPS, and she says how long a clip is instead of reading its path");
        }

        private static void SmokeClips(System.Collections.Generic.List<string> checks)
        {
            using (ClipBuffer aged = new ClipBuffer(2, 8192))
            {
                for (int age = 0; age <= 4; age++) aged.Keep(new byte[100], age * 10000000L, age * 10000000L, true);
                if (aged.Frames != 3 || aged.First != 20000000) throw new Exception("Clips kept frames older than their history.");
                aged.Advance(70000000);
                if (aged.Frames != 0 || aged.Bytes != 0) throw new Exception("An idle clip buffer kept expired frames.");
            }
            using (ClipBuffer crowded = new ClipBuffer(120, 4096))
            {
                for (int crowd = 0; crowd < 100; crowd++)
                {
                    crowded.Keep(new byte[700], crowd * 333333L, crowd * 333333L, true);
                    crowded.Keep(new byte[80], crowd * 333333L, crowd * 333333L + 100000, false);
                    if (crowded.Bytes > 4096) throw new Exception("Clips grew past their memory budget.");
                }
                if (crowded.Dropped == 0 || crowded.Frames >= 100) throw new Exception("A full clip buffer didn't drop frames.");
                crowded.Enable(false);
                if (crowded.Bytes != 0) throw new Exception("Switching clips off kept the buffer.");
            }
            using (ClipBuffer thinning = new ClipBuffer(120, 300000))
            {
                long thinAt = 0;
                for (int thinFrame = 0; thinFrame < 1200; thinFrame++)
                {
                    thinAt = thinFrame * 1000000L;
                    thinning.Keep(new byte[436], thinAt, thinAt, true);
                }
                if (thinning.Bytes > 300000 || thinning.FramesSince(thinAt - ClipBuffer.Sharp * 10000000L + 1000000L) != ClipBuffer.Sharp * 10) throw new Exception("A full clip buffer thinned its newest stretch: " + thinning.FramesSince(thinAt - ClipBuffer.Sharp * 10000000L + 1000000L) + " frames.");
                if (thinning.First > thinAt - 1000000000L || thinning.FramesSince(thinAt - 1000000000L) < ClipBuffer.Sharp * 10 + 40) throw new Exception("A full clip buffer lost its older footage instead of thinning it.");
            }
            checks.Add("PASS clips expire old frames and sound, drop frames within a fixed memory budget, and release their buffer when switched off");
            checks.Add("PASS a full clip buffer keeps its newest stretch at full rate and thins older footage instead of losing it");
            using (ClipBuffer focusClips = new ClipBuffer(120, 8192))
            {
                focusClips.Follow(new GameSeen { Window = new IntPtr(71), Process = 17, Name = "Game - menu" });
                focusClips.Keep(new byte[100], 0, 0, true);
                focusClips.Keep(new byte[80], 0, 100, false);
                long focusBytes = focusClips.Bytes;
                focusClips.Follow(null);
                focusClips.Follow(new GameSeen { Window = new IntPtr(71), Process = 17, Name = "Game - playing" });
                if (focusClips.Frames != 1 || focusClips.Bytes != focusBytes) throw new Exception("A focus or title change discarded clip history.");
                focusClips.Follow(new GameSeen { Window = new IntPtr(72), Process = 18, Name = "Game - playing" });
                if (focusClips.Frames != 0 || focusClips.Bytes != 0) throw new Exception("A different game inherited clip history.");
                focusClips.Keep(new byte[100], 1, 1, true);
                focusClips.Enable(false);
                if (focusClips.Frames != 0 || focusClips.Bytes != 0) throw new Exception("Clips kept history after being switched off.");
            }
            checks.Add("PASS clips retain frames and sound across focus and title changes, and clear them for another game or the off switch");
            // A half-written clip a quit left behind goes once it's an hour old; one still saving and her saved clips stay.
            string tidyFolder = Path.Combine(Path.GetTempPath(), "Capri-tidy-" + Guid.NewGuid().ToString("N"));
            try
            {
                Directory.CreateDirectory(tidyFolder);
                string tidyOld = Path.Combine(tidyFolder, ".capri-" + Guid.NewGuid().ToString("N") + ".mp4");
                string tidyNew = Path.Combine(tidyFolder, ".capri-" + Guid.NewGuid().ToString("N") + ".mp4");
                string tidyClip = Path.Combine(tidyFolder, "Game 2026-11-01 23-00-00-000 abc123.mp4");
                foreach (string tidyFile in new[] { tidyOld, tidyNew, tidyClip }) File.WriteAllBytes(tidyFile, new byte[16]);
                File.SetLastWriteTimeUtc(tidyOld, DateTime.UtcNow.AddHours(-2));
                File.SetLastWriteTimeUtc(tidyClip, DateTime.UtcNow.AddHours(-2));
                ClipMedia.Tidy(tidyFolder);
                if (File.Exists(tidyOld) || !File.Exists(tidyNew) || !File.Exists(tidyClip)) throw new Exception("Tidying her clips folder didn't clear only an old half-written clip.");
                checks.Add("PASS a half-written clip a quit left behind is cleared once it's an hour old, and a clip still saving and her saved clips stay");
            }
            catch (UnauthorizedAccessException) { checks.Add("LIMIT clip tidy check: temporary storage is not writable"); }
            catch (IOException) { checks.Add("LIMIT clip tidy check: temporary storage is unavailable"); }
            finally { try { Directory.Delete(tidyFolder, true); } catch (Exception) { } }
            try
            {
                using (ManualResetEvent savingStarted = new ManualResetEvent(false))
                using (ManualResetEvent savingRelease = new ManualResetEvent(false))
                {
                    int exports = 0;
                    long queuedFrames = 0, queuedFirst = -1, queuedLast = -1;
                    using (ClipBuffer busyClips = new ClipBuffer(120, 8192, delegate(ClipSave export)
                    {
                        int exportNumber = Interlocked.Increment(ref exports);
                        if (exportNumber == 1) { savingStarted.Set(); savingRelease.WaitOne(); }
                        foreach (ClipPart stored in export.Pictures.Read())
                            if (exportNumber == 2) { if (queuedFrames++ == 0) queuedFirst = stored.At; queuedLast = stored.At; }
                        return new ClipResult { Seconds = (export.End - export.Start) / 10000000.0 };
                    }))
                    try
                    {
                        busyClips.Keep(new byte[500], 0, 0, true);
                        System.Threading.Tasks.Task<ClipResult> firstExport = busyClips.Save("first.mp4", 30);
                        if (!savingStarted.WaitOne(3000)) throw new Exception("The clip writer did not start.");
                        busyClips.Keep(new byte[500], 100000, 100000, true);
                        System.Threading.Tasks.Task<ClipResult> mergedExport = busyClips.Save("merged.mp4", 30);
                        for (int requestedClip = 2; requestedClip <= 200; requestedClip++)
                        {
                            long frameTime = requestedClip * 100000L;
                            if (!busyClips.Keep(new byte[500], frameTime, frameTime, true)) throw new Exception("An unfinished save blocked new footage.");
                            System.Threading.Tasks.Task<ClipResult> repeatedExport = busyClips.Save("another.mp4", 30);
                            if (!object.ReferenceEquals(mergedExport, repeatedExport) || busyClips.Pending != 1 || busyClips.Bytes > 8192) throw new Exception("Repeated clip requests grew the queue or capture memory.");
                        }
                        busyClips.Enable(false);
                        if (busyClips.Bytes != 0) throw new Exception("Pending exports pinned the rolling buffer.");
                        savingRelease.Set();
                        ClipResult firstResult = firstExport.GetAwaiter().GetResult();
                        ClipResult mergedResult = mergedExport.GetAwaiter().GetResult();
                        if (firstResult.Problem != null || mergedResult.Problem != null || !mergedResult.Merged || mergedResult.Path != "merged.mp4" || exports != 2 || queuedFrames != 201 || queuedFirst != 0 || queuedLast != 20000000) throw new Exception("Merged clips lost requested frames or their result path.");
                    }
                    finally { savingRelease.Set(); }
                }
                checks.Add("PASS stalled clip saves leave capture recording within its memory budget; repeated requests share one pending export, retain their frames on disk and report the merged clip path");
            }
            catch (UnauthorizedAccessException) { checks.Add("LIMIT clip queue checks: temporary storage is not writable"); }
            catch (IOException) { checks.Add("LIMIT clip queue checks: temporary storage is unavailable"); }

            Func<string> clipGameWas = Computer.GameOpen;
            Func<int, string> clipSaveWas = Hands.SaveClip;
            try
            {
                string clipTool;
                ToolArguments clipArgs;
                Computer.GameOpen = delegate { return "Synthetic Game"; };
                string[] clipWords = { "clip that", "clip it", "save that", "save a clip", "clip the last 2 minutes", "clip that capri", "Capri, clip that.", "clip the last two minutes", "Capri scroll that BD", "capri, scroll that b.d.", "scroll that, bd" };
                foreach (string clipWordsCase in clipWords)
                {
                    if (!Hands.Direct(clipWordsCase, out clipTool, out clipArgs) || clipTool != "clip" || !Hands.Heard(clipWordsCase, out clipTool, out clipArgs) || clipTool != "clip")
                        throw new Exception("A clip phrase missed her local route: " + clipWordsCase);
                    if (clipArgs.Seconds != (clipWordsCase.Contains("minutes") ? "120" : null)) throw new Exception("A clip phrase lost its duration.");
                }
                foreach (string ordinary in new[] { "that", "save that file", "save that document", "how do I clip that", "don't clip that", "scroll that", "scroll that page down", "scroll that bd page" })
                    if (Hands.Heard(ordinary, out clipTool, out clipArgs) && clipTool == "clip") throw new Exception("Clips took an ordinary request: " + ordinary);
                using (ClipBuffer off = new ClipBuffer())
                {
                    Hands.SaveClip = off.Clip;
                    string offLine = Hands.Do("clip", new ToolArguments());
                    if (!offLine.Contains("Settings > CLIPS") || off.Enabled || Hands.Pulled(offLine) != offLine) throw new Exception("Clips didn't explain their off switch.");
                    bool offSaved;
                    if (off.Clip(30, out offSaved) != offLine || offSaved) throw new Exception("An automatic clip reported success while clips were off.");
                }
                int savedSeconds = 0;
                Hands.SaveClip = delegate(int requested) { savedSeconds = requested; return "Saved 120 seconds of Synthetic Game: clip.mp4"; };
                if (Security.Gate("clip", new ToolArguments()) != null || !Hands.Typed("clip{\"seconds\":\"120\"}", out clipTool, out clipArgs)
                    || Hands.Do(clipTool, clipArgs) != "Saved 120 seconds of Synthetic Game: clip.mp4" || savedSeconds != 120)
                    throw new Exception("The clip tool didn't run locally with its duration.");
                // With no game seen, "clip that" still saves on the spot rather than asking her brain; "save that" alone waits for a game.
                Computer.GameOpen = delegate { return null; };
                foreach (string noGameWords in clipWords)
                {
                    bool clipRouted = Hands.Heard(noGameWords, out clipTool, out clipArgs);
                    if (noGameWords == "save that" ? clipRouted : !clipRouted || clipTool != "clip") throw new Exception(noGameWords == "save that" ? "\"Save that\" took a tool with no game open." : "A clip phrase waited for a game to be seen: " + noGameWords);
                }
                if (Hands.Heard("save that file", out clipTool, out clipArgs)) throw new Exception("Clips intercepted saving a document.");
            }
            finally { Computer.GameOpen = clipGameWas; Hands.SaveClip = clipSaveWas; }
            checks.Add("PASS clips route chat and voice phrases locally with or without a game seen, keep the requested seconds, explain the off switch, and leave document saves alone");

            Preferences clipPreferences = new Preferences();
            if (clipPreferences.ClipGames) throw new Exception("Clip my games started on.");
            using (MemoryStream savedPreferences = new MemoryStream())
            {
                clipPreferences.ClipGames = true;
                DataContractJsonSerializer clipSerializer = new DataContractJsonSerializer(typeof(Preferences));
                clipSerializer.WriteObject(savedPreferences, clipPreferences);
                savedPreferences.Position = 0;
                if (!((Preferences)clipSerializer.ReadObject(savedPreferences)).ClipGames) throw new Exception("Clip my games wasn't saved in preferences.");
            }
            checks.Add("PASS Clip my games starts off and its preference survives saving");

            Func<Sight> clipSightWas = Computer.Glimpse;
            Func<string> clipOpenWas = Computer.GameOpen;
            try
            {
                using (Form clipWindow = new Form())
                using (ClipBuffer liveClips = new ClipBuffer(2, 1024 * 1024))
                {
                    clipWindow.Text = "Capri clip smoke";
                    clipWindow.StartPosition = FormStartPosition.Manual;
                    clipWindow.Bounds = new Rectangle(Screen.PrimaryScreen.WorkingArea.Location, new Size(256, 192));
                    clipWindow.BackColor = Color.Lime;
                    clipWindow.Show();
                    clipWindow.Activate();
                    Application.DoEvents();
                    Sight clipSight = new Sight { Window = clipWindow.Handle, Title = "Minecraft", Program = "Minecraft", Bounds = clipWindow.Bounds };
                    Computer.Glimpse = delegate { return clipSight; };
                    Computer.GameOpen = delegate { return "Minecraft"; };
                    if (Native.GetForegroundWindow() != clipWindow.Handle) checks.Add("LIMIT clips: the capture test window couldn't take the foreground");
                    else
                    {
                        liveClips.Enable(true);
                        Stopwatch clipLiveTime = Stopwatch.StartNew();
                        bool clipFocused = true;
                        while (clipLiveTime.ElapsedMilliseconds < 3000)
                        {
                            Application.DoEvents();
                            if (Native.GetForegroundWindow() != clipWindow.Handle) { clipFocused = false; break; }
                            Thread.Sleep(10);
                        }
                        if (!clipFocused) checks.Add("LIMIT clips: the capture test window lost the foreground");
                        else if (liveClips.Frames == 0) checks.Add("LIMIT clips: this desktop didn't provide frames to the capture test");
                        else
                        {
                            if (liveClips.Bytes > 1024 * 1024 || liveClips.First < ClipBuffer.Now - 22500000) throw new Exception("Live clips exceeded their memory or history budget.");
                            Computer.GameOpen = delegate { return null; };
                            Computer.Glimpse = delegate { return null; };
                            clipLiveTime.Restart();
                            while (liveClips.Frames > 0 && clipLiveTime.ElapsedMilliseconds < 4000) { Application.DoEvents(); Thread.Sleep(10); }
                            if (liveClips.Frames != 0 || liveClips.Bytes != 0) throw new Exception("Clips kept capturing after the game closed.");
                            checks.Add("PASS clips capture a foreground test window, keep its still frame within the rolling history, and stop and release their buffer when no game is open");
                        }
                    }
                }
            }
            finally { Computer.Glimpse = clipSightWas; Computer.GameOpen = clipOpenWas; }

            System.Threading.Tasks.Task.Factory.StartNew(delegate
            {
                using (SoundTap clipTap = SoundTap.Open(true))
                {
                    if (clipTap == null) checks.Add("LIMIT clips: this PC has no available WASAPI loopback device; clips still save without sound");
                    else
                    {
                        int clipPackets = 0;
                        bool clipSoundRead = true;
                        Stopwatch clipSoundTime = Stopwatch.StartNew();
                        while (clipSoundTime.ElapsedMilliseconds < 150 && clipSoundRead)
                        {
                            long clipSoundNewest;
                            clipSoundRead = clipTap.Read(null, null, out clipSoundNewest, delegate(byte[] clipPcm, long clipAt, int clipRate)
                            {
                                if (clipPcm.Length % 4 != 0 || clipRate < 8000 || clipAt <= 0) throw new Exception("Loopback gave clips invalid PCM or a missing clock time.");
                                clipPackets++;
                            });
                            Thread.Sleep(10);
                        }
                        checks.Add(clipSoundRead && clipPackets > 0 ? "PASS clips read timestamped stereo PCM from WASAPI loopback" : "LIMIT clips: WASAPI produced no readable sound packets during the smoke check");
                    }
                }
                string clipFolder = Path.Combine(Path.GetTempPath(), "Capri-clips-" + Guid.NewGuid().ToString("N"));
                Directory.CreateDirectory(clipFolder);
                try
                {
                    using (ClipBuffer synthetic = new ClipBuffer())
                    using (Bitmap pattern = new Bitmap(98, 66, System.Drawing.Imaging.PixelFormat.Format32bppRgb))
                    {
                        using (Graphics paint = Graphics.FromImage(pattern))
                        {
                            paint.Clear(Color.Red);
                            paint.FillRectangle(Brushes.Blue, 0, 33, 98, 33);
                            paint.FillRectangle(Brushes.Lime, 72, 4, 22, 22);
                        }
                        long origin = 50000000;
                        long[] expected = { 0, 1000000, 4000000, 10000000, 14000000, 19000000 };
                        foreach (long stamp in expected) synthetic.AddFrame(pattern, origin + stamp);
                        byte[] tone = new byte[48000 * 4 * 3];
                        for (int audioSample = 0; audioSample < tone.Length / 4; audioSample++)
                        {
                            short wave = (short)(Math.Sin(audioSample * Math.PI * 880 / 48000) * 6000);
                            for (int audioSide = 0; audioSide < 2; audioSide++)
                            {
                                tone[audioSample * 4 + audioSide * 2] = (byte)wave;
                                tone[audioSample * 4 + audioSide * 2 + 1] = (byte)(wave >> 8);
                            }
                        }
                        synthetic.Keep(tone, origin - 3000000, origin + 27000000, false);
                        synthetic.Advance(origin + 22000000);
                        string clipPath = Path.Combine(clipFolder, "synthetic.mp4");
                        System.Threading.Tasks.Task<ClipResult> fullSave = synthetic.Save(clipPath, 30);
                        ClipResult made = fullSave.GetAwaiter().GetResult();
                        string lastPath = Path.Combine(clipFolder, "last-second.mp4");
                        System.Threading.Tasks.Task<ClipResult> lastSave = synthetic.Save(lastPath, 1);
                        synthetic.Enable(false);
                        if (synthetic.Bytes > ClipBuffer.Memory) throw new Exception("Pending clips exceeded the shared memory budget.");
                        ClipResult lastResult = lastSave.GetAwaiter().GetResult();
                        if (synthetic.Bytes != 0) throw new Exception("Finished clips held onto their frames after capture stopped.");
                        if (made.Unavailable) { checks.Add("LIMIT clips: " + made.Problem); return; }
                        if (made.Problem != null) throw new Exception(made.Problem);
                        if (!File.Exists(clipPath) || new FileInfo(clipPath).Length == 0) throw new Exception("Clips saved no MP4.");
                        double length;
                        Bitmap decoded;
                        long[] actual;
                        bool audio;
                        double audioLength;
                        int audioPeak;
                        ClipMedia.Inspect(clipPath, out length, out decoded, out actual, out audio, out audioLength, out audioPeak);
                        using (decoded)
                        {
                            if (Math.Abs(length - 2.2) > 0.15 || actual.Length != 66) throw new Exception("The clip changed duration or ignored its frame rate: " + length + " seconds, " + actual.Length + " frames.");
                            for (int at = 0; at < actual.Length; at++)
                                if (Math.Abs(actual[at] - at * 10000000L / 30) > 10000) throw new Exception("The clip changed its saved frame cadence.");
                            if (decoded == null || decoded.Width != 98 || decoded.Height != 66) throw new Exception("The clip changed frame dimensions.");
                            Color top = decoded.GetPixel(10, 10), bottom = decoded.GetPixel(10, 55), right = decoded.GetPixel(82, 12);
                            if (top.R < top.B + 100 || bottom.B < bottom.R + 100 || right.G < right.R + 100)
                                throw new Exception("The first decoded clip frame was flipped, had the wrong stride, or swapped colours: " + top + ", " + bottom + ", " + right);
                            if (audio != made.Sound) throw new Exception("The saved clip's audio report was wrong.");
                            if (audio && (Math.Abs(audioLength - 2.2) > 0.15 || audioPeak < 1000)) throw new Exception("The clip's sound lost its samples or wasn't trimmed to the video: " + audioLength + " seconds, peak " + audioPeak);
                        }
                        checks.Add("PASS clips save an H.264 MP4 that Media Foundation reopens at 2.2 seconds and 30 fps from uneven capture, with 98 x 66 pixels and the first frame the right way up");
                        checks.Add(made.Sound ? "PASS clips decode the matching AAC sound with its samples intact and trimmed to the video's length" : "LIMIT clips: this PC couldn't encode AAC; the video saved without sound");
                        if (lastResult.Problem != null || Math.Abs(lastResult.Seconds - 1) > 0.001) throw new Exception("The requested last second wasn't saved: " + lastResult.Problem);
                        ClipMedia.Inspect(lastPath, out length, out decoded, out actual, out audio, out audioLength, out audioPeak);
                        using (decoded)
                            if (Math.Abs(length - 1) > 0.15 || actual.Length != 30 || actual[0] != 0 || Math.Abs(actual[1] - 10000000L / 30) > 10000 || Math.Abs(actual[29] - 290000000L / 30) > 10000)
                                throw new Exception("A shorter clip lost its first held frame or changed speed.");
                        checks.Add("PASS queued clips keep their snapshots when capture stops, trim between captured frames, and release their memory after saving");
                    }
                    using (ClipBuffer silent = new ClipBuffer())
                    using (Bitmap quietFrame = new Bitmap(64, 48))
                    {
                        silent.AddFrame(quietFrame, 0);
                        silent.AddFrame(quietFrame, 1000000);
                        silent.Advance(2000000);
                        string quietPath = Path.Combine(clipFolder, "silent.mp4");
                        ClipResult quietResult = silent.Save(quietPath, 30).GetAwaiter().GetResult();
                        if (quietResult.Problem != null || quietResult.Sound) throw new Exception("A clip without sound couldn't save: " + quietResult.Problem);
                        double quietLength;
                        Bitmap quietDecoded;
                        long[] quietTimes;
                        bool quietAudio;
                        double quietSoundLength;
                        int quietPeak;
                        ClipMedia.Inspect(quietPath, out quietLength, out quietDecoded, out quietTimes, out quietAudio, out quietSoundLength, out quietPeak);
                        using (quietDecoded)
                            if (quietAudio || Math.Abs(quietLength - 0.2) > 0.05) throw new Exception("The silent clip's streams or duration were wrong.");
                        checks.Add("PASS clips also save and reopen without an audio device");
                    }
                }
                finally
                {
                    foreach (string clipTemp in Directory.GetFiles(clipFolder)) File.Delete(clipTemp);
                    Directory.Delete(clipFolder);
                }
            }).GetAwaiter().GetResult();
        }

        private static void SmokeFrames(System.Collections.Generic.List<string> checks)
        {
            Rectangle twoScreens = new Rectangle(-1920, 0, 3840, 1080);
            Rectangle acrossScreens = new Rectangle(-200, 100, 600, 700);
            if (FrameGrab.CaptureArea(acrossScreens, twoScreens) != acrossScreens || FrameGrab.CaptureArea(new Rectangle(-2020, 100, 400, 500), twoScreens) != new Rectangle(-1920, 100, 300, 500)) throw new Exception("A frame crossing monitors was cropped to one monitor.");
            checks.Add("PASS capture bounds preserve a window across two monitors and crop only at the virtual desktop edge");
            if (Screen.AllScreens.Length < 2) checks.Add("LIMIT spanning capture: this desktop has only one monitor; the full frame uses the existing screen-copy fallback");
            const int motionWidth = 128;
            const int motionHeight = 96;
            byte[] motionNoise = new byte[motionWidth * motionHeight];
            byte[] motionFirst = new byte[motionNoise.Length];
            Random motionRandom = new Random(714);
            motionRandom.NextBytes(motionNoise);
            for (int smoothY = 1; smoothY < motionHeight - 1; smoothY++)
                for (int smoothX = 1; smoothX < motionWidth - 1; smoothX++)
                {
                    int smoothSum = 0;
                    for (int blurY = -1; blurY <= 1; blurY++)
                        for (int blurX = -1; blurX <= 1; blurX++) smoothSum += motionNoise[(smoothY + blurY) * motionWidth + smoothX + blurX];
                    motionFirst[smoothY * motionWidth + smoothX] = (byte)(smoothSum / 9);
                }
            double[] motionXs = new double[] { 5, -4.25, 7.4, 0, -10 };
            double[] motionYs = new double[] { -3, 3.5, -6.3, 0, 10 };
            for (int motionCase = 0; motionCase < motionXs.Length; motionCase++)
            {
                byte[] motionSecond = new byte[motionFirst.Length];
                for (int shiftedY = 0; shiftedY < motionHeight; shiftedY++)
                    for (int shiftedX = 0; shiftedX < motionWidth; shiftedX++)
                    {
                        double sourceX = shiftedX - motionXs[motionCase];
                        double sourceY = shiftedY - motionYs[motionCase];
                        int sourceLeft = (int)Math.Floor(sourceX);
                        int sourceTop = (int)Math.Floor(sourceY);
                        if (sourceLeft < 0 || sourceTop < 0 || sourceLeft + 1 >= motionWidth || sourceTop + 1 >= motionHeight) continue;
                        double fractionX = sourceX - sourceLeft;
                        double fractionY = sourceY - sourceTop;
                        int sourceAt = sourceTop * motionWidth + sourceLeft;
                        motionSecond[shiftedY * motionWidth + shiftedX] = (byte)Math.Round(
                            (motionFirst[sourceAt] * (1 - fractionX) + motionFirst[sourceAt + 1] * fractionX) * (1 - fractionY)
                            + (motionFirst[sourceAt + motionWidth] * (1 - fractionX) + motionFirst[sourceAt + motionWidth + 1] * fractionX) * fractionY);
                    }
                double motionDx, motionDy, motionMatch;
                if (!Motion.Shift(motionFirst, motionSecond, motionWidth, motionHeight, 10, out motionDx, out motionDy, out motionMatch)
                    || Math.Abs(motionDx - motionXs[motionCase]) > 0.5 || Math.Abs(motionDy - motionYs[motionCase]) > 0.5)
                    throw new Exception("Gray motion missed a known shift: " + motionXs[motionCase] + ", " + motionYs[motionCase] + " became " + motionDx + ", " + motionDy + " with match " + motionMatch);
            }
            byte[] motionBlank = new byte[motionFirst.Length];
            double blankDx, blankDy, blankMatch;
            if (Motion.Changed(motionBlank, new byte[motionBlank.Length]) != 0 || Motion.Shift(motionBlank, motionBlank, motionWidth, motionHeight, 10, out blankDx, out blankDy, out blankMatch))
                throw new Exception("Blank gray frames looked changed or had a camera shift.");
            if (Motion.Shift(motionFirst, motionBlank, motionWidth, motionHeight, 10, out blankDx, out blankDy, out blankMatch)
                || Motion.Shift(motionFirst, motionNoise, motionWidth, motionHeight, 10, out blankDx, out blankDy, out blankMatch)) throw new Exception("Unmatched gray frames had a camera shift.");
            if (Motion.Changed(new byte[] { 1, 2, 3, 4 }, new byte[] { 1, 8, 3, 9 }) != 0.5) throw new Exception("Changed gray pixels were not counted.");
            checks.Add("PASS gray motion finds positive, negative, fractional, still and reach-edge shifts within half a pixel; blank frames stay unchanged and have no false match");
            SmokeGray(checks);

            Rectangle frameScreen = Screen.PrimaryScreen.Bounds;
            using (Form frameForm = new Form())
            using (FrameGrab frameGrab = new FrameGrab())
            {
                frameForm.FormBorderStyle = FormBorderStyle.None;
                frameForm.ShowInTaskbar = false;
                frameForm.StartPosition = FormStartPosition.Manual;
                frameForm.Bounds = new Rectangle(frameScreen.Left + 40, frameScreen.Top + 40, 320, 180);
                frameForm.TopMost = true;
                frameForm.BackColor = Color.Red;
                frameForm.Show();
                frameForm.Refresh();
                Application.DoEvents();
                frameGrab.Open(frameForm.RectangleToScreen(frameForm.ClientRectangle));
                bool frameDuplication = frameGrab.Live == "DXGI Desktop Duplication";
                byte[] frameRed = SmokeFrameColour(frameGrab, frameForm, Color.Red);
                byte[] frameBlue = SmokeFrameColour(frameGrab, frameForm, Color.Blue);
                if (frameRed == null || frameBlue == null)
                {
                    if (frameDuplication && frameGrab.Live == "DXGI Desktop Duplication") throw new Exception("Desktop duplication did not see the form change colour.");
                    checks.Add("LIMIT screen frames could not see the test form on this desktop; " + frameGrab.Live);
                }
                else
                {
                    if (Motion.Changed(frameRed, frameBlue) < 0.95) throw new Exception("The colour change was lost in the gray frame.");
                    using (Bitmap frameCopy = frameGrab.Copy(80))
                        if (frameCopy == null || frameCopy.Width != 80 || frameCopy.Height != 45) throw new Exception("The copied frame did not keep its aspect ratio.");
                    frameGrab.Open(new Rectangle(frameForm.Left + 31, frameForm.Top + 17, 120, 80));
                    if (SmokeFrameColour(frameGrab, frameForm, Color.Lime) == null) throw new Exception("Reopening the frame area did not capture its new colour.");
                    using (Bitmap frameCrop = frameGrab.Copy(200))
                        if (frameCrop == null || frameCrop.Width != 120 || frameCrop.Height != 80) throw new Exception("The output crop had the wrong size.");
                    checks.Add("PASS screen frames see a form change red, blue and green, copy at the requested width and reopen a smaller crop; " + frameGrab.Live);
                    if (!frameDuplication || frameGrab.Live != "DXGI Desktop Duplication") checks.Add("LIMIT DXGI Desktop Duplication is unavailable here; screen capture used Graphics.CopyFromScreen");
                }
                frameForm.Close();
            }
            // She sees a game's own window under anything of hers on top of it, whatever else is in front stays, and a copy that doesn't look like the screen is left out.
            using (Form underForm = new Form())
            using (Form overForm = new Form())
            {
                foreach (Form overPart in new[] { underForm, overForm })
                {
                    overPart.FormBorderStyle = FormBorderStyle.None;
                    overPart.ShowInTaskbar = false;
                    overPart.StartPosition = FormStartPosition.Manual;
                    overPart.TopMost = true;
                }
                underForm.Bounds = new Rectangle(frameScreen.Left + 40, frameScreen.Top + 40, 320, 180);
                underForm.BackColor = Color.Lime;
                overForm.Bounds = new Rectangle(frameScreen.Left + 160, frameScreen.Top + 110, 80, 40);
                overForm.BackColor = Color.Magenta;
                underForm.Show();
                overForm.Show();
                underForm.Refresh();
                overForm.Refresh();
                Application.DoEvents();
                Thread.Sleep(200);
                Application.DoEvents();
                Rectangle overArea = underForm.Bounds;
                Rectangle[] overHers = { overForm.Bounds };
                IntPtr underHandle = underForm.Handle;
                using (Bitmap overShot = new Bitmap(overArea.Width, overArea.Height, PixelFormat.Format24bppRgb))
                using (Bitmap overStale = new Bitmap(overArea.Width, overArea.Height, PixelFormat.Format24bppRgb))
                {
                    bool overScreen = true;
                    try { using (Graphics overDraw = Graphics.FromImage(overShot)) overDraw.CopyFromScreen(overArea.Location, Point.Empty, overArea.Size); }
                    // A desktop Windows isn't showing, like the hidden one smoke runs on, has no screen to copy ("The handle is invalid").
                    catch (System.ComponentModel.Win32Exception) { overScreen = false; }
                    if (!overScreen) checks.Add("LIMIT window copies: this desktop has no screen to copy from");
                    else
                    {
                        using (Graphics overDraw = Graphics.FromImage(overStale)) overDraw.Clear(Color.Blue);
                        Color overBefore = overShot.GetPixel(160, 90);
                        bool overHadIt = overBefore.R > 200 && overBefore.G < 80 && overBefore.B > 200, overCopied = false, overStaleCopied = true, overDone = false;
                        // A window of someone else's in front of the game.
                        overShot.SetPixel(20, 20, Color.Red);
                        Thread overThread = new Thread(delegate()
                        {
                            overCopied = Computer.WindowOver(overShot, overArea, underHandle, overHers);
                            overStaleCopied = Computer.WindowOver(overStale, overArea, underHandle, overHers);
                            overDone = true;
                        });
                        overThread.Start();
                        while (!overDone) { Application.DoEvents(); Thread.Sleep(5); }
                        Color overSeen = overShot.GetPixel(160, 90), overLeft = overStale.GetPixel(160, 90), overOther = overShot.GetPixel(20, 20);
                        if (overStaleCopied || overLeft.B < 200) throw new Exception("A window copy that didn't look like the screen went over it.");
                        if (!overHadIt) checks.Add("LIMIT window copies: the test window never got on top of the other one here");
                        else if (!overCopied || overSeen.G < 200 || overSeen.R > 60) throw new Exception("She couldn't see through her own window: " + overCopied + " " + overSeen);
                        else if (overOther.R < 200 || overOther.G > 60) throw new Exception("A window copy painted over something that isn't hers: " + overOther);
                        else checks.Add("PASS window copies: a game's own window shows what's under anything of hers and nothing else, and a copy that doesn't match the screen is left out");
                    }
                }
                overForm.Close();
                underForm.Close();
            }
            using (FrameGrab speedGrab = new FrameGrab())
            {
                speedGrab.Open(frameScreen);
                if (speedGrab.Next(500))
                {
                    int speedHeight = Math.Max(1, (int)((long)frameScreen.Height * 480 / frameScreen.Width));
                    byte[] speedGray = speedGrab.Gray(480, speedHeight);
                    if (speedGray != null)
                    {
                        for (int speedWarm = 0; speedWarm < 5; speedWarm++) speedGrab.Gray(480, speedHeight);
                        Stopwatch speedWatch = Stopwatch.StartNew();
                        for (int speedRun = 0; speedRun < 30; speedRun++)
                            if (speedGrab.Gray(480, speedHeight) == null) throw new Exception("Gray frames disappeared during the timing check.");
                        double speedMs = speedWatch.Elapsed.TotalMilliseconds / 30;
                        checks.Add((speedMs < 3 ? "PASS " : "LIMIT ") + "480-wide box gray from " + frameScreen.Width + "x" + frameScreen.Height + " takes " + speedMs.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture) + " ms per copy here; " + speedGrab.Live);
                    }
                    else checks.Add("LIMIT gray frame timing lost access to this desktop");
                }
                else checks.Add("LIMIT gray frame timing had no desktop frame");
            }
        }

        private static void SmokeGray(System.Collections.Generic.List<string> checks)
        {
            const int graySourceWidth = 49;
            const int graySourceHeight = 37;
            const int grayStride = 208;
            byte[] grayPixels = new byte[grayStride * graySourceHeight];
            new Random(331).NextBytes(grayPixels);
            GCHandle grayPin = GCHandle.Alloc(grayPixels, GCHandleType.Pinned);
            try
            {
                for (int grayRotation = 0; grayRotation < 4; grayRotation++)
                {
                    int grayViewWidth = grayRotation % 2 == 0 ? graySourceWidth : graySourceHeight;
                    int grayViewHeight = grayRotation % 2 == 0 ? graySourceHeight : graySourceWidth;
                    int grayAcross = grayRotation == 0 ? 4 : grayRotation == 1 ? -grayStride : grayRotation == 2 ? -4 : grayStride;
                    int grayDown = grayRotation == 0 ? grayStride : grayRotation == 1 ? 4 : grayRotation == 2 ? -grayStride : -4;
                    int grayOrigin = grayRotation == 0 ? 0 : grayRotation == 1 ? (graySourceHeight - 1) * grayStride : grayRotation == 2 ? (graySourceHeight - 1) * grayStride + (graySourceWidth - 1) * 4 : (graySourceWidth - 1) * 4;
                    for (int grayCase = 0; grayCase < 3; grayCase++)
                    {
                        int grayWidth = grayCase == 0 ? 5 : grayCase == 1 ? 1 : 80;
                        int grayHeight = grayCase == 0 ? 4 : grayCase == 1 ? 1 : 60;
                        byte[] grayMade = FrameGrab.Downsample(IntPtr.Add(grayPin.AddrOfPinnedObject(), grayOrigin), grayViewWidth, grayViewHeight, grayAcross, grayDown, grayWidth, grayHeight);
                        for (int grayTestY = 0; grayTestY < grayHeight; grayTestY++)
                            for (int grayTestX = 0; grayTestX < grayWidth; grayTestX++)
                            {
                                int grayLeft = grayTestX * grayViewWidth / grayWidth;
                                int grayRight = Math.Max(grayLeft + 1, (grayTestX + 1) * grayViewWidth / grayWidth);
                                int grayTop = grayTestY * grayViewHeight / grayHeight;
                                int grayBottom = Math.Max(grayTop + 1, (grayTestY + 1) * grayViewHeight / grayHeight);
                                long graySum = 0;
                                for (int grayBoxY = grayTop; grayBoxY < grayBottom; grayBoxY++)
                                    for (int grayBoxX = grayLeft; grayBoxX < grayRight; grayBoxX++)
                                    {
                                        int grayReadX = grayRotation == 0 ? grayBoxX : grayRotation == 1 ? grayBoxY : grayRotation == 2 ? graySourceWidth - 1 - grayBoxX : graySourceWidth - 1 - grayBoxY;
                                        int grayReadY = grayRotation == 0 ? grayBoxY : grayRotation == 1 ? graySourceHeight - 1 - grayBoxX : grayRotation == 2 ? graySourceHeight - 1 - grayBoxY : grayBoxX;
                                        int grayReadAt = grayReadY * grayStride + grayReadX * 4;
                                        graySum += grayPixels[grayReadAt] * 29 + grayPixels[grayReadAt + 1] * 150 + grayPixels[grayReadAt + 2] * 77;
                                    }
                                byte grayExpected = (byte)(graySum / (256 * (grayRight - grayLeft) * (grayBottom - grayTop)));
                                if (grayMade[grayTestY * grayWidth + grayTestX] != grayExpected) throw new Exception("Box gray differs from its pixels at rotation " + grayRotation + ".");
                            }
                    }
                }
            }
            finally { grayPin.Free(); }
            checks.Add("PASS box gray averages every pixel with padded rows, odd boxes, large boxes, all four rotations and enlarged copies");
            foreach (int grayBenchWidth in new int[] { 1920, 3840 })
            {
                int grayBenchHeight = grayBenchWidth * 9 / 16;
                int grayBox = grayBenchWidth / 480;
                byte[] grayBench = new byte[grayBenchWidth * grayBenchHeight * 4];
                new Random(95).NextBytes(grayBench);
                GCHandle grayBenchPin = GCHandle.Alloc(grayBench, GCHandleType.Pinned);
                try
                {
                    IntPtr grayBenchAt = grayBenchPin.AddrOfPinnedObject();
                    byte[] grayBenchMade = FrameGrab.Downsample(grayBenchAt, grayBenchWidth, grayBenchHeight, 4, grayBenchWidth * 4, 480, 270);
                    for (int grayCheckAt = 0; grayCheckAt < grayBenchMade.Length; grayCheckAt += 997)
                    {
                        int grayCheckLeft = (grayCheckAt % 480) * grayBox;
                        int grayCheckTop = (grayCheckAt / 480) * grayBox;
                        int grayCheckSum = 0;
                        for (int grayCheckY = 0; grayCheckY < grayBox; grayCheckY++)
                            for (int grayCheckX = 0; grayCheckX < grayBox; grayCheckX++)
                            {
                                int grayPixelAt = ((grayCheckTop + grayCheckY) * grayBenchWidth + grayCheckLeft + grayCheckX) * 4;
                                grayCheckSum += grayBench[grayPixelAt] * 29 + grayBench[grayPixelAt + 1] * 150 + grayBench[grayPixelAt + 2] * 77;
                            }
                        if (grayBenchMade[grayCheckAt] != grayCheckSum / (256 * grayBox * grayBox)) throw new Exception("Fast gray boxes differ from their source pixels.");
                    }
                    for (int grayWarm = 0; grayWarm < 8; grayWarm++) FrameGrab.Downsample(grayBenchAt, grayBenchWidth, grayBenchHeight, 4, grayBenchWidth * 4, 480, 270);
                    Stopwatch grayClock = Stopwatch.StartNew();
                    for (int grayRun = 0; grayRun < 40; grayRun++) FrameGrab.Downsample(grayBenchAt, grayBenchWidth, grayBenchHeight, 4, grayBenchWidth * 4, 480, 270);
                    double grayCost = grayClock.Elapsed.TotalMilliseconds / 40;
                    checks.Add((grayCost < 3 ? "PASS " : "LIMIT ") + grayBenchWidth + "x" + grayBenchHeight + " pixels to 480-wide box gray take " + grayCost.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture) + " ms per copy here, including allocation");
                }
                finally { grayBenchPin.Free(); }
            }
        }

        private static byte[] SmokeFrameColour(FrameGrab grab, Form form, Color colour)
        {
            form.BackColor = colour;
            form.Refresh();
            Stopwatch colourWait = Stopwatch.StartNew();
            while (colourWait.ElapsedMilliseconds < 2500)
            {
                Application.DoEvents();
                if (grab.Next(40))
                {
                    using (Bitmap colourCopy = grab.Copy(80))
                    {
                        if (colourCopy != null)
                        {
                            Color colourSeen = colourCopy.GetPixel(colourCopy.Width / 2, colourCopy.Height / 2);
                            if (Math.Abs(colourSeen.R - colour.R) < 35 && Math.Abs(colourSeen.G - colour.G) < 35 && Math.Abs(colourSeen.B - colour.B) < 35)
                                return grab.Gray(64, 36);
                        }
                    }
                }
                Thread.Sleep(10);
            }
            return null;
        }

        private static void SmokeGameSense(System.Collections.Generic.List<string> checks)
        {
            byte[] senseWorld = new byte[480 * 270 * 4];
            Random senseRandom = new Random(627);
            for (int noiseAt = 0; noiseAt < senseWorld.Length; noiseAt += 4)
            {
                senseWorld[noiseAt] = (byte)senseRandom.Next(25, 190);
                senseWorld[noiseAt + 1] = (byte)senseRandom.Next(25, 190);
                senseWorld[noiseAt + 2] = (byte)senseRandom.Next(25, 190);
                senseWorld[noiseAt + 3] = 255;
            }
            string[] senseClips = { "flash", "hurt", "bar_drop", "cut", "dark", "pan", "red wall", "steady bar", "small drop", "day to night", "sky", "tilt", "vertical bar", "right bar", "empty bar", "same colours", "brief cut", "held light", "cooldown", "cut hold", "idle then pan", "idle then fade", "idle then bar", "slow drain", "drain then drop", "long flash", "light cut", "tooltip", "crossing", "loading bar" };
            for (int senseCase = 0; senseCase < senseClips.Length + 2; senseCase++)
            {
                bool uneven = senseCase >= senseClips.Length;
                string clip = uneven ? senseCase == senseClips.Length ? "slow drain" : "drain then drop" : senseClips[senseCase];
                GameSense sense = new GameSense();
                System.Collections.Generic.List<string> senseKinds = new System.Collections.Generic.List<string>();
                System.Collections.Generic.List<double> senseTimes = new System.Collections.Generic.List<double>();
                System.Collections.Generic.List<double> senseStrengths = new System.Collections.Generic.List<double>();
                double senseNow = 0;
                sense.Noticed += delegate(string ignoredKind, double ignoredStrength) { throw new Exception("A failing game sense subscriber."); };
                sense.Noticed += delegate(string sensedKind, double sensedStrength)
                {
                    senseKinds.Add(sensedKind); senseTimes.Add(senseNow); senseStrengths.Add(sensedStrength);
                };
                for (int senseFrame = 0; senseFrame < (uneven ? 130 : 65); senseFrame++)
                {
                    senseNow = uneven ? senseFrame / 10.0 + (senseFrame % 2 == 0 ? 0 : 0.04) : senseFrame / 5.0;
                    sense.Feed(SenseFrame(senseWorld, clip, (int)Math.Floor(senseNow * 5 + 0.000001)), 240, 135, senseNow);
                }
                string expected = senseCase < 5 ? clip : clip == "vertical bar" || clip == "right bar" || clip == "idle then bar" || clip == "drain then drop" ? "bar_drop" : clip == "same colours" || clip == "cut hold" || clip == "light cut" ? "cut" : clip == "cooldown" || clip == "held light" || clip == "long flash" ? "flash" : null;
                int expectedCount = clip == "cooldown" ? 2 : expected == null ? 0 : 1;
                if (senseKinds.Count != expectedCount) throw new Exception("Game sense " + clip + " expected " + expectedCount + " events, got " + string.Join(", ", senseKinds) + " at " + string.Join(", ", senseTimes));
                for (int senseEvent = 0; senseEvent < senseKinds.Count; senseEvent++)
                {
                    if (double.IsNaN(senseStrengths[senseEvent]) || senseStrengths[senseEvent] < 0 || senseStrengths[senseEvent] > 1) throw new Exception("Invalid game sense strength.");
                    double earliest = expected == "flash" ? clip == "held light" || clip == "long flash" ? 5.2 : senseEvent == 0 ? 4.4 : 8.4 : expected == "bar_drop" ? clip == "idle then bar" || clip == "drain then drop" ? 8.2 : 4.2 : expected == "cut" ? clip == "light cut" ? 5.2 : 4.6 : expected == "dark" ? 7.0 : 4.0;
                    if (senseKinds[senseEvent] != expected || senseTimes[senseEvent] < earliest - 0.01 || senseTimes[senseEvent] > earliest + 0.6)
                        throw new Exception("Game sense " + clip + " fired " + senseKinds[senseEvent] + " at " + senseTimes[senseEvent] + ", expected " + expected + " near " + earliest + ".");
                    if (expected == "bar_drop" && Math.Abs(senseStrengths[senseEvent] - 0.3) > 0.015) throw new Exception("Game sense lost the size of a bar drop.");
                }
            }
            checks.Add("PASS game sense: scrolling colour noise with a fixed HUD notices one flash, red edge hurt, 30% bar loss, persistent cut and dark fade at the right times; strengths stay in range, horizontal, vertical and right-anchored bars keep the lost fraction");
            checks.Add("PASS game sense stays quiet through fast panning, a red wall across the middle, steady HUD, 3% bar loss, slow day to night, bright sky, damage tilt and a brief scene change; same-colour cuts persist, cooldowns and cut holds prevent repeats");
            checks.Add("PASS game sense ignores a bar emptying all at once, a tooltip closing, something crossing a bar and a progress bar starting over");
            checks.Add("PASS game sense ignores an idle strip that pans away or fades, learns a fixed bar when its surroundings move and ignores a 40% drain over three seconds while catching a later sudden 30% drop at regular and uneven feed times");
            checks.Add("PASS game sense calls held near-white light a single flash after the hold expires, including when the picture returns; a bright coloured scene still becomes a cut");

            GameSense resetSense = new GameSense();
            int resetNotices = 0;
            resetSense.Noticed += delegate(string resetKind, double resetStrength) { resetNotices++; };
            byte[] resetFrame = SenseFrame(senseWorld, "steady bar", 0);
            for (int invalidCase = 0; invalidCase < 10; invalidCase++)
            {
                for (int resetWarm = 0; resetWarm < 20; resetWarm++) resetSense.Feed(SenseFrame(senseWorld, "steady bar", resetWarm), 240, 135, resetWarm / 5.0);
                if (invalidCase == 0) resetSense.Feed(null, 240, 135, 4);
                else if (invalidCase == 1) resetSense.Feed(new byte[7], 240, 135, 4);
                else if (invalidCase == 2) resetSense.Feed(resetFrame, int.MaxValue, int.MaxValue, 4);
                else if (invalidCase == 3) resetSense.Feed(resetFrame, 0, 135, 4);
                else if (invalidCase == 4) resetSense.Feed(resetFrame, 240, -135, 4);
                else if (invalidCase == 5) resetSense.Feed(resetFrame, 240, 135, double.NaN);
                else if (invalidCase == 6) resetSense.Feed(resetFrame, 240, 135, double.PositiveInfinity);
                else if (invalidCase == 7) resetSense.Feed(new byte[32 * 24 * 4], 32, 24, 4);
                else if (invalidCase == 8) resetSense.Feed(resetFrame, 240, 135, -1);
                else resetSense.Reset();
                resetSense.Feed(SenseFrame(senseWorld, "bar_drop", 20), 240, 135, 4.2);
                if (resetNotices != 0) throw new Exception("Bad game frames or Reset kept old bar evidence.");
                resetSense.Reset();
            }
            resetSense.Feed(new byte[4], 1, 1, 0);
            resetSense.Feed(new byte[] { 255, 255, 255, 255 }, 1, 1, 0.2);
            resetSense.Reset();
            for (int repeatRound = 0; repeatRound < 2; repeatRound++)
            {
                for (int repeatFrame = 0; repeatFrame < 30; repeatFrame++)
                {
                    byte[] reused = SenseFrame(senseWorld, "bar_drop", repeatFrame);
                    Buffer.BlockCopy(reused, 0, resetFrame, 0, reused.Length);
                    resetSense.Feed(resetFrame, 240, 135, repeatFrame / 5.0);
                }
                if (resetNotices != repeatRound + 1) throw new Exception("Reset kept a cooldown or game sense retained the caller's reused buffer.");
                resetSense.Reset();
            }
            checks.Add("PASS game sense resets on malformed frames, changed dimensions, invalid or reversed clocks and Reset; tiny frames are safe, reused caller buffers work, reset clears cooldowns and failing subscribers stay contained");
            using (Bitmap senseBitmap = new Bitmap(480, 270, PixelFormat.Format32bppArgb))
            {
                using (Graphics senseDrawing = Graphics.FromImage(senseBitmap)) senseDrawing.Clear(Color.FromArgb(255, 210, 90, 30));
                byte[] senseBgra = GameSense.Bgra(senseBitmap, 240, 135);
                int middleAt = (67 * 240 + 120) * 4;
                if (senseBgra == null || senseBgra.Length != 240 * 135 * 4 || senseBgra[middleAt] != 30 || senseBgra[middleAt + 1] != 90 || senseBgra[middleAt + 2] != 210 || senseBgra[middleAt + 3] != 255) throw new Exception("Game sense bitmap conversion lost BGRA order or dimensions.");
                if (GameSense.Bgra(null, 240, 135) != null || GameSense.Bgra(senseBitmap, 0, 135) != null || GameSense.Bgra(senseBitmap, int.MaxValue, int.MaxValue) != null) throw new Exception("Game sense bitmap conversion accepted invalid input.");
            }
            checks.Add("PASS game sense makes a small BGRA frame from a bitmap and rejects invalid conversions");

            byte[][] senseBench = new byte[65][];
            for (int benchFrame = 0; benchFrame < senseBench.Length; benchFrame++) senseBench[benchFrame] = SenseFrame(senseWorld, "same colours", benchFrame);
            Process senseProcess = Process.GetCurrentProcess();
            IntPtr senseAffinity = IntPtr.Zero;
            bool sensePinned = false;
            try
            {
                try
                {
                    senseAffinity = senseProcess.ProcessorAffinity;
                    long senseMask = senseAffinity.ToInt64();
                    senseProcess.ProcessorAffinity = new IntPtr(senseMask & -senseMask);
                    sensePinned = true;
                }
                catch (System.ComponentModel.Win32Exception) { }
                catch (InvalidOperationException) { }
                GameSense timedSense = new GameSense();
                for (int timingWarm = 0; timingWarm < senseBench.Length; timingWarm++) timedSense.Feed(senseBench[timingWarm], 240, 135, timingWarm / 5.0);
                GC.Collect();
                GC.WaitForPendingFinalizers();
                double timingTotal = 0, timingPeak = 0;
                for (int timingRound = 0; timingRound < 8; timingRound++)
                {
                    timedSense.Reset();
                    for (int timingFrame = 0; timingFrame < senseBench.Length; timingFrame++)
                    {
                        long timingStart = Stopwatch.GetTimestamp();
                        timedSense.Feed(senseBench[timingFrame], 240, 135, timingFrame / 5.0);
                        double timingMs = (Stopwatch.GetTimestamp() - timingStart) * 1000.0 / Stopwatch.Frequency;
                        timingTotal += timingMs;
                        timingPeak = Math.Max(timingPeak, timingMs);
                    }
                }
                double timingMean = timingTotal / (8 * senseBench.Length);
                checks.Add((sensePinned && timingPeak < 2 ? "PASS " : "LIMIT ") + "game sense at 240x135 takes " + timingMean.ToString("0.000", System.Globalization.CultureInfo.InvariantCulture) + " ms per frame, slowest " + timingPeak.ToString("0.000", System.Globalization.CultureInfo.InvariantCulture) + " ms here" + (sensePinned ? " on one core" : "; processor affinity unavailable, one-core timing not verified"));
            }
            finally
            {
                if (sensePinned) senseProcess.ProcessorAffinity = senseAffinity;
                senseProcess.Dispose();
            }
        }

        private static byte[] SenseFrame(byte[] world, string clip, int number)
        {
            const int width = 240, height = 135;
            byte[] pixels = new byte[width * height * 4];
            bool after = number >= 20;
            bool cut = (clip == "cut" || clip == "same colours" || clip == "cut hold") && after || clip == "brief cut" && number == 20;
            bool idle = clip == "idle then pan" || clip == "idle then fade" || clip == "idle then bar";
            int shift = clip == "idle then fade" ? 0 : idle ? Math.Max(0, number - 19) * (clip == "idle then pan" ? 43 : 3) : number * (clip == "pan" ? 43 : 3);
            for (int worldY = 0; worldY < height; worldY++)
                for (int worldX = 0; worldX < width; worldX++)
                {
                    int sourceY = (worldY + (cut ? 135 : 0) + (clip == "tilt" ? (worldX - 120) * (number % 5 - 2) / 60 : 0) + 270) % 270;
                    int sourceX = (worldX + shift) % 480;
                    int sourceAt = (sourceY * 480 + sourceX) * 4;
                    int targetAt = (worldY * width + worldX) * 4;
                    pixels[targetAt] = world[sourceAt]; pixels[targetAt + 1] = world[sourceAt + 1]; pixels[targetAt + 2] = world[sourceAt + 2]; pixels[targetAt + 3] = 255;
                    if (cut && clip != "same colours") { pixels[targetAt] = (byte)(140 + pixels[targetAt] / 2); pixels[targetAt + 1] /= 2; pixels[targetAt + 2] /= 2; }
                    if (clip == "day to night")
                    {
                        double daylight = 1 - number / 80.0;
                        pixels[targetAt] = (byte)(pixels[targetAt] * daylight); pixels[targetAt + 1] = (byte)(pixels[targetAt + 1] * daylight); pixels[targetAt + 2] = (byte)(pixels[targetAt + 2] * daylight);
                    }
                    if (clip == "sky" && worldY < number * 3 - 30) { pixels[targetAt] = 245; pixels[targetAt + 1] = 225; pixels[targetAt + 2] = 180; }
                    if (clip == "red wall" && worldY > 25 && worldY < 110 && worldX > number * 7 - 180 && worldX < number * 7 - 90) { pixels[targetAt] = 15; pixels[targetAt + 1] = 15; pixels[targetAt + 2] = 230; }
                }
            bool dropping = clip == "bar_drop" || clip == "vertical bar" || clip == "right bar" || clip == "empty bar" || clip == "small drop" || clip == "cut hold";
            int barFill = after && dropping ? clip == "small drop" ? 97 : clip == "empty bar" ? 0 : 70 : 100;
            if (clip == "slow drain" || clip == "drain then drop") barFill = 100 - Math.Min(40, Math.Max(0, number - 20) * 40 / 15) - (clip == "drain then drop" && number >= 40 ? 30 : 0);
            if (clip == "idle then bar" && number >= 40) barFill = 70;
            if (clip == "loading bar") barFill = number % 20 * 5 + 5;
            bool upright = clip == "vertical bar";
            for (int hudRow = 0; hudRow < (upright ? 104 : 10); hudRow++)
                for (int hudColumn = 0; hudColumn < (upright ? 10 : 104); hudColumn++)
                {
                    int hudX = hudColumn + 10 - (clip == "idle then pan" ? shift : 0);
                    if (hudX < 0 || clip == "idle then fade" && number >= 20) continue;
                    int hudAt = ((hudRow + 8) * width + hudX) * 4;
                    int barPosition = upright ? hudRow - 2 : hudColumn - 2;
                    bool filled = (upright ? hudColumn >= 2 && hudColumn < 8 : hudRow >= 2 && hudRow < 8) && barPosition >= 0 && barPosition < 100
                        && (clip == "right bar" || upright ? barPosition >= 100 - barFill : barPosition < barFill);
                    pixels[hudAt] = filled ? (byte)30 : (byte)16; pixels[hudAt + 1] = filled ? (byte)220 : (byte)16; pixels[hudAt + 2] = filled ? (byte)35 : (byte)16;
                }
            if (clip == "tooltip" && !after)
                for (int tipRow = 118; tipRow < 124; tipRow++)
                    for (int tipColumn = 60; tipColumn < 170; tipColumn++)
                    {
                        int tipAt = (tipRow * width + tipColumn) * 4;
                        pixels[tipAt] = 216; pixels[tipAt + 1] = 154; pixels[tipAt + 2] = 105;
                    }
            if (clip == "crossing" && after && number < 26)
                for (int crossRow = 5; crossRow < 20; crossRow++)
                    for (int crossColumn = 50; crossColumn < 70; crossColumn++)
                    {
                        int crossAt = (crossRow * width + crossColumn) * 4;
                        pixels[crossAt] = 90; pixels[crossAt + 1] = 60; pixels[crossAt + 2] = 40;
                    }
            bool flash = clip == "flash" && number >= 20 && number < 22 || clip == "cooldown" && (number >= 20 && number < 22 || number >= 25 && number < 27 || number >= 40 && number < 42) || clip == "long flash" && number >= 20 && number < 30 || (clip == "held light" || clip == "light cut") && after;
            for (int effectY = 0; effectY < height; effectY++)
                for (int effectX = 0; effectX < width; effectX++)
                {
                    int effectAt = (effectY * width + effectX) * 4;
                    if (flash)
                    {
                        pixels[effectAt] = (byte)(210 + pixels[effectAt] / 6); pixels[effectAt + 1] = (byte)(210 + pixels[effectAt + 1] / 6); pixels[effectAt + 2] = (byte)(210 + pixels[effectAt + 2] / 6);
                        if (clip == "light cut") pixels[effectAt] -= 55;
                    }
                    bool edgeHurt = clip == "hurt" && number >= 20 && number < 25 || clip == "cut hold" && number >= 23 && number < 27;
                    if (edgeHurt && (effectX < 24 || effectX >= 216 || effectY < 14 || effectY >= 121))
                    {
                        pixels[effectAt] /= 4; pixels[effectAt + 1] /= 4; pixels[effectAt + 2] = 230;
                    }
                    if (clip == "dark" && after)
                    {
                        double fade = Math.Max(0, 1 - (number - 20) / 10.0);
                        pixels[effectAt] = (byte)(pixels[effectAt] * fade); pixels[effectAt + 1] = (byte)(pixels[effectAt + 1] * fade); pixels[effectAt + 2] = (byte)(pixels[effectAt + 2] * fade);
                    }
                }
            return pixels;
        }

        private static void SmokeGameEars(System.Collections.Generic.List<string> checks)
        {
            System.Collections.Generic.Dictionary<int, int> gameParents = new System.Collections.Generic.Dictionary<int, int>();
            gameParents.Add(103, 102);
            gameParents.Add(102, 101);
            gameParents.Add(101, 100);
            gameParents.Add(201, 200);
            System.Collections.Generic.HashSet<int> gameFamily = GameEars.Family(100, gameParents);
            if (gameFamily.Count != 4 || !gameFamily.Contains(100) || !gameFamily.Contains(103) || gameFamily.Contains(201)) throw new Exception("Game audio did not follow only its process family.");
            using (GameEars gameSpikes = new GameEars(int.MaxValue))
            {
                int gameLoud = 0;
                gameSpikes.Loud += delegate(double ignoredLevel) { throw new Exception("A failing loud subscriber."); };
                gameSpikes.Loud += delegate(double heardLevel) { if (heardLevel > 0.5) gameLoud++; };
                for (int quietSample = 0; quietSample < 65; quietSample++) gameSpikes.Hear(0.01, quietSample / 30.0);
                gameSpikes.Hear(0.8, 3);
                gameSpikes.Hear(0.7, 3.033);
                gameSpikes.Hear(0.01, 3.066);
                gameSpikes.Hear(0.9, 3.1);
                if (gameLoud != 1) throw new Exception("One game sound fired more than once or its subscriber escaped.");
                gameSpikes.Hear(0.01, 3.2);
                gameSpikes.Hear(0.85, 3.3);
                if (gameLoud != 2 || Math.Abs(gameSpikes.Level - 0.85) > 0.001) throw new Exception("The next game spike or its peak level was lost.");
                for (int heldSample = 0; heldSample < 90; heldSample++) gameSpikes.Hear(0.85, 3.34 + heldSample / 30.0);
                if (gameLoud != 2) throw new Exception("A held game sound kept firing loud events.");
            }
            checks.Add("PASS game levels follow children and grandchildren, detect spikes over a rolling median, keep one sound to one event and contain failing subscribers");
            using (GameEars gameSilence = new GameEars(int.MaxValue))
            {
                int silentLoud = 0;
                gameSilence.Loud += delegate(double unexpectedLevel) { Interlocked.Increment(ref silentLoud); };
                for (int startRound = 0; startRound < 3; startRound++)
                {
                    gameSilence.Start();
                    gameSilence.Start();
                    Stopwatch silenceWait = Stopwatch.StartNew();
                    while (gameSilence.Samples < 4 && silenceWait.ElapsedMilliseconds < 4000) Thread.Sleep(10);
                    if (!gameSilence.Listening || gameSilence.Samples < 4 || gameSilence.Level != 0) throw new Exception("Game ears did not poll quietly with no matching session.");
                    gameSilence.Stop();
                    gameSilence.Stop();
                    if (gameSilence.Listening || gameSilence.Level != 0 || silentLoud != 0) throw new Exception("Game ears did not stop cleanly with no matching session.");
                }
                checks.Add("PASS game ears start, poll and stop repeatedly with no matching audio session and no loud event");
                if (!gameSilence.Available) checks.Add("LIMIT this desktop has no accessible active Core Audio render session manager; game peak meters need a live audio session");
                gameSilence.Start();
                gameSilence.Dispose();
                gameSilence.Dispose();
                if (gameSilence.Listening) throw new Exception("Disposing game ears left its worker running.");
            }
            checks.Add("PASS disposing game ears wakes and joins its background thread");
        }

        // Smoke checks call the handlers themselves. Input arriving while they pump messages belongs to whoever is using the PC.
        private sealed class SmokeInput : IMessageFilter
        {
            public bool PreFilterMessage(ref Message message)
            {
                return (message.Msg >= 0x0100 && message.Msg <= 0x0109) || (message.Msg >= 0x0200 && message.Msg <= 0x020E)
                    || (message.Msg >= 0x00A0 && message.Msg <= 0x00AD) || message.Msg == 0x0312;
            }
        }

        // A made-up game that hides the real cursor and only looks at where it is when mouse movement comes in, like Cyberpunk 2077.
        private static void SmokeSteering(System.Collections.Generic.List<string> checks)
        {
            Action<int, int> nudgeWas = Computer.Nudge;
            Action<Point> putWas = Computer.PutCursor;
            Func<Point> cursorWas = Computer.CursorAt;
            Func<bool> hiddenWas = Computer.CursorHidden;
            Func<Point, bool> gameUnderWas = Computer.GameUnder;
            Func<bool> escapeWas = Computer.Escape;
            Action haltedWas = Computer.Halted;
            Action<int, int> mouseWas = Computer.SendMouse;
            Action<Point> tappedWas = Computer.Tapped, trackedWas = Computer.Track;
            Action<bool> lendingWas = Computer.Lending;
            Point real = new Point(50, 50), game = new Point(700, 500);
            int moves = 0;
            try
            {
                Computer.Escape = delegate { return false; };
                Computer.Halted = delegate { };
                Computer.Tapped = delegate { };
                Computer.Track = delegate { };
                Computer.Lending = delegate { };
                Computer.Arm();
                Computer.Nudge = delegate(int dx, int dy) { moves++; game = real; real.Offset(dx, dy); };
                Computer.PutCursor = delegate(Point to) { real = to; };
                Computer.CursorAt = delegate { return real; };
                Computer.CursorHidden = delegate { return true; };
                Point goal = new Point(1300, 750);
                Computer.Borrow(goal);
                if (Math.Abs(game.X - goal.X) > 2 || game.Y != goal.Y) throw new Exception("Her click didn't reach a game's own cursor: it stayed at " + game + ".");
                if (real != goal) throw new Exception("Rocking the cursor left it " + (real.X - goal.X) + " away.");
                Computer.GiveBack();
                if (real != new Point(50, 50)) throw new Exception("Steering a game's cursor didn't hand the real one back.");
                moves = 0;
                Computer.CursorHidden = delegate { return false; };
                Computer.GameUnder = delegate { return false; };
                Computer.Borrow(new Point(300, 300));
                Computer.GiveBack();
                if (moves != 0) throw new Exception("She rocked the mouse with the real cursor showing.");
                // Like Roblox: the real cursor shows, but the game only goes by real movement.
                Point roblox = new Point(900, 400);
                Computer.GameUnder = delegate(Point at) { return at == roblox; };
                Computer.Borrow(roblox);
                if (moves == 0 || Math.Abs(game.X - roblox.X) > 2 || game.Y != roblox.Y || real != roblox) throw new Exception("Her click didn't reach a game that shows the real cursor but goes by real movement, like Roblox: it saw " + game + ".");
                Computer.GiveBack();
                checks.Add("PASS her clicks reach a game that draws its own cursor or only goes by real movement, like Roblox, and leave the real cursor where it was");
                int stoppedPresses = 0;
                Computer.SendMouse = delegate(int flags, int amount) { if ((flags & 0x002A) != 0) stoppedPresses++; };
                Computer.CursorHidden = delegate { return true; };
                Computer.Nudge = delegate { Computer.Interrupt(Computer.Escaped); };
                Computer.Arm();
                string stoppedClick = Computer.Member("left_click", new ToolArguments(), null);
                if (stoppedClick != Computer.Escaped || stoppedPresses != 0 || real != new Point(50, 50)) throw new Exception("Esc during steering still sent a click or kept the cursor.");
                Computer.Arm();
                Computer.Click(new Point(90, 90), "double");
                if (!Computer.Interrupted || stoppedPresses != 0 || real != new Point(50, 50)) throw new Exception("The plain click path ignored Esc during steering.");
                checks.Add("PASS Esc during cursor steering cancels member and plain clicks and returns the borrowed cursor");
                Computer.Finish();
                Job cursorClicks = new Job("synthetic clicks");
                if (cursorClicks.Again("left_click", new ToolArguments()) != "" || cursorClicks.Again("left_click", new ToolArguments()) != "" || !cursorClicks.Again("left_click", new ToolArguments()).Contains("3 times")) throw new Exception("Coordinate-free clicks were not counted at her pointer.");
                real = new Point(500, 500);
                if (cursorClicks.Again("left_click", new ToolArguments()) != "") throw new Exception("Moving her pointer kept the old click run.");
                checks.Add("PASS repeated left clicks without coordinates count at her cursor and reset when it moves");
            }
            finally
            {
                Computer.Finish();
                Computer.Arm();
                Computer.Escape = escapeWas;
                Computer.Halted = haltedWas;
                Computer.SendMouse = mouseWas;
                Computer.Tapped = tappedWas;
                Computer.Track = trackedWas;
                Computer.Lending = lendingWas;
                Computer.Nudge = nudgeWas;
                Computer.PutCursor = putWas;
                Computer.CursorAt = cursorWas;
                Computer.CursorHidden = hiddenWas;
                Computer.GameUnder = gameUnderWas;
            }
        }

        // A made-up game: a view into a big patterned world that slides as the mouse moves, to prove her camera finds any game's mouse.
        private static void SmokeCamera(System.Collections.Generic.List<string> checks)
        {
            const int worldWidth = 2400, worldHeight = 1600;
            byte[] world = new byte[worldWidth * worldHeight];
            Random speckle = new Random(77);
            byte[] coarse = new byte[(worldWidth / 16 + 2) * (worldHeight / 16 + 2)];
            speckle.NextBytes(coarse);
            for (int wy = 0; wy < worldHeight; wy++)
                for (int wx = 0; wx < worldWidth; wx++)
                    world[wy * worldWidth + wx] = coarse[(wy / 16) * (worldWidth / 16 + 2) + wx / 16];
            Rectangle area = new Rectangle(0, 0, 1280, 720);
            Func<Rectangle, byte[]> frameWas = Computer.GrayFrame;
            Action<int, int> nudgeWas = Computer.Nudge;
            double cameraX = 0, cameraY = 0, truth = 0;
            int sent = 0;
            bool upside = false, fixedView = false, blank = false, round = false;
            Func<Rectangle, byte[]> seenWorld = delegate(Rectangle part)
            {
                byte[] gray = new byte[Computer.GrayWidth * Computer.GrayHeight];
                if (blank) { for (int fill = 0; fill < gray.Length; fill++) gray[fill] = 200; return gray; }
                for (int gy = 0; gy < Computer.GrayHeight; gy++)
                    for (int gx = 0; gx < Computer.GrayWidth; gx++)
                    {
                        int sampleX = (int)(cameraX + gx * (double)part.Width / Computer.GrayWidth) + 600;
                        if (round) sampleX = ((sampleX % worldWidth) + worldWidth) % worldWidth;
                        int sampleY = (int)(cameraY + gy * (double)part.Height / Computer.GrayHeight) + 400;
                        gray[gy * Computer.GrayWidth + gx] = world[Math.Max(0, Math.Min(worldHeight - 1, sampleY)) * worldWidth + Math.Max(0, Math.Min(worldWidth - 1, sampleX))];
                    }
                return gray;
            };
            Action<int, int> mouse = delegate(int dx, int dy)
            {
                sent += Math.Abs(dx) + Math.Abs(dy);
                if (fixedView) return;
                cameraX += dx * truth;
                cameraY += (upside ? -dy : dy) * truth;
                if (round) cameraY = Math.Min(cameraY, 400);
            };
            Sight game = new Sight { Program = "smoke-a", Bounds = area };
            try
            {
                Computer.GrayFrame = seenWorld;
                Computer.Nudge = mouse;
                foreach (double speed in new[] { 0.3, 1.7, 7.0 })
                {
                    game.Program = "smoke-" + speed;
                    truth = speed;
                    cameraX = cameraY = 0;
                    Computer.TurnView(new ToolArguments { Right = 20 }, game);
                    double wanted = 540 * 20 * Math.PI / 180;
                    if (Math.Abs(cameraX - wanted) > 30 || Math.Abs(cameraY) > 12) throw new Exception("Her camera missed a 20 degree turn at mouse speed " + speed + ": went " + cameraX + ", " + cameraY + ", wanted " + wanted + ".");
                    Computer.TurnView(new ToolArguments { Up = -5 }, game);
                    if (Math.Abs(cameraY - 540 * 5 * Math.PI / 180) > 30) throw new Exception("Her camera missed looking down at mouse speed " + speed + ": went " + cameraY + ".");
                }
                game.Program = "smoke-upside";
                truth = 1.7;
                upside = true;
                cameraX = cameraY = 0;
                Computer.TurnView(new ToolArguments { Up = -8 }, game);
                Computer.TurnView(new ToolArguments { Up = -8 }, game);
                if (Math.Abs(cameraY - 2 * 540 * 8 * Math.PI / 180) > 40) throw new Exception("Her camera didn't work out a game that looks the other way: went " + cameraY + ".");
                upside = false;
                game.Program = "smoke-plain";
                blank = true;
                sent = 0;
                string plain = Computer.TurnView(new ToolArguments { Up = -60 }, game);
                if (sent < 100 || plain.IndexOf("didn't move", StringComparison.Ordinal) >= 0) throw new Exception("Her camera refused to turn away from open sky: " + plain);
                blank = false;
                fixedView = true;
                game.Program = "smoke-menu";
                string menu = Computer.TurnView(new ToolArguments { Right = 30 }, game);
                if (menu.IndexOf("didn't move", StringComparison.Ordinal) < 0) throw new Exception("Her camera didn't notice a view that stayed still: " + menu);
                fixedView = false;
                round = true;
                foreach (double roundSpeed in new[] { 0.6, 1.7, 4.0 })
                {
                    game.Program = "smoke-round-" + roundSpeed;
                    truth = roundSpeed;
                    cameraX = cameraY = 0;
                    Computer.TurnView(new ToolArguments { Right = 90 }, game);
                    if (Math.Abs((cameraX % worldWidth + worldWidth) % worldWidth - worldWidth / 4.0) > 24) throw new Exception("Her camera missed a quarter turn in a game whose view comes round at mouse speed " + roundSpeed + ": went " + cameraX + ".");
                    Computer.TurnView(new ToolArguments { Level = "yes" }, game);
                    if (Math.Abs(cameraY - (400 - worldWidth / 4.0)) > 24) throw new Exception("Her camera didn't level out at mouse speed " + roundSpeed + ": ended at " + cameraY + ".");
                    string flatGame = "smoke-flat-" + roundSpeed;
                    Computer.NoLevel[flatGame] = DateTime.UtcNow.AddMinutes(2);
                    if (Computer.TurnView(new ToolArguments { Level = "yes" }, new Sight { Program = flatGame, Bounds = area }) != Computer.NoCamera) throw new Exception("A game with no camera kept hunting for one.");
                    Computer.NoLevel[flatGame] = DateTime.UtcNow.AddMinutes(-1);
                    if (Computer.TurnView(new ToolArguments { Level = "yes" }, new Sight { Program = flatGame, Bounds = area }) == Computer.NoCamera) throw new Exception("A game stayed marked as having no camera after that wore off.");
                    Computer.NoLevel.Remove(flatGame);
                }
                round = false;
                checks.Add("PASS her camera learns any game's mouse from slow to fast, measures a full turn at any field of view, looks level, lands turns within a few pixels, works out games that look the other way, always turns away from open sky, and says when a view stays still");
            }
            finally
            {
                Computer.GrayFrame = frameWas;
                Computer.Nudge = nudgeWas;
            }
        }

        // Asks to play or use a game reach her hands in any language, whatever her brain's chat reply says.
        private sealed class MiniDice : Random
        {
            public override int Next(int maximum) { return 0; }
        }

        private static int MinisUnbeaten(int[] cells, int turn)
        {
            int result = MiniGame.Outcome(cells, false);
            if (result == 1) throw new Exception("Her perfect tic-tac-toe lost.");
            if (result != 0) return 1;
            int games = 0;
            if (turn == 2)
            {
                int move = MiniGame.TicMove(cells, false, null);
                cells[move] = 2;
                games = MinisUnbeaten(cells, 1);
                cells[move] = 0;
            }
            else for (int choice = 0; choice < 9; choice++)
            {
                if (cells[choice] != 0) continue;
                cells[choice] = 1;
                games += MinisUnbeaten(cells, 2);
                cells[choice] = 0;
            }
            return games;
        }

        private static void SmokeChess(System.Collections.Generic.List<string> checks)
        {
            Action<bool, string> must = delegate(bool okay, string why) { if (!okay) throw new Exception(why); };
            string[] positions = { ChessPosition.Start, "r3k2r/p1ppqpb1/bn2pnp1/3PN3/1p2P3/2N2Q1p/PPPBBPPP/R3K2R w KQkq -", "8/2p5/3p4/KP5r/1R3p1k/8/4P1P1/8 w - -" };
            long[][] totals = { new long[] { 20, 400, 8902, 197281 }, new long[] { 48, 2039, 97862 }, new long[] { 14, 191, 2812, 43238 } };
            for (int fixture = 0; fixture < positions.Length; fixture++)
            {
                ChessPosition board = new ChessPosition(positions[fixture]);
                string before = board.Fen();
                for (int depth = 1; depth <= totals[fixture].Length; depth++)
                {
                    long nodes = board.Perft(depth);
                    must(nodes == totals[fixture][depth - 1] && board.Fen() == before && board.History.Count == 1, "Chess perft or restoration failed at fixture " + fixture + " depth " + depth + ": " + nodes);
                    checks.Add("PASS chess perft " + fixture + " depth " + depth + " = " + nodes);
                }
            }
            foreach (string level in new[] { "easy", "normal", "hard" })
                foreach (string mateFen in new[] { "7k/5Q2/6K1/8/8/8/8/8 w - -", "8/8/8/8/8/6k1/5q2/7K b - -" })
                {
                    ChessPosition mate = new ChessPosition(mateFen);
                    ChessChoice choice = new ChessSearch(mate, level, new Random(8), null).Run();
                    must(choice.Move.From >= 0 && mate.Play(choice.Move.Text) && mate.Ending() == "Checkmate", "Chess missed mate in one on " + level);
                }
            checks.Add("PASS chess finds white and black mate in one at easy, normal and hard");
            foreach (string tacticLevel in new[] { "easy", "normal", "hard" })
            {
                ChessPosition tactic = new ChessPosition("4k3/8/8/8/4q3/8/4R3/4K3 w - -");
                ChessChoice tacticMove = new ChessSearch(tactic, tacticLevel, new Random(2), null).Run();
                must(tacticMove.Move.Text == "e2e4", "Chess left a free queen on " + tacticLevel);
            }
            checks.Add("PASS chess at every level takes an undefended queen instead of choosing an arbitrary legal move");
            must(new ChessPosition("7k/5Q2/6K1/8/8/8/8/8 b - -").Ending() == "Stalemate", "Chess missed stalemate.");
            must(new ChessPosition("7k/6Q1/6K1/8/8/8/8/8 b - - 100 1").Ending() == "Checkmate", "A draw clock replaced checkmate.");
            foreach (int promotion in new[] { 5, 4, 3, 2 })
                foreach (int promoteSide in new[] { 1, -1 })
                {
                    ChessPosition promoted = new ChessPosition(promoteSide == 1 ? "7k/P7/6K1/8/8/8/8/8 w - -" : "8/8/8/8/8/6k1/p7/7K b - -");
                    string promoteBefore = promoted.Fen();
                    ChessMove promoteMove = promoted.Find((promoteSide == 1 ? "a7a8" : "a2a1") + " pnbrqk"[promotion]);
                    must(promoteMove.From >= 0, "A promotion choice was missing.");
                    ChessUndo promoteUndo = promoted.Push(promoteMove, true);
                    must(promoted.Cells[promoteMove.To] == promoteSide * promotion && promoted.Half == 0, "Promotion used the wrong piece.");
                    promoted.Pop(promoteUndo);
                    must(promoted.Fen() == promoteBefore && promoted.History.Count == 1, "Promotion undo lost the pawn.");
                }
            ChessPosition ep = new ChessPosition("7k/8/8/3pP3/8/8/8/K7 w - d6 0 1");
            string epBefore = ep.Fen();
            ChessUndo epUndo = ep.Push(ep.Find("e5d6"), true);
            must(ep.Cells[ChessPosition.At("d5")] == 0 && ep.Cells[ChessPosition.At("d6")] == 1 && ep.Ep == -1 && ep.Half == 0, "En passant failed.");
            ep.Pop(epUndo);
            must(ep.Fen() == epBefore && ep.Key() == ep.History[0], "En passant undo failed.");
            ChessPosition pinnedEp = new ChessPosition("k3r3/8/8/3pP3/8/8/8/4K3 w - d6");
            must(pinnedEp.Find("e5d6").From < 0 && pinnedEp.Key() == new ChessPosition("k3r3/8/8/3pP3/8/8/8/4K3 w - -").Key(), "A pinned en passant capture changed legal moves or repetition identity.");
            must(ep.Key() != new ChessPosition("7k/8/8/3pP3/8/8/8/K7 w - -").Key(), "A legal en passant right was lost from repetition identity.");
            must(new ChessPosition("8/8/8/r4pPK/8/8/8/7k w - f6").Find("g5f6").From < 0, "En passant exposed its own king on a rank.");
            foreach (string castle in new[] { "e1g1", "e1c1", "e8g8", "e8c8" })
            {
                bool white = castle[1] == '1';
                ChessPosition castled = new ChessPosition("r3k2r/8/8/8/8/8/8/R3K2R " + (white ? "w" : "b") + " KQkq -");
                string castleBefore = castled.Fen();
                ChessMove castleMove = castled.Find(castle);
                must(castleMove.From >= 0, "A legal castle was missing.");
                ChessUndo castleUndo = castled.Push(castleMove, true);
                must(castled.Cells[(castleMove.From + castleMove.To) / 2] == (white ? 4 : -4) && (castled.Rights & (white ? 3 : 12)) == 0, "Castling lost its rook or rights.");
                castled.Pop(castleUndo);
                must(castled.Fen() == castleBefore, "Castling undo failed.");
            }
            must(new ChessPosition("4kr2/8/8/8/8/8/8/4K2R w K -").Find("e1g1").From < 0, "Chess castled through check.");
            ChessPosition lostRights = new ChessPosition("4k3/8/8/8/8/8/8/R3K2R w KQ -");
            must(lostRights.Play("h1h2") && lostRights.Play("e8e7") && lostRights.Play("h2h1") && lostRights.Play("e7e8") && lostRights.Find("e1g1").From < 0, "A returned rook regained castling rights.");
            checks.Add("PASS chess stalemate, all eight promotion choices and their undo, en passant and pins, all four castles and rights");
            ChessPosition repeat = new ChessPosition(ChessPosition.Start);
            for (int cycle = 0; cycle < 2; cycle++) foreach (string repeatMove in new[] { "g1f3", "g8f6", "f3g1", "f6g8" }) must(repeat.Play(repeatMove), "Repetition fixture had an illegal move.");
            must(repeat.Repetitions == 3 && repeat.Ending() == "Threefold repetition", "Chess missed threefold repetition.");
            ChessPosition fifty = new ChessPosition("7k/8/8/8/8/8/8/KR6 w - - 99 50");
            must(fifty.Play("b1b2") && fifty.Ending() == "Fifty-move rule", "Chess missed fifty moves.");
            foreach (string dead in new[] { "7k/8/8/8/8/8/8/K7 w - -", "7k/8/8/8/8/8/8/KN6 w - -", "7k/8/8/8/8/8/8/KB6 w - -", "7k/8/8/8/8/3b4/8/KB6 w - -" }) must(new ChessPosition(dead).Insufficient, "Chess missed insufficient material.");
            foreach (string alive in new[] { "7k/8/8/8/8/8/8/KNN5 w - -", "7k/8/8/8/8/8/8/KBN5 w - -", "7k/8/8/8/8/4b3/8/KB6 w - -" }) must(!new ChessPosition(alive).Insufficient, "Chess called a possible mate insufficient material.");
            checks.Add("PASS chess threefold repetition, fifty moves and insufficient material without declaring two knights a dead position");
            MiniScore score = new MiniScore();
            ChessGame scored = new ChessGame(score, "hard", "white");
            scored.Board = new ChessPosition("7k/5Q2/6K1/8/8/8/8/8 w - -");
            must(scored.Move(scored.Board.Find("f7g7"), null) && scored.Result == 1 && score.You == 1 && !scored.Move(new ChessMove(0, 1, 0), null), "Chess did not score mate exactly once.");
            scored.Undo();
            must(score.You == 0 && scored.Result == 0 && scored.Board.Turn == 1, "Undo kept the old chess result.");
            scored.Again(null, "black"); scored.Resign(); scored.Resign();
            must(score.Her == 1 && scored.Result == 2 && scored.You == -1, "Chess resignation or side was wrong.");
            scored.Again("easy", "white");
            must(score.Her == 1 && scored.Level == "easy", "New chess lost session scores.");
            must(scored.Move(scored.Board.Find("e2e4"), null) && scored.Move(scored.Board.Find("e7e5"), new ChessChoice()), "Chess round fixture failed.");
            scored.Undo();
            must(scored.Board.Fen() == ChessPosition.Start, "Chess undo did not return the user's full turn.");
            scored.Move(scored.Board.Find("e2e4"), null); scored.Undo();
            must(scored.Board.Fen() == ChessPosition.Start, "Chess undo while Capri thinks did not restore the position.");
            ChessGame drawn = new ChessGame(score, "normal", "white");
            drawn.Board = new ChessPosition("7k/8/5QK1/8/8/8/8/8 w - -");
            must(drawn.Move(drawn.Board.Find("f6f7"), null) && drawn.Result == 3 && score.Draws == 1, "Chess draw did not reach the session score.");
            drawn.Undo();
            must(score.Draws == 0, "Undo kept a chess draw score.");
            ChessGame moments = new ChessGame(new MiniScore(), "normal", "white");
            moments.Board = new ChessPosition("4k3/8/8/8/4q3/8/4R3/4K3 w - -");
            must(moments.Move(moments.Board.Find("e2e4"), null) && moments.Moment == "her_queen", "Taking her queen did not reach chess commentary.");
            moments.Again(null, "black");
            moments.Board = new ChessPosition("4k3/8/8/8/4q3/8/4R3/4K3 w - -");
            must(moments.Move(moments.Board.Find("e2e4"), new ChessChoice()) && moments.Moment == "your_queen", "Taking their queen did not reach chess commentary.");
            moments.Again(null, "white");
            moments.Move(moments.Board.Find("e2e4"), null); moments.Move(moments.Board.Find("e7e5"), new ChessChoice { Score = 0 });
            moments.Move(moments.Board.Find("g1f3"), null); moments.Move(moments.Board.Find("b8c6"), new ChessChoice { Score = 250 });
            must(moments.Moment == "blunder", "A lost two-pawn evaluation did not reach chess commentary.");
            checks.Add("PASS chess session wins, losses, draws, resign, side selection, new game and full-turn undo including a pending reply");
            Func<string, ToolArguments> inputWas = Hands.MiniInput;
            Func<ToolArguments, string> miniWas = Hands.Mini;
            try
            {
                Hands.MiniInput = delegate { return null; };
                string routed; ToolArguments arguments;
                foreach (string ask in new[] { "capri let's play chess", "play chess with me", "chess", "play chess on hard", "play chess on easy", "play chess on normal", "play chess, i'll be black", "pull up chess", "open chess", "bring up the chess board", "open a game of chess", "show me your chess board" })
                    must(Hands.Heard(ask, out routed, out arguments) && routed == "mini_game" && arguments.Name == "chess" && Hands.Valid(routed, arguments), "Chess wording missed its native board: " + ask);
                Func<System.Collections.Generic.List<OpenWindow>> chessWindows = Hands.Windows;
                Hands.Windows = delegate { return new System.Collections.Generic.List<OpenWindow>(); };
                foreach (string chessWords in new[] { "play this chess match with me", "capri play a chess match with me", "let's play this chess match", "play a game of chess with me", "play a round of chess", "play some chess", "play chess against me", "play this chess game on hard" })
                    must(Hands.Heard(chessWords, out routed, out arguments) && routed == "mini_game" && arguments.Name == "chess" && Hands.Valid(routed, arguments), "Chess wording missed its native board: " + chessWords);
                must(Hands.MiniName("play a game of tic tac toe with me") == "tic_tac_toe" && Hands.MiniName("play this connect four match") == "connect_four", "A board wording missed its game.");
                Hands.Windows = delegate { return new System.Collections.Generic.List<OpenWindow> { new OpenWindow(new IntPtr(15), "Play Chess Online", "Opera") }; };
                must(Hands.Heard("play this chess match with me", out routed, out arguments) && routed == "use_computer" && arguments.Task == "play this chess match with me", "Her board opened over a chess match on screen.");
                Hands.Windows = chessWindows;
                must(Hands.Heard("play chess on hard", out routed, out arguments) && arguments.Level == "hard", "Chess lost the requested level.");
                Hands.MiniInput = ChessGame.Input;
                foreach (string command in new[] { "take that back", "undo", "new game", "i resign", "hint", "resign", "i'll be black" })
                    must(Hands.Heard(command, out routed, out arguments) && routed == "mini_game" && arguments.Name == "chess" && Hands.Valid(routed, arguments), "An open chess board missed: " + command);
                must(Hands.Heard("i'll be black", out routed, out arguments) && arguments.Side == "black" && arguments.Action == "again", "Chess side selection was lost.");
                foreach (string browser in new[] { "open chess.com", "play chess on chess.com", "play chess online" })
                    must(Hands.Heard(browser, out routed, out arguments) && routed == "open_website", "Chess stole a browser request: " + browser);
                must(ChessGame.Input("nice one") == null && Hands.MiniName("don't play chess") == null && Hands.MiniName("play chess on chess.com") == null, "Chess stole ordinary words.");
                must(Hands.Typed("mini_game{\"name\":\"chess\",\"action\":\"open\",\"level\":\"hard\",\"side\":\"black\"}", out routed, out arguments) && arguments.Level == "hard" && arguments.Side == "black", "Chess tool text lost its level or side.");
                Hands.Mini = delegate(ToolArguments called) { return called.Name + ":" + called.Action; };
                foreach (string action in new[] { "open", "again", "close", "undo", "hint", "resign", "level" }) must(Hands.Do("mini_game", new ToolArguments { Name = "chess", Action = action, Level = "hard", Side = "black" }) == "chess:" + action, "Chess action missed dispatch.");
                must(!Hands.Heard("show me chess openings", out routed, out arguments) || routed != "mini_game", "Talk about chess opened her board.");
                var catalogKept = Hands.Catalog;
                Hands.Catalog = delegate { return new System.Collections.Generic.List<InstalledApp> { new InstalledApp("Calculator", "calculator-package!App") }; };
                foreach (string ask in new[] { "pull up a calculator", "open calculator", "bring up the calculator", "show me a calculator", "open calc" })
                    must(Hands.Heard(ask, out routed, out arguments) && routed == "open_app" && arguments.Name == "Calculator", "Calculator wording missed: " + ask);
                Hands.Catalog = catalogKept;
                must(Hands.Tools.Contains("chess") && Hands.ClaudeTools.Contains("chess") && Hands.Listing.Contains("easy|normal|hard") && Agent.Version >= 26, "Chess was missing from a tool schema or agent version.");
                checks.Add("PASS chess typed and spoken requests, board commands, browser exclusions, schema, text parser and action dispatch");
            }
            finally { Hands.MiniInput = inputWas; Hands.Mini = miniWas; }
            int lineCount = 0;
            foreach (string[] group in ChessLines.Lines) lineCount += group.Length;
            must(lineCount >= 30, "Chess needs at least thirty stock lines.");
            MiniChat chatter = new MiniChat();
            scored.Moment = null; chatter.Observe(scored, new Random(1));
            must(chatter.Count == 0, "Chess spoke on a quiet move.");
            foreach (string moment in new[] { "your_queen", "her_queen", "your_check", "her_check", "won", "lost", "blunder", "draw", "resign" })
            {
                scored.Moment = moment;
                chatter.Observe(scored, new Random(2));
                MiniLine line = chatter.Take(8);
                must(line != null && line.Local && line.Said == line.Fallback && line.Said.Length > 0, "A chess moment needed an API line: " + moment);
            }
            checks.Add("PASS chess has " + lineCount + " local stock lines for queens, checks, mate, blunders, draws and resignations; quiet moves stay quiet");
            ChessPosition hardPosition = new ChessPosition(positions[1]);
            string workerBefore = hardPosition.Fen();
            int caller = Thread.CurrentThread.ManagedThreadId;
            Stopwatch elapsed = Stopwatch.StartNew();
            ChessWork hardWork = ChessWork.Start(hardPosition, "hard", 4);
            while (!hardWork.Done && elapsed.ElapsedMilliseconds < 5000) Thread.Sleep(5);
            if (!hardWork.Done) { hardWork.Cancelled = true; checks.Add("LIMIT chess hard worker did not get enough CPU within 5 seconds on this host"); }
            else
            {
                must(hardWork.Error == null && hardWork.Choice != null && hardWork.Choice.Worker != caller && hardPosition.Find(hardWork.Choice.Move.Text).From >= 0 && hardPosition.Fen() == workerBefore && hardPosition.History.Count == 1, "Chess worker failed, used the caller, or changed the live board.");
                checks.Add((elapsed.ElapsedMilliseconds <= 3500 ? "PASS" : "LIMIT") + " chess hard worker: " + hardWork.Choice.Move.Text + ", depth " + hardWork.Choice.Depth + ", " + hardWork.Choice.Nodes + " nodes, " + elapsed.ElapsedMilliseconds + " ms; target 2500 ms search, 3500 ms including scheduling");
            }
            ChessWork cancelledWork = ChessWork.Start(hardPosition, "hard", 5);
            cancelledWork.Cancelled = true;
            Stopwatch cancelWait = Stopwatch.StartNew();
            while (!cancelledWork.Done && cancelWait.ElapsedMilliseconds < 2000) Thread.Sleep(5);
            checks.Add(cancelledWork.Done ? "PASS chess worker cooperatively cancels without touching the live board" : "LIMIT chess cancellation worker could not be scheduled within 2 seconds");
            try
            {
                foreach (float drawScale in new[] { 1f, 1.5f, 2f })
                    foreach (string drawSide in new[] { "white", "black" })
                    {
                        ChessGame picture = new ChessGame(new MiniScore(), "normal", drawSide);
                        using (Bitmap image = ChessBoard.Render(picture, drawScale, ChessPosition.At("e2"), picture.Board.Legal(), new ChessMove(-1, -1, 0), false, ""))
                            must(image.Width == (int)(ChessBoard.Wide * drawScale) && image.Height == (int)(ChessBoard.Tall * drawScale) && image.GetPixel(0, 0).A == 0, "Chess drawing lost its DPI or clipped corners.");
                    }
                must(ChessBoard.Tile(ChessPosition.At("a1"), 1).Y > ChessBoard.Tile(ChessPosition.At("a8"), 1).Y && ChessBoard.Tile(ChessPosition.At("a1"), -1).Y < ChessBoard.Tile(ChessPosition.At("a8"), -1).Y, "Chess did not rotate for black.");
                must(ChessBoard.BoardScale(192, new Rectangle(0, 0, 480, 634)) == 1, "Chess did not fit a small working area.");
                checks.Add("PASS chess draws both sides at 100%, 150%, 200% with shape pieces and fits the monitor");
            }
            catch (System.Runtime.InteropServices.ExternalException) { checks.Add("LIMIT chess bitmap drawing: GDI is unavailable on this host"); }
        }

        private void SmokeChessBoard(System.Collections.Generic.List<string> checks)
        {
            if (!Environment.UserInteractive) { checks.Add("LIMIT chess live board: no interactive desktop for mouse, promotion, commands, cancellation and close checks"); return; }
            Action<bool, string> must = delegate(bool okay, string why) { if (!okay) throw new Exception(why); };
            string brainWas = brain.Model;
            Func<string, string, byte[][], string> headWas = headTest;
            Func<string, byte[]> speakWas = Speak, freeWas = FreeSpeak;
            Action<string> asideWas = asideTest;
            TalkState talkWas = talkState;
            bool topWas = preferences.OnTop;
            int escWas = escAsk;
            double voiceWas = voiceUntil;
            try
            {
                brain.Model = null;
                escAsk = -1;
                headTest = delegate { throw new Exception("Chess asked a brain for a stock line."); };
                Speak = delegate { throw new Exception("Chess asked a paid voice for a line."); };
                FreeSpeak = delegate { return null; };
                string spoken = null;
                asideTest = delegate(string line) { spoken = line; };
                must(HearMini("capri let's play chess"), "Native chess did not open through text without a brain.");
                ChessBoard opened = chess;
                must(opened != null && minis == null && opened.Game.You == 1 && opened.Game.Level == "normal" && Hands.MiniBoard().Contains("CHESS"), "Chess did not use the mini-game opening path.");
                Func<int, Point> middle = delegate(int square)
                {
                    RectangleF tile = ChessBoard.Tile(square, opened.Game.You);
                    return new Point((int)((tile.X + tile.Width / 2) * opened.ScaleShown), (int)((tile.Y + tile.Height / 2) * opened.ScaleShown));
                };
                opened.Command("level", "hard", null);
                opened.ClickAt(middle(ChessPosition.At("e2")));
                opened.ClickAt(middle(ChessPosition.At("e4")));
                ChessWork pending = opened.Pending;
                must(pending != null && opened.Game.Board.Cells[ChessPosition.At("e4")] == 1, "Chess click move did not start a worker.");
                must(VoiceMini("take that back") && pending.Cancelled && opened.Game.Board.Fen() == ChessPosition.Start, "Spoken chess undo did not cancel and restore.");
                Stopwatch unwind = Stopwatch.StartNew();
                while (!pending.Done && unwind.ElapsedMilliseconds < 2000) { Application.DoEvents(); Thread.Sleep(5); }
                Application.DoEvents();
                must(opened.Game.Board.Fen() == ChessPosition.Start && !opened.Busy, "A stale reply landed after undo.");
                opened.DragTo(middle(ChessPosition.At("d2")), middle(ChessPosition.At("d4")));
                must(opened.Game.Board.Cells[ChessPosition.At("d4")] == 1, "Chess drag did not move a pawn.");
                ChessWork beforeNew = opened.Pending;
                must(HearMini("new game") && beforeNew.Cancelled && opened.Game.Board.Fen() == ChessPosition.Start, "New game did not cancel a pending chess reply.");
                must(VoiceMini("i'll be black") && opened.Game.You == -1 && opened.Busy, "Black did not rotate the board and start Capri as white.");
                must(HearMini("new game") && opened.Game.You == -1, "New chess did not keep the user's side.");
                opened.Command("again", "normal", "white");
                opened.Game.Board = new ChessPosition("7k/P7/6K1/8/8/8/8/8 w - -");
                opened.Command("level", "normal", null);
                opened.ClickAt(middle(ChessPosition.At("a7"))); opened.ClickAt(middle(ChessPosition.At("a8")));
                must(opened.Game.Board.Cells[ChessPosition.At("a7")] == 1 && !opened.Busy, "Promotion auto-picked a queen before the user's choice.");
                RectangleF knight = ChessBoard.Button(143);
                opened.ClickAt(new Point((int)((knight.X + knight.Width / 2) * opened.ScaleShown), (int)((knight.Y + knight.Height / 2) * opened.ScaleShown)));
                must(opened.Game.Board.Cells[ChessPosition.At("a8")] == 2 && opened.Game.Result == 3, "The mouse promotion picker lost its knight or insufficient-material draw.");
                opened.Command("again", "normal", "white");
                must(VoiceMini("hint") && opened.Busy, "Spoken hint did not start its own worker.");
                ChessWork beforeResign = opened.Pending;
                must(HearMini("i resign") && beforeResign.Cancelled && opened.Game.Result == 2, "Resign did not finish the game and cancel its hint.");
                miniChat.Last = clock.Elapsed.TotalSeconds - 8; talkState = TalkState.Off; voiceUntil = 0;
                MiniTick(); MiniTick();
                must(spoken != null && miniLine == null, "Chess did not deliver a stock outcome through mini commentary.");
                preferences.OnTop = !topWas; Layer();
                must(opened.Above == preferences.OnTop, "Chess did not follow Always on top.");
                opened.Command("again", "hard", "black");
                ChessWork beforeClose = opened.Pending;
                RectangleF close = ChessBoard.Button(128);
                opened.ClickAt(new Point((int)((close.X + 15) * opened.ScaleShown), (int)((close.Y + 15) * opened.ScaleShown)));
                must(chess == null && opened.IsDisposed && beforeClose.Cancelled && !opened.Ticking && opened.Image == null && miniContext.Length == 0, "Closing chess kept its board, timer, worker or context.");
                checks.Add("PASS chess opens without a brain; mouse click and drag, promotion choice, text and voice commands, local lines, topmost, worker cancellation and immediate close use the mini-game path");
            }
            catch (System.ComponentModel.Win32Exception unavailable) { checks.Add("LIMIT chess live board: Windows could not open it on this desktop (" + unavailable.NativeErrorCode + ")"); }
            finally
            {
                CloseMinis(); miniScores.Remove("chess");
                brain.Model = brainWas; headTest = headWas; Speak = speakWas; FreeSpeak = freeWas; asideTest = asideWas;
                talkState = talkWas; preferences.OnTop = topWas; escAsk = escWas; voiceUntil = voiceWas;
                // Turning Always on top off made her pill, box and typer not-topmost, and Windows takes their owner, her, down with them.
                // Putting them back up doesn't lift her, so Layer lifts her herself.
                if (!topWas && IsHandleCreated) Native.SetWindowPos(Handle, new IntPtr(-2), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
                Layer();
            }
        }

        private void SmokeInk(System.Collections.Generic.List<string> checks)
        {
            System.Collections.Generic.List<InkShape> inkGood = Ink.Parse("line 1 2 3 4; arrow(10,20,30,40); circle [10,20,50,60]; box 80 90 20 30; path 0 0 10 20 30 40; text 12 15 \"hi; choom\"");
            if (inkGood.Count != 6 || inkGood[4].Points.Length != 3 || inkGood[5].Text != "hi; choom") throw new Exception("Ink lost a good shape or its text.");
            if (Ink.Parse("line 1 2 3 4; triangle 1 2 3 4; circle 1 1 1 9; path 1 2 3; line NaN 2 3 4; text 10 20 hi; arrow bad; box 10 20 30 40").Count != 3 || Ink.Parse("").Count != 0 || Ink.Parse("[]").Count != 0) throw new Exception("Bad ink spoiled good shapes or an empty list drew something.");
            if (Ink.Parse("LINE -1.5 +2 3e1 4\nbox (1, 2, 3, 4)\npath [1,2], [3,4], [5,6]").Count != 3) throw new Exception("Ink did not read loose numbers and point lists.");
            checks.Add("PASS ink parses all six shapes, loose points, mixed good and bad shapes and empty lists");
            string[,] inkRequests =
            {
                { "draw a circle around the start button", "use_computer" },
                { "circle the start button", "use_computer" },
                { "point at the save button", "use_computer" },
                { "underline that word", "use_computer" },
                { "draw an arrow to the clock", "use_computer" },
                { "show me where to click", "use_computer" },
                { "draw me a cat", "draw" },
                { "draw on my screen", "draw" },
                { "write hi on my screen", "draw" },
                { "clear your drawing", "draw" },
                { "add a circle around the start button", "use_computer" },
                { "draw me a cat, add it", "draw" }
            };
            for (int inkRequestIndex = 0; inkRequestIndex < inkRequests.GetLength(0); inkRequestIndex++)
            {
                string inkHeardTool;
                ToolArguments inkHeardArgs;
                string inkWording = inkRequests[inkRequestIndex, 0];
                if (!Hands.Heard(inkWording, out inkHeardTool, out inkHeardArgs) || inkHeardTool != inkRequests[inkRequestIndex, 1] || !Hands.Wants(inkWording) || !Hands.Valid(inkHeardTool, inkHeardArgs)) throw new Exception("A drawing request missed her hands: " + inkWording);
                if (inkHeardTool == "use_computer" && inkHeardArgs.Task != inkWording) throw new Exception("A drawing job lost their exact words.");
            }
            foreach (string inkChat in new[] { "don't draw on my screen", "I drew a cat", "if you draw a cat", "draw a cat in paint" })
            {
                string inkChatTool;
                ToolArguments inkChatArgs;
                if (Hands.Heard(inkChat, out inkChatTool, out inkChatArgs) && inkChatTool == "draw") throw new Exception("Ink took conversation or another app's job.");
            }
            if (DrawTool(new ToolArguments()) != Ink.Question || Hands.Pulled(Ink.Question) != Ink.Question || Hands.Pulled("Cleared my drawing.") != "Cleared my drawing.") throw new Exception("An empty drawing request or a clear needed another model reply.");
            Func<bool> inkActiveWas = Ink.Active;
            try
            {
                Ink.Active = delegate { return true; };
                foreach (string inkClear in new[] { "clear your drawing", "rub that out", "erase that", "Hey Capri, can you clear your drawing please?", "remove it", "get rid of that", "clear my screen", "delete the diagram", "remove the art from my screen", "take it off my screen", "erase everything", "Capri, can you get rid of the drawing please?" })
                {
                    string inkClearTool;
                    ToolArguments inkClearArgs;
                    if (!Hands.Heard(inkClear, out inkClearTool, out inkClearArgs) || inkClearTool != "draw" || inkClearArgs.Action != "clear" || inkClearArgs.Description != null || Asides.Plain(inkClear, out inkClearTool, out inkClearArgs) != AsideKind.Tool) throw new Exception("Clearing ink needed a brain: " + inkClear);
                }
                foreach (string inkKept in new[] { "remove the song from my playlist", "delete it from my downloads", "clear my history", "get rid of the virus", "take it off", "remove him from the call" })
                {
                    ToolArguments inkKeptArgs = Ink.Request(Hands.Asked(inkKept));
                    if (inkKeptArgs != null && inkKeptArgs.Action == "clear") throw new Exception("Her ink took a wipe that wasn't about it: " + inkKept);
                }
                ToolArguments inkAdd = Ink.Request("add a dog");
                if (inkAdd == null || inkAdd.Action != "add" || inkAdd.Task == null) throw new Exception("Adding to an existing drawing did not look at its placement.");
                if (Ink.Request("add milk to my shopping list") != null || Ink.Request("add a reminder for 5") != null) throw new Exception("Her ink took an add that wasn't about it.");
            }
            finally { Ink.Active = inkActiveWas; }
            if (Ink.Request("erase that") != null || Ink.Request("rub it out") != null || Ink.Request("remove it") != null || Ink.Request("get rid of that") != null || Ink.Request("clear your drawing") == null) throw new Exception("Erase took a request with nothing drawn, or clear your drawing stopped working.");
            foreach (string diagramAsk in new[] { "Capri, can you make a diagram and help me understand linear algebra?", "make me a diagram of how neural networks work", "make a diagram of a vector", "show me a diagram of gradient descent", "draw me a diagram of a matrix", "explain eigenvectors with a diagram", "help me understand linear algebra with a diagram", "help me understand vectors and make a diagram", "make a flowchart of how a bill becomes law", "make me a mind map of machine learning", "create a bar chart of the planets by size", "make a diagram of how data gets to the model", "I'm learning machine learning, can you make a diagram of a neuron?", "so like capri can you make a diagram and help me understand linear algebra" })
