        {
            Func<string, byte[]> jobSpeakWas = Speak, jobFreeWas = FreeSpeak;
            bool jobQuietWas = preferences.Quiet, jobSilentWas = preferences.Silent, jobServerWas = preferences.ServerVoice;
            bool jobLocalWas = local, jobChatWas = chatting, jobBrokenWas = voiceBroke, jobHushedWas = shushed;
            Job jobVoiceWas = job;
            string jobWorkingWas = working;
            double jobPlayedWas = playVoiced;
            try
            {
                CloseTalk();
                preferences.Quiet = preferences.Silent = preferences.ServerVoice = voiceBroke = shushed = false;
                local = chatting = asideVoiceTest = true;
                int jobPaid = 0, jobFree = 0;
                string jobWords = null;
                byte[] jobWav = Voice.Wave(new short[12000], 24000);
                Speak = delegate(string pickedWords) { jobWords = pickedWords; Interlocked.Increment(ref jobPaid); return jobWav; };
                FreeSpeak = delegate { Interlocked.Increment(ref jobFree); return jobWav; };
                Job speakingJob = new Job("voice routing check");
                job = speakingJob;
                working = Lines.OnIt[0];
                int jobTicket = asking;
                SayJobStart(working, speakingJob);
                WaitVoice(delegate { return jobPaid == 1 && voiceUntil > 0; }, "Opening offline ears made a job start use the wrong voice.");
                if (jobFree != 0 || jobWords != Voice.Spoken(working.Replace("Esc", "Escape")) || asking != jobTicket || reply != null) throw new Exception("The job's chosen voice changed its words or the reply turn.");
                voiceUntil = 0;
                SayAside("Got it.", speakingJob);
                WaitVoice(delegate { return jobPaid == 2 && voiceUntil > 0; }, "A mid-job line lost the selected voice.");
                Func<string, byte[]> jobFallback;
                Speak = delegate { throw new VoiceException("Out of ElevenLabs credits."); };
                Func<string, byte[]> jobPicked = PickVoice(false, out jobFallback, false);
                string jobProblem;
                if (Voiced(jobPicked, jobFallback, "On it.", out jobProblem, false) != null || jobProblem == null || jobFree != 0 || voiceBroke) throw new Exception("A quick job line fell back to the stock voice.");
                voiceBroke = true;
                if (PickVoice(false, out jobFallback, false) != null) throw new Exception("A broken chosen voice made a job line switch voices.");
                voiceBroke = false;
                preferences.Silent = true;
                if (PickVoice(false, out jobFallback, false) != null) throw new Exception("Silent left a job voice selected.");
                preferences.Silent = false;
                local = false;
                int jobVoiceTicket = asideVoice;
                SayJobStart(working, speakingJob);
                if (asideVoice != jobVoiceTicket) throw new Exception("An ElevenLabs chat got a second job voice.");
                checks.Add("PASS job starts and mid-job lines keep ElevenLabs when offline ears open, pronounce Esc as Escape without changing the bubble or reply turn, leave failed or unavailable quick lines silent, respect Silent, and don't duplicate ElevenLabs voice chat");
            }
            finally
            {
                asideVoiceTest = false; asideVoice++; CloseTalk();
                Speak = jobSpeakWas; FreeSpeak = jobFreeWas;
                preferences.Quiet = jobQuietWas; preferences.Silent = jobSilentWas; preferences.ServerVoice = jobServerWas;
                local = jobLocalWas; chatting = jobChatWas; voiceBroke = jobBrokenWas; shushed = jobHushedWas;
                job = jobVoiceWas; working = jobWorkingWas; playVoiced = jobPlayedWas;
            }
        }

        private static IntPtr MicFormat(int rate, int channels, int bits, bool floating, bool extensible)
        {
            IntPtr format = Marshal.AllocCoTaskMem(extensible ? 40 : 18);
            Marshal.Copy(new byte[extensible ? 40 : 18], 0, format, extensible ? 40 : 18);
            int align = channels * (bits / 8);
            Marshal.StructureToPtr(new WaveFormat { Tag = extensible ? unchecked((short)0xFFFE) : (short)(floating ? 3 : 1), Channels = (short)channels, SampleRate = rate, BytesPerSecond = rate * align, Align = (short)align, Bits = (short)bits, Extra = (short)(extensible ? 22 : 0) }, format, false);
            if (extensible)
            {
                Marshal.WriteInt16(format, 18, (short)(bits == 32 && !floating ? 24 : bits));
                Marshal.StructureToPtr(new Guid(floating ? "00000003-0000-0010-8000-00aa00389b71" : "00000001-0000-0010-8000-00aa00389b71"), IntPtr.Add(format, 24), false);
            }
            return format;
        }

        private static byte[] MicSamples(int rate, int channels, int bits, bool floating)
        {
            int width = bits / 8;
            byte[] bytes = new byte[rate * channels * width];
            for (int frame = 0; frame < rate; frame++) for (int side = 0; side < channels; side++)
            {
                double value = side == channels - 1 ? (frame < rate / 2 ? 0.25 : -0.25) : channels == 2 ? (frame < rate / 2 ? -0.25 : 0.25) : 0;
                int offset = (frame * channels + side) * width;
                byte[] sample = floating ? BitConverter.GetBytes((float)value) : bits == 8 ? new[] { (byte)(128 + value * 128) } : bits == 16 ? BitConverter.GetBytes((short)(value * 32768)) : BitConverter.GetBytes((int)(value * 2147483648.0));
                Buffer.BlockCopy(sample, bits == 24 ? 1 : 0, bytes, offset, width);
            }
            return bytes;
        }

        private sealed class MicCheck : ISoundClient, ISoundCapture, IDisposable
        {
            internal int SessionRequests, SessionFailure;
            internal bool SessionThrows;
            internal int Failure;
            internal string Fail;
            internal volatile bool Empty;
            internal int Starts, Stops, Released;
            private readonly IntPtr audio;
            private int at, held;

            internal MicCheck()
            {
                byte[] bytes = MicSamples(48000, 6, 32, true);
                audio = Marshal.AllocHGlobal(bytes.Length);
                Marshal.Copy(bytes, 0, audio, bytes.Length);
            }

            private int Result(string operation) { return Fail == operation ? Failure : 0; }
            public int Initialize(int mode, int flags, long duration, long period, IntPtr format, IntPtr session)
            {
                WaveFormat wave = (WaveFormat)Marshal.PtrToStructure(format, typeof(WaveFormat));
                if (mode != 0 || flags != 0 || period != 0 || wave.SampleRate != 48000 || wave.Channels != 6 || wave.Bits != 32) throw new Exception("Mic fallback didn't use the shared native format.");
                at = held = 0;
                return Result("initialize");
            }
            public int GetBufferSize(out int frames) { frames = 4800; return 0; }
            public int GetStreamLatency(out long latency) { latency = 0; return 0; }
            public int GetCurrentPadding(out int frames) { frames = 0; return 0; }
            public int IsFormatSupported(int mode, IntPtr format, out IntPtr closest) { closest = IntPtr.Zero; return 0; }
            public int GetMixFormat(out IntPtr format) { format = MicFormat(48000, 6, 32, true, true); return 0; }
            public int GetDevicePeriod(out long normal, out long shortest) { normal = shortest = 100000; return 0; }
            public int Start() { Starts++; return Result("start"); }
            public int Stop() { Stops++; return 0; }
            public int Reset() { return 0; }
            public int SetEventHandle(IntPtr handle) { return 0; }
            public int GetService(ref Guid id, out object service)
            {
                service = this;
                if (id != Mixer.SessionId) return 0;
                SessionRequests++;
                if (SessionThrows) throw new COMException("No capture session.");
                if (SessionFailure < 0) service = null;
                return SessionFailure;
            }
            public int GetNextPacketSize(out int frames) { frames = Empty ? 0 : Math.Min(137, 9600 - at); return Result("packet size"); }
            public int GetBuffer(out IntPtr data, out int frames, out int flags, out long position, out long time)
            {
                frames = held = Math.Min(137, 9600 - at); data = IntPtr.Add(audio, at * 24); flags = 0; position = at; time = 0;
                return Result("get buffer");
            }
            public int ReleaseBuffer(int frames)
            {
                if (frames != held) throw new Exception("Mic packet was released with the wrong length.");
                at += frames; Interlocked.Add(ref Released, frames); held = 0;
                return Result("release buffer");
            }
            public void Dispose() { Marshal.FreeHGlobal(audio); }
        }

        private static void SmokeMicSources(System.Collections.Generic.List<string> checks, string output)
        {
            string logWas = Brain.LogPath;
            string log = Path.Combine(output, "mic-check.txt");
            try
            {
                Brain.LogPath = log;
                File.WriteAllText(log, "");
                foreach (int rate in new[] { 16000, 44100, 48000, 96000 }) foreach (int channels in new[] { 1, 2, 6 }) foreach (int kind in new[] { 8, 16, 24, 32, 3 })
                {
                    bool floating = kind == 3;
                    int bits = floating ? 32 : kind;
                    byte[] bytes = MicSamples(rate, channels, bits, floating);
                    IntPtr data = Marshal.AllocHGlobal(bytes.Length);
                    IntPtr format = MicFormat(rate, channels, bits, floating, channels > 2 || bits > 16);
                    try
                    {
                        Marshal.Copy(bytes, 0, data, bytes.Length);
                        MicPcm whole = new MicPcm(format), split = new MicPcm(format);
                        System.Collections.Generic.List<short> all = new System.Collections.Generic.List<short>(), pieces = new System.Collections.Generic.List<short>();
                        whole.Read(data, rate, false, all.AddRange);
                        for (int at = 0; at < rate; at += 137) split.Read(IntPtr.Add(data, at * channels * (bits / 8)), Math.Min(137, rate - at), false, pieces.AddRange);
                        if (all.Count != Ears.Rate || pieces.Count != all.Count || Math.Abs((int)all[0]) != 8192 || Math.Abs((int)all[all.Count - 1]) != 8192 || all[0] != -all[all.Count - 1]) throw new Exception("Mic conversion lost time, polarity or level: " + whole.Format);
                        for (int i = 0; i < all.Count; i++) if (all[i] != pieces[i]) throw new Exception("Mic conversion changed across packet boundaries: " + whole.Format);
                    }
                    finally { Marshal.FreeHGlobal(data); Marshal.FreeCoTaskMem(format); }
                }
                checks.Add("PASS mic PCM and float conversion at 16, 44.1, 48 and 96 kHz: mono, opposite-phase stereo and six-channel input, 8/16/24/32-bit PCM and float32, extensible 24-in-32, preserved levels and packet boundaries");
                IntPtr floatingFormat = MicFormat(16000, 1, 32, true, false);
                IntPtr floatingData = Marshal.AllocHGlobal(Ears.Chunk * 4);
                try
                {
                    float[] values = new float[Ears.Chunk]; values[0] = float.NaN; values[1] = float.PositiveInfinity; values[2] = 2; values[3] = -2;
                    Marshal.Copy(values, 0, floatingData, values.Length);
                    short[] converted = null;
                    new MicPcm(floatingFormat).Read(floatingData, values.Length, false, delegate(short[] chunk) { converted = chunk; });
                    if (converted == null || converted[0] != 0 || converted[1] != 0 || converted[2] != 32767 || converted[3] != -32768) throw new Exception("Mic float conversion didn't clamp or discard invalid samples.");
                    converted = null;
                    new MicPcm(floatingFormat).Read(IntPtr.Zero, Ears.Chunk, true, delegate(short[] chunk) { converted = chunk; });
                    if (converted == null || Speaker.Loudness(converted, 0, converted.Length) != 0) throw new Exception("WASAPI's silent flag didn't produce silence.");
                    Marshal.WriteInt16(floatingFormat, 0, 6);
                    bool rejected = false;
                    try { new MicPcm(floatingFormat); } catch (VoiceException) { rejected = true; }
                    if (!rejected) throw new Exception("A compressed mic format was treated as PCM.");
                }
                finally { Marshal.FreeHGlobal(floatingData); Marshal.FreeCoTaskMem(floatingFormat); }
                checks.Add("PASS mic silent packets need no pointer; nonfinite float samples become zero, clipping is bounded, and unsupported formats are rejected");
                System.Collections.Generic.List<Mic> available = new System.Collections.Generic.List<Mic> { new Mic("picked", "Fake mic", 7) };
                if (Ears.Find("picked", available).Index != 7 || Ears.Find("gone", available) != null) throw new Exception("Mic selection confused the WaveIn device index with its position in the list.");
                string current = "default-one";
                System.Collections.Generic.List<MicCheck> inputs = new System.Collections.Generic.List<MicCheck>();
                System.Collections.Generic.List<string> opened = new System.Collections.Generic.List<string>();
                int heard = 0;
                double level = 0;
                try
                {
                    using (Ears input = new Ears(delegate(string id, Action<short[]> hear)
                    {
                        MicCheck capture = new MicCheck(); inputs.Add(capture); opened.Add(id);
                        return new SoundIn(id, hear, capture, capture);
                    }, delegate(string chosen) { Mic picked = Ears.Find(chosen, available); return picked == null ? current : picked.Id; }, delegate { return false; }))
                    {
                        input.Chosen = "gone";
                        input.Heard += delegate(short[] chunk) { if (chunk.Length != Ears.Chunk) throw new Exception("Wrong mic chunk size."); Interlocked.Add(ref heard, chunk.Length); };
                        input.Level += delegate(double value) { level = value; };
                        int changes = 0;
                        input.Changed += delegate(string problem) { if (problem != null) throw new Exception("A successful fake input reported a failure."); changes++; };
                        input.Start();
                        WaitSound(delegate { return Interlocked.CompareExchange(ref heard, 0, 0) >= Ears.Chunk * 2; }, "Fake WASAPI mic produced no converted audio.");
                        if (opened[0] != "default-one" || Math.Abs(level - 0.25) > 0.001 || input.DeviceChanged || input.OpenedId != "default-one" || changes != 1) throw new Exception("A missing mic didn't capture the default at its original level or announce its actual input.");
                        current = "default-two";
                        if (!input.DeviceChanged) throw new Exception("A changed default mic was ignored while audio still arrived.");
                        input.Stop(); input.Start();
                        if (opened[1] != "default-two") throw new Exception("Reopening kept the old Windows default mic.");
                        input.Stop(); input.Chosen = "picked"; input.Start(); current = "default-three";
                        if (input.DeviceChanged || opened[2] != "picked" || changes != 3) throw new Exception("A fixed mic followed the Windows default or missed an open notification.");
                        input.Muted = true;
                        short[] muted = null;
                        input.Heard += delegate(short[] chunk) { muted = chunk; };
                        short[] loud = new short[Ears.Chunk];
                        for (int i = 0; i < loud.Length; i++) loud[i] = 12000;
                        input.Feed(loud);
                        if (muted == null || muted[0] != 0 || level != 0) throw new Exception("Fallback mic bypassed mute.");
                        inputs[2].Failure = unchecked((int)0x88890004); inputs[2].Fail = "packet size";
                        WaitSound(delegate { return input.Stalled; }, "A failed WASAPI input stayed healthy.");
                    }
                    foreach (MicCheck input in inputs) if (input.Stops != 1) throw new Exception("Stopping a fake mic didn't release its stream.");
                }
                finally { foreach (MicCheck input in inputs) input.Dispose(); }
                checks.Add("PASS fake WASAPI mic: unavailable saved device falls back to default, a running default change reopens, a fixed pick stays fixed, mute is preserved, capture failure is detected and every stream stops");
                foreach (int failure in new[] { unchecked((int)0x80070005), unchecked((int)0x8889000A) })
                {
                    using (MicCheck capture = new MicCheck { Failure = failure, Fail = "initialize" })
                    using (Ears input = new Ears(delegate(string id, Action<short[]> hear) { return new SoundIn(id, hear, capture, capture); }, delegate { return "fake-blocked"; }, delegate { return false; }))
                    {
                        bool explained = false;
                        string announced = null;
                        input.Changed += delegate(string problem) { announced = problem; };
                        try { input.Start(); } catch (VoiceException error) { explained = error.Message.IndexOf(Ears.Problem(failure), StringComparison.Ordinal) >= 0; }
                        if (!explained || input.Listening || capture.Starts != 0 || announced == null || announced.IndexOf(Ears.Problem(failure), StringComparison.Ordinal) < 0) throw new Exception("A blocked or exclusively held mic didn't explain and announce why it couldn't open.");
                    }
                }
                bool openedBlocked = false;
                using (Ears input = new Ears(delegate(string id, Action<short[]> hear) { openedBlocked = true; return null; }, delegate { return "fake"; }, delegate { return true; }))
                {
                    try { input.Start(); } catch (VoiceException error) { if (error.Message != Dictation.MicBlocked) throw; }
                    if (openedBlocked || input.Listening) throw new Exception("Mic privacy denial attempted capture.");
                }
                if (!Ears.Denied("Deny", "Allow") || !Ears.Denied("Allow", "Deny") || Ears.Denied(null, null) || Ears.Denied("Allow", "Allow")) throw new Exception("Mic privacy values were interpreted incorrectly.");
                string logged = File.ReadAllText(log);
                if (logged.IndexOf("Saved mic gone is unavailable", StringComparison.Ordinal) < 0 || logged.IndexOf("WASAPI opened default-one", StringComparison.Ordinal) < 0 || logged.IndexOf("48000 Hz, 6 channels, 32-bit float -> 16000 Hz", StringComparison.Ordinal) < 0 || logged.IndexOf("0x80070005", StringComparison.Ordinal) < 0 || logged.IndexOf("0x8889000A", StringComparison.Ordinal) < 0) throw new Exception("Mic logs lost the device, conversion format or Windows failure code.");
                checks.Add("PASS mic privacy denial and exclusive-use errors explain the fix; logs name the input, native and converted formats, saved-device fallback and HRESULTs; all sources are fake");
            }
            finally { Brain.LogPath = logWas; }
        }

        private void SmokeMicTest(System.Collections.Generic.List<string> checks)
        {
            if (chatting) StopChat();
            TestMic();
            Ears input = micTest;
            short[] quiet = new short[Ears.Chunk];
            for (int i = 0; i < quiet.Length; i++) quiet[i] = 64;
            input.Feed(quiet);
            Application.DoEvents();
            if (!mainframe.MicTesting || mainframe.VoiceNoteText.IndexOf("-54 dB", StringComparison.Ordinal) < 0 || chatting || dictation != null || input.Listening) throw new Exception("Mic Test didn't show the fake live input level without starting recognition or hardware.");
            CheckMicTest(micTestUntil + 1);
            if (micTest != null || mainframe.MicTesting || mainframe.VoiceNoteText.IndexOf("very quiet", StringComparison.Ordinal) < 0) throw new Exception("A quiet mic test didn't finish with input-volume advice.");
            TestMic(); TestMic();
            if (micTest != null || mainframe.MicTesting || mainframe.VoiceNoteText != MicSilent) throw new Exception("Stopping a silent test didn't explain the missing input.");
            checks.Add("PASS Mainframe mic Test shows a live level from fake audio without recognition or voice setup, stops on click or after ten seconds, and explains silence or low input volume");
            Func<string, bool?> mutedWas = MicMuted;
            try
            {
                MicMuted = delegate { return true; };
                TestMic();
                Ears windowsMuted = micTest;
                Stopwatch asked = Stopwatch.StartNew();
                while (micTestWindowsMuted != true && asked.ElapsedMilliseconds < 3000) { Application.DoEvents(); Thread.Sleep(10); }
                windowsMuted.Feed(new short[Ears.Chunk]);
                Application.DoEvents();
                CheckMicTest(micTestUntil + 1);
                if (micTest != null || mainframe.VoiceNoteText != MicMutedInWindows) throw new Exception("A mic muted in Windows was called silent: " + mainframe.VoiceNoteText);
                if (hearingStatus == null || hearingStatus.Text != "Mic muted in Windows") throw new Exception("The hearing line didn't say the mic is muted in Windows: " + (hearingStatus == null ? "nothing" : hearingStatus.Text));
                checks.Add("PASS a mic muted in Windows is called muted there by the mic Test, not silent or blocked");
            }
            finally { MicMuted = mutedWas; if (micTest != null) StopMicTest(false); hearingWindowsMuted = false; UpdateHearing(); }
            Func<Dictation> makeWas = Dictation.Make;
            Func<string> defaultWas = Dictation.DefaultMic;
            bool? ownWas = ownEarsTest;
            bool? comingWas = earsComingTest;
            try
            {
                string current = "first-fake-default";
                System.Collections.Generic.List<StandInDictation> opened = new System.Collections.Generic.List<StandInDictation>();
                ownEarsTest = false;
                Dictation.DefaultMic = delegate { return current; };
                Dictation.Make = delegate { StandInDictation made = new StandInDictation(); opened.Add(made); return made; };
                StartLocal();
                current = "second-fake-default";
                CheckHearing(dictationMicAt + 1);
                if (opened.Count != 2 || !opened[0].Disposed || !opened[1].Started || dictation != opened[1] || !earsReady || dictationMic != current) throw new Exception("Windows speech kept listening to its old default mic.");
                checks.Add("PASS a Windows default input change closes and restarts Windows speech using stand-in recognizers; no device is opened");
                StopChat();
                earsComingTest = true;
                Dictation.Make = delegate { return new StandInDictation { Problem = Dictation.MicBlocked }; };
                StartLocal();
                if (chatting || earsReady || dictation != null || mainframe.VoiceNoteText != "Windows is blocking the mic" || reply != mainframe.HearingText) throw new Exception("Mic privacy denial was hidden behind a pending ears download.");
                checks.Add("PASS Windows mic privacy denial stays visible while her ears download instead of falling back to another blocked recognizer");
            }
            finally { StopChat(); Dictation.Make = makeWas; Dictation.DefaultMic = defaultWas; ownEarsTest = ownWas; earsComingTest = comingWas; }
        }

        private sealed class SoundCheck : ISoundClient, ISoundRender, ISoundVolume, IDisposable
        {
            internal int SessionRequests, SessionFailure;
            internal bool SessionThrows;
            internal volatile string Fail;
            internal volatile bool Drain = true, Muted;
            internal float Volume = 1;
            internal int Rate, Flags, Starts, Resets, VolumeChanges, Peak;
            internal bool StartedEmpty;
            private int padding, frames, writing;
            private bool started;
            private IntPtr buffer;
            private readonly object gate = new object();

            private int Result(string operation) { return Fail == operation ? unchecked((int)0x88890004) : 0; }
            public int Initialize(int mode, int flags, long duration, long period, IntPtr format, IntPtr session)
            {
                WaveFormat input = (WaveFormat)Marshal.PtrToStructure(format, typeof(WaveFormat));
                if (mode != 0 || duration != 2000000 || period != 0 || input.Tag != 1 || input.Channels != 1 || input.Bits != 16 || input.Align != 2 || input.BytesPerSecond != input.SampleRate * 2) throw new Exception("Wrong speech format.");
                Rate = input.SampleRate; Flags = flags; frames = Rate / 5;
                buffer = Marshal.AllocHGlobal(frames * 2);
                return Result("initialize");
            }
            public int GetBufferSize(out int size) { size = frames; return Result("buffer size"); }
            public int GetStreamLatency(out long delay) { delay = 0; return 0; }
            public int GetCurrentPadding(out int filled)
            {
                lock (gate) { if (started && Drain) padding = Math.Max(0, padding - Rate / 100); filled = padding; }
                return Result("padding");
            }
            public int IsFormatSupported(int mode, IntPtr format, out IntPtr closest) { closest = IntPtr.Zero; return 0; }
            public int GetMixFormat(out IntPtr format)
            {
                format = Marshal.AllocCoTaskMem(Marshal.SizeOf(typeof(WaveFormat)));
                Marshal.StructureToPtr(new WaveFormat { Tag = 3, Channels = 2, SampleRate = 48000, BytesPerSecond = 384000, Align = 8, Bits = 32 }, format, false);
                return 0;
            }
            public int GetDevicePeriod(out long normal, out long shortest) { normal = shortest = 100000; return 0; }
            public int Start() { lock (gate) { StartedEmpty |= padding == 0; started = true; Starts++; } return Result("start"); }
            public int Stop() { lock (gate) started = false; return Result("stop"); }
            public int Reset() { lock (gate) { padding = 0; Resets++; } return Result("reset"); }
            public int SetEventHandle(IntPtr handle) { return 0; }
            public int GetService(ref Guid id, out object service)
            {
                service = this;
                if (id != Mixer.SessionId) return 0;
                SessionRequests++;
                if (SessionThrows) throw new COMException("No playback session.");
                if (SessionFailure < 0) service = null;
                return SessionFailure;
            }
            public int GetBuffer(int count, out IntPtr data) { writing = count; data = buffer; return Result("get buffer"); }
            public int ReleaseBuffer(int count, int flags)
            {
                if (count != writing || flags != 0) throw new Exception("Speech was released as silence or with the wrong length.");
                short[] samples = new short[count];
                Marshal.Copy(buffer, samples, 0, count);
                foreach (short sample in samples) Peak = Math.Max(Peak, Math.Abs((int)sample));
                lock (gate) padding += count;
                return Result("release buffer");
            }
            public int SetMasterVolume(float level, IntPtr context) { VolumeChanges++; Volume = level; return 0; }
            public int GetMasterVolume(out float level) { level = Volume; return 0; }
            public int SetMute(bool mute, IntPtr context) { VolumeChanges++; Muted = mute; return 0; }
            public int GetMute(out bool mute) { mute = Muted; return 0; }
            public void Dispose() { if (buffer != IntPtr.Zero) Marshal.FreeHGlobal(buffer); buffer = IntPtr.Zero; }
        }

        // Her voice in your mic's stand-ins (F66): a mic that hums a tone and a cable that keeps all it's given, so the smoke test
        // never opens a real device. Each runs on a clock the test moves, or a real one. The mic hands over whole 10 ms packets
        // as they fill, and the cable lets Windows take a period at a time, as WASAPI does.
        private sealed class StandInMic : IMixMic
        {
            private readonly Func<double> clock;
            private readonly double opened;
            private readonly int rate, period;
            private readonly double hertz, level, fast, late;
            private long given;
            // A frame that clicks to 0.5 on top of the hum.
            private readonly long click;
            internal volatile bool Lost, Disposed;

            // Its packets land `phase` seconds out of step with the moment it opened, and each up to `late` seconds behind, like
            // a busy PC's. That's under a packet, so they still land in order.
            internal StandInMic(Func<double> clock, int rate, double hertz, double level, double fast, double phase, long click, double late)
            {
                this.clock = clock;
                this.rate = rate;
                this.hertz = hertz;
                this.level = level;
                this.fast = fast;
                this.click = click;
                period = rate / 100;
                this.late = Math.Min(late, 0.9 * period / (rate * fast));
                opened = clock() - phase;
            }

            public int Rate { get { return rate; } }
            public int Period { get { return period; } }
            public WaitHandle Ready { get { return null; } }

            internal double HeardAt(long frame) { return opened + frame / (rate * fast); }

            // When a packet lands: once its last frame is heard on its own clock, which runs fast times the test's like a mic whose
            // crystal is off, and then up to late seconds after that.
            private double Lands(long packet)
            {
                double shake = Math.Abs(Math.Sin(packet * 12.9898) * 43758.5453);
                return HeardAt((packet + 1) * period) + late * (shake - Math.Floor(shake));
            }

            internal double NextPacket { get { return Lands(given / period); } }

            public int Read(float[] into)
            {
                if (Lost) throw new MixLost("Stand-in mic unplugged (0x88890004).");
                double now = clock();
                int count = 0;
                while (count + period <= into.Length && Lands((given + count) / period) <= now) count += period;
                for (int i = 0; i < count; i++)
                {
                    long at = given + i;
                    into[i] = (float)(level * Math.Sin(2 * Math.PI * hertz * at / rate)) + (at == click ? 0.5f : 0f);
                }
                given += count;
                return count;
            }

            public void Dispose() { Disposed = true; }
        }

        private sealed class StandInCable : IMixCable
        {
            private readonly Func<double> clock;
            private readonly double opened;
            private readonly int rate, period;
            private readonly object gate = new object();
            private readonly System.Collections.Generic.List<float> kept = new System.Collections.Generic.List<float>();
            // Where each period Windows took started in what it was given, and when it took it.
            private readonly System.Collections.Generic.List<long> takenFrom = new System.Collections.Generic.List<long>();
            private readonly System.Collections.Generic.List<double> takenAt = new System.Collections.Generic.List<double>();
            private long played, pulls;
            // Periods Windows found short once it had been given something.
            internal int Starved;
            internal volatile bool Lost, Disposed;

            internal StandInCable(Func<double> clock, int rate)
            {
                this.clock = clock;
                this.rate = rate;
                period = rate / 100;
                opened = clock();
            }

            public int Rate { get { return rate; } }
            public int Period { get { return period; } }
            public WaitHandle Ready { get { return null; } }

            internal double NextTake { get { return opened + (Math.Floor((clock() - opened) * rate / period) + 1) * period / rate; } }

            internal double OpenedAt { get { return opened; } }

            private void Take()
            {
                long due = (long)Math.Floor((clock() - opened) * rate / period);
                for (; pulls < due; pulls++)
                {
                    long have = kept.Count - played, take = Math.Min(period, have);
                    takenFrom.Add(played);
                    takenAt.Add(opened + (double)(pulls + 1) * period / rate);
                    played += take;
                    if (take < period && kept.Count > 0) Starved++;
                }
            }

            public int Queued()
            {
                if (Lost) throw new MixLost("Stand-in cable gone (0x88890004).");
                lock (gate) { Take(); return (int)(kept.Count - played); }
            }

            public void Write(float[] mono, int count)
            {
                if (Lost) throw new MixLost("Stand-in cable gone (0x88890004).");
                lock (gate)
                {
                    Take();
                    for (int i = 0; i < count; i++) kept.Add(mono[i]);
                }
            }

            internal float[] Kept { get { lock (gate) return kept.ToArray(); } }

            // When Windows took a frame it was given, or NaN if it hasn't yet.
            internal double PlayedAt(long frame)
            {
                lock (gate)
                {
                    int found = takenFrom.BinarySearch(frame);
                    if (found < 0) found = ~found - 1;
                    while (found >= 0 && found + 1 < takenFrom.Count && takenFrom[found + 1] <= frame) found++;
                    return found < 0 || frame >= played ? double.NaN : takenAt[found];
                }
            }

            public void Dispose() { Disposed = true; }
        }

        private sealed class StandInDevices : IMixDevices
        {
            internal Func<double> Clock;
            // Null for a PC without a cable, VB-CABLE's or Steam's.
            internal MixDevice CableThere;
            internal readonly System.Collections.Generic.List<MixDevice> Mics = new System.Collections.Generic.List<MixDevice>();
            internal string DefaultMic;
            internal int MicRate = 48000, CableRate = 48000;
            internal double Level = 0.25, Fast = 1, Phase, Late;
            internal long Click = -1;
            // Each mic's hum, by id. Any other hums at 440 Hz.
            internal readonly System.Collections.Generic.Dictionary<string, double> Hums = new System.Collections.Generic.Dictionary<string, double>();
            internal bool CableBusy;
            // Windows' volume on the cable's far end, in dB, its mute, and whether Windows won't say.
            internal volatile bool FarMuted, FarUnread;
            internal double FarBoost;
            internal readonly System.Collections.Generic.List<StandInMic> Opened = new System.Collections.Generic.List<StandInMic>();
            internal readonly System.Collections.Generic.List<StandInCable> Cables = new System.Collections.Generic.List<StandInCable>();

            internal StandInDevices()
            {
                Stopwatch own = Stopwatch.StartNew();
                Clock = delegate { return own.Elapsed.TotalSeconds; };
            }

            internal Func<MixDevice> CableRead;

            public MixDevice Cable(string chosen) { return CableRead == null ? CableThere : CableRead(); }

            // Explicit, since Cables is also the list of cables the mix opened.
            System.Collections.Generic.List<MixDevice> IMixDevices.Cables()
            {
                System.Collections.Generic.List<MixDevice> cables = new System.Collections.Generic.List<MixDevice>();
                if (CableThere != null) cables.Add(CableThere);
                return cables;
            }

            // The programs the smoke test says are hearing the cable's far end.
            internal readonly System.Collections.Generic.List<string> Listeners = new System.Collections.Generic.List<string>();

            public System.Collections.Generic.List<string> Listening(string mic) { lock (Listeners) return new System.Collections.Generic.List<string>(Listeners); }

            public bool Boost(MixDevice cable, out double boost, out bool muted) { boost = FarBoost; muted = FarMuted; return cable != null && cable.Far != null && !FarUnread; }

            public MixDevice Mic(string chosen) { lock (Mics) return MicMix.MicFor(Mics, chosen, DefaultMic); }

            public IMixMic OpenMic(MixDevice mic)
            {
                double hum;
                if (!Hums.TryGetValue(mic.Id, out hum)) hum = 440;
                StandInMic made = new StandInMic(Clock, MicRate, hum, Level, Fast, Phase, Click, Late);
                lock (Opened) Opened.Add(made);
                return made;
            }

            public IMixCable OpenCable(MixDevice cable)
            {
                if (CableBusy) throw new MixLost("Stand-in cable busy (0x88890008).");
                StandInCable made = new StandInCable(Clock, CableRate);
                lock (Cables) Cables.Add(made);
                return made;
            }
        }

        private static void WaitSound(Func<bool> done, string problem)
        {
            Stopwatch waited = Stopwatch.StartNew();
            while (!done() && waited.ElapsedMilliseconds < 4500) Thread.Sleep(5);
            if (!done()) throw new Exception(problem);
        }

        // Each of her sounds opts out of Windows quieting other apps before it starts, and keeps going when that fails.
        private static void SmokeDucking(System.Collections.Generic.List<string> checks, string output)
        {
            Func<string, int, object> sessionWas = Mixer.Session;
            Func<object, bool, int> duckingWas = Mixer.Ducking;
            string logWas = Brain.LogPath;
            try
            {
                Brain.LogPath = Path.Combine(output, "ducking-check.txt");
                foreach (int failure in new[] { 0, 1, 2, 3, 4 })
                {
                    using (MicCheck mic = new MicCheck())
                    using (SoundCheck voice = new SoundCheck())
                    {
                        int micAsked = 0, voiceAsked = 0, heard = 0;
                        bool wrong = false;
                        mic.SessionFailure = voice.SessionFailure = failure == 3 ? unchecked((int)0x80004002) : 0;
                        mic.SessionThrows = voice.SessionThrows = failure == 4;
                        Mixer.Ducking = delegate(object session, bool optOut)
                        {
                            if (!optOut) wrong = true;
                            if (session == mic) { micAsked++; if (mic.Starts != 0) wrong = true; }
                            else if (session == voice) { voiceAsked++; if (voice.Starts != 0) wrong = true; }
                            else wrong = true;
                            if (failure == 2) throw new COMException("Ducking is unavailable.");
                            return failure == 1 ? unchecked((int)0x80004005) : 0;
                        };
                        using (SoundIn input = new SoundIn("fake-mic", delegate(short[] chunk) { Interlocked.Add(ref heard, chunk.Length); }, mic, mic))
                        using (SoundOut playback = new SoundOut(Ears.Rate, voice, voice))
                        {
                            short[] sound = new short[Ears.Chunk];
                            for (int i = 0; i < sound.Length; i++) sound[i] = 4096;
                            playback.Write(sound);
                            WaitSound(delegate { return Interlocked.CompareExchange(ref heard, 0, 0) > 0 && Interlocked.Read(ref playback.Played) >= sound.Length; }, "Ducking failure stopped fake capture or playback.");
                            if (!input.Alive || !playback.Alive || mic.Starts != 1 || voice.Starts != 1) throw new Exception("Ducking failure closed a fake audio session.");
                        }
                        int expected = failure < 3 ? 1 : 0;
                        if (wrong || mic.SessionRequests != 1 || voice.SessionRequests != 1 || micAsked != expected || voiceAsked != expected)
                            throw new Exception("A capture or playback session didn't ask to opt out before starting: " + failure);
                    }
                }
                object capture = new object(), render = new object();
                System.Collections.Generic.List<string> routes = new System.Collections.Generic.List<string>();
                int asked = 0;
                bool optedOut = true;
                Mixer.Session = delegate(string id, int flow) { routes.Add((id ?? "default") + ":" + flow); return flow == 1 ? capture : render; };
                Mixer.Ducking = delegate(object session, bool optOut) { asked++; optedOut &= optOut && (session == capture || session == render); return unchecked((int)0x80004005); };
                Mixer.NoDucking("picked-mic", 1); Mixer.NoDucking(null, 0);
                if (asked != 2 || !optedOut || string.Join("|", routes.ToArray()) != "picked-mic:1|default:0") throw new Exception("Wave capture or playback used the wrong fake default session or ducking preference.");
                Mixer.Session = delegate { throw new COMException("No session manager."); };
                Mixer.NoDucking("picked-mic", 1); Mixer.NoDucking(null, 0);
                Mixer.Session = delegate { return null; };
                Mixer.NoDucking("picked-mic", 1); Mixer.NoDucking(null, 0);
                checks.Add("PASS ducking: fake capture and playback sessions request TRUE before starting and keep moving audio after a failed HRESULT, a thrown opt-out or unavailable session service; wave sessions ask on the selected mic and default output, and a missing manager or session is ignored");
            }
            finally { Mixer.Session = sessionWas; Mixer.Ducking = duckingWas; Brain.LogPath = logWas; }
        }

        private static void SmokeSound(System.Collections.Generic.List<string> checks, string output)
        {
            bool waveWas = Speaker.SkipWave;
            int loudnessWas = Voice.Loudness;
            string logWas = Brain.LogPath;
            string log = Path.Combine(output, "speaker-check.txt");
            try
            {
                Brain.LogPath = log;
                File.WriteAllText(log, "");
                Speaker.SkipWave = true;
                Voice.Loudness = 50;
                if (Marshal.SizeOf(typeof(WaveFormat)) != 18 || (int)Marshal.OffsetOf(typeof(WaveFormat), "Extra") != 16) throw new Exception("Her PCM format doesn't match Windows' WAVEFORMATEX.");
                foreach (int soundRate in new[] { 16000, 22050, 24000, 44100, 48000 })
                {
                    System.Collections.Generic.List<SoundCheck> outputs = new System.Collections.Generic.List<SoundCheck>();
                    using (Speaker outputSpeaker = new Speaker(false, delegate(int openedRate)
                    {
                        SoundCheck openedSound = new SoundCheck(); outputs.Add(openedSound);
                        return new SoundOut(openedRate, openedSound, openedSound);
                    }))
                    {
                        try
                        {
                            Voice outputVoice = new Voice(outputSpeaker);
                            short[] sound = new short[soundRate / 10];
                            for (int soundAt = 0; soundAt < sound.Length; soundAt++) sound[soundAt] = 12000;
                            outputVoice.Play(Voice.Wave(sound, soundRate));
                            WaitSound(delegate { return outputSpeaker.ModernPlayed >= sound.Length; }, "Finished speech never reached the fallback's buffer.");
                            if (outputs.Count != 1 || outputs[0].Flags != SoundOut.ConvertFlags || outputs[0].Rate != soundRate || outputs[0].StartedEmpty || outputs[0].Peak != 6000) throw new Exception("Speech bypassed WASAPI, started empty, or applied volume twice.");
                            long fedBeforeClear = outputSpeaker.ModernFed;
                            outputSpeaker.Clear();
                            outputSpeaker.Play(sound);
                            WaitSound(delegate { return outputSpeaker.ModernFed >= fedBeforeClear + sound.Length && outputs[0].Starts == 2; }, "Clear lost the next voice line.");
                            if (outputs[0].Resets != 1 || outputs[0].StartedEmpty) throw new Exception("Clear didn't refill before restarting speech.");
                            outputs[0].Fail = "padding";
                            WaitSound(delegate { return outputSpeaker.ModernFailure != null; }, "A lost WASAPI device stayed alive.");
                            outputSpeaker.Play(sound);
                            WaitSound(delegate { return outputs.Count == 2 && outputSpeaker.ModernPlayed >= sound.Length; }, "The next voice chunk didn't reopen a failed stream.");
                            outputVoice.Play(Voice.Wave(sound, soundRate));
                            WaitSound(delegate { return outputs.Count == 3 && outputSpeaker.ModernPlayed >= sound.Length; }, "A second finished voice line reused a closed stream.");
                            outputVoice.Stop();
                            if (outputSpeaker.Modern) throw new Exception("Stopping a voice left its stream open.");
                        }
                        finally { outputSpeaker.Close(); foreach (SoundCheck used in outputs) used.Dispose(); }
                    }
                }
                checks.Add("PASS finished speech uses Speaker and WASAPI at 16, 22.05, 24, 44.1 and 48 kHz, requests PCM and rate conversion, applies her volume once, fills before starting, survives Clear followed by another line, and reopens after a lost stream or a stopped voice");
                foreach (string operation in new[] { "start", "padding", "get buffer", "release buffer", "stop", "reset" })
                {
                    using (SoundCheck broken = new SoundCheck())
                    using (SoundOut brokenStream = new SoundOut(24000, broken, broken))
                    {
                        if (operation == "stop" || operation == "reset")
                        {
                            brokenStream.Write(new short[2400]);
                            WaitSound(delegate { return broken.Starts > 0; }, "The test stream didn't start.");
                            broken.Fail = operation;
                            brokenStream.Clear();
                        }
                        else
                        {
                            broken.Fail = operation;
                            try { brokenStream.Write(new short[2400]); }
                            catch (VoiceException) { }
                        }
                        WaitSound(delegate { return !brokenStream.Alive; }, "WASAPI " + operation + " failed silently.");
                        if (brokenStream.Failure == null || !brokenStream.Failure.Contains(operation) || !brokenStream.Failure.Contains("88890004")) throw new Exception("A WASAPI error lost its operation or HRESULT.");
                    }
                }
                using (SoundCheck stalledSound = new SoundCheck { Drain = false, Muted = true })
                using (SoundOut stalledStream = new SoundOut(24000, stalledSound, stalledSound))
                {
                    stalledStream.Write(new short[2400]);
                    WaitSound(delegate { return !stalledStream.Alive; }, "A buffer that never drains stayed alive.");
                    if (!stalledStream.Failure.Contains("stopped draining") || stalledSound.VolumeChanges != 0) throw new Exception("A stalled stream wasn't diagnosed, or changed their mute.");
                    stalledSound.Muted = false; stalledSound.Volume = 0;
                    if (SoundOut.Quiet(stalledSound) == null) throw new Exception("Zero session volume wasn't diagnosed.");
                }
                string logged = File.ReadAllText(log);
                if (!logged.Contains("session is muted") || !logged.Contains("stopped draining") || !logged.Contains("release buffer failed") || !logged.Contains("submitted") || !logged.Contains("drained")) throw new Exception("A silent speaker failure left no useful error log.");
                checks.Add("PASS WASAPI logs failed writes, starts, stops, resets and padding calls with their HRESULT and sample counts; a buffer that never drains fails visibly, and session mute and zero volume are diagnosed without changing them");
                short[] original = new short[4800];
                for (int originalAt = 0; originalAt < original.Length; originalAt++) original[originalAt] = (short)(9000 * Math.Sin(originalAt * 0.04));
                byte[] fishWave = Voice.Wave(original, 48000);
                short[] fishSound = VoiceServer.Sound(fishWave, "audio/wav", "Fish Audio");
                if (fishSound.Length != 2400 || Speaker.Loudness(fishSound, 0, fishSound.Length) < 0.1 || !VoiceServer.SoundFormat(fishWave).Contains("48000 Hz") || VoiceServer.SoundFormat(new byte[0]) != "unrecognized audio format") throw new Exception("Fish Audio's rate conversion or format diagnosis went wrong.");
                bool fishUnreadable = false;
                try { VoiceServer.Sound(new byte[] { 102, 76, 97, 67, 0, 0 }, "audio/flac", "Fish Audio"); }
                catch (VoiceException fishError) { fishUnreadable = fishError.Message.Contains("FLAC, 6 bytes") && fishError.Message.Contains("Windows couldn't decode"); }
                if (!fishUnreadable) throw new Exception("An undecodable Fish reply lost its format and size.");
                checks.Add("PASS Fish Audio WAV replies are decoded and resampled from 48 kHz to 24 kHz, and unreadable audio is described by its format and size without logging its contents");
            }
            finally { Speaker.SkipWave = waveWas; Voice.Loudness = loudnessWas; Brain.LogPath = logWas; }
        }

        private static void SmokeHardwareSound(System.Collections.Generic.List<string> checks)
        {
            if (OnGitHub) { checks.Add("LIMIT unattended smoke leaves real audio devices closed; fake sound clients cover playback, and real WASAPI speakers need a live check"); return; }
            bool hardwareWaveWas = Speaker.SkipWave;
            using (Speaker hardwareSpeaker = new Speaker(false))
            {
                try
                {
                    Speaker.SkipWave = true;
                    Voice hardwareVoice = new Voice(hardwareSpeaker);
                    foreach (int hardwareRate in new[] { 24000, 22050 })
                    {
                        hardwareVoice.Play(Voice.Wave(new short[hardwareRate / 10], hardwareRate));
                        Stopwatch hardwareWait = Stopwatch.StartNew();
                        while (hardwareSpeaker.ModernPlayed < hardwareRate / 10 && hardwareSpeaker.ModernFailure == null && hardwareWait.ElapsedMilliseconds < 1500) Thread.Sleep(10);
                        if (!hardwareSpeaker.Modern || hardwareSpeaker.ModernFailure != null || hardwareSpeaker.ModernPlayed < hardwareRate / 10)
                        {
                            checks.Add("LIMIT WASAPI hardware at " + hardwareRate + " Hz: " + (hardwareSpeaker.ModernFailure ?? "submitted " + hardwareSpeaker.ModernFed + ", drained " + hardwareSpeaker.ModernPlayed + " samples"));
                            return;
                        }
                    }
                    hardwareVoice.Stop();
                    checks.Add("PASS finished WAV speech reaches WASAPI and its buffers drain at 24 and 22.05 kHz across two voice lines");
                    checks.Add("LIMIT WASAPI hardware check used silence; actual audibility, Windows mixer settings and the tester's speakers need a listening check");
                }
                catch (VoiceException error) { checks.Add("LIMIT her WASAPI speakers didn't play here: " + error.Message); }
                finally { Speaker.SkipWave = hardwareWaveWas; }
            }
        }

        // A pretend PC for her voice in your mic: VB-CABLE at cableRate and one mic humming 440 Hz at 0.25, on the test's clock.
        private const string MixMicId = "{0.0.1.00000000}.{stand-in-mic}";

        private static StandInDevices MixPc(double[] now, int cableRate, int micRate)
        {
            StandInDevices pc = new StandInDevices();
            pc.Clock = delegate { return now[0]; };
            pc.CableThere = new MixDevice("{0.0.0.00000000}.{stand-in-cable}", "CABLE Input (VB-Audio Virtual Cable)", "{0.0.1.00000000}.{stand-in-cable-out}");
            pc.Mics.Add(new MixDevice(MixMicId, "Microphone (stand-in)"));
            pc.DefaultMic = MixMicId;
            pc.CableRate = cableRate;
            pc.MicRate = micRate;
            return pc;
        }

        // Runs a mix on the test's clock, waking it as WASAPI would: when the mic's packet lands, when the cable takes a period,
        // and every 10 ms while neither is open, each wake a moment late like a real one. during runs first at each wake.
        private static void RunMix(MicMix mix, StandInDevices pc, double[] now, double seconds, Action<double> during)
        {
            double end = now[0] + seconds;
            while (now[0] < end)
            {
                double next = now[0] + 0.01;
                lock (pc.Opened) foreach (StandInMic heard in pc.Opened) if (!heard.Disposed) next = Math.Min(next, heard.NextPacket);
                lock (pc.Cables) foreach (StandInCable playing in pc.Cables) if (!playing.Disposed) next = Math.Min(next, playing.NextTake);
                now[0] = Math.Min(end, next) + 0.0002;
                if (during != null) during(now[0]);
                mix.Step();
            }
        }

        // A steady tone as her speakers hand it over.
        private static short[] Hum(int rate, double hertz, double level, double seconds)
        {
            short[] hum = new short[(int)(rate * seconds)];
            for (int i = 0; i < hum.Length; i++) hum[i] = (short)Math.Round(level * 32767 * Math.Sin(2 * Math.PI * hertz * i / rate));
            return hum;
        }

        private static double[] hannWindow = new double[0];
        private static double hannTotal;

        // How strong hertz is over a stretch of sound, as a sine's amplitude where 1 is full scale: Goertzel with a Hann window.
        private static double ToneIn(float[] sound, int rate, double hertz, double from, double seconds)
        {
            int start = (int)(from * rate), count = Math.Min((int)(seconds * rate), sound.Length - start);
            if (count < 16) return 0;
            if (hannWindow.Length != count)
            {
                hannWindow = new double[count];
                hannTotal = 0;
                for (int i = 0; i < count; i++) hannTotal += hannWindow[i] = 0.5 - 0.5 * Math.Cos(2 * Math.PI * i / (count - 1));
            }
            double turn = 2 * Math.Cos(2 * Math.PI * hertz / rate), one = 0, two = 0;
            for (int i = 0; i < count; i++)
            {
                double next = sound[start + i] * hannWindow[i] + turn * one - two;
                two = one;
                one = next;
            }
            return 2 * Math.Sqrt(Math.Max(0, one * one + two * two - turn * one * two)) / hannTotal;
        }

        // The strongest frequency within spread Hz of near, to 0.05 Hz.
        private static double PeakIn(float[] sound, int rate, double near, double spread, double from, double seconds)
        {
            double best = near, strongest = -1;
            for (double hertz = near - spread; hertz <= near + spread; hertz += 0.05)
            {
                double strength = ToneIn(sound, rate, hertz, from, seconds);
                if (strength > strongest) { strongest = strength; best = hertz; }
            }
            return best;
        }

        // The strongest stray tone: at every 100 Hz, and 37 Hz past each, up to near Nyquist, 20 Hz or more from any tone meant to be
        // there. A glitch each packet or chunk would show at 100 Hz steps.
        private static double StrayIn(float[] sound, int rate, double from, double seconds, params double[] tones)
        {
            double most = 0;
            for (double hertz = 100; hertz < rate * 0.47; hertz += 100)
                foreach (double probe in new[] { hertz, hertz + 37 })
                {
                    bool meant = false;
                    foreach (double tone in tones) meant |= Math.Abs(probe - tone) < 20;
                    if (!meant) most = Math.Max(most, ToneIn(sound, rate, probe, from, seconds));
                }
            return most;
        }

        private static string Khz(int rate) { return (rate / 1000.0).ToString("0.#", System.Globalization.CultureInfo.InvariantCulture); }

        private static string Db(double level) { return (20 * Math.Log10(Math.Max(1e-9, level))).ToString("0", System.Globalization.CultureInfo.InvariantCulture); }

        // Her voice in your mic (F66) on stand-in devices and a pretend clock: no real device opens.
        private static void SmokeVoiceInMic(System.Collections.Generic.List<string> checks, string output)
        {
            string logWas = Brain.LogPath;
            int loudnessWas = Voice.Loudness;
            MicMix currentWas = MicMix.Current;
            try
            {
                Brain.LogPath = Path.Combine(output, "mic-mix-check.txt");
                File.WriteAllText(Brain.LogPath, "");
                Voice.Loudness = 100;
                // Their mic at 440 Hz, her line at 1000 Hz from 24 kHz, and voice chat streaming in at 700 Hz from 16 kHz: each comes
                // out at its own level and pitch, with nothing else in there, at every cable rate from a mic at every rate.
                double worstStray = 0;
                foreach (int cableRate in new[] { 48000, 44100, 16000 })
                    foreach (int micRate in new[] { 48000, 44100, 16000 })
                    {
                        double[] now = { 0 };
                        StandInDevices pc = MixPc(now, cableRate, micRate);
                        pc.Phase = 0.0037;
                        MicMix mix = new MicMix(pc, delegate { return now[0]; });
                        object lines = new object(), chat = new object();
                        mix.Step();
                        if (!mix.Mixing || pc.Opened.Count != 1 || pc.Cables.Count != 1 || mix.Problem != null) throw new Exception("Her mic mix didn't open the stand-in mic and cable at " + Khz(cableRate) + " kHz: " + mix.Problem);
                        mix.Take(lines, Hum(24000, 1000, 0.2, 3), 24000);
                        short[] streamed = Hum(16000, 700, 0.15, 3);
                        int sent = 0;
                        // Voice chat comes in 50 ms chunks, each a little ahead of when it plays.
                        RunMix(mix, pc, now, 2.6, delegate(double at)
                        {
                            while (sent < streamed.Length && sent < (at + 0.1) * 16000)
                            {
                                short[] chunk = new short[Math.Min(800, streamed.Length - sent)];
                                Array.Copy(streamed, sent, chunk, 0, chunk.Length);
                                mix.Take(chat, chunk, 16000);
                                sent += chunk.Length;
                            }
                        });
                        float[] got = pc.Cables[0].Kept;
                        double micLevel = ToneIn(got, cableRate, 440, 1, 1), herLevel = ToneIn(got, cableRate, 1000, 1, 1), chatLevel = ToneIn(got, cableRate, 700, 1, 1);
                        double micHz = PeakIn(got, cableRate, 440, 3, 1, 1), herHz = PeakIn(got, cableRate, 1000, 3, 1, 1), chatHz = PeakIn(got, cableRate, 700, 3, 1, 1);
                        double stray = StrayIn(got, cableRate, 1, 1, 440, 1000, 700);
                        worstStray = Math.Max(worstStray, stray);
                        string seen = Khz(micRate) + " to " + Khz(cableRate) + " kHz: mic " + micLevel.ToString("0.0000") + " at " + micHz.ToString("0.00") + " Hz, her " + herLevel.ToString("0.0000") + " at " + herHz.ToString("0.00") + " Hz, chat " + chatLevel.ToString("0.0000") + " at " + chatHz.ToString("0.00") + " Hz, stray " + stray.ToString("0.00000") + ", " + got.Length + " frames, short " + mix.Starved + "/" + pc.Cables[0].Starved;
                        if (Math.Abs(micLevel / 0.25 - 1) > 0.03 || Math.Abs(herLevel / 0.2 - 1) > 0.03 || Math.Abs(chatLevel / 0.15 - 1) > 0.03 || Math.Abs(micHz - 440) > 0.5 || Math.Abs(herHz - 1000) > 0.25 || Math.Abs(chatHz - 700) > 0.25
                            || stray > 0.0025 || got.Length < 2.55 * cableRate || got.Length > 2.65 * cableRate || mix.Starved != 0 || pc.Cables[0].Starved != 0)
                            throw new Exception("Her mic mix came out wrong from " + seen);
                        mix.Stop();
                        if (!pc.Opened[0].Disposed || !pc.Cables[0].Disposed || mix.Mixing) throw new Exception("Stopping her mic mix kept a device open.");
                    }
                // Going down to 16 kHz a 12 kHz tone doesn't fold back to 4 kHz, and going up from 16 kHz a 6 kHz tone doesn't image at 10 kHz.
                double alias, image, imaged;
                {
                    double[] now = { 0 };
